/* =========================================================================
   1. ГЛОССАРИЙ И КАТЕГОРИИ (TERMS)
   ========================================================================= */
const CATS = { basics: ['Основы', '#22c55e'], trading: ['Торговля', '#38bdf8'], metrics: ['Метрики', '#a78bfa'], algo: ['Алго-модели', '#fb923c'], risk: ['Риск-менеджмент', '#f43f5e'], ru: ['Право РФ', '#f472b6'], infra: ['Инфраструктура', '#eab308'], psy: ['Психология', '#ec4899'] };

const TERMS_RAW = CN_CONTENT.ensure('TERMS_RAW');
const TERMS = TERMS_RAW.filter(Boolean);
function normTermName(s){
  return (s || '').toLowerCase().replace(/\s*\([^)]*\)/g, '').trim();
}
function findTermIndexByName(name){
  if(!name) return -1;
  const n = (name || '').toLowerCase().trim();
  let idx = TERMS.findIndex(g => g.t === name || g.t.toLowerCase() === n);
  if(idx < 0){
    const nn = normTermName(name);
    idx = TERMS.findIndex(g => normTermName(g.t) === nn);
  }
  if(idx < 0){
    idx = TERMS.findIndex(g => g.t.toLowerCase().includes(n) || n.includes(g.t.toLowerCase()));
  }
  if(idx < 0){
    const words = n.split(/[\s\(\)\[\],:—\-]+/).filter(w => w.length >= 4);
    for(let i = 0; i < words.length; i++){
      const w = words[i];
      idx = TERMS.findIndex(g => g.t.toLowerCase().includes(w));
      if(idx >= 0) break;
    }
  }
  return idx;
}

