// Миграция индексных хранилищ (learned, srsState) после дедупликации глоссария: 208 → 205 терминов.
// Удалённые дубли: «Холодный кошелёк» (89), «Халвинг» (93), «Математическое ожидание (Expectancy)» (120).
(function migrateGlossaryIndices(){
  if(localStorage.getItem('cn_gloss_idx_migrated_v3') === '1') return;
  try{
    const removed = [[89, 70], [93, 66], [120, 196]]; // [старый индекс, новый индекс сохранённого двойника]
    const removedOld = removed.map(r => r[0]);
    const remap = (obj) => {
      const next = {};
      Object.keys(obj || {}).forEach(k => {
        const old = parseInt(k, 10);
        if(isNaN(old)) return;
        const ri = removedOld.indexOf(old);
        const ni = ri >= 0 ? removed[ri][1] : old - removedOld.filter(x => x < old).length;
        if(next[ni] === undefined) next[ni] = obj[k];
      });
      return next;
    };
    learned = remap(learned);
    srsState = remap(srsState);
    localStorage.setItem('cn_gloss_idx_migrated_v3', '1');
    save();
  } catch(e){ console.warn('Glossary index migration skipped:', e); }
})();

// Изоляция прогресса: основной % курса и бейдж «Гроссмейстер 56» считают ТОЛЬКО Фазы 0–5.
// Бонус-уроки (phase 6) и матфакультатив (phase 7) не влияют на них.
function coreLessonList(){
  return LESSONS.filter(l => !l.phase || l.phase <= 5);
}
function coreLessonsDoneCount(){
  return coreLessonList().filter(l => lessonsDone[l.id] === 1).length;
}

function updateHeader(){
  const totalLessons = coreLessonList().length;
  const doneLessons = coreLessonsDoneCount();
  const totalTerms = (typeof TERMS !== 'undefined' ? TERMS.length : 50) || 50;
  const doneTerms = Object.values(learned).filter(x=>x===1).length;
  const passedTests = Object.entries(phaseTestsDone).filter(([k,v])=>k!=='exam_capstone' && v>=80).length;
  const capstonePassed = (phaseTestsDone['exam_capstone'] || 0) >= 85;

  const pct = Math.round(
    ((doneLessons / totalLessons) * 0.45 +
     (doneTerms / totalTerms) * 0.20 +
     (passedTests / 6) * 0.25 +
     (capstonePassed ? 0.10 : 0)) * 100
  );

  const hb = document.getElementById('hbar');
  const hp = document.getElementById('hpct');
  if(hb) hb.style.width = pct + '%';
  if(hp) hp.textContent = 'Прогресс курса: ' + pct + '%';
}

