/* =========================================================================
   НОВЫЙ ПОЛНОФУНКЦИОНАЛЬНЫЙ РЕНДЕР УРОКОВ (RENDER LESSON DETAIL)
   Полное соответствие реальной структуре LESSONS:
   timeEst, cognitiveLoad, lead, terms, blocks (concept L1-L4, simpleAnalogy,
   ai_agent_task, interactive_widget, recap), top-level quiz & Feynman Check.
   ========================================================================= */

let lessonQuizPassed = {};
let activeLessonLevelTab = {};


function psyTermLabel(raw){
  return String(raw||'').replace(/\s*\([^)]*[A-Za-z][^)]*\)\s*$/,'').trim();
}
function openPsyTermByName(name){
  const pool = [];
  if(typeof LESSONS !== 'undefined') LESSONS.filter(x=>x&&(x.phase===8||x.phase===9)&&x.terms).forEach(l=>l.terms.forEach(t=>{if(t&&typeof t==='object')pool.push({t:t,ph:l.phase});}));
  const q=String(name||'').trim().toLowerCase();
  const hit=pool.find(x=>psyTermLabel(x.t.ru).toLowerCase()===q)||pool.find(x=>psyTermLabel(x.t.ru).toLowerCase().includes(q)||q.includes(psyTermLabel(x.t.ru).toLowerCase()));
  if(!hit)return;
  const t=hit.t, isAcad=(hit.ph===9);
  const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v||'';};
  const setHtml=(id,v)=>{const e=document.getElementById(id);if(e)e.innerHTML=v||'';};
  set('mTerm',psyTermLabel(t.ru));
  setHtml('mCat',isAcad?'<span class="gcat" style="background:#22d3ee22;color:#22d3ee">Академия Freqtrade</span>':'<span class="gcat" style="background:#ec489922;color:#ec4899">Психология</span>');
  set('mDef',t.desc||'');
  set('mAna',isAcad?'Термин словаря Академии Freqtrade: сверь значение со своим уроком, а при расхождении — с официальной документацией docs.freqtrade.io.':'Прочитай пример в уроке и проверь, как это проявлялось в собственных решениях.');
  set('mWhy',isAcad?'Используй термин как рабочий словарь трека: названия команд и флагов сверяй по docs.freqtrade.io — они могут меняться между версиями.':'Используй термин для разбора поведения и процесса, а не как ярлык личности.');
  const orig=t.en&&t.en!=='—'?t.en:(String(t.ru||'').match(/\(([^)]*[A-Za-z][^)]*)\)/)||[])[1]||'';
  const row=document.getElementById('mOrigRow'), oe=document.getElementById('mOrig');
  if(row&&oe){row.style.display=orig?'':'none';oe.textContent=orig;}
  const modal=document.getElementById('termModal'); if(modal)modal.classList.add('open');
}
function renderLessonDetail(l){
  const box = document.getElementById('lessonContentBox');
  if(!box || !l) return;

  const isDone = lessonsDone[l.id] === 1;
  const isQuizPassed = isDone || lessonQuizPassed[l.id] === true;
  const timeText = l.timeEst || (l.minutes ? `${l.minutes} мин` : '5 мин');
  const simLink = (typeof LESSON_SIM_MAP !== 'undefined') ? LESSON_SIM_MAP[l.id] : null;

  // Cognitive load badge
  const cogBadges = {
    easy: '<span class="badge" style="background:rgba(34,197,94,.15); color:var(--ok)">🟢 Базовый</span>',
    medium: '<span class="badge" style="background:rgba(234,179,8,.15); color:var(--warn)">🟡 Средний</span>',
    hard: '<span class="badge" style="background:rgba(239,68,68,.15); color:var(--bad)">🔴 Хард-кор</span>'
  };
  const cogBadge = cogBadges[l.cognitiveLoad] || cogBadges.easy;

  // Hyper-theme
  const hTheme = (typeof window.P1_HYPER_THEMES !== 'undefined' && window.P1_HYPER_THEMES[l.id]) ? window.P1_HYPER_THEMES[l.id] : null;

  let html = (typeof renderPretestBlock === 'function' && !isDone) ? renderPretestBlock(l) : '';

  html += `
    <div class="lesson-header" style="background:var(--card); border:1px solid var(--line); border-radius:14px; padding:20px; margin-bottom:20px; box-shadow:var(--shadow)">
      <div style="display:flex; justify-content:space-between; align-items:flex-start; flex-wrap:wrap; gap:12px; margin-bottom:12px">
        <div>
          <div style="display:flex; align-items:center; gap:8px; margin-bottom:6px; flex-wrap:wrap">
            <span style="font-size:12px; font-weight:800; color:var(--acc2); text-transform:uppercase">Урок ${l.num || l.id} • Фаза ${l.phase}</span>
            <span class="badge-time" style="font-size:11.5px; background:rgba(255,255,255,.06); padding:2px 8px; border-radius:12px; color:var(--txt)">⏱ ${timeText}</span>
            ${cogBadge}
            ${hTheme ? `<span class="badge" style="background:rgba(124,58,237,.15); color:var(--acc1); font-weight:700">🔮 Гипер-тема: ${hTheme}</span>` : ''}
          </div>
          <h2 style="margin:0 0 8px; font-size:22px; color:var(--txt); line-height:1.3">${l.title}</h2>
          ${l.lead ? `<div style="margin:0 0 4px; padding:10px 14px; background:rgba(6,182,212,.08); border-left:3px solid var(--acc2); border-radius:8px; font-size:14px; color:var(--txt); line-height:1.5"><span style="font-size:11px; font-weight:800; color:var(--acc2); text-transform:uppercase">💭 Зацепка урока</span><br>${autoLinkTerms(l.lead)}</div>` : ''}
        </div>
        <div>
          <button class="btn ${isDone ? 'success' : 'primary'}" id="lesson_complete_btn_${l.id}" ${(l.quiz && !isQuizPassed) ? 'disabled style="opacity:0.5; cursor:not-allowed"' : ''} onclick="completeLessonWithMastery('${l.id}')">
            ${isDone ? '✓ Урок пройден' : '🏆 Завершить урок'}
          </button>
        </div>
      </div>

      ${simLink ? `
        <div style="background:rgba(6,182,212,.08); border:1px solid var(--acc2); border-radius:10px; padding:12px 16px; margin-top:14px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px">
          <div style="font-size:13px; color:var(--txt)">
            <b>🕹️ Практический тренажёр:</b> Закрепите тему на живой симуляции «${simLink.title}».
          </div>
          <button class="btn sm" onclick="goToLessonSim('${simLink.simId}')">🚀 Перейти: ${simLink.title} ➔</button>
        </div>
      ` : ''}

      ${l.terms && l.terms.length ? `
        <div style="margin-top:16px; padding-top:14px; border-top:1px solid var(--line)">
          <div style="font-size:11.5px; font-weight:800; color:var(--mut); text-transform:uppercase; margin-bottom:8px">Ключевые термины урока (нажмите для пояснения):</div>
          <div style="display:flex; flex-wrap:wrap; gap:8px">
            ${l.terms.map(t => `<span class="term-tag" onclick="${typeof t === 'string' ? `openTermByName('${t}')` : `openPsyTermByName(${JSON.stringify(t.ru).replace(/&/g,'&amp;').replace(/"/g,'&quot;')})` }" style="cursor:pointer; background:rgba(255,255,255,.05); border:1px solid var(--line); padding:4px 10px; border-radius:8px; font-size:12.5px; color:var(--txt)">${typeof t === 'string' ? t : psyTermLabel(t.ru)}</span>`).join('')}
          </div>
        </div>
      ` : ''}
    </div>
  `;

  // Render Blocks
  if(l.blocks && l.blocks.length){
    l.blocks.forEach(b => {
      // 0.5. Risk-dashboard (V3-B2) — интерактивный виджет в контенте урока
      if(b.type === 'interactive_risk_dash'){
        const rdId = b.id || ('rd_' + l.id);
        html += `
          <div class="lblock" style="background:#040714; border:1px solid var(--acc2); border-radius:12px; padding:16px 18px; margin-bottom:20px">
            <div style="font-size:11.5px; font-weight:800; color:var(--acc2); text-transform:uppercase; margin-bottom:6px">${b.title || '📊 Интерактив: метрики риска'}</div>
            <div style="font-size:12.5px; color:var(--mut); margin-bottom:10px">${b.desc || 'Крути доходность, волатильность, просадку — и смотри, как пересчитываются метрики.'}</div>
            <div id="${rdId}"></div>
          </div>`;
      }
      // 1. Concept block with 4 levels & analogy
      if(b.type === 'psy_deep_dive'){
        html += `
          <div class="lblock" style="background:linear-gradient(135deg,rgba(124,58,237,.09),rgba(6,182,212,.06));border:1.5px solid rgba(124,58,237,.45);border-radius:14px;padding:20px;margin-bottom:20px;box-shadow:var(--shadow)">
            <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:14px">
              <div style="font-size:12px;font-weight:800;color:var(--acc1);text-transform:uppercase">🧠 Глубокий разбор</div>
              <div style="font-size:12px;color:var(--mut)">Основа: ${b.source||'материалы блока'}</div>
            </div>
            <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px">
              ${[['Что нужно понять','var(--acc2)','understand'],['Как возникает ошибка','var(--acc1)','mechanism'],['Граница применения','var(--warn)','boundary'],['Операционный протокол','var(--ok)','protocol']].map(x=>`<div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px"><div style="font-size:11px;font-weight:800;color:${x[1]};text-transform:uppercase;margin-bottom:6px">${x[0]}</div><div style="font-size:14px;color:var(--txt);line-height:1.65">${autoLinkTerms(b[x[2]]||'')}</div></div>`).join('')}
            </div>
            <div style="margin-top:12px;background:rgba(34,197,94,.08);border-left:4px solid var(--ok);border-radius:8px;padding:13px 15px">
              <div style="font-size:11px;font-weight:800;color:var(--ok);text-transform:uppercase;margin-bottom:5px">Перенос в собственную торговлю</div>
              <div style="font-size:14px;color:var(--txt);line-height:1.65">${autoLinkTerms(b.transfer||'')}</div>
            </div>
          </div>`;
      }
      else if(b.type === 'source_check'){
        html += `
          <div class="lblock" style="background:rgba(245,158,11,.07);border:1.5px solid rgba(245,158,11,.4);border-radius:14px;padding:18px;margin-bottom:20px">
            <div style="font-size:11.5px;font-weight:800;color:var(--warn);text-transform:uppercase;margin-bottom:8px">${b.title||'🔎 Проверка источника'}</div>
            <div style="font-size:13.8px;color:var(--txt);line-height:1.65;margin-bottom:10px">${autoLinkTerms(b.text||'')}</div>
            <div style="font-size:13px;color:var(--mut);border-top:1px dashed var(--line);padding-top:10px"><b style="color:var(--txt)">Вопрос к себе:</b> ${autoLinkTerms(b.question||'')}</div>
          </div>`;
      }
      else if(b.type === 'psy_decision_drill'){
        const did = 'psy_drill_' + l.id;
        html += `
          <div class="lblock" id="${did}" style="background:var(--card);border:1.5px solid var(--ok);border-radius:14px;padding:20px;margin-bottom:20px;box-shadow:var(--shadow)">
            <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap"><span class="badge" style="background:rgba(34,197,94,.18);color:var(--ok);font-weight:800">🎯 РЕШЕНИЕ В СИТУАЦИИ</span><h3 style="margin:0;font-size:17px;color:var(--txt)">Прими решение, а затем разберись почему</h3></div>
            <div style="font-size:14px;color:var(--txt);line-height:1.65;background:rgba(6,182,212,.07);border-left:3px solid var(--acc2);border-radius:8px;padding:13px 15px;margin-bottom:14px">${autoLinkTerms(b.scenario||'')}</div>
            <div style="display:flex;flex-direction:column;gap:8px">${(b.opts||[]).map((o,i)=>`<button class="ans" data-psy-drill="${did}" data-i="${i}" style="text-align:left;padding:12px 14px;font-size:13.5px">${o}</button>`).join('')}</div>
            <div style="margin-top:10px"><button class="btn sm ghost" data-psy-hint="${did}" style="font-size:12px">💡 Подсказка</button></div>
            <div id="${did}_hint" style="display:none;margin-top:8px"></div>
            <div id="${did}_fb" style="display:none;margin-top:12px"></div>
          </div>`;
        setTimeout(()=>{const root=document.getElementById(did);if(!root)return;root.querySelectorAll('[data-psy-drill]').forEach(btn=>btn.addEventListener('click',function(){if(root.dataset.done)return;root.dataset.done='1';const chosen=Number(this.dataset.i),ok=chosen===Number(b.a);if(!ok&&window.PSY_RAG_UI){try{window.PSY_RAG_UI.recordDrillError(l.id)}catch(e){}}root.querySelectorAll('[data-psy-drill]').forEach(x=>x.disabled=true);this.classList.add(ok?'ok':'bad');const fb=document.getElementById(did+'_fb');if(fb){fb.style.display='block';fb.innerHTML='<div style="background:'+(ok?'rgba(34,197,94,.1)':'rgba(239,68,68,.1)')+';border-left:4px solid '+(ok?'var(--ok)':'var(--bad)')+';padding:12px 14px;border-radius:8px;font-size:13.5px;color:var(--txt);line-height:1.6"><b>Разбор: </b><span></span></div>';const sp=fb.querySelector('span');if(sp)sp.textContent=(ok?'Верное решение. ':'Проверь решение. Правильная логика: ')+String(b.explain||'');}}));root.querySelectorAll('[data-psy-hint]').forEach(hb=>hb.addEventListener('click',function(){if(root.dataset.done)return;if(window.PSY_RAG_UI){try{window.PSY_RAG_UI.drillHint(l.id,did,(b.scenario||'')+' '+(b.opts||[]).join(' | '))}catch(e){}}}));},0);
      }
      else       if(b.type === 'microRecall'){
        const mrId = l.id + '_mr_' + (window._mrSeq = (window._mrSeq || 0) + 1);
        const mrS = (typeof shuffledOptions === 'function' && b.opts && b.opts.length > 1) ? shuffledOptions({ q: String(b.q || ''), opts: b.opts, a: (b.a !== undefined ? b.a : 0) }, 9) : { opts: b.opts, a: b.a };
        html += `
          <div class="lblock microrecall" style="background:#090d1f; border:1.5px dashed var(--acc2); border-radius:12px; padding:14px 18px; margin-bottom:20px">
            <div style="font-size:11px; font-weight:800; color:var(--acc2); text-transform:uppercase; margin-bottom:6px">🧠 Микро-проверка извлечения (без штрафа и статистики)</div>
            <div style="font-size:13.5px; color:var(--txt); margin-bottom:10px; line-height:1.5">${b.q}</div>
            <div style="display:flex; flex-direction:column; gap:6px">
              ${(mrS.opts || []).map((o, oi) => `<button class="ans sm" style="text-align:left; font-size:12.5px; padding:8px 10px" onclick="window.handleMicroRecall(this, '${mrId}', ${oi}, ${mrS.a})">${o}</button>`).join('')}
            </div>
            <div id="${mrId}" style="display:none; margin-top:8px; font-size:12.5px"></div>
          </div>`;
      }
      else if(b.type === 'concept'){
        const curTab = activeLessonLevelTab[l.id] || 'l1'; /* №2/A9: читаем тот же стейт, куда пишет setLessonLevelTab — переменная lessonLevelTabs никогда не существовала, селект уровней не переживал перерисовку */
        html += `
          <div class="lblock concept" style="background:var(--card); border:1px solid var(--line); border-radius:14px; padding:20px; margin-bottom:20px; box-shadow:var(--shadow)">
            
            ${b.level1 ? `
              <div style="margin-bottom:16px">
                <div style="font-size:11.5px; font-weight:800; color:var(--ok); text-transform:uppercase; margin-bottom:6px">Объяснение на пальцах (Level 1):</div>
                <div style="font-size:15px; color:var(--txt); line-height:1.6">${autoLinkTerms(b.level1)}</div>
              </div>
            ` : ''}

            ${b.simpleAnalogy ? `
              <div style="background:rgba(6,182,212,.08); border-left:4px solid var(--acc2); border-radius:8px; padding:14px 16px; margin:16px 0; font-size:14px; color:var(--txt); line-height:1.55">
                <b style="color:var(--acc2)">💡 Бытовая аналогия:</b><br>
                ${autoLinkTerms(b.simpleAnalogy)}
              </div>
            ` : ''}

            ${(b.level2 || b.level3 || b.level4) ? `
              <div style="margin-top:16px; padding-top:14px; border-top:1px solid var(--line)">
                <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; flex-wrap:wrap; gap:8px">
                  <div style="font-size:11.5px; font-weight:800; color:var(--mut); text-transform:uppercase">Уровни погружения для архитектора:</div>
                  <div class="controls" style="display:flex; gap:6px; flex-wrap:wrap">
                    ${b.level2 ? `<button class="btn sm ${curTab==='l2'?'':'ghost'}" onclick="setLessonLevelTab('${l.id}', 'l2')">⚙️ Уровень 2: Детали и цифры</button>` : ''}
                    ${b.level3 ? `<button class="btn sm ${curTab==='l3'?'':'ghost'}" onclick="setLessonLevelTab('${l.id}', 'l3')">🔬 Уровень 3: Под капотом</button>` : ''}
                    ${b.level4 ? `<button class="btn sm ${curTab==='l4'?'':'ghost'}" onclick="setLessonLevelTab('${l.id}', 'l4')">💻 Уровень 4: Код и формулы</button>` : ''}
                    ${curTab !== 'l1' ? `<button class="btn sm ghost" style="color:var(--mut)" onclick="setLessonLevelTab('${l.id}', 'l1')">✕ Скрыть детали</button>` : ''}
                  </div>
                </div>

                ${curTab === 'l2' && b.level2 ? `
                  <div style="background:#040714; border:1px solid rgba(255,255,255,.08); border-radius:10px; padding:16px; font-size:13.5px; color:var(--txt); line-height:1.6">
                    <b style="color:var(--acc2)">Практические подробности (Level 2):</b><br>
                    ${autoLinkTerms(b.level2)}
                  </div>
                ` : ''}

                ${curTab === 'l3' && b.level3 ? `
                  <div style="background:#040714; border:1px solid rgba(255,255,255,.08); border-radius:10px; padding:16px; font-size:13.5px; color:var(--txt); line-height:1.6">
                    <b style="color:var(--acc1)">Математическое и ончейн-устройство (Level 3):</b><br>
                    ${autoLinkTerms(b.level3)}
                  </div>
                ` : ''}

                ${curTab === 'l4' && b.level4 ? `
                  <div style="background:#040714; border:1px solid rgba(255,255,255,.08); border-radius:10px; padding:16px">
                    <div style="font-size:11.5px; font-weight:800; color:var(--warn); text-transform:uppercase; margin-bottom:8px">Код и алгоритмическая логика (Level 4):</div>
                    <pre style="margin:0; font-family:var(--mono); font-size:12.5px; color:#38bdf8; overflow-x:auto; background:rgba(0,0,0,.5); padding:12px; border-radius:6px"><code>${b.level4}</code></pre>
                  </div>
                ` : ''}
              </div>
            ` : ''}
          </div>
        `;
      }

      // 2. Simple block
      else if(b.type === 'simple'){
        html += `
          <div class="lblock" style="background:var(--card); border:1px solid var(--line); border-radius:14px; padding:18px 20px; margin-bottom:16px">
            <div style="font-size:15px; color:var(--txt); line-height:1.65">${autoLinkTerms(b.text || '')}</div>
          </div>
        `;
      }

      // 3. Analogy block
      else if(b.type === 'analogy'){
        html += `
          <div class="lblock" style="background:rgba(6,182,212,.08); border-left:4px solid var(--acc2); border-radius:10px; padding:14px 18px; margin-bottom:16px; font-size:14px; color:var(--txt); line-height:1.6">
            <b style="color:var(--acc2)">💡 Бытовая аналогия:</b><br>
            ${autoLinkTerms(b.text || '')}
          </div>
        `;
      }

      // 4. Numbers / Calculations block
      else if(b.type === 'numbers'){
        html += `
          <div class="lblock" style="background:rgba(124,58,237,.06); border-left:4px solid var(--acc1); border-radius:10px; padding:14px 18px; margin-bottom:16px; font-size:14px; color:var(--txt); line-height:1.6">
            <b style="color:var(--acc1)">🔢 Расчёты и конкретные цифры:</b><br>
            ${autoLinkTerms(b.text || '')}
          </div>
        `;
      }

      // 5. Warn / Mistake block
      else if(b.type === 'warn'){
        html += `
          <div class="lblock" style="background:rgba(239,68,68,.08); border-left:4px solid var(--bad); border-radius:10px; padding:14px 18px; margin-bottom:16px; font-size:14px; color:var(--txt); line-height:1.6">
            <b style="color:var(--bad)">⚠️ Частая ошибка новичка:</b><br>
            ${autoLinkTerms(b.text || '')}
          </div>
        `;
      }

      // 6. Insight block
      else if(b.type === 'insight'){
        html += `
          <div class="lblock" style="background:rgba(34,197,94,.08); border-left:4px solid var(--ok); border-radius:10px; padding:14px 18px; margin-bottom:16px; font-size:14px; color:var(--txt); line-height:1.6">
            <b style="color:var(--ok)">🎯 Квант-инсайт:</b><br>
            ${autoLinkTerms(b.text || '')}
          </div>
        `;
      }

      // 6b. Image / инфографика (GPT Image, папка assets/)
      else if(b.type === 'image'){
        html += `
          <figure style="margin:0 0 20px; background:#040714; border:1px solid var(--line); border-radius:12px; overflow:hidden">
            <img src="${b.src}" alt="${(b.alt || '').replace(/"/g, '&quot;')}" loading="lazy" style="width:100%; display:block" onerror="this.parentElement.innerHTML='<div style=&quot;padding:16px;color:var(--mut);font-size:12.5px&quot;>🖼️ Инфографика «${(b.alt || '').replace(/"/g, '&quot;')}» ещё не добавлена: положи файл в ${b.src}</div>'">
            ${b.caption ? `<figcaption style="padding:10px 14px; font-size:12px; color:var(--mut)">${b.caption}</figcaption>` : ''}
          </figure>
        `;
      }

      // 7. Table block
      else if(b.type === 'table'){
        html += `
          <div class="lblock" style="background:var(--card); border:1px solid var(--line); border-radius:12px; padding:16px; margin-bottom:16px; overflow-x:auto">
            ${b.title ? `<div style="font-size:11.5px; font-weight:800; color:var(--acc2); text-transform:uppercase; margin-bottom:10px">${b.title}</div>` : ''}
            <table style="width:100%; border-collapse:collapse; font-size:13px">
              <thead><tr style="background:rgba(255,255,255,.04)">
                ${(b.head || []).map(h => `<th style="padding:10px 12px; text-align:left; color:var(--acc2); border-bottom:1.5px solid var(--line)">${h}</th>`).join('')}
              </tr></thead>
              <tbody>
                ${(b.rows || []).map(r => `<tr>${r.map((c, ci) => `<td style="padding:10px 12px; border-bottom:1px solid var(--line); color:${ci===0?'var(--txt)':'var(--mut)'}; font-weight:${ci===0?'700':'400'}">${c}</td>`).join('')}</tr>`).join('')}
              </tbody>
            </table>
          </div>
        `;
      }

      // 8. List / Steps block
      else if(b.type === 'list' || b.type === 'steps'){
        html += `
          <div class="lblock" style="background:var(--card); border:1px solid var(--line); border-radius:12px; padding:16px 18px; margin-bottom:16px">
            ${b.title ? `<div style="font-size:11.5px; font-weight:800; color:var(--acc2); text-transform:uppercase; margin-bottom:8px">${b.title}</div>` : ''}
            <ul style="margin:0; padding-left:20px; font-size:13.5px; color:var(--txt); line-height:1.7">
              ${(b.items || []).map(it => `<li>${autoLinkTerms(typeof it === 'string' ? it : (it.text || ''))}</li>`).join('')}
            </ul>
          </div>
        `;
      }

      // 9. AI Agent Task Block
      else if(b.type === 'ai_agent_task'){
        html += `
          <div class="lblock ai-task" style="background:linear-gradient(135deg,rgba(124,58,237,.08),rgba(6,182,212,.04)); border:1.5px solid var(--acc1); border-radius:14px; padding:18px 20px; margin-bottom:20px; box-shadow:var(--shadow)">
            <div style="display:flex; align-items:center; gap:8px; margin-bottom:8px">
              <span style="font-size:18px">🤖</span>
              <h3 style="margin:0; font-size:16px; color:var(--txt)">${b.title || 'Задача для ИИ-агента'}</h3>
            </div>
            <div style="background:#040714; border-radius:8px; padding:12px 14px; margin-bottom:10px">
              <div style="font-size:11px; font-weight:800; color:var(--mut); text-transform:uppercase; margin-bottom:4px">Техническое задание:</div>
              <div style="font-size:13px; color:var(--txt); line-height:1.5"><code>${b.spec}</code></div>
            </div>
            <div style="font-size:12.5px; color:var(--acc2); line-height:1.4">
              <b>✓ Критерии приёмки:</b> ${b.acceptanceCriteria}
            </div>
          </div>
        `;
      }

      // 10. Interactive Widget Block
      else if(typeof b.type === 'string' && b.type !== 'interactive_risk_dash' && b.type.startsWith('interactive')){ /* №1/A4: dash уже отрисован своей веткой выше — общий рендер его пропускал, оставляя пустой дубль-контейнер */
        html += `
          <div class="lblock widget-block" style="background:var(--card); border:1.5px solid var(--ok); border-radius:14px; padding:20px; margin-bottom:20px; box-shadow:var(--shadow)">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; flex-wrap:wrap; gap:8px">
              <div style="display:flex; align-items:center; gap:8px">
                <span class="badge" style="background:rgba(34,197,94,.2); color:var(--ok); font-weight:800">🕹️ ПРАКТИКА</span>
                <h3 style="margin:0; font-size:17px; color:var(--txt)">${b.title}</h3>
              </div>
            </div>
            <p style="color:var(--mut); font-size:13.5px; margin:0 0 14px; line-height:1.4">${b.desc}</p>
            <div id="${b.id}"></div>
          </div>
        `;
      }

      // 10.5 Image Block (инфографика D4.3)
      else if(b.type === 'image'){
        const imgSrc = b.src || '';
        const imgCap = b.caption || '';
        const imgAlt = b.alt || imgCap || 'Инфографика урока';
        html += `
          <figure class="lblock image" style="background:#040714; border:1px solid var(--line); border-radius:14px; padding:16px 18px; margin:0 0 20px">
            <img src="${imgSrc}" alt="${imgAlt}" loading="lazy"
                 style="width:100%; border-radius:10px; display:block"
                 onerror="this.style.display='none'; this.nextElementSibling.style.display='flex'">
            <div style="display:none; min-height:140px; align-items:center; justify-content:center; text-align:center; border:1.5px dashed var(--line); border-radius:10px; padding:20px; color:var(--mut); font-size:12.5px; line-height:1.6">
              🖼️ Инфографика «${imgCap}» появится здесь после генерации<br>(файл ${imgSrc} — см. assets/infographics/README.md)
            </div>
            ${imgCap ? `<figcaption style="margin-top:10px; font-size:12px; color:var(--mut); text-align:center">${imgCap}</figcaption>` : ''}
          </figure>
        `;
      }

      // 11. Recap Block
      else if(b.type === 'recap'){
        html += `
          <div class="lblock recap" style="background:#040714; border:1px solid var(--line); border-radius:14px; padding:18px 20px; margin-bottom:20px">
            <div style="font-size:12px; font-weight:800; color:var(--acc2); text-transform:uppercase; margin-bottom:10px">
              📌 Главные выводы урока:
            </div>
            <ul style="margin:0 0 14px; padding-left:20px; font-size:13.5px; color:var(--txt); line-height:1.6">
              ${b.points.map(pt => `<li>${autoLinkTerms(pt)}</li>`).join('')}
            </ul>
            ${b.english && b.english.length ? `
              <div style="border-top:1px dashed var(--line); padding-top:10px; font-size:12px; color:var(--mut)">
                <b>🇬🇧 Английская терминология:</b> ${b.english.map(e => `<span style="color:var(--txt); margin-left:6px">${e.ru} ➔ <code style="color:var(--acc2)">${e.en}</code></span>`).join(' | ')}
              </div>
            ` : ''}
          </div>
        `;
      }
    });
  }

  // v11.1: Полноценная лаборатория с командой, ожидаемым результатом, ошибками и критерием зачёта
  if(l.lab){
    const safe = x => String(x ?? '').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    html += `
      <section class="v11-lab-card" aria-label="Лаборатория урока">
        <div class="v11-lab-card-head">
          <div><span class="v11-badge">🧪 ЛАБОРАТОРИЯ</span> <b>${safe(l.lab.title)}</b></div>
          <span class="v11-lab-gate">Обязательный практический зачёт</span>
        </div>
        <div class="v11-lab-grid">
          <div class="v11-lab-col">
            <div class="v11-lab-label">1. Что сделать</div>
            <div class="v11-lab-text">${autoLinkTerms(l.lab.action)}</div>
          </div>
          <div class="v11-lab-col">
            <div class="v11-lab-label">2. Команды</div>
            <div class="v11-command-list">${(l.lab.commands||[]).map(c=>`<pre><code>${safe(c)}</code></pre>`).join('')}</div>
          </div>
          <div class="v11-lab-col">
            <div class="v11-lab-label">3. Ожидаемый результат</div>
            <div class="v11-lab-text">${autoLinkTerms(l.lab.expected)}</div>
          </div>
          <div class="v11-lab-col">
            <div class="v11-lab-label">4. Проверка типовых ошибок</div>
            <div class="v11-lab-text">${autoLinkTerms(l.lab.errors)}</div>
          </div>
        </div>
        <div class="v11-lab-accept"><b>✓ Критерий зачёта:</b> ${autoLinkTerms(l.lab.acceptance)}</div>
        <div class="v11-lab-bridge"><b>🔗 Связь с исследовательским стеком:</b> ${autoLinkTerms(l.lab.bridge)}</div>
      </section>`;
  }

  // Practice & Checks & Resources
  if(l.practice && l.practice.length){
    html += `
      <div class="lblock" style="background:linear-gradient(135deg,rgba(124,58,237,.08),rgba(6,182,212,.04)); border:1.5px solid var(--acc1); border-radius:14px; padding:18px 20px; margin-bottom:20px">
        <div style="font-size:12px; font-weight:800; color:var(--acc1); text-transform:uppercase; margin-bottom:10px">🤖 Практика с ИИ-агентом</div>
        ${l.practice.map(pr => `
          <div style="background:#040714; border-radius:8px; padding:12px 14px; margin-bottom:10px">
            <div style="font-size:13.5px; color:var(--txt); line-height:1.55">${autoLinkTerms(pr.text)}</div>
            ${pr.criteria ? `<div style="margin-top:8px; font-size:12.5px; color:var(--acc2)"><b>✓ Критерии приёмки:</b> ${autoLinkTermsSoft(pr.criteria)}</div>` : ''}
          </div>
        `).join('')}
      </div>
    `;
  }
  if(l.checks && l.checks.length){
    html += `
      <div class="lblock" style="background:var(--card); border:1px solid var(--line); border-left:3.5px solid var(--ok); border-radius:12px; padding:16px 18px; margin-bottom:20px">
        <div style="font-size:11.5px; font-weight:800; color:var(--ok); text-transform:uppercase; margin-bottom:8px">✓ Чек-лист самопроверки</div>
        <ul style="margin:0; padding-left:20px; font-size:13.5px; color:var(--txt); line-height:1.7">
          ${l.checks.map(c => `<li>${autoLinkTerms(c)}</li>`).join('')}
        </ul>
      </div>
    `;
  }
  if(l.resources && l.resources.length){
    html += `
      <div class="lblock" style="background:#040714; border:1px solid var(--line); border-radius:12px; padding:14px 18px; margin-bottom:20px">
        <div style="font-size:11.5px; font-weight:800; color:var(--mut); text-transform:uppercase; margin-bottom:8px">📚 Что читать дальше</div>
        <ul style="margin:0; padding-left:20px; font-size:13px; color:var(--mut); line-height:1.7">
          ${l.resources.map(r => `<li><b style="color:var(--txt)">${r.t}</b>${r.note ? ' — ' + r.note : ''}</li>`).join('')}
        </ul>
      </div>
    `;
  }

  // 📰 Исторический реальный кейс
  if(l.case){
    html += `
      <div style="background:rgba(234,179,8,.06); border-left:4px solid var(--warn); border-radius:10px; padding:16px 18px; margin:20px 0; font-size:14.5px; line-height:1.6; box-shadow:var(--shadow)">
        <div style="font-weight:800; color:var(--warn); margin-bottom:6px; font-size:13px; text-transform:uppercase; display:flex; align-items:center; gap:6px">
          <span>📰</span> ${l.case.title}
        </div>
        <div style="color:var(--txt)">${l.case.text}</div>
      </div>
    `;
  }

  // Feynman Method Self-Check
  if(typeof renderFeynmanBox === 'function'){
    html += renderFeynmanBox(l);
  }

  // Mandatory Lesson Comprehension Quiz
  if(l.quiz){
    // D0.1: перемешиваем варианты при каждом открытии урока
    const _lqv = shuffledOptions(l.quiz, nextShuffleSalt() * 7 + 1);
    const qData = Object.assign({}, l.quiz, { opts: _lqv.opts, explain: _lqv.explain });
    const correctIdx = _lqv.a;
    html += `
      <div id="lesson_quiz_container_${l.id}" class="panel" style="background:#090d1f; border:2px solid var(--acc1); border-radius:14px; padding:20px; margin:24px 0">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; flex-wrap:wrap; gap:8px">
          <span style="font-size:12px; font-weight:800; color:var(--acc1); text-transform:uppercase">🎯 Проверка понимания (обязательный квиз)</span>
          <span id="quiz_badge_${l.id}" class="badge" style="background:${isQuizPassed?'rgba(34,197,94,.2)':'rgba(234,179,8,.2)'}; color:${isQuizPassed?'var(--ok)':'var(--warn)'}">
            ${isQuizPassed ? '✓ Пройден успешно' : 'Требуется для завершения урока'}
          </span>
        </div>
        <h4 style="margin:0 0 14px; font-size:16px; color:var(--txt); line-height:1.4">${autoLinkTermsSoft(qData.q)}</h4>
        <div id="lquiz_opts_${l.id}" style="display:flex; flex-direction:column; gap:10px">
          ${qData.opts.map((opt, oIdx) => `
            <button class="ans ${isDone && oIdx===correctIdx ? 'correct' : ''}" onclick="handleLessonQuizAnswer('${l.id}', ${oIdx}, ${correctIdx})" style="text-align:left; padding:12px 16px; font-size:13.5px; border-radius:8px; border:1px solid var(--line); background:#040714; color:var(--txt); cursor:pointer">
              ${autoLinkTermsSoft(opt)}
            </button>
          `).join('')}
        </div>
        <div id="lquiz_fb_${l.id}" style="${isDone?'':'display:none;'} margin-top:14px; padding:12px 16px; border-radius:8px; font-size:13.5px; background:rgba(34,197,94,.12); border:1px solid var(--ok); color:var(--txt)">
          <b>Объяснение:</b> ${autoLinkTermsSoft(qData.explain || 'Верный ответ! Вы отлично усвоили ключевой концепт этого урока.')}
        </div>
      </div>
    `;
  }

  // V3-A1: числовая задача с открытым вводом (Active Recall 2.0 — конструирование вместо узнавания)
  if(l.numericQuiz){
    const nq = l.numericQuiz;
    html += `
      <div class="panel" style="background:#090d1f; border:2px solid var(--acc2); border-radius:14px; padding:20px; margin:24px 0">
        <div style="font-size:12px; font-weight:800; color:var(--acc2); text-transform:uppercase; margin-bottom:10px">🧮 Задача с открытым ответом (без вариантов — посчитай сам)</div>
        <div style="font-size:14.5px; color:var(--txt); line-height:1.55; margin-bottom:12px">${nq.q}</div>
        <div style="display:flex; gap:10px; align-items:center; flex-wrap:wrap">
          <input id="lnum_in_${l.id}" type="text" inputmode="decimal" placeholder="твой ответ" style="width:160px; background:#040714; border:1px solid var(--acc2); border-radius:8px; padding:10px 12px; color:var(--txt); font-size:15px; font-weight:700">
          <span style="color:var(--mut); font-size:14px">${nq.unit || ''}</span>
          <button class="btn sm" onclick="handleLessonNumeric('${l.id}')">Проверить</button>
          <span style="font-size:11.5px; color:var(--mut)">допуск: ${nq.absTol !== undefined ? '±' + nq.absTol + ' ' + (nq.unit || '') : '±' + (nq.tolPct || 2) + '%'}</span>
        </div>
        <div id="lnum_fb_${l.id}" style="display:none; margin-top:12px; padding:12px 14px; border-radius:8px; font-size:13.5px; line-height:1.55"></div>
      </div>`;
  }

  // Bottom Navigation Bar
  html += `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-top:28px; padding-top:20px; border-top:1px solid var(--line); flex-wrap:wrap; gap:12px">
      <button class="btn ghost" onclick="navLesson(-1)">← Предыдущий урок</button>
      <button id="lesson_bottom_complete_btn_${l.id}" class="btn ${isDone?'success':'primary'}" ${(l.quiz && !isQuizPassed) ? 'disabled style="opacity:0.5; cursor:not-allowed"' : ''} onclick="completeLessonWithMastery('${l.id}')">
        ${isDone ? '✓ Урок пройден' : '🏆 Завершить урок (зачёт темы)'}
      </button>
      <button class="btn" onclick="navLesson(1)">Следующий урок →</button>
    </div>
  `;

  box.innerHTML = html;

  // Auto-render interactive widgets inside the lesson
  if(l.blocks && l.blocks.length){
    l.blocks.forEach(b => {
      if(typeof b.type === 'string' && b.type.startsWith('interactive') && typeof renderPhase0Widget === 'function'){
        setTimeout(() => {
          if(b.type === 'interactive_risk_dash'){ mountRiskDashboard(b.id, b.cfg || {}); return; }
          renderPhase0Widget(b.id);
        }, 20);
      }
    });
  }
}


// V3-A1: проверка числового ответа с допуском и эталонным решением
window.handleLessonNumeric = function(lessonId){
  const l = LESSONS.find(x => x.id === lessonId);
  if(!l || !l.numericQuiz) return;
  const nq = l.numericQuiz;
  const inp = document.getElementById('lnum_in_' + lessonId);
  const fb = document.getElementById('lnum_fb_' + lessonId);
  if(!inp || !fb) return;
  const val = parseFloat(String(inp.value).replace(/\s/g, '').replace(',', '.'));
  fb.style.display = 'block';
  if(isNaN(val)){
    fb.style.background = 'rgba(234,179,8,.12)'; fb.style.border = '1px solid var(--warn)';
    fb.innerHTML = '<b>Введи число</b> — например, ' + nq.answer + '.';
    return;
  }
  const tol = nq.absTol !== undefined ? nq.absTol : Math.abs(nq.answer) * (nq.tolPct || 2) / 100;
  if(Math.abs(val - nq.answer) <= tol){
    inp.disabled = true;
    fb.style.background = 'rgba(34,197,94,.12)'; fb.style.border = '1px solid var(--ok)';
    fb.innerHTML = '<b>✅ Верно (' + val + (nq.unit ? ' ' + nq.unit : '') + ').</b><br>📐 Эталонное решение: ' + nq.solution;
    if(!(lessonCheckState[lessonId] && lessonCheckState[lessonId].nqDone)){
      addFundCapital(8000, 30, 'Решена числовая задача без вариантов');
      lessonCheckState[lessonId] = Object.assign({}, lessonCheckState[lessonId], { nqDone: true });
      if(typeof save === 'function') save();
    } else {
      fb.innerHTML += '<div style="margin-top:6px;font-size:12.5px;color:var(--mut)">💰 Капитал за эту задачу уже начислен ранее — повторно не начисляем.</div>';
    } /* №6: nqDone в существующем cn_lesson_checks — капитал за numericQuiz начисляется один раз на профиль */
  } else {
    fb.style.background = 'rgba(239,68,68,.12)'; fb.style.border = '1px solid var(--bad)';
    fb.innerHTML = '<b>❌ Не сходится (' + val + ').</b> Пересчитай шаг за шагом — и после второй попытки сверься с эталоном.<br><button class="btn sm ghost" style="margin-top:8px" onclick="document.getElementById(\'lnum_fb_' + lessonId + '\').innerHTML += \'<div style=\\\'margin-top:8px;border-top:1px dashed var(--line);padding-top:8px\\\'>📐 <b>Эталон:</b> ' + nq.solution.replace(/'/g, '’') + '</div>\'">Показать эталонное решение</button>' +
      (typeof window.offerMistakeClassification === 'function' ? window.offerMistakeClassification('numeric:' + lessonId) : '');
  }
};

function setLessonLevelTab(lessonId, tabName){
  activeLessonLevelTab[lessonId] = tabName;
  const l = LESSONS.find(x => x.id === lessonId);
  if(l) renderLessonDetail(l);
}

window.handleMicroRecall = function(btn, mrId, chosen, correct){
  const fb = document.getElementById(mrId);
  if(!fb) return;
  btn.parentElement.querySelectorAll('button').forEach((b, oi) => {
    b.disabled = true;
    if(oi === correct) b.classList.add('ok'); else if(b === btn) b.classList.add('bad');
  });
  fb.style.display = 'block';
  fb.innerHTML = (chosen === correct)
    ? '<span style="color:var(--ok)">✅ Верно — продолжай.</span>'
    : '<span style="color:var(--bad)">Не совсем.</span> Микро-recall не влияет на статистику — уточни мысленно и читай дальше.';
};

function handleLessonQuizAnswer(lessonId, selectedIdx, correctIdx){
  const l = LESSONS.find(x => x.id === lessonId);
  const optsContainer = document.getElementById(`lquiz_opts_${lessonId}`);
  const fb = document.getElementById(`lquiz_fb_${lessonId}`);
  const statusBadge = document.getElementById(`quiz_badge_${lessonId}`);
  const completeBtnTop = document.getElementById(`lesson_complete_btn_${lessonId}`);
  const completeBtnBottom = document.getElementById(`lesson_bottom_complete_btn_${lessonId}`);

  if(!optsContainer || !l) return;

  const buttons = optsContainer.querySelectorAll('button');
  buttons.forEach((btn, idx) => {
    btn.classList.remove('correct', 'wrong');
    if(idx === selectedIdx){
      if(idx === correctIdx){
        btn.classList.add('correct');
        btn.style.borderColor = 'var(--ok)';
        btn.style.background = 'rgba(34,197,94,.15)';
      } else {
        btn.classList.add('wrong');
        btn.style.borderColor = 'var(--bad)';
        btn.style.background = 'rgba(239,68,68,.15)';
      }
    }
  });

  if(selectedIdx === correctIdx){
    lessonQuizPassed[lessonId] = true;
    // Персистентность: сданный проверочный вопрос переживает перезагрузку страницы
    lessonCheckState[lessonId] = Object.assign({}, lessonCheckState[lessonId], { quizDone: true });
    if(typeof save === 'function') save();
    if(fb){
      fb.style.display = 'block';
      fb.style.background = 'rgba(34,197,94,.12)';
      fb.style.borderColor = 'var(--ok)';
      fb.innerHTML = `<b>Верно! 🎯</b> ${l.quiz.explain || 'Отличный ответ! Теперь урок можно отметить завершённым.'}`;
    }
    if(statusBadge){
      statusBadge.style.background = 'rgba(34,197,94,.2)';
      statusBadge.style.color = 'var(--ok)';
      statusBadge.innerHTML = '✓ Вопрос сдан';
    }
    [completeBtnTop, completeBtnBottom].forEach(btn => {
      if(btn){
        btn.disabled = false;
        btn.style.opacity = '1';
        btn.style.cursor = 'pointer';
      }
    });
    showToast('Тест пройден! Кнопка завершения урока разблокирована.', '🎯');
  } else {
    if(fb){
      fb.style.display = 'block';
      fb.style.background = 'rgba(239,68,68,.12)';
      fb.style.borderColor = 'var(--bad)';
      fb.innerHTML = `<b>Пока неверно.</b> Попробуйте перечитать основную суть урока и выбрать другой вариант.`;
    }
  }
}

function checkLessonMasteryQuiz(lessonId, blockIdx, optIdx){
  const lesson = LESSONS.find(l=>l.id===lessonId);
  if(!lesson) return;
  const block = lesson.blocks[blockIdx];
  if(!block) return;

  const container = document.getElementById(`lquiz_${lessonId}_${blockIdx}`);
  const expBox = document.getElementById(`lquiz_exp_${lessonId}_${blockIdx}`);
  if(!container) return;

  const buttons = container.querySelectorAll('.ans');
  buttons.forEach((btn, i)=>{
    btn.disabled = true;
    if(i === block.a) btn.classList.add('ok');
    else if(i === optIdx && i !== block.a) btn.classList.add('bad');
  });

  const isCorrect = (optIdx === block.a);
  if(!lessonCheckState[lessonId]) lessonCheckState[lessonId] = {};
  lessonCheckState[lessonId].quizDone = isCorrect;

  if(expBox){
    expBox.style.display = 'block';
    if(isCorrect){
      expBox.style.background = 'rgba(34,197,94,.15)';
      expBox.style.border = '1px solid var(--ok)';
      expBox.innerHTML = `<b>Верно! 🎯</b> ${block.explain && block.explain[optIdx] ? block.explain[optIdx] : ''}`;
    } else {
      expBox.style.background = 'rgba(239,68,68,.15)';
      expBox.style.border = '1px solid var(--bad)';
      expBox.innerHTML = `<b>Ошибка! ❌</b> ${block.explain && block.explain[optIdx] ? block.explain[optIdx] : ''} <br><span style="font-size:12px; color:var(--mut)">Повторите материал блока и перезагрузите урок для повторной проверки.</span>`;
    }
  }

  updateLessonCompleteBtn(lessonId);
}

function togglePromptConfirmation(lessonId, isChecked){
  if(!lessonCheckState[lessonId]) lessonCheckState[lessonId] = {};
  lessonCheckState[lessonId].promptConfirmed = isChecked;
  updateLessonCompleteBtn(lessonId);
}

function updateLessonCompleteBtn(lessonId){
  const state = lessonCheckState[lessonId] || {};
  const lesson = LESSONS.find(x => x.id === lessonId);
  const hasMasteryBlocks = !!(lesson && lesson.blocks && lesson.blocks.some(b => b.type === 'mastery_check'));
  const isReady = hasMasteryBlocks ? (state.quizDone && state.promptConfirmed) : (state.quizDone === true);
  const btn = document.getElementById(`lesson_complete_btn_${lessonId}`);
  if(btn && lessonsDone[lessonId] !== 1){
    if(isReady){
      btn.disabled = false;
      btn.style.opacity = '1';
      btn.style.cursor = 'pointer';
      btn.textContent = '✅ Завершить урок (Освоен)';
    } else {
      btn.disabled = true;
      btn.style.opacity = '0.5';
      btn.style.cursor = 'not-allowed';
      btn.textContent = '🔒 Завершить урок (Выполните проверку)';
    }
  }
}

function completeLessonWithMastery(id){
  const state = lessonCheckState[id] || {};
  const lesson = LESSONS.find(x => x.id === id);
  const hasMasteryBlocks = !!(lesson && lesson.blocks && lesson.blocks.some(b => b.type === 'mastery_check'));
  if(!lessonsDone[id]){
    if(hasMasteryBlocks){
      if(!state.quizDone || !state.promptConfirmed){
        alert('Для освоения урока необходимо правильно ответить на проверочный вопрос (Level 2) и подтвердить критерий приёмки (Level 5)!');
        return;
      }
    } else {
      const quizOk = lessonQuizPassed[id] === true || state.quizDone === true;
      if(!quizOk){
        alert('Сначала правильно ответьте на проверочный вопрос в конце урока — он разблокирует завершение.');
        return;
      }
    }
  }
  lessonsDone[id] = lessonsDone[id] ? 0 : 1;
  save();
  renderPhaseLessonsView(curPhaseLesson);
}

/* Duplicate navLesson removed in favor of active definition below */

function toggleLessonDone(id){
  lessonsDone[id] = lessonsDone[id] ? 0 : 1;
  save();
  renderPhaseLessonsView(curPhaseLesson);
}

function checkLessonQuiz(lessonId, blockIdx, optIdx){
  const lesson = LESSONS.find(l=>l.id===lessonId);
  if(!lesson) return;
  const block = lesson.blocks[blockIdx];
  if(!block) return;

  const container = $(`#lquiz_${lessonId}_${blockIdx}`);
  const expBox = $(`#lquiz_exp_${lessonId}_${blockIdx}`);
  const buttons = container.querySelectorAll('.ans');

  buttons.forEach((btn, i)=>{
    btn.disabled = true;
    if(i === block.a){
      btn.classList.add('ok');
    } else if(i === optIdx && i !== block.a){
      btn.classList.add('bad');
    }
  });

  if(block.explain && block.explain[optIdx]){
    expBox.style.display = 'block';
    expBox.innerHTML = `<b>Разбор:</b> ${block.explain[optIdx]}`;
  }
}

/* =========================================================================
   8. МОДАЛКА ГЛОССАРИЯ (TERM POPUP)
   ========================================================================= */
function openTermModal(idx){
  const t = TERMS[idx];
  if(!t) return;
  $('#mTerm').textContent = t.t;
  $('#mCat').innerHTML = `<span class="gcat" style="background:${CATS[t.c][1]}22;color:${CATS[t.c][1]}">${CATS[t.c][0]}</span>`;
  $('#mDef').textContent = t.d;
  if($('#mOrig')) $('#mOrig').textContent=''; if($('#mOrigRow')) $('#mOrigRow').style.display='none';
  $('#mAna').textContent = t.a;
  $('#mWhy').textContent = t.w;
  const size = localStorage.getItem('cn_account_size') || 'small';
  const capNote = {
    small: '≤ 50К ₽: комиссии и спред съедают большую долю — частые сделки вреднее, предпочтительны лимитные ордера и более редкие ребалансировки.',
    mid: '50К–500К ₽: комиссии терпимы, но контролируй проскальзывание на неликвидных парах и объём не больше 2–5% объёма стакана.',
    large: '500К+ ₽: исполнение и проскальзывание — ключевой риск: дроби ордера (TWAP/VWAP), считай рыночный импакт и следи за глубиной стакана.'
  }[size];
  const capEl = document.getElementById('mCapNote');
  if(capEl) capEl.textContent = capNote;
  $('#termModal').classList.add('open');
}

function openTermByName(name){
  if(!name) return;
  var q = name.toLowerCase().trim();
  var idx = TERMS.findIndex(x => x.t.toLowerCase() === q || x.t.toLowerCase().startsWith(q) || q.startsWith(x.t.toLowerCase()));
  if(idx === -1) idx = TERMS.findIndex(x => x.t.toLowerCase().includes(q) || q.includes(x.t.toLowerCase()));
  if(idx === -1){
    var words = q.split(/[\s\(\)\[\],:—\-]+/).filter(w => w.length >= 4);
    for(var i = 0; i < words.length; i++){
      var w = words[i];
      idx = TERMS.findIndex(x => x.t.toLowerCase().includes(w));
      if(idx !== -1) break;
    }
  }
  if(idx !== -1) openTermModal(idx);
}

function closeTermModal(e){
  if(e.target.id==='termModal') $('#termModal').classList.remove('open');
}
function closeTermModalDirect(){
  $('#termModal').classList.remove('open');
}

