window.runFundingDragSim = function(){
  const N = parseFloat(document.getElementById('fd_notional').value) || 0;
  const rateBps = parseFloat(document.getElementById('fd_rate').value) || 0;
  const days = Math.max(1, parseFloat(document.getElementById('fd_days').value) || 1);
  const side = document.getElementById('fd_side').value;
  const payPer8h = N * rateBps / 10000;
  const perDay = payPer8h * 3;
  const total = perDay * days;
  const apyPct = rateBps * 3 * 365 / 100; // bps → % годовых
  const dragPct = (total / N * 100).toFixed(2);
  const edgeNeededBps = (perDay / N * 10000).toFixed(2);
  document.getElementById('fd_result').innerHTML = `
    <div style="font-weight:700; margin-bottom:8px">Funding Drag за ${days} дн. (${side} при фандинге ${rateBps} bps/8ч):</div>
    <table style="width:100%; border-collapse:collapse; font-size:13.5px">
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">Платёж каждые 8 ч</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); font-weight:700; text-align:right">${payPer8h.toFixed(0)} ₽</td></tr>
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">Драг за день (3 платежа)</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); font-weight:700; text-align:right">${perDay.toFixed(0)} ₽</td></tr>
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">Итого за период</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); font-weight:800; color:var(--bad); text-align:right">−${total.toFixed(0)} ₽ (−${dragPct}%)</td></tr>
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">Эквивалент APY</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); font-weight:700; text-align:right">≈ ${apyPct.toFixed(1)}% годовых</td></tr>
      <tr><td style="padding:6px 10px; color:var(--mut)">Ожидание на день для безубытка</td><td style="padding:6px 10px; font-weight:800; color:var(--warn); text-align:right">≥ ${edgeNeededBps} bps/день</td></tr>
    </table>
    <div style="font-size:12.5px; color:var(--mut); margin-top:10px">Вывод: фандинг — это «аренда» позиции. Стратегия с ожиданием ниже ${edgeNeededBps} bps/день уходит в минус без единой ошибки в прогнозе.</div>`;
};
window.runTCostSim = function(){
  const N = parseFloat(document.getElementById('tc_notional').value) || 0;
  const feePct = parseFloat(document.getElementById('tc_fee').value) || 0;
  const spreadBps = parseFloat(document.getElementById('tc_spread').value) || 0;
  const slipBps = parseFloat(document.getElementById('tc_slip').value) || 0;
  const rt = Math.max(1, parseFloat(document.getElementById('tc_rt').value) || 1);
  const costRt = N * (2 * feePct / 100 + (spreadBps + 2 * slipBps) / 10000);
  const total = costRt * rt;
  const breakevenBps = (costRt / N * 10000).toFixed(1);
  document.getElementById('tc_result').innerHTML = `
    <div style="font-weight:700; margin-bottom:8px">Издержки на ${rt} round-trip сделок:</div>
    <table style="width:100%; border-collapse:collapse; font-size:13.5px">
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">Комиссии (вход+выход)</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); text-align:right">${(N * 2 * feePct / 100).toFixed(0)} ₽/RT</td></tr>
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">Спред</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); text-align:right">${(N * spreadBps / 10000).toFixed(0)} ₽/RT</td></tr>
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">Слиппедж (вход+выход)</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); text-align:right">${(N * 2 * slipBps / 10000).toFixed(0)} ₽/RT</td></tr>
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">Полная стоимость round-trip</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); font-weight:800; color:var(--bad); text-align:right">${costRt.toFixed(0)} ₽ (${breakevenBps} bps)</td></tr>
      <tr><td style="padding:6px 10px; color:var(--mut)">Итого за серию</td><td style="padding:6px 10px; font-weight:800; color:var(--bad); text-align:right">−${total.toFixed(0)} ₽</td></tr>
    </table>
    <div style="font-size:12.5px; color:var(--mut); margin-top:10px">Правило безубытка: ожидание на сделку ≥ <b style="color:var(--warn)">${breakevenBps} bps</b>. Maker-ордера срезают комиссию, но добавляют риск неисполнения — обсуждается в уроке про стакан.</div>`;
};

