window.togglePomodoro = function(){
  const p = window._pomodoro;
  const btn = document.getElementById('pomodoro_btn');
  if(p.running){
    p.running = false;
    if(p.id) clearInterval(p.id);
    if(btn){ btn.classList.remove('active'); btn.textContent = '🍅 ' + window._fmtPomo(p.left); }
    return;
  }
  if(p.left <= 0) p.left = 1500;
  p.running = true;
  if(btn) btn.classList.add('active');
  p.id = setInterval(() => {
    p.left--;
    const b = document.getElementById('pomodoro_btn');
    if(b) b.textContent = '🍅 ' + window._fmtPomo(p.left);
    if(p.left <= 0){
      clearInterval(p.id);
      p.running = false;
      p.left = 1500;
      if(b){ b.classList.remove('active'); b.textContent = '🍅 25:00'; }
      showToast('🍅 25 минут фокуса! Сделай 5–10 мин перерыва БЕЗ телефона — консолидация усилится (~30%).', '🍅', 9000);
      if(typeof showConsolidationScreen === 'function'){
        setTimeout(() => { try{ showConsolidationScreen(null, 'Помодоро завершён — время закрепить'); }catch(e){} }, 600);
      }
    }
  }, 1000);
};
