// V3-B4: DeFi Yield Lab — APY vs IL vs HODL
window.runDefiSim = function(){
  const dep = parseFloat(document.getElementById('df_dep').value) || 0;
  const apy = parseFloat(document.getElementById('df_apy').value) || 0;
  const move = parseFloat(document.getElementById('df_move').value) || 0;
  const days = Math.max(1, parseFloat(document.getElementById('df_days').value) || 1);
  const k = 1 + move / 100;
  const ilPct = (2 * Math.sqrt(k) / (1 + k) - 1) * 100; // стандартная формула IL
  const hodl = dep * k;
  const pool = dep * (1 + ilPct / 100) * k;
  const reward = dep * (apy / 100) * (days / 365);
  const total = pool + reward;
  const vsHodl = total - hodl;
  const breakevenApy = Math.abs(ilPct) * 365 / days;
  document.getElementById('df_result').innerHTML = `
    <div style="font-weight:700; margin-bottom:8px">Фарминг ${days} дн. при движении цены ${move}%:</div>
    <table style="width:100%; border-collapse:collapse; font-size:13.5px">
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">HODL (просто держать)</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); font-weight:700; text-align:right">${hodl.toFixed(0)} ₽</td></tr>
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">IL (непостоянная потеря)</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); font-weight:700; color:var(--bad); text-align:right">${ilPct.toFixed(2)}%</td></tr>
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">Награда за период (APY ${apy}%)</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); font-weight:700; color:var(--ok); text-align:right">+${reward.toFixed(0)} ₽</td></tr>
      <tr><td style="padding:6px 10px; border-bottom:1px solid var(--line); color:var(--mut)">Итог в пуле (с наградой)</td><td style="padding:6px 10px; border-bottom:1px solid var(--line); font-weight:800; text-align:right">${total.toFixed(0)} ₽</td></tr>
      <tr><td style="padding:6px 10px; color:var(--mut)">Пул vs HODL</td><td style="padding:6px 10px; font-weight:800; color:${vsHodl >= 0 ? 'var(--ok)' : 'var(--bad)'}; text-align:right">${vsHodl >= 0 ? '+' : ''}${vsHodl.toFixed(0)} ₽</td></tr>
    </table>
    <div style="font-size:12.5px; color:var(--mut); margin-top:10px">Безубыток: APY ≥ <b style="color:var(--warn)">${breakevenApy.toFixed(1)}%</b> при таком движении цены. Волатильные пары требуют заметно больше APY — это главный скрытый риск DeFi-фарминга.</div>`;
};

