function filterSimulators(phase, btn){
  if(btn){
    const container = btn.parentElement || document.getElementById('sim_phase_chips');
    if(container) container.querySelectorAll('.chip').forEach(c => c.classList.remove('active'));
    btn.classList.add('active');
  }

  const allSims = document.querySelectorAll('#sims .sim-box');
  if(phase === 'all'){
    allSims.forEach(s => {
      if(s.id === 'sim_meme') s.style.display = 'none';
      else s.style.display = '';
    });
    return;
  }

  const targetIds = SIM_PHASE_MAP[phase] || [];
  allSims.forEach(s => {
    if(targetIds.includes(s.id)){
      s.style.display = '';
    } else {
      s.style.display = 'none';
    }
  });
}

