function renderObTable(){
  const tbody = $('#ob_tbody');
  tbody.innerHTML = '';

  // Asks (reversed order so lowest ask is bottom)
  orderBookState.asks.slice().sort((a,b)=>b.price-a.price).forEach(a=>{
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${a.qty.toFixed(3)}</td><td class="ob-ask">$${a.price.toFixed(2)}</td><td>Ask (Sell)</td><td><div class="ob-depth" style="width:${Math.min(100, a.qty*40)}%; height:6px; background:rgba(239,68,68,.3)"></div></td>`;
    tbody.appendChild(tr);
  });

  // Spread row
  const bestAsk = orderBookState.asks.length ? Math.min(...orderBookState.asks.map(x=>x.price)) : 0;
  const bestBid = orderBookState.bids.length ? Math.max(...orderBookState.bids.map(x=>x.price)) : 0;
  const spread = (bestAsk - bestBid).toFixed(2);
  const spreadPct = bestBid > 0 ? ((bestAsk - bestBid)/bestBid*100).toFixed(4) : 0;

  const spTr = document.createElement('tr');
  spTr.style.background = 'rgba(255,255,255,.06)';
  spTr.style.fontWeight = '700';
  spTr.innerHTML = `<td colspan="4" style="text-align:center; padding:8px; color:var(--acc2)">⚡ Спред: $${spread} (${spreadPct}%) | Best Bid: $${bestBid} — Best Ask: $${bestAsk}</td>`;
  tbody.appendChild(spTr);

  // Bids
  orderBookState.bids.slice().sort((a,b)=>b.price-a.price).forEach(b=>{
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${b.qty.toFixed(3)}</td><td class="ob-bid">$${b.price.toFixed(2)}</td><td>Bid (Buy)</td><td><div class="ob-depth" style="width:${Math.min(100, b.qty*40)}%; height:6px; background:rgba(34,197,94,.3)"></div></td>`;
    tbody.appendChild(tr);
  });
}

function obMatchAgainstBook(side, reqQty){
  // Исполнение по рынку против лучших уровней: для BUY съедаем asks, для SELL — bids
  let remaining = reqQty;
  let totalValue = 0;
  let fills = [];
  if(side === 'buy'){
    orderBookState.asks.sort((a,b)=>a.price-b.price);
    for(let i=0; i<orderBookState.asks.length && remaining > 0; i++){
      let level = orderBookState.asks[i];
      let fillQty = Math.min(remaining, level.qty);
      totalValue += fillQty * level.price;
      level.qty -= fillQty;
      remaining -= fillQty;
      fills.push(`${fillQty.toFixed(3)} BTC по $${level.price}`);
    }
    orderBookState.asks = orderBookState.asks.filter(x=>x.qty > 0.0001);
  } else {
    orderBookState.bids.sort((a,b)=>b.price-a.price);
    for(let i=0; i<orderBookState.bids.length && remaining > 0; i++){
      let level = orderBookState.bids[i];
      let fillQty = Math.min(remaining, level.qty);
      totalValue += fillQty * level.price;
      level.qty -= fillQty;
      remaining -= fillQty;
      fills.push(`${fillQty.toFixed(3)} BTC по $${level.price}`);
    }
    orderBookState.bids = orderBookState.bids.filter(x=>x.qty > 0.0001);
  }
  return { filledQty: reqQty - remaining, totalValue, fills, remaining };
}

function executeObSim(){
  const type = $('#ob_type').value;
  const side = $('#ob_side').value;
  const reqQty = parseFloat($('#ob_qty').value) || 0;
  const limitPrice = parseFloat($('#ob_price').value) || 0;
  const log = $('#ob_log');

  if(!log) return;
  if(reqQty <= 0){
    log.innerHTML = '<span style="color:var(--bad)">Укажите количество > 0</span>';
    return;
  }

  const bestAsk = orderBookState.asks.length ? Math.min(...orderBookState.asks.map(x=>x.price)) : Infinity;
  const bestBid = orderBookState.bids.length ? Math.max(...orderBookState.bids.map(x=>x.price)) : 0;
  const posNote = side === 'sell'
    ? '<br><span style="color:var(--mut); font-size:12px">ℹ️ Это продажа актива со спотового баланса (выход из лонга), а не открытие шорта.</span>'
    : '';

  if(type === 'limit'){
    if(limitPrice <= 0){
      log.innerHTML = '<span style="color:var(--bad)">Укажите корректную цену лимитки</span>';
      return;
    }
    // Marketable limit: цена пересекает стакан → мгновенное исполнение как Taker
    const marketable = (side === 'buy' && limitPrice >= bestAsk) || (side === 'sell' && limitPrice <= bestBid);
    if(marketable){
      const r = obMatchAgainstBook(side, reqQty);
      const vwap = r.filledQty > 0 ? r.totalValue / r.filledQty : 0;
      const ref = side === 'buy' ? bestAsk : bestBid;
      const slipBps = r.filledQty > 0 && ref > 0 ? ((vwap - ref) / ref * 10000) : 0;
      const takerFee = r.totalValue * 0.00055;
      log.innerHTML = `
        <div style="background:rgba(255,255,255,.05); padding:12px; border-radius:10px; border-left:4px solid var(--warn)">
          <b>⚡ MARKETABLE LIMIT (${side.toUpperCase()} @ $${limitPrice}) — исполнена немедленно как TAKER:</b><br>
          Твоя лимитная цена пересекает стакан (лучший ${side==='buy'?'Ask':'Bid'} = $${side==='buy'?bestAsk:bestBid}), поэтому заявка не встала в книгу, а съела её.<br>
          Исполнено: <b>${r.filledQty.toFixed(3)} BTC</b> на сумму <b>$${r.totalValue.toFixed(2)}</b> · VWAP: <b>$${vwap.toFixed(2)}</b><br>
          Комиссия Taker (0.055%): <b>$${takerFee.toFixed(2)}</b><br>
          Slippage относительно лучшей цены: <b>${slipBps>=0?'+':''}${slipBps.toFixed(1)} bps</b>
          ${r.remaining > 0 ? `<br><span style="color:var(--mut)">Остаток ${(reqQty-r.filledQty).toFixed(3)} BTC, который не смог исполниться, остаётся в книге как пассивная заявка.</span>` : ''}
          ${posNote}
        </div>`;
      recordOrderBookAction('market', Math.max(0, slipBps));
      renderObTable();
      return;
    }
    // Пассивная лимитка: добавляет ликвидность в книгу (Maker)
    if(side === 'buy'){
      orderBookState.bids.push({price:limitPrice, qty:reqQty});
      orderBookState.bids.sort((a,b)=>b.price-a.price);
    } else {
      orderBookState.asks.push({price:limitPrice, qty:reqQty});
      orderBookState.asks.sort((a,b)=>a.price-b.price);
    }
    log.innerHTML = `<div style="background:rgba(255,255,255,.05); padding:12px; border-radius:10px; border-left:4px solid var(--ok)">
      ✓ <b>Пассивная LIMIT-заявка (MAKER)</b>: ${reqQty} BTC по $${limitPrice} поставлена в книгу ордеров.<br>
      Цена не пересекает стакан, поэтому заявка ждёт исполнителя, ДОБАВЛЯЯ ликвидность. Комиссия Maker = 0.02%. Проскальзывание = $0.
      ${posNote}</div>`;
    recordOrderBookAction('limit');
    renderObTable();
    return;
  }

  // MARKET Execution: мгновенный Taker-ордер против лучших уровней
  const r = obMatchAgainstBook(side, reqQty);
  const vwap = r.filledQty > 0 ? r.totalValue / r.filledQty : 0;
  const ref = side === 'buy' ? bestAsk : bestBid;
  const slipBps = r.filledQty > 0 && ref > 0 ? ((vwap - ref) / ref * 10000) : 0;
  const takerFee = r.totalValue * 0.00055;

  log.innerHTML = `
    <div style="background:rgba(255,255,255,.05); padding:12px; border-radius:10px; border-left:4px solid var(--acc2)">
      <b>Результат Market ${side.toUpperCase()} ордера:</b><br>
      Исполнено: <b>${r.filledQty.toFixed(3)} BTC</b> на сумму <b>$${r.totalValue.toFixed(2)}</b><br>
      Средняя цена исполнения (VWAP): <b>$${vwap.toFixed(2)}</b><br>
      Комиссия Taker (0.055%): <b>$${takerFee.toFixed(2)}</b><br>
      Проскальзывание к лучшей цене ($${ref}): <b style="color:${Math.abs(slipBps)>5?'var(--bad)':'var(--ok)'}">${slipBps>=0?'+':''}${slipBps.toFixed(1)} bps</b><br>
      Срезы уровней стакана: ${r.fills.join(' + ') || '—'}
      ${r.remaining > 0 ? `<br><span style="color:var(--bad)">⚠️ Не хватило ликвидности в стакане для ${r.remaining.toFixed(3)} BTC!</span>` : ''}
      ${posNote}
    </div>
  `;
  recordOrderBookAction('market', slipBps);
  renderObTable();
}

function calcLiquidation(){
  const margin = parseFloat(document.getElementById('liq_margin')?.value) || 0;
  const lev = parseFloat(document.getElementById('liq_lev')?.value) || 1;
  const entry = parseFloat(document.getElementById('liq_entry')?.value) || 0;
  const side = document.getElementById('liq_dir')?.value || 'long';
  const mmr = (parseFloat(document.getElementById('liq_mmr')?.value) || 0.5) / 100;

  const out = document.getElementById('liq_output');
  if(!out) return;

  if(margin <= 0 || entry <= 0){
    out.innerHTML = 'Заполните корректные параметры.';
    return;
  }

  const notional = margin * lev;
  const btcQty = notional / entry;
  
  let liqPrice = 0;
  let dropPct = 0;

  if(side === 'long'){
    liqPrice = entry * (1 - (1/lev) + mmr);
    dropPct = ((entry - liqPrice) / entry) * 100;
  } else {
    liqPrice = entry * (1 + (1/lev) - mmr);
    dropPct = ((liqPrice - entry) / entry) * 100;
  }

  // Calculate PnL table at +-5%, +-10%, +-20% price movement
  const scenarios = [
    { move: -20, mult: -0.20 },
    { move: -10, mult: -0.10 },
    { move: -5, mult: -0.05 },
    { move: 5, mult: 0.05 },
    { move: 10, mult: 0.10 },
    { move: 20, mult: 0.20 }
  ];

  const pnlRows = scenarios.map(sc => {
    const targetPrice = entry * (1 + sc.mult);
    let pnlUsd = 0;
    let pnlRoi = 0;

    if(side === 'long'){
      pnlUsd = notional * sc.mult;
      pnlRoi = sc.mult * lev * 100;
    } else {
      pnlUsd = -notional * sc.mult;
      pnlRoi = -sc.mult * lev * 100;
    }

    // Check if liquidated
    const isLiquidated = (side === 'long' && targetPrice <= liqPrice) || (side === 'short' && targetPrice >= liqPrice);
    const displayPnl = isLiquidated ? `−$${margin.toFixed(0)} (−100% ЛИКВИДАЦИЯ)` : `${pnlUsd>0?'+':''}$${pnlUsd.toFixed(0)} (${pnlRoi>0?'+':''}${pnlRoi.toFixed(1)}%)`;
    const pnlColor = isLiquidated ? 'var(--bad)' : pnlUsd > 0 ? 'var(--ok)' : 'var(--bad)';

    return `
      <tr>
        <td><b>${sc.move > 0 ? '+' : ''}${sc.move}%</b></td>
        <td>$${targetPrice.toFixed(0)}</td>
        <td style="color:${pnlColor}; font-weight:800">${displayPnl}</td>
      </tr>
    `;
  }).join('');

  out.innerHTML = `
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px; margin-bottom:14px">
      <div class="pitem"><div class="lbl">Объем позиции (Notional):</div><div class="val" style="font-weight:800">$${notional.toLocaleString()} (${btcQty.toFixed(4)} BTC)</div></div>
      <div class="pitem"><div class="lbl">Цена ликвидации:</div><div class="val" style="font-weight:800; color:${lev>=20?'var(--bad)':'var(--warn)'}">$${liqPrice.toFixed(2)}</div></div>
      <div class="pitem"><div class="lbl">Допустимое движение цены:</div><div class="val" style="font-weight:800; color:${dropPct<5?'var(--bad)':'var(--ok)'}">${dropPct.toFixed(2)}%</div></div>
      <div class="pitem"><div class="lbl">Эффективное плечо:</div><div class="val" style="font-weight:800; color:var(--acc2)">x${lev}</div></div>
    </div>

    <div style="padding:10px 12px; border-radius:8px; background:rgba(234,179,8,.07); border-left:3px solid var(--warn); font-size:12px; color:var(--txt); line-height:1.55; margin-bottom:12px">
      ℹ️ <b>Как это работает в реальности:</b> биржи считают ликвидацию по <b>mark price</b> (средневзвешенной цене мультибиржевого индекса), а не по цене последней сделки, и закрывают позицию, когда маржа опускается до уровня поддерживающей маржи (MMR). Формула здесь — упрощённая учебная модель: у конкретной биржи добавляются комиссии, ступенчатые лимиты и буферы страхового фонда, поэтому фактическая цена ликвидации будет отличаться. При x1 ликвидация возможна только почти при обнулении цены актива (≈ −99%+ для лонга) — плечо не меняет направление риска, лишь его масштаб.
    </div>

    <!-- PnL Matrix Table -->
    <div style="background:#040714; border:1px solid var(--line); border-radius:10px; padding:12px; margin-top:8px">
      <div style="font-weight:700; color:var(--acc2); font-size:13px; margin-bottom:8px">📊 Матрица PnL при изменении цены актива (±5%, ±10%, ±20%):</div>
      <table class="order-book-table" style="width:100%; font-size:12.5px">
        <thead>
          <tr>
            <th>Движение рынка</th>
            <th>Цена BTC</th>
            <th>Финансовый результат (PnL / ROI)</th>
          </tr>
        </thead>
        <tbody>
          ${pnlRows}
        </tbody>
      </table>
    </div>
  `;
}

function calcFunding(){
  const pos = parseFloat($('#fund_pos').value) || 10000;
  const ratePct = parseFloat($('#fund_rate').value) || 0.01;
  const side = $('#fund_side').value;

  const rate = ratePct / 100;
  const fee8h = pos * Math.abs(rate);
  const fee24h = fee8h * 3;
  const fee30d = fee24h * 30;

  // Simple APR vs Compounded APY: (1 + rate)^1095 - 1
  const aprPct = ratePct * 3 * 365;
  const apyPct = (Math.pow(1 + Math.abs(rate), 1095) - 1) * 100;

  let payer = '', receiver = '';
  if(rate > 0){
    payer = 'ЛОНГИ платят ШОРТАМ';
    receiver = side === 'long' ? 'Ты ПЛАТИШЬ' : 'Ты ПОЛУЧАЕШЬ';
  } else if(rate < 0){
    payer = 'ШОРТЫ платят ЛОНГАМ';
    receiver = side === 'short' ? 'Ты ПЛАТИШЬ' : 'Ты ПОЛУЧАЕШЬ';
  } else {
    payer = 'Ставка 0% — никто никому не платит';
    receiver = 'Платежей нет';
  }

  const isYouPay = receiver.includes('ПЛАТИШЬ');

  const out = $('#fund_output');
  if(!out) return;

  out.innerHTML = `
    <div style="font-weight:800; color:var(--acc2); margin-bottom:10px">Кто кому платит: <span style="color:${rate>0?'var(--ok)':'var(--bad)'}">${payer}</span> (${receiver})</div>
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
      <div class="pitem"><div class="lbl">Платеж за 8 часов:</div><div class="val" style="color:${isYouPay?'var(--bad)':'var(--ok)'}; font-weight:800">${isYouPay?'−':'+'}$${fee8h.toFixed(2)}</div></div>
      <div class="pitem"><div class="lbl">Платеж за 24 часа (сутки):</div><div class="val" style="color:${isYouPay?'var(--bad)':'var(--ok)'}; font-weight:800">${isYouPay?'−':'+'}$${fee24h.toFixed(2)}</div></div>
      <div class="pitem"><div class="lbl">Платеж за 30 дней:</div><div class="val" style="color:${isYouPay?'var(--bad)':'var(--ok)'}; font-weight:800">${isYouPay?'−':'+'}$${fee30d.toFixed(2)}</div></div>
      <div class="pitem"><div class="lbl">Годовой эквивалент при неизменной ставке (APR / APY):</div><div class="val" style="font-weight:800; font-size:16px; color:var(--acc2)">${aprPct.toFixed(1)}% APR <span style="font-size:11px; display:block; color:var(--mut)">APY: ${apyPct.toFixed(1)}% — расчёт сложного процента, ЕСЛИ ставка не меняется весь год</span></div></div>
    </div>
    <div style="margin-top:10px; padding:10px 12px; border-radius:8px; background:rgba(234,179,8,.07); border-left:3px solid var(--warn); font-size:12px; color:var(--txt); line-height:1.55">
      ⚠️ Funding rate пересматривается каждые 8 часов и зависит от баланса спроса лонгов/шортов. Это НЕ гарантированный APY: приведённые цифры показывают годовой эквивалент только в гипотезе, что текущая ставка сохранится. В реальности она колеблется — иногда уходит в минус.
    </div>
  `;
}

/* =========================================================================
   ДОПОЛНЕНИЯ СИМУЛЯТОРОВ ФАЗЫ 1 (LOOK-AHEAD, OVERFITTING, WALK-FORWARD)
   ========================================================================= */
const SNIPPETS = [
  {
    title: 'Сниппет 1: Вычисление торгового сигнала',
    code: [
      '# 1. Загрузка минутных данных',
      'df = load_ohlcv("BTCUSDT", "1m")',
      '# 2. Вычисление индикатора SMA',
      'df["sma_fast"] = df["close"].rolling(10).mean()',
      'df["sma_slow"] = df["close"].rolling(30).mean()',
      '# 3. Формирование сигнала на покупку',
      'df["signal"] = (df["sma_fast"] > df["sma_slow"]).astype(int)',
      '# 4. Расчет доходности стратегии',
      'df["strategy_ret"] = df["signal"] * df["log_ret"]  # <--- КЛИКНИ СЮДА ЕСЛИ ЗДЕСЬ ОШИБКА'
    ],
    bugLine: 8,
    explain: '<b>Грубейший Look-Ahead Bias!</b> Строка 8 умножает `df["signal"]` бара t на доходность этого же бара `df["log_ret"]`. Но сигнал на баре t формируется только в момент закрытия свечи (Close)! Торговать по нему можно только на следующем баре t+1. Исправление: `df["signal"].shift(1) * df["log_ret"]`.'
  },
  {
    title: 'Сниппет 2: Нормализация признаков (Feature Scaling)',
    code: [
      '# 1. Подготовка датасета фичей',
      'features = df[["rsi", "volatility", "volume"]]',
      '# 2. Масштабирование MinMaxScaler',
      'scaler = MinMaxScaler()',
      'scaled_data = scaler.fit_transform(features)  # <--- КЛИКНИ СЮДА',
      '# 3. Разделение на Train и Test',
      'train = scaled_data[:split_idx]',
      'test = scaled_data[split_idx:]',
      '# 4. Обучение модели регрессии',
      'model.fit(train, y_train)'
    ],
    bugLine: 4,
    explain: '<b>Утечка данных из будущего (Data Leakage)!</b> В строке 4 `scaler.fit_transform()` вычисляет минимум и максимум по ВСЕМУ датасету, включая будущий Test период. Значения из 2025 года протекли в обучающую выборку 2022 года. Исправление: вызывать `scaler.fit(train)` строго на обучающей выборке, а затем делать `scaler.transform(test)`.'
  },
  {
    title: 'Сниппет 3: Ресемплинг таймфрейма (1h -> 1D)',
    code: [
      '# 1. Загрузка 1-часовых свечей',
      'df_1h = load_data("ETHUSDT", "1h")',
      '# 2. Агрегация в дневные уровни',
      'daily_high = df_1h["high"].resample("1D").max()',
      '# 3. Объединение назад в часовой датасет',
      'df_1h["day_high"] = df_1h.index.map(daily_high)  # <--- КЛИКНИ СЮДА',
      '# 4. Пробой дневного максимума',
      'df_1h["breakout"] = df_1h["close"] > df_1h["day_high"]'
    ],
    bugLine: 5,
    explain: '<b>Заглядывание в будущее через ресемплинг!</b> В строке 5 утренний бар в 08:00 получает значение `day_high`, которое включает в себя максимум, установленный в 23:00 этого же дня. Бот утром "знает", каким будет максимум вечером. Исправление: сдвигать дневной агрегат `.shift(1)`.'
  }
];

curSnippetIdx = 0;

function loadSnippet(idx, btn){
  curSnippetIdx = idx;
  if(btn){
    btn.parentElement.querySelectorAll('.chip').forEach(c=>c.classList.remove('active'));
    btn.classList.add('active');
  }
  const snip = SNIPPETS[idx];
  const box = $('#snippet_box');
  const fb = $('#snippet_feedback');
  fb.style.display = 'none';

  box.innerHTML = snip.code.map((line, lIdx)=>`
    <div style="cursor:pointer; padding:3px 8px; border-radius:6px; transition:.15s" 
         onmouseover="this.style.background='rgba(255,255,255,.08)'" 
         onmouseout="this.style.background='transparent'" 
         onclick="checkSnippetLine(${idx}, ${lIdx})">
      <span style="color:var(--mut); user-select:none; margin-right:12px">${lIdx+1}</span>
      <span>${escapeHtml(line)}</span>
    </div>
  `).join('');
}

function escapeHtml(text){
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function checkSnippetLine(snipIdx, lineIdx){
  const snip = SNIPPETS[snipIdx];
  const fb = $('#snippet_feedback');
  fb.style.display = 'block';

  if(lineIdx === snip.bugLine){
    fb.style.background = 'rgba(34,197,94,.15)';
    fb.style.border = '1px solid var(--ok)';
    fb.innerHTML = `🎯 <b>В ТОЧКУ! Строка ${lineIdx+1} содержит Look-Ahead Bias.</b><br><br>${snip.explain}`;
    checkSnippetLeak(snipIdx, true); // фиксируем найденный уровень для бейджа
  } else {
    fb.style.background = 'rgba(239,68,68,.12)';
    fb.style.border = '1px solid var(--bad)';
    fb.innerHTML = `❌ <b>Строка ${lineIdx+1} не содержит критической ошибки.</b> Ищи строку, где используются данные будущего или не применен .shift(1).`;
  }
}

/* OVERFITTING LAB SIMULATOR */
function updateOverfitSim(){
  const p = parseInt($('#param_slider').value) || 1;
  $('#param_count_val').textContent = p + (p===1?' параметр':p<5?' параметра':' параметров');

  // Train Sharpe grows with complexity: 1.1 -> 3.8
  const trainSharpe = (1.1 + Math.log(p) * 0.95).toFixed(2);
  // Test Sharpe peaks at p=2..3 then collapses
  let testSharpe = 0;
  if(p <= 3){
    testSharpe = (1.1 + p * 0.35).toFixed(2);
  } else {
    testSharpe = (1.1 + 3 * 0.35 - (p - 3) * 0.28).toFixed(2);
  }

  $('#of_train_sharpe').textContent = trainSharpe;
  $('#of_test_sharpe').textContent = testSharpe;
  $('#of_test_sharpe').style.color = testSharpe > 1.5 ? 'var(--ok)' : testSharpe > 0.5 ? 'var(--warn)' : 'var(--bad)';

  const status = $('#of_status');
  const exp = $('#overfit_explanation');

  if(p <= 3){
    status.innerHTML = '<span style="color:var(--ok)">✅ Устойчивая модель (Робастность)</span>';
    exp.innerHTML = '💡 <b>Оптимальная сложность:</b> Модель уловила реальную закономерность рынка. Результат на Out-of-Sample подтверждает качество гипотезы.';
  } else if(p <= 7){
    status.innerHTML = '<span style="color:var(--warn)">⚠️ Начало переобучения (Overfitting)</span>';
    exp.innerHTML = '⚠️ <b>Предупреждение:</b> Рост параметров увеличивает Train Sharpe, но Out-of-Sample Sharpe начинает деградировать. Модель запоминает шум.';
  } else {
    status.innerHTML = '<span style="color:var(--bad)">💥 Катастрофическое переобучение!</span>';
    exp.innerHTML = '❌ <b>Ловушка квантов:</b> Train Sharpe = '+trainSharpe+' создает иллюзию грааля, но на реальном рынке стратегия сливает (OOS Sharpe = '+testSharpe+'). Вы подогнали алгоритм под случайный исторический шум.';
  }

  drawOverfitGraph(p);
}

function drawOverfitGraph(activeP){
  const canvas = document.getElementById('overfit_canvas');
  if(!canvas) return;
  if(!canvas || !canvas.getContext) return; const ctx = canvas.getContext('2d');
  const w = canvas.width;
  const h = canvas.height;

  ctx.clearRect(0,0,w,h);

  // Background grid
  ctx.strokeStyle = 'rgba(255,255,255,0.06)';
  ctx.lineWidth = 1;
  for(let y=20; y<h; y+=40){
    ctx.beginPath(); ctx.moveTo(40,y); ctx.lineTo(w-20,y); ctx.stroke();
  }

  // Axes
  ctx.strokeStyle = 'rgba(255,255,255,0.2)';
  ctx.beginPath();
  ctx.moveTo(40, 20); ctx.lineTo(40, h-30); ctx.lineTo(w-20, h-30);
  ctx.stroke();

  // Labels
  ctx.fillStyle = '#9aa3c7';
  ctx.font = '11px sans-serif';
  ctx.fillText('Sharpe', 5, 25);
  ctx.fillText('Сложность (Параметры 1..15)', w/2 - 60, h-10);

  const getX = (p) => 40 + ((p - 1) / 14) * (w - 70);
  const getY = (s) => (h - 30) - ((s + 1.0) / 5.0) * (h - 60);

  // Draw Train Curve (Green)
  ctx.strokeStyle = '#22c55e';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  for(let p=1; p<=15; p++){
    const s = 1.1 + Math.log(p) * 0.95;
    const x = getX(p); const y = getY(s);
    if(p===1) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.stroke();

  // Draw Test Curve (Cyan / Red)
  ctx.strokeStyle = '#06b6d4';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  for(let p=1; p<=15; p++){
    let s = p <= 3 ? 1.1 + p * 0.35 : 1.1 + 3 * 0.35 - (p - 3) * 0.28;
    const x = getX(p); const y = getY(s);
    if(p===1) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.stroke();

  // Active Marker
  const curX = getX(activeP);
  ctx.strokeStyle = '#f59e0b';
  ctx.setLineDash([4, 4]);
  ctx.beginPath(); ctx.moveTo(curX, 20); ctx.lineTo(curX, h-30); ctx.stroke();
  ctx.setLineDash([]);

  // Legend
  ctx.fillStyle = '#22c55e'; ctx.fillText('● Train (In-Sample)', w - 180, 25);
  ctx.fillStyle = '#06b6d4'; ctx.fillText('● Test (Out-of-Sample)', w - 180, 42);
}

/* WALK-FORWARD SIMULATOR */
let wfStep = 1;
const WF_STAGES = [
  { step: 1, train: '2021-01 .. 2021-12 (12 мес)', test: '2022-01 .. 2022-03 (3 мес)', trainSh: 2.1, testSh: 1.8, status: 'Успешно' },
  { step: 2, train: '2021-04 .. 2022-03 (12 мес)', test: '2022-04 .. 2022-06 (3 мес)', trainSh: 1.9, testSh: 1.7, status: 'Успешно' },
  { step: 3, train: '2021-07 .. 2022-06 (12 мес)', test: '2022-07 .. 2022-09 (3 мес)', trainSh: 2.3, testSh: 1.5, status: 'Успешно' },
  { step: 4, train: '2021-10 .. 2022-09 (12 мес)', test: '2022-10 .. 2022-12 (3 мес)', trainSh: 1.8, testSh: 1.6, status: 'Успешно (FTX крах пройден)' },
  { step: 5, train: '2022-01 .. 2022-12 (12 мес)', test: '2023-01 .. 2023-03 (3 мес)', trainSh: 2.0, testSh: 1.9, status: 'Успешно' },
  { step: 6, train: '2022-04 .. 2023-03 (12 мес)', test: '2023-04 .. 2023-06 (3 мес)', trainSh: 2.2, testSh: 1.8, status: 'Финал цикла' }
];

function stepWalkForward(){
  if(wfStep < WF_STAGES.length) wfStep++;
  else wfStep = 1;
  renderWalkForward(); initSentimentSim(); initWhaleSim(); initPortfolioSim(); initKellySim(); initTaxSim(); init115FzSim(); runStationaritySim(); calcAlphaBetaSim(); calcExecDevSim(); initScalingSim(); initRebalanceSim();
}

function resetWalkForward(){
  wfStep = 1;
  renderWalkForward(); initSentimentSim(); initWhaleSim(); initPortfolioSim(); initKellySim(); initTaxSim(); init115FzSim(); runStationaritySim(); calcAlphaBetaSim(); calcExecDevSim(); initScalingSim(); initRebalanceSim();
}

function renderWalkForward(){
  const tBox = $('#wf_timeline_box');
  const sBox = $('#wf_summary_box');

  let html = `<div style="font-weight:700; color:var(--acc2); margin-bottom:12px">Шаг ${wfStep} из ${WF_STAGES.length}: Скользящие окна In-Sample / Out-of-Sample</div>`;

  WF_STAGES.slice(0, wfStep).forEach((st, idx)=>{
    html += `
      <div style="display:flex; align-items:center; gap:10px; margin:8px 0; font-size:13px; flex-wrap:wrap">
        <span style="width:70px; font-weight:700; color:var(--txt)">Окно ${st.step}:</span>
        <span style="background:rgba(34,197,94,.15); color:var(--ok); border:1px solid rgba(34,197,94,.3); padding:4px 8px; border-radius:6px">Train: ${st.train}</span>
        <span style="background:rgba(6,182,212,.15); color:var(--acc2); border:1px solid rgba(6,182,212,.3); padding:4px 8px; border-radius:6px">OOS Test: ${st.test}</span>
        <span style="color:var(--txt); margin-left:auto">OOS Sharpe: <b>${st.testSh}</b></span>
      </div>
    `;
  });

  tBox.innerHTML = html;

  const current = WF_STAGES[wfStep-1];
  const avgOosSharpe = (WF_STAGES.slice(0, wfStep).reduce((acc, x)=>acc+x.testSh, 0) / wfStep).toFixed(2);

  sBox.innerHTML = `
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
      <div class="pitem"><div class="lbl">Текущий шаг OOS:</div><div class="val" style="font-weight:800">${current.test}</div></div>
      <div class="pitem"><div class="lbl">Средний OOS Sharpe по цепочке:</div><div class="val" style="font-weight:800; color:var(--ok)">${avgOosSharpe}</div></div>
      <div class="pitem"><div class="lbl">Результат валидации:</div><div class="val" style="font-weight:800; color:var(--ok)">${current.status}</div></div>
    </div>
    <p style="margin-top:12px; font-size:13px; color:var(--mut)">
      💡 Walk-Forward проверяет, как параметры адаптируются к рынку без заглядывания в будущее. Соединяя непрерывные OOS-кусочки, мы получаем истинную кривую капитала для продакшна.
    </p>
  `;
}



