const EARNING_METHODS = CN_CONTENT.ensure('EARNING_METHODS');

function initEarningMethods(){
  renderEarningCards(EARNING_METHODS);
}

function filterEarningMethods(){
  const capF = $('#em_cap_filter').value;
  const catF = $('#em_cat_filter').value;
  const riskF = $('#em_risk_filter').value;

  let filtered = EARNING_METHODS.filter(m => {
    if(catF !== 'all' && m.cat !== catF) return false;
    if(riskF !== 'all' && m.risk !== riskF) return false;
    if(capF === 'zero' && !(m.entry.includes('$0') || m.entry.includes('$10') || m.entry.includes('$20') || m.entry.includes('$50'))) return false;
    if(capF === 'high' && m.risk === 'extreme') return false;
    return true;
  });

  renderEarningCards(filtered);
}

function renderEarningCards(list){
  const box = $('#earning_cards_container');
  if(!box) return;

  if(list.length === 0){
    box.innerHTML = '<div style="grid-column:1/-1; text-align:center; padding:30px; color:var(--mut)">По выбранным фильтрам способов не найдено. Сбросьте фильтры.</div>';
    return;
  }

  box.innerHTML = list.map(m => {
    const isExtreme = m.risk === 'extreme';
    const riskColor = isExtreme ? 'var(--bad)' : m.risk === 'high' ? 'var(--bad)' : m.risk === 'med' ? 'var(--warn)' : 'var(--ok)';
    const cardBorder = isExtreme ? '1px solid rgba(239,68,68,.4)' : '1px solid var(--line)';
    const cardBg = isExtreme ? 'rgba(239,68,68,.05)' : 'var(--card)';

    return `
      <div style="background:${cardBg}; border:${cardBorder}; border-radius:14px; padding:18px; display:flex; flex-direction:column; justify-content:space-between; box-shadow:var(--shadow)">
        <div>
          <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px; margin-bottom:10px">
            <span style="font-size:12px; font-weight:800; color:var(--acc2); background:rgba(6,182,212,.12); padding:3px 8px; border-radius:6px">Направление ${m.num}</span>
            <span style="font-size:11.5px; font-weight:700; color:${riskColor}; background:rgba(255,255,255,.05); padding:3px 8px; border-radius:6px">Риск: ${m.riskText}</span>
          </div>

          <h3 style="font-size:16px; margin-bottom:8px; color:var(--txt)">${m.title}</h3>
          <p style="font-size:13px; color:var(--mut); line-height:1.5; margin-bottom:14px">${m.summary}</p>

          <div style="background:#090d1f; border-radius:10px; padding:10px 12px; font-size:12.5px; margin-bottom:12px; line-height:1.6">
            <div><span style="color:var(--mut)">💰 Порог входа:</span> <b>${m.entry}</b></div>
            <div><span style="color:var(--mut)">📈 Доходность:</span> <b style="color:var(--ok)">${m.apr}</b></div>
            <div><span style="color:var(--mut)">⚖️ Статус в РФ:</span> <span style="color:var(--acc2)">${m.legalRF}</span></div>
            ${m.source ? `<div style="margin-top:4px; font-size:11.5px; color:var(--mut)"><b>📜 Первоисточник:</b> <i>${m.source}</i></div>` : ''}
          </div>

          <details style="font-size:12.5px; color:var(--txt); margin-bottom:10px">
            <summary style="cursor:pointer; color:var(--acc2); font-weight:700; margin-bottom:8px">📋 Пошаговый алгоритм действий</summary>
            <div style="padding:8px 0 4px 6px; line-height:1.6; color:var(--txt)">
              ${m.steps.map(s => `<div style="margin-bottom:6px">${s}</div>`).join('')}
            </div>
          </details>

          <div style="font-size:12px; color:var(--bad); background:rgba(239,68,68,.08); border-left:3px solid var(--bad); padding:6px 10px; border-radius:4px; margin-bottom:8px">
            <b>⚠️ Главные риски:</b> ${m.pitfalls}
          </div>
        </div>

        <div style="font-size:11.5px; color:var(--acc2); background:rgba(6,182,212,.08); padding:8px 10px; border-radius:8px; margin-top:8px">
          💡 <b>Комментарий кванта:</b> ${m.zainullinTip}
        </div>
      </div>
    `;
  }).join('');
}

