/* =========================================================================
   ДОПОЛНЕНИЯ СИМУЛЯТОРОВ ФАЗЫ 3 (ПОРТФЕЛЬ И ДРОБНЫЙ КЕЛЛИ)
   ========================================================================= */
function initPortfolioSim(){
  calcPortfolioSim();
}

function calcPortfolioSim(){
  let w1 = parseFloat($('#pf_w1').value) || 0;
  let w2 = parseFloat($('#pf_w2').value) || 0;
  let w3 = parseFloat($('#pf_w3').value) || 0;
  const corr = parseFloat($('#pf_corr').value) || 0;

  const totalW = w1 + w2 + w3;
  if(totalW <= 0) return;
  w1 /= totalW; w2 /= totalW; w3 /= totalW;

  // Strategy parameters: (Return %, Volatility %, Sharpe)
  // S1 Trend: Ret=35%, Vol=25%, Sh=1.40
  // S2 Pairs: Ret=28%, Vol=12%, Sh=2.33
  // S3 Fund:  Ret=18%, Vol=5%,  Sh=3.60
  const r1=0.35, v1=0.25;
  const r2=0.28, v2=0.12;
  const r3=0.18, v3=0.05;

  const portRet = w1*r1 + w2*r2 + w3*r3;

  // Portfolio Variance = sum(w_i^2 * v_i^2) + 2 * sum(w_i * w_j * v_i * v_j * corr)
  const varDiag = (w1*v1)**2 + (w2*v2)**2 + (w3*v3)**2;
  const cov12 = 2 * w1 * w2 * v1 * v2 * corr;
  const cov13 = 2 * w1 * w3 * v1 * v3 * corr;
  const cov23 = 2 * w2 * w3 * v2 * v3 * corr;
  const portVol = Math.sqrt(Math.max(0.0001, varDiag + cov12 + cov13 + cov23));

  const portSharpe = (portRet / portVol).toFixed(2);
  // Условная стресс-оценка просадки: волатильность × эвристический коэффициент.
  // Это НЕ рассчитанный исторический Max Drawdown — реальная просадка зависит от пути цен.
  const maxDD = ((portVol * 1.8) * 100).toFixed(1);

  // Трекинг для бейджа «Архитектор Риск-Паритета» (критерий: Sharpe > 2.0)
  if(parseFloat(portSharpe) > 2.0 && simActionStats.port !== true){
    simActionStats.port = true;
    save();
    checkAndUnlockBadge('port');
  }

  const resBox = $('#pf_result_box');
  resBox.innerHTML = `
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
      <div class="pitem"><div class="lbl">Ожидаемая доходность портфеля:</div><div class="val" style="font-weight:800; color:var(--ok)">+${(portRet*100).toFixed(1)}% годовых</div></div>
      <div class="pitem"><div class="lbl">Совокупная волатильность (σ):</div><div class="val" style="font-weight:800; color:var(--acc2)">${(portVol*100).toFixed(1)}%</div></div>
      <div class="pitem"><div class="lbl">Итоговый Sharpe Ratio:</div><div class="val" style="font-weight:800; font-size:18px; color:${portSharpe>2.0?'var(--ok)':'var(--warn)'}">⚡ ${portSharpe}</div></div>
      <div class="pitem"><div class="lbl">Условная стресс-оценка просадки:</div><div class="val" style="font-weight:800; color:${maxDD<15?'var(--ok)':'var(--bad)'}">−${maxDD}%</div></div>
    </div>
    <p style="margin-top:10px; font-size:12px; color:var(--warn)">
      ⚠️ Упрощение модели: «стресс-оценка просадки» здесь = σ × 1.8 (эвристика), а не рассчитанный по истории Max Drawdown. Корреляция задаётся одним ползунком и применяется ко всем трём парам стратегий одинаково (в реальности корреляции различаются и меняются в кризис).
    </p>
    <p style="margin-top:8px; font-size:13px; color:var(--mut)">
      ${corr > 0.5 ? '⚠️ Внимание: При высокой корреляции (стресс-рынок) диверсификационный эффект снижается.' : '💡 Отличная диверсификация: низкая корреляция гасит локальные просадки и поднимает Шарп выше отдельных компонентов.'}
    </p>
  `;
}

/* FRACTIONAL KELLY SIMULATOR & MONTE CARLO */
function initKellySim(){
  calcKellySim();
}

function kellyFraction(win, rr){
  // f* = (p*b − q)/b; при edge ≤ 0 доля = 0 (позиция не открывается)
  return Math.max(0, (win * rr - (1 - win)) / rr);
}

function calcKellySim(){
  const win = (parseFloat($('#k_win').value) || 50) / 100;
  const rr = parseFloat($('#k_rr').value) || 1.0;
  const cap = parseFloat($('#k_cap').value) || 10000;

  const fFull = kellyFraction(win, rr);
  const fHalf = fFull * 0.5;
  const fQuarter = fFull * 0.25;
  const noEdge = fFull <= 0;

  const resBox = $('#k_result_box');
  if(resBox){
    resBox.innerHTML = noEdge ? `
      <div style="padding:14px; border-radius:10px; background:rgba(239,68,68,.10); border-left:4px solid var(--bad); font-size:13px; color:var(--txt); line-height:1.6">
        🚨 <b>Математического преимущества нет (Kelly ≤ 0): корректный размер позиции — 0% ($0).</b><br>
        При p·b ≤ q матожидание каждой ставки отрицательное или нулевое. Дробные Келли в такой ситуации — не «безопасный минимум», а способ медленно терять капитал.
      </div>
    ` : `
      <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
        <div class="pitem"><div class="lbl">Full Kelly (1.0x):</div><div class="val" style="font-weight:800; color:var(--bad)">${(fFull*100).toFixed(1)}% ($${(cap*fFull).toFixed(0)}) <span style="font-size:11px; display:block; color:var(--bad)">Максимум скорости роста лог-капитала и максимальная дисперсия пути</span></div></div>
        <div class="pitem"><div class="lbl">Half Kelly (0.5x):</div><div class="val" style="font-weight:800; color:var(--warn)">${(fHalf*100).toFixed(1)}% ($${(cap*fHalf).toFixed(0)}) <span style="font-size:11px; display:block; color:var(--warn)">Компромисс: меньшая волатильность при сохранении большей части темпа роста</span></div></div>
        <div class="pitem"><div class="lbl">Quarter Kelly (0.25x):</div><div class="val" style="font-weight:800; color:var(--ok)">${(fQuarter*100).toFixed(1)}% ($${(cap*fQuarter).toFixed(0)}) <span style="font-size:11px; display:block; color:var(--ok)">Консервативная практика на случай переоценки p и b</span></div></div>
      </div>
      <div style="margin-top:8px; font-size:11.5px; color:var(--mut)">Оценки чувствительны к точности p и b: завышенный винрейт сдвигает все доли вверх. Реальные просадки зависят от параметров — смотри Монте-Карло ниже.</div>
    `;
  }

  runKellyMonteCarlo();
}

function runKellyMonteCarlo(){
  const win = (parseFloat($('#k_win').value) || 50) / 100;
  const rr = parseFloat($('#k_rr').value) || 1.0;
  const cap = parseFloat($('#k_cap').value) || 10000;

  const TRAJS = 1000, TRADES = 100;
  const fracs=[
    ['Full Kelly', kellyFraction(win, rr), '#ef4444'],
    ['Half Kelly', kellyFraction(win, rr) * 0.5, '#f59e0b'],
    ['Quarter Kelly', kellyFraction(win, rr) * 0.25, '#22c55e']
  ];

  const stats=fracs.map(([name,f,color])=>{
    const finals=new Array(TRAJS);
    const maxDDs=new Array(TRAJS);
    const avgPath=new Array(TRADES+1).fill(0);
    for(let t=0;t<TRAJS;t++){
      let eq=cap, peak=cap, maxDD=0;
      for(let s=0;s<TRADES;s++){
        const bet=eq*f;
        if(bet>0){
          eq += (Math.random()<win)? bet*rr : -bet;
          if(eq<0) eq=0;
          if(eq>peak) peak=eq;
          const dd=(peak-eq)/(peak||1);
          if(dd>maxDD) maxDD=dd;
        }
        avgPath[s+1]+=eq;
      }
      finals[t]=eq; maxDDs[t]=maxDD;
    }
    finals.sort((a,b)=>a-b); maxDDs.sort((a,b)=>a-b);
    for(let s=0;s<=TRADES;s++) avgPath[s]/=TRAJS;
    return {
      name,color,f,
      median:finals[Math.floor(TRAJS/2)],
      p5:finals[Math.floor(TRAJS*0.05)],
      p95:finals[Math.floor(TRAJS*0.95)],
      medDD:maxDDs[Math.floor(TRAJS/2)]*100,
      loss50:finals.filter(v=>v<cap*0.5).length/TRAJS*100,
      path:avgPath
    };
  });

  // Трекинг для бейджа «Математик Сайзинга Келли» (Монте-Карло выполнен: 1000 сессий ≥ 100 из описания)
  if(simActionStats.kelly !== true){
    simActionStats.kelly = true;
    save();
    checkAndUnlockBadge('kelly');
  }

  const box=document.getElementById('k_mc_stats');
  if(box){
    box.innerHTML=`
      <div style="background:#090d1f; border:1px solid var(--line); border-radius:12px; padding:16px">
        <div style="font-weight:800; color:var(--acc2); font-size:13px; margin-bottom:10px">📊 Монте-Карло: ${TRAJS.toLocaleString()} траекторий × ${TRADES} сделок (фиксированная доля от текущего капитала)</div>
        <table class="order-book-table" style="width:100%; font-size:12.5px">
          <thead><tr><th>Стратегия</th><th>Доля</th><th>Медиана финала</th><th>5–95 перцентиль</th><th>Медианная Max DD</th><th>P(потеря >50%)</th></tr></thead>
          <tbody>
            ${stats.map(s=>`<tr>
              <td style="color:${s.color}; font-weight:700">${s.name}</td>
              <td>${(s.f*100).toFixed(1)}%</td>
              <td>$${Math.round(s.median).toLocaleString()}</td>
              <td>$${Math.round(s.p5).toLocaleString()} … $${Math.round(s.p95).toLocaleString()}</td>
              <td>${s.medDD.toFixed(1)}%</td>
              <td style="color:${s.loss50>30?'var(--bad)':(s.loss50>10?'var(--warn)':'var(--ok)')}; font-weight:700">${s.loss50.toFixed(1)}%</td>
            </tr>`).join('')}
          </tbody>
        </table>
        <div style="margin-top:8px; font-size:11.5px; color:var(--mut)">График ниже — средняя траектория по всем прогонам; отдельные траектории могут сильно отклоняться от неё. Результаты не являются обещанием доходности.</div>
      </div>`;
  }

  drawKellyCanvas(stats[0].path, stats[1].path, stats[2].path);
}

function drawKellyCanvas(full, half, quarter){
  const canvas = document.getElementById('kelly_canvas');
  if(!canvas) return;
  if(!canvas || !canvas.getContext) return; const ctx = canvas.getContext('2d');
  const w = canvas.width;
  const h = canvas.height;

  ctx.clearRect(0,0,w,h);

  // Background Grid
  ctx.strokeStyle = 'rgba(255,255,255,0.06)';
  ctx.lineWidth = 1;
  for(let y=20; y<h; y+=40){
    ctx.beginPath(); ctx.moveTo(40,y); ctx.lineTo(w-20,y); ctx.stroke();
  }

  const allVals = [...full, ...half, ...quarter];
  const maxVal = Math.max(...allVals) * 1.05;
  const minVal = Math.min(...allVals) * 0.95;

  const getX = (idx) => 40 + (idx / 100) * (w - 60);
  const getY = (val) => (h - 25) - ((val - minVal) / (maxVal - minVal + 1)) * (h - 50);

  // Axes
  ctx.strokeStyle = 'rgba(255,255,255,0.2)';
  ctx.beginPath(); ctx.moveTo(40, 15); ctx.lineTo(40, h-25); ctx.lineTo(w-20, h-25); ctx.stroke();

  // Draw Full Kelly (Red)
  ctx.strokeStyle = '#ef4444';
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  full.forEach((v,i)=>{ const x=getX(i), y=getY(v); if(i===0)ctx.moveTo(x,y); else ctx.lineTo(x,y); });
  ctx.stroke();

  // Draw Half Kelly (Yellow)
  ctx.strokeStyle = '#f59e0b';
  ctx.lineWidth = 2.0;
  ctx.beginPath();
  half.forEach((v,i)=>{ const x=getX(i), y=getY(v); if(i===0)ctx.moveTo(x,y); else ctx.lineTo(x,y); });
  ctx.stroke();

  // Draw Quarter Kelly (Green)
  ctx.strokeStyle = '#22c55e';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  quarter.forEach((v,i)=>{ const x=getX(i), y=getY(v); if(i===0)ctx.moveTo(x,y); else ctx.lineTo(x,y); });
  ctx.stroke();

  // Legend
  ctx.font = '11px sans-serif';
  ctx.fillStyle = '#ef4444'; ctx.fillText('● Full Kelly (средняя траектория)', w - 240, 25);
  ctx.fillStyle = '#f59e0b'; ctx.fillText('● Half Kelly (0.5x)', w - 240, 42);
  ctx.fillStyle = '#22c55e'; ctx.fillText('● Quarter Kelly (0.25x)', w - 240, 59);
}


/* =========================================================================
   ДОПОЛНЕНИЯ СИМУЛЯТОРОВ ФАЗЫ 4 (3-НДФЛ FIFO, 115-ФЗ И KILL-SWITCH)
   ========================================================================= */
/* =========================================================================
   ДОПОЛНЕНИЯ СИМУЛЯТОРОВ ФАЗЫ 4 (3-НДФЛ FIFO, N СДЕЛОК, ВЫЧЕТ КОМИССИЙ И CSV)
   ========================================================================= */
let taxTrades = [
  { id: 1, date: '2025-02-10', type: 'BUY', asset: 'BTC', qty: 0.40, amount: 2000000, fee: 2000 },
  { id: 2, date: '2025-04-15', type: 'BUY', asset: 'BTC', qty: 0.50, amount: 3000000, fee: 3000 },
  { id: 3, date: '2025-08-20', type: 'SELL', asset: 'BTC', qty: 0.60, amount: 4800000, fee: 4800 },
  { id: 4, date: '2025-11-05', type: 'SELL', asset: 'BTC', qty: 0.20, amount: 1900000, fee: 1900 }
];

function initTaxSim(){
  renderTaxTradesTable();
  calcTaxSim();
}

function renderTaxTradesTable(){
  const tbody = $('#tax_trades_tbody');
  if(!tbody) return;

  tbody.innerHTML = taxTrades.map((t, idx) => `
    <tr>
      <td><input type="date" value="${t.date}" style="padding:3px 6px; font-size:11.5px" onchange="updateTaxTrade(${idx}, 'date', this.value)"></td>
      <td><b style="color:${t.type==='BUY'?'var(--ok)':'var(--acc2)'}">${t.type==='BUY'?'ПОКУПКА':'ПРОДАЖА'}</b></td>
      <td><b>${t.asset}</b></td>
      <td><input type="number" step="0.01" value="${t.qty}" style="width:70px; padding:3px 6px; font-size:11.5px" oninput="updateTaxTrade(${idx}, 'qty', parseFloat(this.value)||0)"></td>
      <td><input type="number" step="10000" value="${t.amount}" style="width:105px; padding:3px 6px; font-size:11.5px" oninput="updateTaxTrade(${idx}, 'amount', parseFloat(this.value)||0)"></td>
      <td><input type="number" step="100" value="${t.fee}" style="width:75px; padding:3px 6px; font-size:11.5px" oninput="updateTaxTrade(${idx}, 'fee', parseFloat(this.value)||0)"></td>
      <td><button class="btn ghost sm" style="padding:2px 6px; font-size:11px; color:var(--bad)" onclick="removeTaxTrade(${idx})">✕</button></td>
    </tr>
  `).join('');
}

function updateTaxTrade(idx, field, val){
  if(taxTrades[idx]){
    taxTrades[idx][field] = val;
    calcTaxSim();
  }
}

function addTaxTrade(type){
  const nextId = taxTrades.length ? Math.max(...taxTrades.map(t=>t.id)) + 1 : 1;
  taxTrades.push({
    id: nextId,
    date: new Date().toISOString().slice(0,10),
    type: type,
    asset: 'BTC',
    qty: type==='BUY'?0.2:0.2,
    amount: type==='BUY'?1000000:1300000,
    fee: 1000
  });
  renderTaxTradesTable();
  calcTaxSim();
}

function removeTaxTrade(idx){
  taxTrades.splice(idx, 1);
  renderTaxTradesTable();
  calcTaxSim();
}

function calcTaxSim(){
  // 1. Sort trades chronologically
  const sorted = [...taxTrades].sort((a,b) => new Date(a.date) - new Date(b.date));

  let buyQueue = [];
  let totalGrossIncome = 0;
  let totalCostDeduction = 0;   // себестоимость активов (без комиссий)
  let buyFeesConsumed = 0;      // комиссии покупок, пропорционально списанные с проданных партий
  let sellFeesTotal = 0;        // комиссии продаж (списываются полностью в момент продажи)

  sorted.forEach(trade => {
    if(trade.type === 'BUY'){
      buyQueue.push({
        qty: trade.qty,
        costPerUnit: trade.qty > 0 ? trade.amount / trade.qty : 0,
        amount: trade.amount,
        feeLeft: trade.fee || 0   // остаток комиссии покупки живёт на лоте до его полной продажи
      });
    } else if(trade.type === 'SELL'){
      totalGrossIncome += trade.amount;
      sellFeesTotal += (trade.fee || 0);
      let remainingQtyToSell = trade.qty;

      while(remainingQtyToSell > 0 && buyQueue.length > 0){
        let oldestBuy = buyQueue[0];
        const consumed = Math.min(oldestBuy.qty, remainingQtyToSell);
        // Комиссия приобретения списывается ПРОПОРЦИОНАЛЬНО проданному количеству
        const feePortion = oldestBuy.qty > 0 ? oldestBuy.feeLeft * (consumed / oldestBuy.qty) : 0;
        totalCostDeduction += consumed * oldestBuy.costPerUnit;
        buyFeesConsumed += feePortion;
        oldestBuy.qty -= consumed;
        oldestBuy.feeLeft -= feePortion;
        remainingQtyToSell -= consumed;
        if(oldestBuy.qty <= 1e-9) buyQueue.shift(); // лот полностью закрыт
      }
    }
  });

  // Расходы = себестоимость проданных активов (FIFO) + комиссии, относящиеся к этим продажам
  // (комиссии покупки — только в доле проданного количества; остаток остаётся на непроданном лоте)
  const totalFees = buyFeesConsumed + sellFeesTotal;
  const totalExpenses = totalCostDeduction + totalFees;
  const taxableProfit = Math.max(0, totalGrossIncome - totalExpenses);

  // Progressive Tax Rate 2025: 13% up to 2.4M, 15% above 2.4M
  // D0.2-К5: полная пятиступенчатая шкала НДФЛ-2025 (база складывается с прочими доходами)
  const NDFL_BRACKETS = [
    { upTo: 2400000,  rate: 0.13 },
    { upTo: 5000000,  rate: 0.15 },
    { upTo: 20000000, rate: 0.18 },
    { upTo: 50000000, rate: 0.20 },
    { upTo: Infinity, rate: 0.22 }
  ];
  const taxParts = [];
  let _prev = 0, totalTax = 0;
  for(const br of NDFL_BRACKETS){
    if(taxableProfit > _prev){
      const part = (Math.min(taxableProfit, br.upTo) - _prev) * br.rate;
      taxParts.push({ rate: br.rate, upTo: br.upTo, tax: part });
      totalTax += part;
      _prev = br.upTo;
    } else break;
  }

  const resBox = $('#tax_result_box');
  if(!resBox) return;

  resBox.innerHTML = `
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
      <div class="pitem"><div class="lbl">Валовой доход от продаж:</div><div class="val" style="font-weight:800">${Math.round(totalGrossIncome).toLocaleString()} ₽</div></div>
      <div class="pitem"><div class="lbl">Себестоимость покупок (FIFO):</div><div class="val" style="font-weight:800; color:var(--mut)">${Math.round(totalCostDeduction).toLocaleString()} ₽</div></div>
      <div class="pitem"><div class="lbl">Комиссии по проданным партиям:</div><div class="val" style="font-weight:800; color:var(--acc2)">−${Math.round(totalFees).toLocaleString()} ₽ <span style="font-weight:400; font-size:11px">(покупки ${Math.round(buyFeesConsumed).toLocaleString()} + продажи ${Math.round(sellFeesTotal).toLocaleString()})</span></div></div>
      <div class="pitem"><div class="lbl">Чистая налоговая база:</div><div class="val" style="font-weight:800; color:var(--ok)">${Math.round(taxableProfit).toLocaleString()} ₽</div></div>
      ${taxParts.map(p => `<div class="pitem"><div class="lbl">НДФЛ ${Math.round(p.rate*100)}% (ступень до ${p.upTo===Infinity?'∞':(p.upTo/1e6)+' млн'} ₽):</div><div class="val" style="font-weight:800; color:${p.rate>0.13?'var(--warn)':'var(--txt)'}">${Math.round(p.tax).toLocaleString()} ₽</div></div>`).join('')}
      <div class="pitem"><div class="lbl" style="font-size:11px; color:var(--mut)">Шкала-2025: 13% ≤2.4 млн · 15% 2.4–5 · 18% 5–20 · 20% 20–50 · 22% >50 млн ₽; база складывается с прочими доходами</div><div></div></div>
      <div class="pitem" style="grid-column:1/-1; background:rgba(6,182,212,.08); border-color:var(--acc2)"><div class="lbl" style="color:var(--txt)">ИТОГО НАЛОГ К УПЛАТЕ В БЮДЖЕТ РФ:</div><div class="val" style="font-weight:900; font-size:22px; color:var(--acc2)">⚡ ${Math.round(totalTax).toLocaleString()} ₽</div></div>
    </div>
    <div style="margin-top:12px; font-size:12.5px; color:var(--mut); line-height:1.5">
      ⚖️ <b>Правовая справка (418-ФЗ от 29.11.2024):</b> Налоговая база рассчитывается как превышение доходов от реализации цифровой валюты над документально подтвержденными расходами на ее приобретение и уплату биржевых комиссий.
    </div>
    <div style="margin-top:10px; padding:10px 12px; border-radius:8px; background:rgba(6,182,212,.06); border-left:3px solid var(--acc2); font-size:12px; color:var(--txt); line-height:1.55">
      🧮 <b>Пример пропорционального списания комиссии:</b> куплено 2 BTC за 1 000 000 ₽ с комиссией покупки 1 000 ₽, затем продано 0.5 BTC (¼ лота). В расходы по этой продаже идёт только ¼ комиссии — <b>250 ₽</b> (1000 × 0.5/2). Остаток <b>750 ₽</b> остаётся на непроданной части лота и спишется при продаже оставшихся 1.5 BTC.
    </div>
  `;
}

function exportTaxToCSV(){
  let csvContent = "data:text/csv;charset=utf-8,\uFEFF";
  csvContent += "ID,Дата,Тип операции,Актив,Количество,Сумма в рублях,Комиссия в рублях\n";

  taxTrades.forEach(t => {
    csvContent += `${t.id},${t.date},${t.type==='BUY'?'Покупка':'Продажа'},${t.asset},${t.qty},${t.amount},${t.fee}\n`;
  });

  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  link.setAttribute("href", encodedUri);
  link.setAttribute("download", `3_NDFL_crypto_tax_report_${new Date().getFullYear()}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  recordTaxCsvExportAction(); // трекинг для бейджа «Налоговый Инженер 3-НДФЛ»
}

