function init115FzSim(){
  curFzIdx = 0;
  // Динамический подсчёт ситуаций из массива (вместо жёстко зашитого числа)
  const cntEl = document.getElementById('fz_total_count');
  if(cntEl) cntEl.textContent = FZ_CASES.length;
  render115FzCard();
}

function render115FzCard(){
  const item = FZ_CASES[curFzIdx];
  const card = document.getElementById('fz_card');
  const optsBox = document.getElementById('fz_options');
  const fb = document.getElementById('fz_feedback');
  if(!card || !optsBox) return;

  if(fb) fb.style.display = 'none';

  card.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; flex-wrap:wrap; gap:8px">
      <span style="font-size:12px; font-weight:800; color:var(--acc2)">Ситуация ${item.id} из ${FZ_CASES.length}</span>
      <span style="font-size:11.5px; font-weight:700; background:rgba(255,255,255,.06); padding:3px 8px; border-radius:6px; color:var(--warn)">${item.riskLevel}</span>
    </div>
    <h4 style="color:var(--txt); font-size:16px; margin-bottom:8px">${item.title}</h4>
    <p style="color:var(--mut); font-size:13.5px; line-height:1.5; margin:0">${item.desc}</p>
  `;

  optsBox.innerHTML = item.options.map((opt, i)=>`
    <button class="ans" onclick="handleFzAnswer(${i})">${opt.text}</button>
  `).join('');
}

function handleFzAnswer(optIdx){
  const item = FZ_CASES[curFzIdx];
  const opt = item.options[optIdx];
  const fb = document.getElementById('fz_feedback');
  if(!fb) return;
  fb.style.display = 'block';

  const nextCaseText = curFzIdx === FZ_CASES.length - 1 ? 'Начать сначала 🔄' : 'Следующая ситуация →';

  if(opt.correct){
    fb.style.background = 'rgba(34,197,94,.15)';
    fb.style.border = '1px solid var(--ok)';
    fb.innerHTML = `<div>${opt.exp}</div><button class="btn sm" style="margin-top:12px" onclick="nextFzCase()">${nextCaseText}</button>`;
  } else {
    fb.style.background = 'rgba(239,68,68,.15)';
    fb.style.border = '1px solid var(--bad)';
    fb.innerHTML = `<div>${opt.exp}</div><button class="btn sm" style="margin-top:12px" onclick="nextFzCase()">${nextCaseText}</button>`;
  }
}

function nextFzCase(){
  curFzIdx = (curFzIdx + 1) % FZ_CASES.length;
  render115FzCard();
}

/* KILL-SWITCH CRASH SIMULATOR (HONEST GAP & EXECUTION SLIPPAGE) */
function runCrashSimulation(){
  const dep = parseFloat($('#ks_deposit').value) || 50000;
  const limitPct = parseFloat($('#ks_limit').value) || 2.0;
  const gapPct = parseFloat($('#ks_gap').value) || 0.5;
  const resBox = $('#ks_result_box');
  resBox.style.display = 'block';

  // Honest actual loss = Limit + Execution Gap (stop executes WORSE than theoretical limit)
  const actualLossPct = limitPct + gapPct;
  const actualLossUsd = dep * (actualLossPct / 100);
  const theoreticalLossUsd = dep * (limitPct / 100);
  const savedBalance = dep - actualLossUsd;

  // Сценарий «без Kill-Switch»: результат РАССЧИТЫВАЕТСЯ из параметров сценария,
  // а не задаётся заранее. Убыток по залогу ≈ движение × плечо, максимум −100% (учебная модель).
  const levNoKs = parseFloat($('#ks_lev_no_ks')?.value) || 3;
  const moveNoKs = parseFloat($('#ks_move_no_ks')?.value) || 12;
  const lossNoKsPct = Math.min(100, moveNoKs * levNoKs);
  const withoutKsBalance = dep * (1 - lossNoKsPct / 100);

  const isWorse = gapPct > 0.1;

  // Трекинг для бейджа «Страж Надежности» (стресс-тест Kill-Switch выполнен)
  if(simActionStats.killswitch !== true){
    simActionStats.killswitch = true;
    save();
    checkAndUnlockBadge('killswitch');
  }

  resBox.innerHTML = `
    <div style="font-weight:800; color:var(--bad); font-size:16px; margin-bottom:10px">🚨 РЕЗУЛЬТАТЫ СТРЕСС-ТЕСТА СРАБАТЫВАНИЯ KILL-SWITCH (учебная модель исполнения):</div>
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
      <div class="pitem"><div class="lbl">Заданный порог отсечки:</div><div class="val" style="color:var(--txt); font-weight:800">−${limitPct.toFixed(1)}% (−$${theoreticalLossUsd.toFixed(0)})</div></div>
      <div class="pitem"><div class="lbl">Гэп исполнения (Execution Gap):</div><div class="val" style="color:var(--bad); font-weight:800">+${gapPct.toFixed(2)}% (Проскальзывание в стакане)</div></div>
      <div class="pitem"><div class="lbl">Фактический зафиксированный убыток:</div><div class="val" style="color:${actualLossPct>3?'var(--bad)':'var(--warn)'}; font-weight:800; font-size:18px">−${actualLossPct.toFixed(2)}% (−$${Math.round(actualLossUsd).toLocaleString()})</div></div>
      <div class="pitem"><div class="lbl">Остаток сохраненного капитала:</div><div class="val" style="color:var(--ok); font-weight:800; font-size:18px">$${Math.round(savedBalance).toLocaleString()} (${(savedBalance/dep*100).toFixed(1)}%)</div></div>
    </div>
    <div style="margin-top:14px; padding:12px; border-radius:10px; background:rgba(255,255,255,0.04); font-size:13px; line-height:1.5">
      <b>🔍 Честный квант-анализ исполнения:</b><br>
      • Из-за резкого расширения спреда и очереди ордеров маркет-стоп закрылся <b>хуже заданного лимита на $${Math.round(actualLossUsd - theoreticalLossUsd).toLocaleString()}</b>.<br>
      • В выбранном сценарии БЕЗ Kill-Switch (плечо x${levNoKs}, движение −${moveNoKs}% против позиции) расчётный убыток по залогу: <b>−$${Math.round(dep - withoutKsBalance).toLocaleString()} (−${lossNoKsPct.toFixed(0)}%${lossNoKsPct>=100?', позиция ликвидирована':''})</b>, остаток $${Math.round(withoutKsBalance).toLocaleString()}.<br>
      • Это не приговор «всегда −58%» и не обещание: итог без защиты зависит от того, насколько далеко уйдёт цена и как быстро вы вмешаетесь вручную.<br>
      <span style="color:var(--acc2); font-weight:700">Вывод: в реальном риск-менеджменте всегда закладывается Execution Gap от 0.3% до 1.5% сверх целевого порога отсечки.</span>
    </div>
  `;
}

/* =========================================================================
   ДОПОЛНЕНИЯ СИМУЛЯТОРОВ ФАЗЫ 5 (МАСШТАБИРОВАНИЕ И РЕБАЛАНСИРОВКА 40/40/20)
   ========================================================================= */
function initScalingSim(){
  calcScalingSim();
}

function calcScalingSim(){
  const cap = parseFloat($('#sc_cap').value) || 6000000;
  const type = $('#sc_type').value;

  let baseRet = 0, slippagePct = 0, capacityLimit = 0, stratName = '';

  if(type === 'port40'){
    stratName = 'Портфель 40/40/20 (Многостратегический)';
    baseRet = 28.0; // 28% gross
    capacityLimit = 50000000; // 50M rub
    slippagePct = 0.02 + (cap / capacityLimit) * 0.04;
  } else if(type === 'pairs'){
    stratName = 'Парный арбитраж Top-10 пар';
    baseRet = 38.0;
    capacityLimit = 15000000; // 15M rub
    slippagePct = 0.02 + (cap / capacityLimit) * 0.12;
  } else {
    stratName = 'Микро-скальпинг альтами';
    baseRet = 55.0;
    capacityLimit = 1500000; // 1.5M rub
    slippagePct = 0.02 + (cap / capacityLimit) * 0.55;
  }

  const netRet = Math.max(-15, baseRet - (slippagePct * 200)); // friction effect
  const expectedProfitRub = Math.round(cap * (netRet / 100));
  const isBroken = netRet <= 0 || (cap > capacityLimit && type === 'scalp');

  const resBox = $('#sc_result_box');
  resBox.innerHTML = `
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
      <div class="pitem"><div class="lbl">Торговый капитал:</div><div class="val" style="font-weight:800">${cap.toLocaleString()} ₽ ($${Math.round(cap/92).toLocaleString()})</div></div>
      <div class="pitem"><div class="lbl">Слиппедж на сделку (Market Impact):</div><div class="val" style="font-weight:800; color:${slippagePct>0.1?'var(--bad)':'var(--ok)'}">${(slippagePct*100).toFixed(2)}%</div></div>
      <div class="pitem"><div class="lbl">Чистая годовая доходность (Net APR):</div><div class="val" style="font-weight:800; font-size:18px; color:${netRet>15?'var(--ok)':netRet>0?'var(--warn)':'var(--bad)'}">⚡ ${netRet.toFixed(1)}% APR</div></div>
      <div class="pitem"><div class="lbl">Ожидаемая годовая прибыль:</div><div class="val" style="font-weight:800; color:${expectedProfitRub>0?'var(--ok)':'var(--bad)'}">${expectedProfitRub.toLocaleString()} ₽</div></div>
    </div>
    <p style="margin-top:12px; font-size:13px; color:${isBroken?'var(--bad)':'var(--mut)'}">
      ${isBroken ? '❌ ВНИМАНИЕ: Превышен лимит ёмкости стратегии! Проскальзывание крупного сайза полностью уничтожило альфу. Переходите на портфельную архитектуру 40/40/20.' : '💡 Отличная масштабируемость: емкость ликвидности позволяет эффективно переваривать сайз без существенного рыночного влияния.'}
    </p>
  `;
}

/* REBALANCER 40/40/20 & DRAWDOWN RECOVERY */
function initRebalanceSim(){
  calcRebalanceSim();
}

function calcRebalanceSim(){
  const c1 = parseFloat($('#rb_c1').value) || 0;
  const c2 = parseFloat($('#rb_c2').value) || 0;
  const c3 = parseFloat($('#rb_c3').value) || 0;

  const total = c1 + c2 + c3;
  if(total <= 0) return;

  const target1 = total * 0.40;
  const target2 = total * 0.40;
  const target3 = total * 0.20;

  const diff1 = target1 - c1;
  const diff2 = target2 - c2;
  const diff3 = target3 - c3;

  const resBox = $('#rb_result_box');
  resBox.innerHTML = `
    <div style="font-weight:800; color:var(--acc2); margin-bottom:10px">Суммарный капитал портфеля: ${total.toLocaleString()} ₽</div>
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
      <div class="pitem"><div class="lbl">1. Дельта-нейтральная (Цель 40% = ${Math.round(target1).toLocaleString()} ₽):</div><div class="val" style="font-weight:800; color:${diff1<0?'var(--ok)':'var(--warn)'}">Факт: ${c1.toLocaleString()} ₽ (${(c1/total*100).toFixed(1)}%) <br><span style="font-size:12px">${diff1>0?'Пополнить на +'+Math.round(diff1).toLocaleString()+' ₽':'Снять излишек −'+Math.round(Math.abs(diff1)).toLocaleString()+' ₽'}</span></div></div>
      <div class="pitem"><div class="lbl">2. Активный эдж (Цель 40% = ${Math.round(target2).toLocaleString()} ₽):</div><div class="val" style="font-weight:800; color:${diff2<0?'var(--ok)':'var(--warn)'}">Факт: ${c2.toLocaleString()} ₽ (${(c2/total*100).toFixed(1)}%) <br><span style="font-size:12px">${diff2>0?'Пополнить на +'+Math.round(diff2).toLocaleString()+' ₽':'Снять излишек −'+Math.round(Math.abs(diff2)).toLocaleString()+' ₽'}</span></div></div>
      <div class="pitem"><div class="lbl">3. Ликвидный резерв (Цель 20% = ${Math.round(target3).toLocaleString()} ₽):</div><div class="val" style="font-weight:800; color:${diff3<0?'var(--ok)':'var(--warn)'}">Факт: ${c3.toLocaleString()} ₽ (${(c3/total*100).toFixed(1)}%) <br><span style="font-size:12px">${diff3>0?'Пополнить на +'+Math.round(diff3).toLocaleString()+' ₽':'Снять излишек −'+Math.round(Math.abs(diff3)).toLocaleString()+' ₽'}</span></div></div>
    </div>
    <div style="margin-top:16px; padding:12px; border-radius:10px; background:rgba(255,255,255,.05)">
      <div style="font-weight:700; color:var(--txt); margin-bottom:4px">📐 Памятка нелинейности просадок (Recovery Law):</div>
      <div style="font-size:12.5px; color:var(--mut); line-height:1.6">
        • Просадка −10% требует <b>+11.1%</b> для выхода в безубыток<br>
        • Просадка −20% требует <b>+25.0%</b><br>
        • Просадка −35% требует <b>+53.8%</b><br>
        • Просадка −50% требует <b>+100.0%</b> (удвоение счета!)<br>
        • Просадка −75% требует <b>+300.0%</b><br>
        <span style="color:var(--acc2); font-weight:700">Именно поэтому архитектура 40/40/20 с жестким контролем рисков — единственный надежный путь сохранения и приумножения капитала 5–6 млн рублей.</span>
      </div>
    </div>
  `;
}

