function renderPhases(){
  const box = document.getElementById('phases');
  if(!box) return;

  drawInteractiveSvgRoadmap();

  box.innerHTML = PHASES.map(ph => {
    const isPassed = (phaseTestsDone[`p${ph.p}`] || 0) >= 80 || (ph.p === 0 && (phaseTestsDone['test_literacy_zero'] || 0) >= 80);
    const lessonsInPhase = LESSONS.filter(l => l.phase === ph.p);
    const doneCount = lessonsInPhase.filter(l => lessonsDone[l.id] === 1).length;
    const totalCount = lessonsInPhase.length;
    const isAllLessonsDone = totalCount > 0 && doneCount === totalCount;
    const testScore = ph.p === 0 ? (phaseTestsDone['p0'] || phaseTestsDone['test_literacy_zero'] || 0) : (phaseTestsDone[`p${ph.p}`] || 0);

    return `
      <div class="phase-card ${isPassed ? 'done' : ''}" style="background:var(--card); border:1.5px solid ${isPassed?'var(--ok)':'var(--line)'}; border-radius:14px; padding:20px; margin-bottom:16px; box-shadow:var(--shadow)">
        <div style="display:flex; justify-content:space-between; align-items:flex-start; flex-wrap:wrap; gap:10px; margin-bottom:10px">
          <div>
            <div style="font-size:12px; font-weight:800; color:${ph.p===0?'var(--ok)':'var(--acc2)'}; text-transform:uppercase; margin-bottom:4px">${ph.time}</div>
            <h3 style="margin:0 0 6px; font-size:18px; color:var(--txt)">${ph.title}</h3>
            <div style="font-size:13px; color:var(--mut); line-height:1.5">${ph.desc}</div>
          </div>
          <div style="text-align:right">
            <span class="badge" style="background:${isAllLessonsDone?'rgba(34,197,94,.15)':'rgba(6,182,212,.15)'}; color:${isAllLessonsDone?'var(--ok)':'var(--acc2)'}; font-size:12px">
              Уроки: ${doneCount}/${totalCount}
            </span>
            <div style="font-size:11.5px; color:${isPassed?'var(--ok)':'var(--mut)'}; margin-top:4px; font-weight:700">
              ${isPassed ? `✓ Тест сдан (${testScore}%)` : `Тест не сдан (${testScore}%)`}
            </div>
          </div>
        </div>

        <div style="background:#040714; padding:12px 14px; border-radius:8px; margin:12px 0">
          <div style="font-size:11.5px; font-weight:800; color:var(--mut); text-transform:uppercase; margin-bottom:6px">🎯 Ключевые цели и задачи фазы:</div>
          <ul style="margin:0; padding-left:18px; font-size:12.5px; color:var(--txt); line-height:1.6">
            ${ph.tasks.map(t => `<li>${t}</li>`).join('')}
          </ul>
        </div>

        <div style="display:flex; gap:10px; flex-wrap:wrap; margin-top:14px">
          <button class="btn sm" style="${ph.p===0?'background:var(--ok)':''}" onclick="go('lessons'); renderPhaseLessonsView(${ph.p});">
            📖 Перейти к урокам фазы (${totalCount})
          </button>
          <button class="btn sm ghost" onclick="go('tests'); ${ph.p===0?'startPhase0Test()':'startPhaseTest('+ph.p+')'};">
            📝 Сдать аттестационный тест
          </button>
        </div>
      </div>
    `;
  }).join('');
}

function runStationaritySim(){
  const scenarioEl = document.getElementById('st_scenario');
  const scenario = scenarioEl ? scenarioEl.value : 'mean_rev';
  const resBox = document.getElementById('st_result_box');

  // Трекинг для бейджа «Метролог Стационарности»
  if(!simActionStats.stat) simActionStats.stat = { tested: [] };
  if(!simActionStats.stat.tested.includes(scenario)){
    simActionStats.stat.tested.push(scenario);
    save();
    checkAndUnlockBadge('stat');
  }

  let adfP = 0, kpssP = 0, isStat = false, verdict = '', exp = '';
  let points = [];

  const N = 100;
  if(scenario === 'mean_rev'){
    adfP = 0.008; kpssP = 0.42; isStat = true;
    verdict = '✅ СТРОГО СТАЦИОНАРЕН (ADF p<0.05 И KPSS p>0.05)';
    exp = 'Идеальный стационарный процесс возврата к среднему (Ornstein-Uhlenbeck). Дисперсия и среднее стабильны во времени. Пригодно для парного арбитража.';
    let val = 0;
    for(let i=0; i<N; i++){ val = val * 0.7 + (Math.random() - 0.5) * 2; points.push(val); }
  } else if(scenario === 'random_walk'){
    adfP = 0.68; kpssP = 0.01; isStat = false;
    verdict = '❌ НЕСТАЦИОНАРЕН (Random Walk / Сырая цена BTC)';
    exp = 'Дисперсия ряда неограниченно растет со временем. Торговать возврат к среднему на сырых ценах категорически запрещено (риск бесконечного расхождения).';
    let val = 100;
    for(let i=0; i<N; i++){ val += (Math.random() - 0.48) * 3; points.push(val); }
  } else if(scenario === 'trend_stat'){
    adfP = 0.35; kpssP = 0.02; isStat = false;
    verdict = '⚠️ ТРЕНД-НЕСТАЦИОНАРЕН (Требуется детрендирование)';
    exp = 'Ряд имеет детерминированный восходящий дрейф. Требуется переход к первым разностям (differencing / pct_change) для устранения тренда.';
    for(let i=0; i<N; i++){ points.push(10 + i * 0.8 + (Math.random() - 0.5) * 4); }
  } else {
    // Disagree case
    adfP = 0.02; kpssP = 0.01; isStat = false;
    verdict = '🚨 DISAGREE-КЕЙС: Структурный срыв! (ADF врет p=0.02, KPSS отвергает p=0.01)';
    exp = '<b>Классическая ловушка кванта!</b> Тест Дики-Фуллера обманут локальным колебанием и показывает p<0.05, но KPSS фиксирует сдвиг среднего уровня (Structural Break). Использовать такой ряд нельзя!';
    for(let i=0; i<N; i++){ points.push(i < 50 ? (Math.random()-0.5)*2 : 12 + (Math.random()-0.5)*2); }
  }

  if(resBox){
    resBox.innerHTML = `
      <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
        <div class="pitem"><div class="lbl">ADF Test (H0: Единичный корень):</div><div class="val" style="font-weight:800; color:${adfP<0.05?'var(--ok)':'var(--bad)'}">p-value = ${adfP} (${adfP<0.05?'H0 отвергнута':'H0 принята'})</div></div>
        <div class="pitem"><div class="lbl">KPSS Test (H0: Стационарен):</div><div class="val" style="font-weight:800; color:${kpssP>0.05?'var(--ok)':'var(--bad)'}">p-value = ${kpssP} (${kpssP>0.05?'H0 не отвергнута':'H0 отвергнута'})</div></div>
        <div class="pitem" style="grid-column:1/-1; background:rgba(255,255,255,.04)"><div class="lbl">Комплексный вердикт Конституции:</div><div class="val" style="font-weight:900; font-size:16px; color:${isStat?'var(--ok)':'var(--bad)'}">${verdict}</div></div>
      </div>
      <p style="margin-top:12px; font-size:13px; color:var(--txt)">${exp}</p>
    `;
  }

  drawStationarityCanvas(points);
}

function drawStationarityCanvas(points){
  const canvas = document.getElementById('st_canvas');
  if(!canvas || !canvas.getContext) return;
  if(!canvas || !canvas.getContext) return; const ctx = canvas.getContext('2d');
  const w = canvas.width, h = canvas.height;
  ctx.clearRect(0,0,w,h);

  ctx.strokeStyle = 'rgba(255,255,255,0.06)';
  for(let y=20; y<h; y+=40){ ctx.beginPath(); ctx.moveTo(30,y); ctx.lineTo(w-20,y); ctx.stroke(); }

  const minV = Math.min(...points) - 1, maxV = Math.max(...points) + 1;
  const getX = (i) => 30 + (i / (points.length - 1)) * (w - 50);
  const getY = (v) => (h - 20) - ((v - minV) / (maxV - minV)) * (h - 40);

  ctx.strokeStyle = '#06b6d4';
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  points.forEach((v, i)=>{ const x=getX(i), y=getY(v); if(i===0)ctx.moveTo(x,y); else ctx.lineTo(x,y); });
  ctx.stroke();
}

// NEW SIM B: ALPHA/BETA DECOMPOSER
function calcAlphaBetaSim(){
  const rP = parseFloat(document.getElementById('ab_strat_ret')?.value) || 48;
  const rM = parseFloat(document.getElementById('ab_btc_ret')?.value) || 30;
  const beta = parseFloat(document.getElementById('ab_beta')?.value) || 0.45;
  const rf = parseFloat(document.getElementById('ab_rf')?.value) || 5.0;

  const expMarketReturn = rf + beta * (rM - rf);
  const alpha = rP - expMarketReturn;

  const resBox = document.getElementById('ab_result_box');
  if(!resBox) return;

  const isAlphaTrue = alpha > 5.0;

  // Трекинг для бейджа «Генератор Истинной Альфы»
  if(simActionStats.alpha !== true){
    simActionStats.alpha = true;
    save();
    checkAndUnlockBadge('alpha');
  }

  resBox.innerHTML = `
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
      <div class="pitem"><div class="lbl">Рыночная доходность от Беты BTC:</div><div class="val" style="font-weight:800; color:var(--mut)">+${expMarketReturn.toFixed(1)}% годовых</div></div>
      <div class="pitem"><div class="lbl">Чистая квантовая Альфа (Jensen's Alpha):</div><div class="val" style="font-weight:900; font-size:18px; color:${alpha>0?'var(--ok)':'var(--bad)'}">⚡ +${alpha.toFixed(1)}% годовых</div></div>
      <div class="pitem"><div class="lbl">Чувствительность к рынку (Beta):</div><div class="val" style="font-weight:800; color:var(--acc2)">${beta.toFixed(2)} (${beta<0.5?'Низкая корреляция':'Высокая зависимость'})</div></div>
      <div class="pitem"><div class="lbl">Оценка Information Ratio:</div><div class="val" style="font-weight:800; color:${isAlphaTrue?'var(--ok)':'var(--warn)'}">${(alpha / 12).toFixed(2)}</div></div>
    </div>
    <div style="margin-top:12px; font-size:13px; color:var(--txt)">
      ${isAlphaTrue ? '💡 <b>Отличный результат!</b> Стратегия генерирует независимую альфу, а не просто копирует рост биткоина с плечом.' : '⚠️ <b>Внимание:</b> Значительная часть доходности объясняется общим ростом BTC (Beta). При падении рынка стратегия понесет убытки.'}
    </div>
  `;
}

// NEW SIM C: EXECUTION DEVIATION TRAINER
function calcExecDevSim(){
  const btSharpe = parseFloat(document.getElementById('ed_bt_sharpe')?.value) || 2.4;
  const latency = parseFloat(document.getElementById('ed_latency')?.value) || 45;
  const slipBps = parseFloat(document.getElementById('ed_slip_bps')?.value) || 3.5;

  const latencyPenalty = (latency / 100) * 0.35;
  const slipPenalty = (slipBps / 10) * 0.40;
  const paperSharpe = Math.max(0.1, btSharpe - latencyPenalty - slipPenalty);

  const deviationPct = ((paperSharpe - btSharpe) / btSharpe) * 100;

  const resBox = document.getElementById('ed_result_box');
  if(!resBox) return;

  const isPass = Math.abs(deviationPct) <= 20;

  resBox.innerHTML = `
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:12px">
      <div class="pitem"><div class="lbl">Теоретический Sharpe бэктеста:</div><div class="val" style="font-weight:800">${btSharpe.toFixed(2)}</div></div>
      <div class="pitem"><div class="lbl">Фактический Sharpe на Paper Trading:</div><div class="val" style="font-weight:900; font-size:18px; color:${paperSharpe>1.5?'var(--ok)':'var(--warn)'}">⚡ ${paperSharpe.toFixed(2)}</div></div>
      <div class="pitem"><div class="lbl">Отклонение исполнения (Execution Deviation):</div><div class="val" style="font-weight:800; color:${isPass?'var(--ok)':'var(--bad)'}">${deviationPct.toFixed(1)}%</div></div>
      <div class="pitem"><div class="lbl">Допуск к микро-лайву (Порог ≤ 20%):</div><div class="val" style="font-weight:800; color:${isPass?'var(--ok)':'var(--bad)'}">${isPass?'✅ ДОПУЩЕН К ЛАЙВУ':'❌ ОТКЛОНЕН (Слишком высокое трение)'}</div></div>
    </div>
    <p style="margin-top:12px; font-size:13px; color:var(--txt)">
      ${isPass ? '🎯 <b>Отличное качество исполнения!</b> Реальное рыночное трение укладывается в допустимые 15–20% от бэктеста.' : '🚨 <b>Критическая деградация:</b> Задержка сети и проскальзывание съедают большую часть математического эджа. Разместите бота на VPS ближе к серверам биржи (Франкфурт/Токио) и перейдите на лимитные Maker ордера.'}
    </p>
  `;
}

/* Накопительные задания: проверка переноса навыков между уроками. */
const PSY_CUMULATIVE_QUESTIONS = CN_CONTENT.ensure('PSY_CUMULATIVE_QUESTIONS');
// PHASE TESTS & CAPSTONE EXAM LOGIC
function switchPhaseTest(phaseNum, btn){
  curPhaseTest = phaseNum;
  document.querySelectorAll('#tests .chip').forEach(c=>c.classList.remove('active'));
  if(btn) btn.classList.add('active');
  renderPhaseTestView(phaseNum);
}

function renderPhaseTestView(phaseNum){
  const box = document.getElementById('phaseTestBox');
  if(!box) return;

  const test = phaseNum === 6 ? CAPSTONE_EXAM : (typeof PHASE_TESTS !== 'undefined' ? PHASE_TESTS.find(t=>t.phase===phaseNum) : null);
  if(!test){
    box.innerHTML = `<div style="padding:20px; color:var(--mut)">Тест Фазы ${phaseNum} готовится к открытию.</div>`;
    return;
  }

  const testKey = phaseNum === 6 ? 'exam_capstone' : `p${phaseNum}`;
  // E8: спидран — метка старта попытки
  window._ptStart = window._ptStart || {};
  if(!window._ptStart[phaseNum]){
    let __savedPt = null;
    try{ __savedPt = JSON.parse(localStorage.getItem('cn_pt_start') || 'null'); }catch(__e){ __savedPt = null; }
    window._ptStart[phaseNum] = (__savedPt && typeof __savedPt[phaseNum] === 'number' && __savedPt[phaseNum] > 0) ? __savedPt[phaseNum] : Date.now(); /* №13: спидран продолжается после перезагрузки (cn_pt_start) */
  }
  try{ const __ptsAll = JSON.parse(localStorage.getItem('cn_pt_start') || '{}'); __ptsAll[phaseNum] = window._ptStart[phaseNum]; localStorage.setItem('cn_pt_start', JSON.stringify(__ptsAll)); }catch(__e2){}
  // D0.1: перемешанная копия вопросов для этой отрисовки (новая соль на каждый заход)
  const _ptSalt = nextShuffleSalt();
  window._ptView = window._ptView || {};
  window._ptView[phaseNum] = test.questions.map(function(q, qi){
    const sv = shuffledOptions(q, _ptSalt * 1000 + qi);
    return Object.assign({}, q, { opts: sv.opts, a: sv.a, explain: sv.explain });
  });
  const bestScore = phaseTestsDone[testKey] || 0;
  // Динамический порог: обычные фазы 80% вопросов, Capstone 85% — считается из фактического числа вопросов
  const reqRate = phaseNum === 6 ? 0.85 : 0.80;
  const requiredCorrect = Math.ceil(test.questions.length * reqRate);
  const requiredPct = Math.round(requiredCorrect / test.questions.length * 100);
  const isPassed = bestScore >= requiredPct;

  let html = `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:18px; flex-wrap:wrap; gap:10px">
      <div>
        <h2 style="margin:0 0 4px">${test.title}</h2>
        <div style="font-size:13px; color:var(--mut)">Количество вопросов: ${test.questions.length} · Проходной балл: ${Math.round(reqRate*100)}% (${requiredCorrect} из ${test.questions.length})</div>
      </div>
      <div style="display:flex; gap:8px; align-items:center">
        <span class="badge" style="background:${isPassed?'rgba(34,197,94,.15)':'rgba(234,179,8,.15)'}; color:${isPassed?'var(--ok)':'var(--warn)'}">
          ${isPassed ? '✓ СДАН (' + bestScore + '%)' : 'Не сдан (Лучший: ' + bestScore + '%)'}
        </span>
        ${(() => { const sr = load('cn_speedrun', {}); const g = sr[testKey];
          return g ? `<span class="badge" title="Лучшее время (ghost) и сезон" style="background:rgba(6,182,212,.12); color:var(--acc2)">👻 ${Math.floor(g.secs/60)}:${String(g.secs%60).padStart(2,'0')} · ${g.season}</span>` : '';
        })()}
      </div>
    </div>
  `;

  let _cumDividerShown = false;
  (window._ptView[phaseNum] || test.questions).forEach((q, qIdx)=>{
    if(q._cumulative && !_cumDividerShown){
      _cumDividerShown = true;
      html += `<div style="margin:26px 0 16px;padding:14px 16px;border:1.5px solid var(--acc1);border-radius:12px;background:rgba(124,58,237,.08)"><b style="color:var(--acc1)">🧠 Накопительный контроль переноса</b><div style="font-size:13px;color:var(--mut);margin-top:5px">Здесь проверяется соединение нескольких пройденных навыков. Для сдачи нужен отдельный результат этой части.</div></div>`;
    }
    // V3-A1: числовые вопросы с открытым вводом — отдельный рендер
    if(q.type === 'numeric'){
      html += `
      <div class="lblock" style="background:#090d1f; border:1px solid var(--acc2); border-radius:12px; padding:16px; margin-bottom:16px">
        <div style="font-weight:700; font-size:14.5px; color:var(--txt); margin-bottom:6px; line-height:1.5">${q.q}</div>
        <div style="font-size:11.5px; color:var(--acc2); margin-bottom:10px">🧮 Открытый ввод — вариантов нет, посчитай сам (допуск ${q.absTol !== undefined ? '±' + q.absTol + ' ' + (q.unit || '') : '±' + (q.tolPct || 2) + '%'})</div>
        <div id="ptest_${phaseNum}_${qIdx}" style="display:flex; gap:10px; align-items:center; flex-wrap:wrap">
          <input id="pnum_in_${phaseNum}_${qIdx}" type="text" inputmode="decimal" placeholder="число" style="width:150px; background:#040714; border:1px solid var(--acc2); border-radius:8px; padding:9px 12px; color:var(--txt); font-size:14.5px; font-weight:700">
          <span style="color:var(--mut); font-size:13.5px">${q.unit || ''}</span>
          <button class="btn sm" onclick="checkPhaseTestNumeric(${phaseNum}, ${qIdx})">Проверить</button>
        </div>
        <div id="ptest_exp_${phaseNum}_${qIdx}" style="display:none; margin-top:10px; font-size:13px"></div>
      </div>
      `;
      return;
    }
    html += `
      <div class="lblock" style="background:#090d1f; border:1px solid var(--line); border-radius:12px; padding:16px; margin-bottom:16px">
        <div style="font-weight:700; font-size:14.5px; color:var(--txt); margin-bottom:12px; line-height:1.5">${q.q}</div>
        <div id="ptest_${phaseNum}_${qIdx}" style="display:flex; flex-direction:column; gap:8px">
          ${q.opts.map((opt, oIdx)=>`
            <button class="ans" onclick="checkPhaseTestAnswer(${phaseNum}, ${qIdx}, ${oIdx})">${opt}</button>
          `).join('')}
        </div>
        <div id="ptest_exp_${phaseNum}_${qIdx}" style="display:none; margin-top:10px; font-size:13px"></div>
      </div>
    `;
  });

  html += `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-top:24px; padding-top:16px; border-top:1px solid var(--line)">
      <button class="btn" style="background:linear-gradient(135deg,#7c3aed,#06b6d4)" onclick="calcPhaseTestResult(${phaseNum})">🏁 Завершить тест и проверить результат</button>
      <div id="ptest_final_score_${phaseNum}" style="font-weight:800; font-size:16px"></div>
    </div>
  `;

  if (phaseNum === 8 && typeof renderPsySituationalDrill === 'function') { /* v12.2: тренажёр решений */
    html += renderPsySituationalDrill();
  }
  box.innerHTML = html;
  if (phaseNum === 8 && typeof initPsySituationalDrill === 'function') initPsySituationalDrill();
}

function checkPhaseTestAnswer(phaseNum, qIdx, optIdx){
  const test = phaseNum === 6 ? CAPSTONE_EXAM : (typeof PHASE_TESTS !== 'undefined' ? PHASE_TESTS.find(t=>t.phase===phaseNum) : null);
  if(!test) return;
  const q = (window._ptView && window._ptView[phaseNum]) ? window._ptView[phaseNum][qIdx] : test.questions[qIdx];
  if(!q) return;

  const container = document.getElementById(`ptest_${phaseNum}_${qIdx}`);
  const expBox = document.getElementById(`ptest_exp_${phaseNum}_${qIdx}`);
  if(!container) return;
  const buttons = container.querySelectorAll('.ans');

  buttons.forEach((btn, i)=>{
    btn.disabled = true;
    if(i === q.a) btn.classList.add('ok');
    else if(i === optIdx && i !== q.a) btn.classList.add('bad');
  });

  if(q.explain && q.explain[optIdx] && expBox){
    expBox.style.display = 'block';
    expBox.innerHTML = `<b>Разбор варианта:</b> ${q.explain[optIdx]}`;
  }
}

// V3-A1: проверка числового вопроса аттестации (скрытые .ans.ok/.ans.bad — совместимость со скорингом)
window.checkPhaseTestNumeric = function(phaseNum, qIdx){
  const test = phaseNum === 6 ? CAPSTONE_EXAM : (typeof PHASE_TESTS !== 'undefined' ? PHASE_TESTS.find(t=>t.phase===phaseNum) : null);
  if(!test) return;
  const q = (window._ptView && window._ptView[phaseNum]) ? window._ptView[phaseNum][qIdx] : test.questions[qIdx];
  if(!q || q.type !== 'numeric') return;
  const container = document.getElementById(`ptest_${phaseNum}_${qIdx}`);
  const expBox = document.getElementById(`ptest_exp_${phaseNum}_${qIdx}`);
  const inp = document.getElementById(`pnum_in_${phaseNum}_${qIdx}`);
  if(!container || !inp) return;
  const val = parseFloat(String(inp.value).replace(/\s/g, '').replace(',', '.'));
  if(isNaN(val)){ showToast('Введи число — без вариантов, только расчёт.', '🧮'); return; }
  const tol = q.absTol !== undefined ? q.absTol : Math.abs(q.answer) * (q.tolPct || 2) / 100;
  const ok = Math.abs(val - q.answer) <= tol;
  inp.disabled = true;
  const marker = document.createElement('span');
  marker.className = 'ans ' + (ok ? 'ok' : 'bad');
  marker.style.display = 'none';
  container.appendChild(marker);
  const checkBtn = container.querySelector('button');
  if(checkBtn) checkBtn.disabled = true;
  if(expBox){
    expBox.style.display = 'block';
    expBox.style.background = ok ? 'rgba(34,197,94,.1)' : 'rgba(239,68,68,.1)';
    expBox.style.borderLeft = '3px solid ' + (ok ? 'var(--ok)' : 'var(--bad)');
    expBox.style.borderRadius = '6px';
    expBox.style.padding = '8px 10px';
    expBox.innerHTML = (ok ? '✅ <b>Верно!</b> ' : '❌ <b>Неверно (' + val + ').</b> ') + '📐 <b>Эталон:</b> ' + (q.solution || '') + (q.explain ? '<br><span style="color:var(--mut)">💡 ' + q.explain + '</span>' : '');
  }
  if(!ok && typeof window.offerMistakeClassification === 'function'){
    window.offerMistakeClassification('ptest:' + phaseNum + ':' + qIdx);
  }
};

function calcPhaseTestResult(phaseNum){
  const test = phaseNum === 6 ? CAPSTONE_EXAM : (typeof PHASE_TESTS !== 'undefined' ? PHASE_TESTS.find(t=>t.phase===phaseNum) : null);
  if(!test) return;

  let correctCount = 0;
  test.questions.forEach((q, qIdx)=>{
    const container = document.getElementById(`ptest_${phaseNum}_${qIdx}`);
    if(container){
      const okBtn = container.querySelector('.ans.ok');
      if(okBtn && !container.querySelector('.ans.bad')) correctCount++;
    }
  });

  const pct = Math.round((correctCount / test.questions.length) * 100);
  const cumulativeQs = test.questions.filter(q=>q && q._cumulative);
  const capPsychQs = test.questions.filter(q=>q && q._psychology_capstone);
  const cumulativeCorrect = cumulativeQs.reduce((n,q)=>{ const idx=test.questions.indexOf(q); const c=document.getElementById(`ptest_${phaseNum}_${idx}`); return n + (c && c.querySelector('.ans.ok') && !c.querySelector('.ans.bad') ? 1 : 0); },0);
  const capPsychCorrect = capPsychQs.reduce((n,q)=>{ const idx=test.questions.indexOf(q); const c=document.getElementById(`ptest_${phaseNum}_${idx}`); return n + (c && c.querySelector('.ans.ok') && !c.querySelector('.ans.bad') ? 1 : 0); },0);
  const testKey = phaseNum === 6 ? 'exam_capstone' : `p${phaseNum}`;
  phaseTestsDone[testKey] = Math.max(phaseTestsDone[testKey] || 0, pct);
  // E8: спидран — сравнение с ghost
  try {
    const t0 = (window._ptStart || {})[phaseNum];
    if(t0){
      const secs = Math.round((Date.now() - t0) / 1000);
      window._ptStart[phaseNum] = 0;
      try{ const __ptf = JSON.parse(localStorage.getItem('cn_pt_start') || '{}'); __ptf[phaseNum] = 0; localStorage.setItem('cn_pt_start', JSON.stringify(__ptf)); }catch(__e3){} /* №13: попытка завершена — сохранённый старт сброшен, следующая попытка стартует с нуля */
      const season = ['❄️ Зима','🌱 Весна','☀️ Лето','🍂 Осень'][Math.floor((new Date().getMonth() % 12) / 3)] + ' ' + new Date().getFullYear();
      const sr = load('cn_speedrun', {});
      const prev = sr[testKey];
      if(!prev || secs < prev.secs){
        sr[testKey] = { secs, pct, season, when: Date.now() };
        localStorage.setItem('cn_speedrun', JSON.stringify(sr));
        showToast(`⏱ Новый спидран-рекорд: ${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')} (${pct}%)!`, '🏁');
      } else {
        const d = secs - prev.secs;
        showToast(`⏱ Время: ${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')} · ghost ${d >= 0 ? '+' : ''}${d}с к рекорду`, '🏁');
      }
    }
  } catch(e){}
  save();
  updateHeader();
  renderProgressStats();

  const scoreBox = document.getElementById(`ptest_final_score_${phaseNum}`);
  // Динамический порог: считается из фактического числа вопросов теста
  const reqRate = phaseNum === 6 ? 0.85 : 0.80;
  const requiredCorrect = Math.ceil(test.questions.length * reqRate);
  const passThreshold = Math.round(requiredCorrect / test.questions.length * 100);
  const cumulativeRequired = cumulativeQs.length ? Math.ceil(cumulativeQs.length * 0.70) : 0;
  const capPsychRequired = capPsychQs.length ? Math.ceil(capPsychQs.length * 0.75) : 0;
  const cumulativePass = !cumulativeQs.length || cumulativeCorrect >= cumulativeRequired;
  const capPsychPass = !capPsychQs.length || capPsychCorrect >= capPsychRequired;

  if(correctCount >= requiredCorrect && cumulativePass && capPsychPass){
    if(phaseNum === 6){
      const ptBox = document.getElementById('phaseTestBox');
      if(ptBox) ptBox.innerHTML = renderCapstoneCertificate(correctCount, test.questions.length);
      window.scrollTo({top:100, behavior:'smooth'});
      return;
    }
    if(scoreBox) scoreBox.innerHTML = `<span style="color:var(--ok)">🎉 ТЕСТ СДАН! Результат: ${pct}% (${correctCount}/${test.questions.length})</span>`;
if (window.LEARN_PLAYER_ACTIVE) { LearnPlayer.onTestResult(`Поздравляем! Тест Фазы ${phaseNum} успешно сдан на ${pct}%.${cumulativeQs.length ? ` Накопительный контроль: ${cumulativeCorrect}/${cumulativeQs.length}.` : ''}${capPsychQs.length ? ` Психологический блок: ${capPsychCorrect}/${capPsychQs.length}.` : ''}`); } else { alert(`Поздравляем! Тест Фазы ${phaseNum} успешно сдан на ${pct}%.${cumulativeQs.length ? ` Накопительный контроль: ${cumulativeCorrect}/${cumulativeQs.length}.` : ''}${capPsychQs.length ? ` Психологический блок: ${capPsychCorrect}/${capPsychQs.length}.` : ''}`); }
    // D2.1: аттестация тоже требует консолидации — экран паузы после сдачи
    try{ setTimeout(() => showConsolidationScreen(null, `Аттестация Фазы ${phaseNum} сдана на ${pct}%`), 600); }catch(e){}
  } else {
    if(scoreBox) scoreBox.innerHTML = `<span style="color:var(--bad)">❌ НЕ СДАНО: ${pct}% (${correctCount} из ${test.questions.length}; необходимо ≥ ${requiredCorrect}).${!cumulativePass ? ` Накопительный контроль: ${cumulativeCorrect}/${cumulativeQs.length}, нужно ≥ ${cumulativeRequired}.` : ''}${!capPsychPass ? ` Психологический блок: ${capPsychCorrect}/${capPsychQs.length}, нужно ≥ ${capPsychRequired}.` : ''}</span>`;
if (window.LEARN_PLAYER_ACTIVE) { LearnPlayer.onTestResult(`Результат: ${pct}%. Основной порог: ${requiredCorrect} из ${test.questions.length} (${passThreshold}%).${!cumulativePass ? ` Накопительный контроль: ${cumulativeCorrect}/${cumulativeQs.length}, нужно ≥ ${cumulativeRequired}.` : ''}${!capPsychPass ? ` Психологический блок: ${capPsychCorrect}/${capPsychQs.length}, нужно ≥ ${capPsychRequired}.` : ''} Повторите материал и попробуйте снова.`); } else { alert(`Результат: ${pct}%. Основной порог: ${requiredCorrect} из ${test.questions.length} (${passThreshold}%).${!cumulativePass ? ` Накопительный контроль: ${cumulativeCorrect}/${cumulativeQs.length}, нужно ≥ ${cumulativeRequired}.` : ''}${!capPsychPass ? ` Психологический блок: ${capPsychCorrect}/${capPsychQs.length}, нужно ≥ ${capPsychRequired}.` : ''} Повторите материал и попробуйте снова.`); }
    /* v12 P2-8: карта восстановления перед пересдачей */
    try{
      const wrongByCat = {};
      test.questions.forEach((q, qIdx) => {
        const c = document.getElementById(`ptest_${phaseNum}_${qIdx}`);
        if(c && c.querySelector('.ans.bad')){
          const cat = (q && q.category) || 'общий';
          (wrongByCat[cat] = wrongByCat[cat] || []).push(qIdx);
        }
      });
      const catList = Object.keys(wrongByCat).map(cat => '<li>' + cat + ' — ошибок: ' + wrongByCat[cat].length + '</li>').join('');
      if(scoreBox && catList){
        scoreBox.innerHTML += '<div style="margin-top:10px;background:rgba(245,158,11,.08);border:1px dashed var(--warn);border-radius:10px;padding:12px 14px;font-size:13px;color:var(--txt)"><b style="color:var(--warn)">🗺️ Карта восстановления:</b> перед пересдачей разбери темы, где были ошибки:<ul style="margin:6px 0 8px 18px;color:var(--mut)">' + catList + '</ul><button class="btn sm ghost" onclick="go(\'lessons\'); renderPhaseLessonsView(' + phaseNum + ');">📖 Открыть уроки фазы ' + phaseNum + '</button></div>';
      }
    }catch(e){}
  }
}

