curCat = 'all';

function renderChips(){
  const box = document.querySelector('#glossary .controls');
  if(!box) return;

  const existingChips = box.querySelectorAll('.chip');
  if(existingChips.length > 1) return; // already rendered

  box.innerHTML = '<input id="search" placeholder="🔍 Поиск термина…" oninput="renderGloss()" style="padding:6px 12px; font-size:13px; border-radius:8px; background:rgba(255,255,255,.06); border:1px solid var(--line); color:var(--txt); margin-right:8px">';

  const allBtn = document.createElement('button');
  allBtn.className = 'chip active';
  allBtn.textContent = 'Все';
  allBtn.onclick = () => {
    curCat = 'all';
    box.querySelectorAll('.chip').forEach(c => c.classList.remove('active'));
    allBtn.classList.add('active');
    renderGloss();
  };
  box.appendChild(allBtn);

  Object.keys(CATS).forEach(k => {
    const b = document.createElement('button');
    b.className = 'chip';
    b.dataset.cat = k;
    b.textContent = CATS[k][0];
    b.style.borderColor = CATS[k][1];
    b.onclick = () => {
      curCat = k;
      box.querySelectorAll('.chip').forEach(c => c.classList.remove('active'));
      b.classList.add('active');
      renderGloss();
    };
    box.appendChild(b);
  });
}

/* Duplicate renderGloss removed in favor of active definition below */


/* =========================================================================
   КВАНТ-ВИКТОРИНА (SUPERCHARGED QUIZ ENGINE & 3 MODES)
   ========================================================================= */
const QUIZ_CASES = CN_CONTENT.ensure('QUIZ_CASES');

/* V3-C2: еженедельный квиз «Гипотезы из данных» — чтение мини-таблиц и вывод */
const QUIZ_DATA = CN_CONTENT.ensure('QUIZ_DATA');


const QUIZ_LEGAL = CN_CONTENT.ensure('QUIZ_LEGAL');

/* =========================================================================
   РАСЧЁТНЫЕ ЗАДАЧИ (НОВЫЙ РЕЖИМ КВИЗА)
   ========================================================================= */
const QUIZ_CALC = CN_CONTENT.ensure('QUIZ_CALC');


const QUIZ_PSY = CN_CONTENT.ensure('QUIZ_PSY');

function setQuizMode(mode, btn){
  quizMode = mode;
  document.querySelectorAll('#quiz .controls .chip').forEach(c => c.classList.remove('active'));
  if(btn) btn.classList.add('active');
  startQuiz();
}

function startQuiz(){
  // Пользовательские сессии (адаптивная тренировка, интерливинг) сами задают вопросы — не пересобирать их
  if(quiz.preserveQs){
    quiz.preserveQs = false;
    quiz._shuffleSalt = nextShuffleSalt();
    renderQuizQuestion();
    return;
  }
  quiz.mode = 'standard';
  quiz.isAdaptive = false;
  quiz.targetTopic = null;
  const sb = document.getElementById('quiz_session_banner');
  if(sb) sb.innerHTML = '';
  quiz.score = 0;
  quiz.cur = 0;
  quiz.total = 10;
  quiz.qs = [];
  quiz._shuffleSalt = nextShuffleSalt();

  if(quizMode === 'cases'){
    quiz.qs = [...QUIZ_CASES];
  } else if(quizMode === 'legal'){
    quiz.qs = [...QUIZ_LEGAL];
  } else if(quizMode === 'calc'){
    quiz.qs = [...QUIZ_CALC];
  } else if(quizMode === 'data'){
    quiz.qs = [...QUIZ_DATA];
  } else if(quizMode === 'psy'){
    quiz.qs = [...QUIZ_PSY];
  } else {
    // Generate 10 random terms questions
    const shuffled = [...TERMS].sort(() => 0.5 - Math.random()).slice(0, 10);
    quiz.qs = shuffled.map(t => {
      const others = TERMS.filter(x => x.t !== t.t).sort(() => 0.5 - Math.random()).slice(0, 3);
      const allOpts = [t.t, ...others.map(o => o.t)].sort(() => 0.5 - Math.random());
      const correctIdx = allOpts.indexOf(t.t);

      return {
        q: Math.random() > 0.5 ? `💡 Определение: «${t.d}». О каком понятии речь?` : `🎭 Жизненная аналогия: «${t.a}». Какой это термин?`,
        opts: allOpts,
        a: correctIdx,
        explain: `Верный ответ: <b>${t.t}</b> (${CATS[t.c][0]}). ${t.d}`
      };
    });
  }

  quiz.total = quiz.qs.length;
  renderQuizQuestion();
}

function getRank(streak){
  if(streak >= 25) return '🏛️ Архитектор капитала 6 млн ₽';
  if(streak >= 15) return '💎 Senior Quant Developer';
  if(streak >= 8) return '⚡ Алго-инженер';
  if(streak >= 3) return '🔍 Исследователь';
  return '🌱 Крипто-юнга';
}

function renderQuizQuestion(){
  const box = document.getElementById('quizBox');
  if(!box) return;

  if(quiz.cur >= quiz.total){
    if(quiz.mode === 'interleaving' && typeof finishInterleavingSession === 'function'){
      finishInterleavingSession(box);
      return;
    }
    const pct = Math.round((quiz.score / quiz.total) * 100);
    quizBest = Math.max(quizBest, pct);
    save();
    updateHeader();
    renderProgressStats();

    box.innerHTML = `
      <div style="text-align:center; padding:24px">
        <div style="font-size:44px; margin-bottom:10px">${pct>=80?'🎉':'📚'}</div>
        <h2>Раунд завершен!</h2>
        <div style="font-size:24px; font-weight:800; color:${pct>=80?'var(--ok)':'var(--warn)'}; margin:10px 0">${quiz.score} из ${quiz.total} (${pct}%)</div>
        <div style="font-size:14px; color:var(--txt); margin-bottom:16px">🔥 Текущая серия: <b>${quizStreak}</b> · Твой ранг: <b style="color:var(--acc2)">${getRank(quizStreak)}</b></div>
        <button class="btn" onclick="startQuiz()">🔄 Сыграть еще раунд</button>
      </div>
    `;
    return;
  }

  const q = quiz.qs[quiz.cur];
  // D0.1: перемешиваем варианты при каждом показе (повторный заход = другой порядок)
  if(!q._sv || q._svCur !== quiz.cur + '_' + quiz._shuffleSalt){
    q._sv = shuffledOptions(q, (quiz._shuffleSalt || 0) * 131 + quiz.cur);
    q._svCur = quiz.cur + '_' + quiz._shuffleSalt;
  }
  const qd = { q: q.q, opts: q._sv.opts, a: q._sv.a, explain: q._sv.explain };

  box.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px; flex-wrap:wrap; gap:8px">
      <span style="font-size:12px; font-weight:700; color:var(--mut)">Вопрос ${quiz.cur + 1} из ${quiz.total}</span>
      <div style="display:flex; gap:10px; font-size:12px">
        <span style="color:var(--warn); font-weight:700">🔥 Серия: ${quizStreak}</span>
        <span style="color:var(--acc2); font-weight:700">Ранг: ${getRank(quizStreak)}</span>
      </div>
    </div>

    <div style="font-size:15px; font-weight:700; color:var(--txt); margin-bottom:16px; line-height:1.5">${autoLinkTermsSoft(qd.q)}</div>

    <div id="quiz_ans_btns" style="display:flex; flex-direction:column; gap:8px">
      ${qd.opts.map((opt, idx) => `
        <button class="ans" onclick="checkQuizAnswer(${idx})">${autoLinkTermsSoft(opt)}</button>
      `).join('')}
    </div>

    <div id="quiz_feedback" style="display:none; margin-top:14px; padding:12px; border-radius:10px; font-size:13px"></div>
    <div style="margin-top:16px; text-align:right">
      <button class="btn sm ghost" id="quiz_next_btn" style="display:none" onclick="nextQuizQuestion()">Следующий вопрос →</button>
    </div>
  `;
}

/* Duplicate checkQuizAnswer removed in favor of active definition below */

function nextQuizQuestion(){
  quiz.cur++;
  renderQuizQuestion();
}



/* =========================================================================
   ДОПОЛНЕНИЯ P2: ГЛОБАЛЬНЫЙ ПОИСК, БЕЙДЖИ, ЭКЗАМЕН НА 30 ВОПРОСОВ, JSON ЭКСПОРТ/ИМПОРТ
   ========================================================================= */

// 1. GLOBAL SEARCH ENGINE
function handleGlobalSearch(query){
  const resBox = $('#globalSearchResults');
  if(!resBox) return;

  const q = query.trim().toLowerCase();
  if(!q || q.length < 2){
    resBox.style.display = 'none';
    return;
  }

  let results = [];

  // Search Lessons
  LESSONS.forEach(l => {
    if(l.title.toLowerCase().includes(q) || (l.terms && l.terms.some(t=>t.toLowerCase().includes(q)))){
      results.push({
        type: 'Урок',
        title: l.title,
        badge: `Фаза ${l.phase}`,
        action: () => { go('lessons'); switchPhaseLessons(l.phase); curLessonId = l.id; renderPhaseLessonsView(l.phase); }
      });
    }
  });

  // Search Terms
  TERMS.forEach((t, idx) => {
    if(t.t.toLowerCase().includes(q) || t.d.toLowerCase().includes(q)){
      results.push({
        type: 'Термин',
        title: t.t,
        badge: 'Глоссарий',
        action: () => { openTermModal(idx); }
      });
    }
  });

  // Search Earning Methods
  EARNING_METHODS.forEach(m => {
    if(m.title.toLowerCase().includes(q) || m.summary.toLowerCase().includes(q) || m.legalRF.toLowerCase().includes(q)){
      results.push({
        type: 'Заработок',
        title: `${m.num}. ${m.title}`,
        badge: m.riskText,
        action: () => { go('earnings'); }
      });
    }
  });

  if(results.length === 0){
    resBox.innerHTML = '<div style="padding:10px; font-size:13px; color:var(--mut); text-align:center">Ничего не найдено. Попробуйте другой запрос.</div>';
  } else {
    resBox.innerHTML = results.slice(0, 8).map((r, i) => `
      <div style="padding:8px 10px; border-radius:8px; cursor:pointer; display:flex; justify-content:space-between; align-items:center; transition:.15s" onmouseover="this.style.background='rgba(255,255,255,.06)'" onmouseout="this.style.background='transparent'" onclick="executeSearchResult(${i})">
        <div>
          <span style="font-size:11px; font-weight:700; color:var(--acc2); background:rgba(6,182,212,.12); padding:2px 6px; border-radius:4px; margin-right:6px">${r.type}</span>
          <span style="font-size:13px; font-weight:600; color:var(--txt)">${r.title}</span>
        </div>
        <span style="font-size:11px; color:var(--mut)">${r.badge}</span>
      </div>
    `).join('');
    window._lastSearchResults = results;
  }
  resBox.style.display = 'block';
}

function executeSearchResult(idx){
  if(window._lastSearchResults && window._lastSearchResults[idx]){
    window._lastSearchResults[idx].action();
    $('#globalSearchResults').style.display = 'none';
    $('#globalSearchInput').value = '';
  }
}

