/* =========================================================================
   КЛАССИЧЕСКИЙ АЛГОРИТМ SUPERMEMO-2 (CANONICAL SM-2 SCHEDULER)
   ========================================================================= */
/* Duplicate getSrsStats removed in favor of active definition below */

/* Duplicate startSrsReviewSession removed in favor of active definition below */

function calcCanonicalSm2NextInterval(item, quality){
  const ease = item.ease || 2.5;
  const reps = item.reps || 0;

  if(quality < 3){
    return { interval: 1, reps: 0, ease: Math.max(1.3, ease - 0.2) };
  }

  let nextInterval = 1;
  if(reps === 0){
    nextInterval = 1; // First repetition: 1 day
  } else if(reps === 1){
    nextInterval = 6; // Second repetition: 6 days (Canonical SM-2)
  } else {
    const baseInt = item.interval || 6;
    nextInterval = Math.round(baseInt * ease);
  }

  // Multiplier bonus for 'Easy' (5)
  if(quality === 5){
    nextInterval = Math.round(nextInterval * 1.3);
  }

  const nextEase = Math.max(1.3, ease + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)));
  return { interval: Math.max(1, nextInterval), reps: reps + 1, ease: nextEase };
}

/* Duplicate renderSrsCard removed in favor of active definition below */

/* Duplicate revealSrsAnswer removed in favor of active definition below */

function rateSrsTerm(quality){
  const termIdx = srsActiveQueue[srsCurrentIdx];
  const now = Date.now();
  const currentItem = srsState[termIdx] || { interval: 0, ease: 2.5, reps: 0 };

  const calc = calcCanonicalSm2NextInterval(currentItem, quality);
  srsState[termIdx] = {
    interval: calc.interval,
    reps: calc.reps,
    ease: calc.ease,
    lastReviewed: now,
    nextReview: now + calc.interval * 86400000
  };

  learned[termIdx] = quality >= 3 ? 1 : 0;
  save();

  srsCurrentIdx++;
  renderSrsCard();
}



