// 1. Whale Simulator 2.0 with rigorous stat tracking
function handleWhaleChoice(choice){
  const item = WHALE_TX_CASES[curWhaleIdx];
  const fb = document.getElementById('whale_feedback');
  if(!fb) return;

  if(!simActionStats.whale) simActionStats.whale = { correct: 0, total: 0, insufficient: 0, internal: 0, whale: 0 };
  const st = simActionStats.whale;
  st.total++;

  const isCorrect = (choice === item.correctType);
  if(isCorrect){
    st.correct++;
    if(choice === 'insufficient') st.insufficient++;
    else if(choice === 'internal') st.internal++;
    else if(choice === 'whale') st.whale++;
  }

  fb.style.display = 'block';
  if(isCorrect){
    fb.style.background = 'rgba(34,197,94,.15)';
    fb.style.border = '1px solid var(--ok)';
    fb.innerHTML = `<div>${item.explain}</div><button class="btn sm" style="margin-top:10px" onclick="nextWhaleCase()">Следующая транзакция →</button>`;
  } else {
    fb.style.background = 'rgba(239,68,68,.15)';
    fb.style.border = '1px solid var(--bad)';
    fb.innerHTML = `<div>${item.explain}</div><button class="btn sm" style="margin-top:10px" onclick="nextWhaleCase()">Следующая транзакция →</button>`;
  }

  save();
  checkAndUnlockBadge('whale');
}

// 2. Chaos Engineering Lab with incident resolution tracking
function handleChaosChoice(optIdx){
  const s = CHAOS_SCENARIOS[curChaosIdx];
  const opt = s.opts[optIdx];
  const fb = document.getElementById('chaos_feedback_box');
  if(!fb) return;

  if(!simActionStats.chaos) simActionStats.chaos = { resolved: [], errors: 0 };
  const st = simActionStats.chaos;

  fb.style.display = 'block';
  if(opt.correct){
    if(!st.resolved.includes(curChaosIdx)) st.resolved.push(curChaosIdx);
    fb.style.background = 'rgba(34,197,94,.15)';
    fb.style.border = '1.5px solid var(--ok)';
    fb.innerHTML = `<div style="font-weight:800; color:var(--ok); margin-bottom:6px">🎯 ВЕРНО! ИНФРАСТРУКТУРА ЗАЩИЩЕНА</div><div style="color:var(--txt)">${opt.exp}</div>`;
    recordTopicResult('production_reliability', true);
  } else {
    st.errors = (st.errors || 0) + 1;
    fb.style.background = 'rgba(239,68,68,.15)';
    fb.style.border = '1.5px solid var(--bad)';
    fb.innerHTML = `<div style="font-weight:800; color:var(--bad); margin-bottom:6px">💥 АВАРИЯ! КАПИТАЛ ПОД УГРОЗОЙ</div><div style="color:var(--txt)">${opt.exp}</div>`;
    recordTopicResult('production_reliability', false);
  }

  save();
  checkAndUnlockBadge('chaos');
}

// 3. Lookahead Snippet Check with 6/6 Level Tracking
function checkSnippetLeak(levelIdx, isLeakLine){
  if(!simActionStats.lookahead) simActionStats.lookahead = [];
  if(isLeakLine && !simActionStats.lookahead.includes(levelIdx)){
    simActionStats.lookahead.push(levelIdx);
    save();
    checkAndUnlockBadge('lookahead');
  }
}

// 4. Orderbook Action Tracking
function recordOrderBookAction(type, slippageBps){
  if(!simActionStats.ob) simActionStats.ob = { limitPlaced: false, marketPlaced: false, maxSlippageBps: 0 };
  if(type === 'limit') simActionStats.ob.limitPlaced = true;
  if(type === 'market') {
    simActionStats.ob.marketPlaced = true;
    simActionStats.ob.maxSlippageBps = Math.max(simActionStats.ob.maxSlippageBps || 0, slippageBps || 0);
  }
  save();
  checkAndUnlockBadge('ob');
}

// 5. Tax CSV Export Tracking
function recordTaxCsvExportAction(){
  simActionStats.taxCsvExported = true;
  save();
  checkAndUnlockBadge('tax');
}

