curChaosIdx = 0;

function loadChaosScenario(idx, btn){
  curChaosIdx = idx;
  if(btn){
    document.querySelectorAll('#sim_chaos .controls .chip').forEach(c=>c.classList.remove('active'));
    btn.classList.add('active');
  }
  const s = CHAOS_SCENARIOS[idx];
  const cardBox = document.getElementById('chaos_card_box');
  const fb = document.getElementById('chaos_feedback_box');
  if(!cardBox) return;
  if(fb) fb.style.display = 'none';

  cardBox.innerHTML = `
    <div style="font-size:12px; font-weight:800; color:var(--bad); text-transform:uppercase; margin-bottom:6px">Инцидент ${idx + 1} из ${CHAOS_SCENARIOS.length}</div>
    <h3 style="color:var(--txt); margin:0 0 10px">${s.title}</h3>
    <p style="color:var(--txt); font-size:14px; line-height:1.6; margin-bottom:16px">${s.desc}</p>
    <div style="font-weight:700; color:var(--acc2); font-size:13px; margin-bottom:10px">Реакция квант-архитектора:</div>
    <div style="display:flex; flex-direction:column; gap:8px">
      ${s.opts.map((opt, oIdx)=>`
        <button class="ans" style="text-align:left; font-size:13px" onclick="handleChaosChoice(${oIdx})">${opt.text}</button>
      `).join('')}
    </div>
  `;
}



