/* Earlier roadmap consolidated into comprehensive master */

function initWhaleSim(){
  curWhaleIdx = 0;
  renderWhaleCard();
}

function renderWhaleCard(){
  if(typeof WHALE_TX_CASES === 'undefined' || !WHALE_TX_CASES.length) return;
  curWhaleIdx = curWhaleIdx % WHALE_TX_CASES.length;
  const item = WHALE_TX_CASES[curWhaleIdx] || WHALE_TX_CASES[0];
  const box = document.getElementById('whale_tx_box');
  const fb = document.getElementById('whale_feedback');
  if(!box) return;
  if(fb) fb.style.display = 'none';

  const signals = item.signals || [
    'Кластерная ончейн-разметка кошельков',
    'Анализ глубины стакана и времени транзакции'
  ];

  box.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px">
      <span style="font-size:12px; font-weight:800; color:var(--acc2)">Кейс ${curWhaleIdx + 1} из ${WHALE_TX_CASES.length}</span>
      <span style="font-size:12px; color:var(--txt); font-family:monospace">Хеш: ${item.tx || item.txid || '0x7a9f...'}</span>
    </div>
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:10px; margin-bottom:14px">
      <div class="pitem"><div class="lbl">Сумма перевода:</div><div class="val" style="font-weight:900; color:var(--warn)">${item.amount}</div></div>
      <div class="pitem"><div class="lbl">Адрес-отправитель:</div><div class="val" style="font-size:12px">${item.from}</div></div>
      <div class="pitem"><div class="lbl">Адрес-получатель:</div><div class="val" style="font-size:12px">${item.to}</div></div>
    </div>
    <div style="background:#040714; padding:12px; border-radius:8px; margin-bottom:14px">
      <div style="font-size:11.5px; font-weight:800; color:var(--mut); text-transform:uppercase; margin-bottom:6px">🔍 Ончейн-улики и ончейн-следы:</div>
      <ul style="margin:0; padding-left:18px; font-size:12px; color:var(--txt); line-height:1.6">
        ${signals.map(s => `<li>${s}</li>`).join('')}
      </ul>
    </div>
  `;
}



