function renderDDFlags(){
  const box=document.getElementById('dd_flags_box');
  if(!box) return;
  box.innerHTML=DD_ITEMS.map((it,i)=>`
    <label style="display:flex; gap:8px; align-items:flex-start; background:#040714; padding:9px 12px; border-radius:8px; font-size:12.5px; color:var(--txt); cursor:pointer">
      <input type="checkbox" id="dd_flag_${i}" style="margin-top:2px">
      <span><b>${i+1}.</b> ${it.t}</span>
    </label>`).join('');
}
function submitDDFlags(){
  const box=document.getElementById('dd_verdict_box');
  if(!box) return;
  let correct=0, marked=0;
  let rows='';
  DD_ITEMS.forEach((it,i)=>{
    const el=document.getElementById('dd_flag_'+i);
    const checked=!!(el&&el.checked);
    if(checked) marked++;
    const hit=checked===it.flag;
    if(hit) correct++;
    rows+=`<li style="margin-bottom:4px"><span style="color:${hit?'var(--ok)':'var(--bad)'}">${hit?'✔':'✘'}</span> <b>«${it.flag?'Флаг':'Не флаг'}»</b> — ${it.exp}</li>`;
  });
  box.innerHTML=`
    <div style="padding:12px 14px; border-radius:10px; background:rgba(255,255,255,.04); border-left:4px solid var(--acc1); font-size:12.5px; color:var(--txt); line-height:1.6">
      <b>Результат: ${correct} из ${DD_ITEMS.length} верно</b> (отмечено флагов: ${marked}, настоящих флагов: ${DD_ITEMS.filter(x=>x.flag).length})<br>
      Вывод по проекту: ${DD_ITEMS.filter(x=>x.flag).length>=3?'4 красных флага из 7 пунктов — проект проходит по профилю скама; корректное решение — НЕ входить.':'—'}
      <ul style="margin:8px 0 0; padding-left:18px">${rows}</ul>
    </div>`;
}

