function setShareAnswer(i,val){
  shareAnswers[i]=val;
  const y=document.getElementById('share_yes_'+i), n=document.getElementById('share_no_'+i);
  if(y) y.style.borderColor=val?'var(--ok)':'';
  if(n) n.style.borderColor=(val===false)?'var(--bad)':'';
}
function checkShareAnswers(){
  const fb=document.getElementById('share_fb_box');
  if(!fb) return;
  let score=0, rows='';
  SHARE_ITEMS.forEach((it,i)=>{
    const a=shareAnswers[i];
    if(a===undefined){ rows+=`<li>⏳ <b>${it.t}</b> — ответ не выбран.</li>`; return; }
    const ok=a===it.safe;
    if(ok) score++;
    rows+=`<li style="margin-bottom:4px"><span style="color:${ok?'var(--ok)':'var(--bad)'}">${ok?'✔':'✘'}</span> <b>${it.t}</b>: ${it.exp}</li>`;
  });
  fb.innerHTML=`
    <div style="padding:12px 14px; border-radius:10px; background:rgba(34,197,94,.08); border-left:4px solid var(--ok); font-size:12.5px; color:var(--txt); line-height:1.6">
      <b>Верно: ${score} из ${SHARE_ITEMS.length}</b>. Золотое правило: публичные данные (адрес, TXID, QR адреса) показывать можно; всё, что даёт ДОСТУП (seed, приватный ключ, пароль), — никогда и никому.
      <ul style="margin:8px 0 0; padding-left:18px">${rows}</ul>
    </div>`;
}

