function updateP0Candle(){
  const op = parseInt(document.getElementById('p0_c_open')?.value || 95);
  const cl = parseInt(document.getElementById('p0_c_close')?.value || 105);
  let hi = parseInt(document.getElementById('p0_c_high')?.value || 112);
  let lo = parseInt(document.getElementById('p0_c_low')?.value || 88);

  hi = Math.max(hi, op, cl);
  lo = Math.min(lo, op, cl);

  if(!document.getElementById('p0_c_open_val')) return; /* №7: разметка урока перерисована — осиротевший таймер молча выходит */
  document.getElementById('p0_c_open_val').innerText = '$' + op;
  document.getElementById('p0_c_close_val').innerText = '$' + cl;
  document.getElementById('p0_c_high_val').innerText = '$' + hi;
  document.getElementById('p0_c_low_val').innerText = '$' + lo;

  const isBull = cl >= op;
  const col = isBull ? '#22c55e' : '#ef4444';
  const box = document.getElementById('p0_candle_render_box');
  if(!box) return;

  // Scale prices (70..130) to Y (140..10)
  const toY = (p) => 140 - ((p - 70) / 60) * 130;

  const yHigh = toY(hi);
  const yLow = toY(lo);
  const yTop = toY(Math.max(op, cl));
  const yBot = toY(Math.min(op, cl));
  const hBody = Math.max(4, yBot - yTop);

  box.innerHTML = `
    <svg width="80" height="150" viewBox="0 0 80 150">
      <line x1="40" y1="${yHigh}" x2="40" y2="${yLow}" stroke="${col}" stroke-width="2"/>
      <rect x="25" y="${yTop}" width="30" height="${hBody}" fill="${col}" rx="2"/>
    </svg>
    <div style="font-size:11px; font-weight:800; color:${col}">${isBull?'🟢 Зеленая (Рост)':'🔴 Красная (Спад)'}</div>
  `;
}

