let p0L4State = { bid: 99.80, ask: 100.20 };
function addP0L4Order(type, price){
  if(type === 'buy') p0L4State.bid = price;
  else p0L4State.ask = price;
  updateP0L4View();
}
function resetP0L4(){
  p0L4State = { bid: 99.80, ask: 100.20 };
  updateP0L4View();
}
function updateP0L4View(){
  const bidEl = document.getElementById('p0_l4_bid');
  const askEl = document.getElementById('p0_l4_ask');
  const spreadEl = document.getElementById('p0_l4_spread');
  if(!bidEl || !askEl || !spreadEl) return;

  bidEl.textContent = `$${p0L4State.bid.toFixed(2)}`;
  askEl.textContent = `$${p0L4State.ask.toFixed(2)}`;
  const spread = Math.max(0, p0L4State.ask - p0L4State.bid);
  const bps = ((spread / ((p0L4State.ask + p0L4State.bid)/2)) * 10000).toFixed(0);
  spreadEl.textContent = `$${spread.toFixed(2)} (${bps} bps)`;
}

