function updateP0L8Candle(){
  const o = parseFloat(document.getElementById('p0_l8_open')?.value || 100);
  const c = parseFloat(document.getElementById('p0_l8_close')?.value || 110);
  const h = Math.max(parseFloat(document.getElementById('p0_l8_high')?.value || 115), Math.max(o,c));
  const l = Math.min(parseFloat(document.getElementById('p0_l8_low')?.value || 95), Math.min(o,c));

  if(document.getElementById('p0_l8_open_val')) document.getElementById('p0_l8_open_val').textContent = o;
  if(document.getElementById('p0_l8_close_val')) document.getElementById('p0_l8_close_val').textContent = c;
  if(document.getElementById('p0_l8_high_val')) document.getElementById('p0_l8_high_val').textContent = h;
  if(document.getElementById('p0_l8_low_val')) document.getElementById('p0_l8_low_val').textContent = l;

  const isGreen = c >= o;
  const color = isGreen ? '#22c55e' : '#ef4444';

  const view = document.getElementById('p0_l8_candle_view');
  if(!view) return;

  const minY = 70, maxY = 130;
  const scaleY = (val) => 150 - ((val - minY) / (maxY - minY)) * 140;

  const yHigh = scaleY(h);
  const yLow = scaleY(l);
  const yTop = scaleY(Math.max(o, c));
  const yBot = scaleY(Math.min(o, c));
  const height = Math.max(4, yBot - yTop);

  view.innerHTML = `
    <svg width="100" height="160" viewBox="0 0 100 160">
      <!-- Wick -->
      <line x1="50" y1="${yHigh}" x2="50" y2="${yLow}" stroke="${color}" stroke-width="2"/>
      <!-- Body -->
      <rect x="35" y="${yTop}" width="30" height="${height}" fill="${color}" rx="2"/>
    </svg>
    <div style="position:absolute; bottom:6px; font-size:10px; font-weight:800; color:${color}">${isGreen?'🟢 БЫЧЬЯ (РОСТ)':'🔴 МЕДВЕЖЬЯ (СПАД)'}</div>
  `;
}

let p0L10Side = 'LONG';
function setP0L10Side(side){
  p0L10Side = side;
  const btnL = document.getElementById('p0_l10_btn_long');
  const btnS = document.getElementById('p0_l10_btn_short');
  if(side === 'LONG'){
    if(btnL) { btnL.className = 'btn sm'; btnL.style.background = 'var(--ok)'; }
    if(btnS) { btnS.className = 'btn sm ghost'; btnS.style.background = 'transparent'; }
  } else {
    if(btnS) { btnS.className = 'btn sm'; btnS.style.background = 'var(--bad)'; }
    if(btnL) { btnL.className = 'btn sm ghost'; btnL.style.background = 'transparent'; }
  }
  updateP0L10PnL();
}
function updateP0L10PnL(){
  const p = parseFloat(document.getElementById('p0_l10_slider')?.value || 110);
  const textVal = document.getElementById('p0_l10_price_val');
  const pnlText = document.getElementById('p0_l10_pnl_text');
  const exp = document.getElementById('p0_l10_explanation');
  if(textVal) textVal.textContent = p;

  let pnl = 0;
  if(p0L10Side === 'LONG'){
    pnl = p - 100;
    if(exp) exp.textContent = `Купил по $100 ➔ Продал по $${p}`;
  } else {
    pnl = 100 - p;
    if(exp) exp.textContent = `Продал по $100 (Short) ➔ Откупил по $${p}`;
  }

  const isProf = pnl >= 0;
  const col = isProf ? 'var(--ok)' : 'var(--bad)';
  if(pnlText){
    pnlText.style.color = col;
    pnlText.textContent = `${isProf?'+':''}$${pnl.toFixed(2)} (${isProf?'+':''}${pnl.toFixed(1)}%)`;
  }
}

function updateP0L11Drawdown(){
  const loss = parseFloat(document.getElementById('p0_l11_slider')?.value || 50);
  const lossEl = document.getElementById('p0_l11_loss_val');
  const remEl = document.getElementById('p0_l11_rem');
  const recEl = document.getElementById('p0_l11_rec');
  if(lossEl) lossEl.textContent = loss;

  const rem = 10000 * (1 - loss/100);
  const rec = ((1 / (1 - loss/100)) - 1) * 100;

  if(remEl) remEl.textContent = `$${rem.toLocaleString('en-US')}`;
  if(recEl) recEl.textContent = `+${rec.toFixed(1)}%`;
}

function runP0L13Flips(N){
  let heads = 0;
  for(let i=0; i<N; i++){
    if(Math.random() < 0.5) heads++;
  }
  const tails = N - heads;
  const freq = ((heads / N) * 100).toFixed(2);

  const hEl = document.getElementById('p0_l13_heads');
  const tEl = document.getElementById('p0_l13_tails');
  const totEl = document.getElementById('p0_l13_total');
  const fEl = document.getElementById('p0_l13_freq');

  if(hEl) hEl.textContent = heads;
  if(tEl) tEl.textContent = tails;
  if(totEl) totEl.textContent = N;
  if(fEl) {
    fEl.textContent = `${freq}%`;
    fEl.style.color = Math.abs(parseFloat(freq) - 50.0) < 1.0 ? 'var(--ok)' : 'var(--warn)';
  }
}






