// 2. Тренажёр «Прочитай свечу» и критическое мышление (Урок 0.8)
let candleTrainerStep = 0;
const CANDLE_TRAINER_DATA = [
  { open: 92, close: 108, high: 115, low: 88, isBull: true, q: 'Какова цена закрытия (Close) у этой зеленой свечи?', ask: 'close' },
  { open: 110, close: 95, high: 118, low: 90, isBull: false, q: 'Какова цена открытия (Open) у этой красной свечи?', ask: 'open' }
];
/* P2-8: генератор случайных свечей — тренажёр действительно «генерирует», а не показывает 2 фиксированных */
(function generateCandles(){
  let seed = 20260831;
  const rnd = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
  /* вопросы теперь строятся по полю ask (ротация O/H/L/C) — чек-лист экспертов p0_l8 */
  for(let k = 0; k < 10; k++){
    const isBull = rnd() > 0.5;
    const open = 60 + Math.round(rnd() * 60);
    const close = isBull ? open + 8 + Math.round(rnd() * 24) : open - 8 - Math.round(rnd() * 24);
    const high = Math.max(open, close) + Math.round(rnd() * 10);
    const low = Math.min(open, close) - Math.round(rnd() * 10);
    const ASK_CYCLE = ['close','high','low','open'];
    const ask = ASK_CYCLE[k % 4];
    const qText = {close:'Какова цена закрытия (Close) этой свечи?', high:'Определи максимум свечи: какова цена High?', low:'Определи минимум свечи: какова цена Low?', open:'Какова цена открытия (Open) этой свечи?'}[ask];
    CANDLE_TRAINER_DATA.push({ open, close, high, low, isBull, q: qText, ask });
  }
})();

function renderCandleTrainer(){
  const box = document.getElementById('widget_p0_l8');
  if(!box) return;

  const data = CANDLE_TRAINER_DATA[candleTrainerStep % CANDLE_TRAINER_DATA.length];
  /* варианты = все 4 цены OHLC, порядок детерминированно «тасуется» от шага к шагу */
  const optsBase = [data.high, Math.max(data.open, data.close), Math.min(data.open, data.close), data.low];
  const shift = candleTrainerStep % 4;
  const opts = optsBase.map((_, i) => optsBase[(i + shift) % 4]);
  const col = data.isBull ? '#22c55e' : '#ef4444';

  box.innerHTML = `
    <div style="background:rgba(34,197,94,.05); border:1.5px solid var(--ok); border-radius:12px; padding:16px; margin:16px 0">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px">
        <span style="font-size:12px; font-weight:800; color:var(--ok); text-transform:uppercase">🕯️ ТРЕНАЖЁР «ПРОЧИТАЙ СВЕЧУ»</span>
        <span class="badge" style="background:${col}22; color:${col}">${data.isBull?'🟢 Зеленая (Рост)':'🔴 Красная (Спад)'}</span>
      </div>

      <div style="display:grid; grid-template-columns:140px 1fr; gap:16px; align-items:center; background:#040714; padding:14px; border-radius:8px; margin-bottom:12px">
        <!-- SVG Candle -->
        <div style="text-align:center">
          <svg width="100" height="150" viewBox="0 0 100 150">
            <!-- Wick -->
            <line x1="50" y1="15" x2="50" y2="135" stroke="${col}" stroke-width="2.5"/>
            <!-- Body -->
            <rect x="30" y="${data.isBull?40:30}" width="40" height="70" fill="${col}" rx="2"/>
            <!-- Labels -->
            <text x="75" y="20" fill="#94a3b8" font-size="10">High: $${data.high}</text>
            <text x="75" y="${data.isBull?45:35}" fill="#f8fafc" font-size="10" font-weight="700">${data.isBull?'Close':'Open'}: $${data.isBull?data.close:data.open}</text>
            <text x="75" y="${data.isBull?105:95}" fill="#f8fafc" font-size="10" font-weight="700">${data.isBull?'Open':'Close'}: $${data.isBull?data.open:data.close}</text>
            <text x="75" y="140" fill="#94a3b8" font-size="10">Low: $${data.low}</text>
          </svg>
        </div>

        <div>
          <div style="font-size:13.5px; font-weight:700; color:var(--txt); margin-bottom:10px">${data.q} <span style="font-size:11px;color:var(--mut)">· вопрос ${(candleTrainerStep % 4) + 1}/4 цикла OHLC</span></div>
          <div style="display:flex; gap:8px; flex-wrap:wrap">
            ${opts.map(v => '<button class="btn sm ghost" onclick="handleCandleAns(' + v + ')">$' + v + '</button>').join('')}
          </div>
          <div id="candle_fb" style="margin-top:10px; display:none; padding:8px 12px; border-radius:6px; font-size:12px"></div>
        </div>
      </div>

      <!-- Critical Thinking Block: What the candle does NOT tell you -->
      <div style="background:rgba(255,255,255,.02); border-left:3px solid var(--warn); padding:10px 14px; border-radius:4px; font-size:12.5px; color:var(--txt); line-height:1.5">
        <b>🧠 Что мы ТОЧНО знаем:</b> За этот час цена стартовала со $${data.open}, долетала до $${data.high}, падала до $${data.low} и зафиксировалась на $${data.close}.<br>
        <b>⚠️ Чего мы НЕ знаем:</b> Свеча НЕ гарантирует, куда цена пойдет в следующий час. Будущее всегда остается вероятностным.
      </div>
    </div>
  `;
}

function handleCandleAns(val){
  const data = CANDLE_TRAINER_DATA[candleTrainerStep % CANDLE_TRAINER_DATA.length];
  const askName = {close:'закрытия (Close)', high:'максимум (High)', low:'минимум (Low)', open:'открытия (Open)'}[data.ask || 'close'];
  const target = data[data.ask || 'close'];
  const fb = document.getElementById('candle_fb');
  if(!fb) return;

  fb.style.display = 'block';
  if(val === target){
    fb.style.background = 'rgba(34,197,94,.15)';
    fb.style.border = '1px solid var(--ok)';
    fb.innerHTML = `<b>Верно! 🎯</b> ${askName} = $${val}. <button class="btn sm" style="margin-left:8px" onclick="candleTrainerStep++; renderCandleTrainer();">Следующая свеча ➔</button>`;
  } else {
    fb.style.background = 'rgba(239,68,68,.15)';
    fb.style.border = '1px solid var(--bad)';
    fb.innerHTML = `<b>Неверно.</b> Ищем цену ${askName} — внимательно посмотри на соответствующий уровень свечи.`;
  }
}


