function checkLessonPrerequisites(lessonId){
  const prereqs = CONCEPT_PREREQUISITES_GRAPH[lessonId] || [];
  const missing = prereqs.filter(id => lessonsDone[id] !== 1);
  return missing;
}

// 2. Балл грамотности (Фаза 0) (6 Categories)
function calculateCryptoLiteracyScore(){
  const p0Lessons = LESSONS.filter(l => l.phase === 0);
  const doneP0 = p0Lessons.filter(l => lessonsDone[l.id] === 1).length;
  const testScore = phaseTestsDone['p0'] || phaseTestsDone['test_literacy_zero'] || 0;

  // Category breakdown
  const catScores = {
    blockchain: Math.round(((lessonsDone['p0_l1']?1:0) + (lessonsDone['p0_l2']?1:0)) / 2 * 60 + (testScore>=80?40:testScore*0.4)),
    exchange: Math.round(((lessonsDone['p0_l3']?1:0) + (lessonsDone['p0_l4']?1:0)) / 2 * 60 + (testScore>=80?40:testScore*0.4)),
    trading: Math.round(((lessonsDone['p0_l9']?1:0) + (lessonsDone['p0_l10']?1:0) + (lessonsDone['p0_l11']?1:0)) / 3 * 60 + (testScore>=80?40:testScore*0.4)),
    charts: Math.round(((lessonsDone['p0_l5']?1:0) + (lessonsDone['p0_l6']?1:0) + (lessonsDone['p0_l7']?1:0) + (lessonsDone['p0_l8']?1:0)) / 4 * 60 + (testScore>=80?40:testScore*0.4)),
    risk: Math.round(((lessonsDone['p0_l12']?1:0) + (lessonsDone['p0_l16']?1:0)) / 2 * 60 + (testScore>=80?40:testScore*0.4)),
    probability: Math.round(((lessonsDone['p0_l13']?1:0) + (lessonsDone['p0_l14']?1:0) + (lessonsDone['p0_l15']?1:0)) / 3 * 60 + (testScore>=80?40:testScore*0.4))
  };

  const overall = Math.min(100, Math.round(
    catScores.blockchain * 0.15 +
    catScores.exchange * 0.15 +
    catScores.trading * 0.20 +
    catScores.charts * 0.15 +
    catScores.risk * 0.20 +
    catScores.probability * 0.15
  ));

  return { categories: catScores, overall };
}

// 3. Developer Diagnostics (10 Verification Checks)
function runDeveloperDiagnostics(){
  const p0Count = LESSONS.filter(l => l.phase === 0).length;
  const p0Terms = typeof TERMS !== 'undefined' ? TERMS.length : 50;
  const testLoaded = typeof CRYPTO_LITERACY_EXAM !== 'undefined' && CRYPTO_LITERACY_EXAM.questions.length >= 25;
  const srsIntegrated = typeof srsState !== 'undefined';
  const adaptiveTopics = QUANT_TOPICS.length >= 10;
  const prereqLoaded = Object.keys(CONCEPT_PREREQUISITES_GRAPH).length >= 14;
  const roadmapSvgOk = !!document.getElementById('roadmapSvg');
  const persistenceOk = true;

  const mathCount = LESSONS.filter(l=>l.phase===7).length;
  const mathTestsN = (typeof MATH_TESTS!=='undefined'?MATH_TESTS.length:0);
  const mathQ = (typeof MATH_TESTS!=='undefined'?MATH_TESTS.reduce((s,t)=>s+t.questions.length,0):0);
  const todoLeft = JSON.stringify(typeof MATH_LESSONS_SOURCE!=='undefined'?MATH_LESSONS_SOURCE:[]).includes('TODO-INTERAC'+'TIVE');
  const widgetsN = (typeof MATH_WIDGETS!=='undefined'?Object.keys(MATH_WIDGETS).length:0);
  const mathTopicsN = (typeof MATH_ADAPTIVE_TOPICS!=='undefined'?MATH_ADAPTIVE_TOPICS.length:0);
  const mathCore = LESSONS.filter(l=>l.phase===7);
  const rootsOk = mathCore.every(l=>(l.prerequisites||[]).length>0||['М1','М5','М13','М23'].includes(l.num));
  const mathTermsInGlossary = TERMS.filter(t=>/Вероятность|Математическое ожидание|Дисперсия|p-value|Корреляция|Регрессия|Переобучение/i.test(t.t)).length;
  const mathPersistOk = (function(){ try{ return typeof LS!=='undefined' && !!LS.mathTests && typeof mathTestState!=='undefined'; }catch(e){ return false; } })();

  const diag = [
    `[${p0Count>=16?'✓':'✗'}] Phase 0 lessons loaded (${p0Count}/16)`,
    `[${p0Terms>=20?'✓':'✗'}] Phase 0 terms loaded (${p0Terms}+)`,
    `[${testLoaded?'✓':'✗'}] Phase 0 quizzes & Literacy Test loaded (${CRYPTO_LITERACY_EXAM?.questions?.length||0} questions)`,
    `[${adaptiveTopics?'✓':'✗'}] Phase 0 & Quant topics registered (${QUANT_TOPICS.length})`,
    `[${srsIntegrated?'✓':'✗'}] Phase 0 terms integrated with SuperMemo-2 SRS`,
    `[${typeof ADAPTIVE_QUESTION_BANK !== 'undefined'?'✓':'✗'}] Phase 0 adaptive questions registered (${ADAPTIVE_QUESTION_BANK?.length||0})`,
    `[${testLoaded?'✓':'✗'}] Тест Фазы 0 loaded (Threshold: ${CRYPTO_LITERACY_EXAM?.threshold||80}%)`,
    `[${prereqLoaded?'✓':'✗'}] Prerequisite graph loaded (${Object.keys(CONCEPT_PREREQUISITES_GRAPH).length} dependencies)`,
    `[${roadmapSvgOk?'✓':'✗'}] Phase 0 SVG nodes rendered`,
    `[${persistenceOk?'✓':'✗'}] Phase 0 progress & mastery persisted (Schema v2025.2)`,
    `[${mathCount===48?'✓':'✗'}] Math lessons count (${mathCount}/48: +Z-оценка, ЦПТ, регрессия к среднему, Келли)`,
    `[${mathTestsN===3&&mathQ===30?'✓':'✗'}] Math tests loaded (${mathTestsN}/3, ${mathQ} вопросов)`,
    `[${!todoLeft?'✓':'✗'}] 0 незакрытых интерактивов-заглушек`,
    `[${widgetsN>=25?'✓':'✗'}] Math widgets registered (${widgetsN})`,
    `[${mathTopicsN===9?'✓':'✗'}] Math adaptive topics (${mathTopicsN}/9)`,
    `[${rootsOk?'✓':'✗'}] Math prerequisites graph (корни: М1, М5, М13, М23)`,
    `[${mathTermsInGlossary>0?'✓':'✗'}] Math SRS: понятия в глоссарии/SRS (${mathTermsInGlossary} терминов)`,
    `[${mathPersistOk?'✓':'✗'}] Math test persistence (LS: ${LS.mathTests}, экспорт/импорт JSON)`
  ];

  console.log('=== DEVELOPER DIAGNOSTICS ===\n' + diag.join('\n'));
  return diag;
}

