const ABBREVIATION_GLOSSARY = {
  'OOS': { title: 'Out-of-Sample (OOS)', text: 'Тестирование стратегии на чистых данных, которые алгоритм никогда не видел при подборе параметров.' },
  // D2.4: hover-хинты жаргона Фаз 1–5
  'EDA': { title: 'EDA — Exploratory Data Analysis', text: 'Разведочный анализ данных: графики, распределения, пропуски и выбросы до построения модели. Первый шаг любой исследовательской работы с рядом.' },
  'SIGINT': { title: 'SIGINT (сигнал прерывания)', text: 'Системный сигнал остановки процесса (Ctrl+C). Продакшн-бот обязан перехватывать его и корректно закрывать позиции и соединения, а не умирать мгновенно.' },
  'SIGTERM': { title: 'SIGTERM (сигнал завершения)', text: 'Системный сигнал «вежливого» завершения процесса (от systemd/оркестратора). Обработчик должен выполнить graceful shutdown: отменить ордера, закрыть WebSocket, сохранить состояние.' },
  'OOM': { title: 'OOM — Out Of Memory', text: 'Исчерпание оперативной памяти процессом. Linux-ядро тогда убивает процесс (OOM-killer) — для торгового бота это внезапная смерть посреди позиции. Лечится лимитами, стримингом данных и мониторингом.' },
  'NVMe': { title: 'NVMe-диск', text: 'Быстрый твердотельный накопитель (новее SATA SSD). Для бота важен при записи тиковых данных и логов: не «захлёбывается» на пиковых нагрузках.' },
  'mark price': { title: 'Mark Price (расчётная цена)', text: 'Справедливая цена контракта по индексу спота, которую биржа использует для ликвидаций и расчёта маржи — чтобы случайный «фитиль» на самой бирже не выбивал позиции.' },
  'OU': { title: 'Процесс Орнштейна — Уленбека', text: 'Математическая модель возврата к среднему: спред «тянет» к равновесию с постоянной скоростью. Half-Life показывает, за какое время отклонение в среднем сокращается вдвое.' },
  'Kalman': { title: 'Фильтр Калмана', text: 'Рекурсивный алгоритм оценки скрытого состояния (например, истинного hedge ratio) по зашумлённым наблюдениям. Обновляет оценку с каждым новым наблюдением без пересчёта всей истории.' },
  'MinHash': { title: 'MinHash / SimHash', text: 'Алгоритмы быстрого поиска почти-дубликатов текстов. Боту нужны, чтобы не реагировать на одну и ту же новость, перепостенную в 20 каналах.' },
  'stationary_series': { title: 'Стационарный ряд', text: 'Ряд, чьи статистические свойства (среднее, дисперсия) не меняются во времени. Доходности близки к стационарным, цены — нет. Проверяется тестами ADF и KPSS.' },
  'Look-ahead': { title: 'Утечка из будущего (Look-ahead Bias)', text: 'Критическая ошибка бэктеста: использование данных из будущего (например, цены Close до закрытия свечи или глобального min/max датасета).' },
  'look-ahead': { title: 'Утечка из будущего (Look-ahead Bias)', text: 'Критическая ошибка бэктеста: использование данных из будущего (например, цены Close до закрытия свечи или глобального min/max датасета).' },
  'bps': { title: 'Базисный пункт (bps)', text: '1 bps = 0.01% (одна сотая процента, или 0.0001 от суммы). Стандартная единица измерения биржевых комиссий и проскальзывания.' },
  'slippage': { title: 'Проскальзывание (Slippage)', text: 'Разница между ценой в момент отправки ордера и фактической ценой его исполнения на бирже из-за движения стакана.' },
  'spread': { title: 'Спред (Bid/Ask Spread)', text: 'Разница между лучшей ценой покупки (Bid) и лучшей ценой продажи (Ask) в книге заявок.' },
  'trend': { title: 'Бычий тренд (Trend / Momentum)', text: 'Устойчивое направленное движение цены вверх, где эффективны пробойные и трендовые стратегии.' },
  'range': { title: 'Боковик / Флэт (Range / Mean Reversion)', text: 'Фаза рынка без явного направления, где цена колеблется вокруг средней, сливая трендовых ботов.' },
  'regime': { title: 'Смена рыночного режима (Market Regime)', text: 'Переход рынка из одного статистического состояния в другое (например, из импульсного тренда в пилообразный боковик).' },
  'Sharpe': { title: 'Коэффициент Шарпа (Sharpe Ratio)', text: 'Отношение избыточной доходности стратегии к её волатильности (риску). Значение > 1.5 говорит о высоком качестве альфы.' },
  'drawdown_asymmetry': { title: 'Асимметрия просадки', text: 'Математический закон: чтобы восстановить убыток −50%, нужен рост +100%; после −80% нужен рост +400%, а после −90% — уже +900%.' },
  'risk_per_trade': { title: 'Риск на сделку (1–2%)', text: 'Максимальный размер потерь от депозита при срабатывании стоп-лосса. Гарантирует выживание капитала на дистанции.' },
  'loss_streak': { title: 'Серия убытков (Losing Streak)', text: 'Математически неизбежная череда убытков подряд: при 500 сделках стрик из 8–10 убытков случается даже у ботов с винрейтом 55%.' },
  'bips': { title: 'Базисный пункт (bips)', text: 'То же, что bps: 1 bips = 0.01% от объёма сделки.' },
  'APY': { title: 'Годовая доходность (APY)', text: 'Annual Percentage Yield — доходность за год с учётом сложного процента.' },
  'MMR': { title: 'Поддерживающая маржа (MMR)', text: 'Maintenance Margin Rate — критический порог обеспечения, ниже которого биржа принудительно ликвидирует позицию.' },
  'FIFO': { title: 'Метод FIFO (First In, First Out)', text: 'Налоговый метод списания активов: первыми продаются монеты, купленные раньше всех.' },
  'CAPM': { title: 'Модель CAPM', text: 'Разложение доходности стратегии на рыночный риск (Beta) и чистое мастерство архитектора (Alpha).' },
  'SM-2': { title: 'Алгоритм SuperMemo-2 (SM-2)', text: 'Алгоритм интервальных повторений, адаптирующий интервал карточки под качество запоминания.' },
  'ADF': { title: 'Тест Дики-Фуллера (ADF Test)', text: 'Статистический тест на стационарность ценового ряда (проверка наличия единичного корня).' },
  'KPSS': { title: 'Тест KPSS', text: 'Тест на стационарность ценового ряда вокруг детерминированного тренда. Используется в паре с ADF.' },
  'TWAP': { title: 'Алгоритм TWAP', text: 'Time-Weighted Average Price — исполнение крупной заявки равными частями через фиксированные интервалы времени.' },
  'VWAP': { title: 'Алгоритм VWAP', text: 'Volume-Weighted Average Price — исполнение крупной заявки пропорционально рыночному объёму торгов.' },
  'VaR': { title: 'Value-at-Risk (VaR)', text: 'Оценка максимального ожидаемого убытка с заданной доверительной вероятностью (например, 95%) за 1 день.' },
  'CVaR': { title: 'Conditional VaR (CVaR)', text: 'Средний размер катастрофического убытка в случае пробития худшего сценария VaR.' },
  'CEX': { title: 'Централизованная биржа (CEX)', text: 'Биржа с единым оператором (кастодиальная), требующая KYC и хранящая средства пользователей.' },
  'DEX': { title: 'Децентрализованная биржа (DEX)', text: 'Торговля на смарт-контрактах через пулы ликвидности прямо с некастодиального кошелька.' },
  'PnL': { title: 'Profit & Loss (PnL)', text: 'Финансовый результат сделки: прибыль или убыток в абсолютном выражении или процентах.' },
  'MaxDD': { title: 'Максимальная просадка (Max Drawdown)', text: 'Наибольшее падение капитала от исторического пика до локального дна.' },
  'OHLC': { title: 'Свечи OHLC', text: 'Open (открытие), High (максимум), Low (минимум), Close (закрытие).' }
};

function searchGlossary(query){
  const inp = document.getElementById('glossary_search') || document.getElementById('search');
  if(inp){
    inp.value = query;
    inp.dispatchEvent(new Event('input'));
  }
}



/* =========================================================================
   ТРЕНАЖЁР: КОНСТРУКТОР СВЕЧИ 2.0 (5 РЕЖИМОВ · МАРКИРОВКА 🟢 НОВИЧОК)
   ========================================================================= */

var candle2State = {
  mode: 'interactive', // 'interactive' | 'guess' | 'feed' | 'resample'
  open: 100,
  high: 115,
  low: 92,
  close: 110,
  timeframe: '1m',
  guessTarget: null,
  feedTicks: []
};


/* =========================================================================
   ГЕНЕРАТИВНЫЙ РЫНОЧНЫЙ ДВИЖОК ДЛЯ ТРЕНАЖЁРА СВЕЧЕЙ & ГРАФИКОВ
   ========================================================================= */

var liveTickTimer = null;
var liveCandleData = {
  regime: 'chop', // 'bull', 'bear', 'chop', 'flash_crash'
  volatility: 1.5,
  ticksCount: 0,
  currentPrice: 100.0,
  history: []
};

function setMarketRegime(regime, btn){
  liveCandleData.regime = regime;
  document.querySelectorAll('#market_regime_controls .chip').forEach(c => c.classList.remove('active'));
  if(btn) btn.classList.add('active');

  const descEl = document.getElementById('market_regime_desc');
  if(!descEl) return;

  if(regime === 'bull'){
    liveCandleData.volatility = 2.0;
    descEl.innerHTML = '🚀 <b>Бычий импульс:</b> Покупатели доминируют в стакане, преобладают покупки по рынку (Market Taker Buy), восходящий дрейф цены.';
  } else if(regime === 'bear'){
    liveCandleData.volatility = 2.5;
    descEl.innerHTML = '📉 <b>Медвежий дамп:</b> Агрессивные продажи, каскадные срабатывания стоп-лоссов, длинные верхние тени свечей.';
  } else if(regime === 'chop'){
    liveCandleData.volatility = 1.0;
    descEl.innerHTML = '🦀 <b>Боковик (Пила / Mean Reversion):</b> Равновесие спроса и предложения, ложные пробои уровней, формируются свечи Доджи.';
  } else if(regime === 'flash_crash'){
    liveCandleData.volatility = 6.0;
    descEl.innerHTML = '⚡ <b>Черный лебедь (Flash Crash):</b> Мгновенное исчезновение ликвидности в стакане, гигантское проскальзывание и длинный фитиль снизу.';
  }
}

function generateNextMarketTick(){
  let drift = 0;
  let jump = 0;

  if(liveCandleData.regime === 'bull'){
    drift = 0.45;
  } else if(liveCandleData.regime === 'bear'){
    drift = -0.50;
  } else if(liveCandleData.regime === 'chop'){
    drift = (100.0 - liveCandleData.currentPrice) * 0.15; // Возврат к среднему
  } else if(liveCandleData.regime === 'flash_crash'){
    if(liveCandleData.ticksCount < 4) drift = -4.0;
    else drift = +3.5; // Откуп пролива
  }

  // Случайный шум (Geometric Brownian Motion)
  const noise = (Math.random() - 0.49) * liveCandleData.volatility * 2.2;
  const delta = drift + noise + jump;

  liveCandleData.currentPrice = Math.max(10, Math.min(200, liveCandleData.currentPrice + delta));
  liveCandleData.ticksCount++;

  // Обновляем параметры свечи в candle2State
  candle2State.close = Math.round(liveCandleData.currentPrice * 10) / 10;
  candle2State.high = Math.max(candle2State.high, candle2State.close);
  candle2State.low = Math.min(candle2State.low, candle2State.close);

  renderCandleConstructor2();

  const tickLog = document.getElementById('candle_tick_feed');
  if(tickLog){
    const col = delta >= 0 ? 'var(--ok)' : 'var(--bad)';
    const arrow = delta >= 0 ? '▲' : '▼';
    const logItem = `<span style="display:inline-block; margin-right:8px; color:${col}; font-family:var(--mono)">${arrow} $${candle2State.close.toFixed(1)}</span>`;
    tickLog.innerHTML = logItem + tickLog.innerHTML.substring(0, 300);
  }
}

function toggleLiveTickSimulation(btn){
  if(liveTickTimer){
    clearInterval(liveTickTimer);
    liveTickTimer = null;
    if(btn) {
      btn.textContent = '▶ Запустить тиковый поток';
      btn.classList.remove('active');
    }
  } else {
    liveCandleData.ticksCount = 0;
    liveTickTimer = setInterval(generateNextMarketTick, 350);
    if(btn) {
      btn.textContent = '⏸ Остановить тиковый поток';
      btn.classList.add('active');
    }
  }
}

function generateRandomMarketCandle(){
  if(liveTickTimer) toggleLiveTickSimulation();

  const openPrice = 90 + Math.round(Math.random() * 25);
  const isUp = Math.random() > 0.5;
  const bodySize = 5 + Math.round(Math.random() * 25);
  const closePrice = isUp ? openPrice + bodySize : openPrice - bodySize;

  const topWick = Math.round(Math.random() * 15);
  const botWick = Math.round(Math.random() * 15);

  candle2State.open = openPrice;
  candle2State.close = closePrice;
  candle2State.high = Math.max(openPrice, closePrice) + topWick;
  candle2State.low = Math.min(openPrice, closePrice) - botWick;
  liveCandleData.currentPrice = closePrice;

  renderCandleConstructor2();
}

function applyPatternPreset(patternName){
  if(liveTickTimer) toggleLiveTickSimulation();

  if(patternName === 'hammer'){
    candle2State.open = 100;
    candle2State.close = 105;
    candle2State.high = 106;
    candle2State.low = 75; // Длинный нижний фитиль
  } else if(patternName === 'shooting_star'){
    candle2State.open = 105;
    candle2State.close = 100;
    candle2State.high = 130; // Длинный верхний фитиль
    candle2State.low = 98;
  } else if(patternName === 'doji'){
    candle2State.open = 100;
    candle2State.close = 100;
    candle2State.high = 120;
    candle2State.low = 80;
  } else if(patternName === 'marubozu'){
    candle2State.open = 85;
    candle2State.close = 125;
    candle2State.high = 125; // Без теней
    candle2State.low = 85;
  }

  liveCandleData.currentPrice = candle2State.close;
  renderCandleConstructor2();
}


// Паттерны свечей доступны ТОЛЬКО в продвинутом режиме панели симуляторов
let candle2AdvancedMode = false;
function toggleCandleAdvanced(){
  candle2AdvancedMode = !candle2AdvancedMode;
  renderCandleConstructor2('sim_candle_widget_container');
}

function renderCandleConstructor2(containerId = 'widget_p0_l6'){
  const box = document.getElementById(containerId) || document.getElementById('sim_candle_widget_container');
  if(!box) return;

  // Основной режим Phase 0 (урок 0.6) — без паттернов; продвинутый режим — только в панели симуляторов
  const advAllowed = containerId !== 'widget_p0_l6';
  const adv = advAllowed && candle2AdvancedMode;

  const isBull = candle2State.close >= candle2State.open;
  const col = isBull ? '#22c55e' : '#ef4444';
  const bodyH = Math.abs(candle2State.close - candle2State.open);
  const upWick = candle2State.high - Math.max(candle2State.open, candle2State.close);
  const lowWick = Math.min(candle2State.open, candle2State.close) - candle2State.low;

  // SVG Scaler (prices 60..150 -> Y 190..15)
  const toY = (p) => 190 - ((p - 60) / 90) * 175;

  const yHigh = toY(candle2State.high);
  const yLow = toY(candle2State.low);
  const yTop = toY(Math.max(candle2State.open, candle2State.close));
  const yBot = toY(Math.min(candle2State.open, candle2State.close));
  const svgBodyH = Math.max(4, yBot - yTop);

  // Pattern detection (только продвинутый режим)
  let patternName = 'Обычная свеча';
  let patternClass = 'var(--txt)';
  if(adv){
    if(bodyH <= 1 && upWick >= 10 && lowWick >= 10){
      patternName = '⚖️ Доджи (Doji) — неопределённость рынка';
      patternClass = 'var(--warn)';
    } else if(lowWick >= bodyH * 2.5 && upWick <= bodyH * 0.5){
      patternName = '🔨 Молот (Hammer) — часто читается как бычий откуп';
      patternClass = 'var(--ok)';
    } else if(upWick >= bodyH * 2.5 && lowWick <= bodyH * 0.5){
      patternName = '💫 Падающая звезда (Shooting Star) — часто читается как медвежий сигнал';
      patternClass = 'var(--bad)';
    } else if(upWick <= 2 && lowWick <= 2 && bodyH >= 20){
      patternName = '🚀 Марубозу (Marubozu) — сильное однонаправленное движение бара';
      patternClass = isBull ? 'var(--ok)' : 'var(--bad)';
    }
    patternName += ' · ⚠️ паттерн не гарантирует направление: это описание формы бара, а не прогноз';
  }

  box.innerHTML = `
    <div style="background:var(--card); border:1.5px solid var(--line); border-radius:14px; padding:20px; margin:16px 0; box-shadow:var(--shadow)">
      
      <!-- Заголовок и пресеты паттернов -->
      <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:16px">
        <div style="display:flex; align-items:center; gap:8px">
          <span class="badge" style="background:rgba(34,197,94,.15); color:var(--ok); font-weight:800">ГЕНЕРАТИВНЫЙ ДВИЖОК 2.0</span>
          <h4 style="margin:0; font-size:16px; color:var(--txt)">🕯️ Интерактивный конструктор свечи</h4>
        </div>
        <div style="display:flex; gap:6px; flex-wrap:wrap">
          ${adv ? `
            <button class="btn sm ghost" onclick="applyPatternPreset('hammer')">🔨 Молот</button>
            <button class="btn sm ghost" onclick="applyPatternPreset('shooting_star')">💫 Звезда</button>
            <button class="btn sm ghost" onclick="applyPatternPreset('doji')">⚖️ Доджи</button>
            <button class="btn sm ghost" onclick="applyPatternPreset('marubozu')">🚀 Марубозу</button>
          ` : ''}
          ${advAllowed ? `<button class="btn sm ghost" style="${adv?'':'color:var(--acc1)'}" onclick="toggleCandleAdvanced()">${adv?'🎓 Базовый режим':'🚀 Продвинутый режим (паттерны)'}</button>` : ''}
          <button class="btn sm" onclick="generateRandomMarketCandle()">🎲 Случайная свеча</button>
        </div>
      </div>

      <!-- Переключатель рыночных режимов -->
      <div style="background:rgba(255,255,255,.02); border:1px solid var(--line); border-radius:10px; padding:12px; margin-bottom:16px">
        <div style="font-size:11px; font-weight:800; color:var(--mut); text-transform:uppercase; margin-bottom:8px">Рыночный режим генератора тиков:</div>
        <div class="controls" id="market_regime_controls" style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:8px">
          <button class="chip" onclick="setMarketRegime('bull', this)">🚀 Бычий импульс</button>
          <button class="chip" onclick="setMarketRegime('bear', this)">📉 Медвежий дамп</button>
          <button class="chip active" onclick="setMarketRegime('chop', this)">🦀 Боковик / Пила</button>
          <button class="chip" onclick="setMarketRegime('flash_crash', this)">⚡ Flash Crash</button>
        </div>
        <div id="market_regime_desc" style="font-size:12.5px; color:var(--mut); margin-bottom:10px">
          🦀 <b>Боковик (Пила / Mean Reversion):</b> Равновесие спроса и предложения, возврат к средней цене.
        </div>
        <div style="display:flex; align-items:center; gap:12px; flex-wrap:wrap">
          <button class="btn sm" id="btn_live_ticks" onclick="toggleLiveTickSimulation(this)">▶ Запустить тиковый поток</button>
          <div id="candle_tick_feed" style="font-size:12px; color:var(--mut); overflow:hidden; white-space:nowrap; max-width:400px"></div>
        </div>
      </div>

      <!-- Основная область: Свеча SVG + Ползунки -->
      <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(280px, 1fr)); gap:20px; align-items:center">
        
        <!-- SVG Графика свечи -->
        <div style="background:#090d1f; border:1px solid var(--line); border-radius:12px; padding:16px; text-align:center">
          <svg width="220" height="210" style="overflow:visible; margin:0 auto; display:block">
            <!-- Сетка цен -->
            <line x1="30" y1="${toY(140)}" x2="190" y2="${toY(140)}" stroke="rgba(255,255,255,.07)" stroke-dasharray="3"/>
            <text x="25" y="${toY(140)+4}" fill="var(--mut)" font-size="10" text-anchor="end">$140</text>
            <line x1="30" y1="${toY(100)}" x2="190" y2="${toY(100)}" stroke="rgba(255,255,255,.07)" stroke-dasharray="3"/>
            <text x="25" y="${toY(100)+4}" fill="var(--mut)" font-size="10" text-anchor="end">$100</text>
            <line x1="30" y1="${toY(70)}" x2="190" y2="${toY(70)}" stroke="rgba(255,255,255,.07)" stroke-dasharray="3"/>
            <text x="25" y="${toY(70)+4}" fill="var(--mut)" font-size="10" text-anchor="end">$70</text>

            <!-- Верхняя и нижняя тени (Фитиль) -->
            <line x1="110" y1="${yHigh}" x2="110" y2="${yLow}" stroke="${col}" stroke-width="3" stroke-linecap="round"/>
            
            <!-- Тело свечи -->
            <rect x="85" y="${yTop}" width="50" height="${svgBodyH}" fill="${col}" rx="4" stroke="${col}" stroke-width="1.5"/>

            <!-- Маркеры цен -->
            <text x="145" y="${yHigh+4}" fill="var(--mut)" font-size="11" font-weight="700">H: $${candle2State.high.toFixed(1)}</text>
            <text x="145" y="${yTop+10}" fill="var(--txt)" font-size="11" font-weight="700">O: $${candle2State.open.toFixed(1)}</text>
            <text x="145" y="${yBot+10}" fill="var(--txt)" font-size="11" font-weight="700">C: $${candle2State.close.toFixed(1)}</text>
            <text x="145" y="${yLow+4}" fill="var(--mut)" font-size="11" font-weight="700">L: $${candle2State.low.toFixed(1)}</text>
          </svg>

          <!-- Распознанный паттерн (только продвинутый режим) -->
          ${adv ? `
          <div style="margin-top:12px; padding:8px 12px; background:rgba(255,255,255,.04); border-radius:8px; font-size:13px; font-weight:800; color:${patternClass}">
            ${patternName}
            <div style="margin-top:6px; font-weight:400; font-size:11.5px; color:var(--warn)">⚠️ Паттерн — лишь описание формы бара. Он НЕ гарантирует направление будущей цены.</div>
          </div>` : ''}
        </div>

        <!-- Ручные ползунки параметров -->
        <div style="display:flex; flex-direction:column; gap:12px">
          <div>
            <div style="display:flex; justify-content:space-between; font-size:12.5px; color:var(--mut); margin-bottom:4px">
              <span>Цена открытия (Open):</span><b style="color:var(--txt)">$${candle2State.open.toFixed(1)}</b>
            </div>
            <input type="range" min="65" max="135" step="0.5" value="${candle2State.open}" oninput="updateCandle2Param('open', this.value)" style="width:100%">
          </div>
          <div>
            <div style="display:flex; justify-content:space-between; font-size:12.5px; color:var(--mut); margin-bottom:4px">
              <span>Максимум (High):</span><b style="color:var(--txt)">$${candle2State.high.toFixed(1)}</b>
            </div>
            <input type="range" min="65" max="145" step="0.5" value="${candle2State.high}" oninput="updateCandle2Param('high', this.value)" style="width:100%">
          </div>
          <div>
            <div style="display:flex; justify-content:space-between; font-size:12.5px; color:var(--mut); margin-bottom:4px">
              <span>Минимум (Low):</span><b style="color:var(--txt)">$${candle2State.low.toFixed(1)}</b>
            </div>
            <input type="range" min="60" max="135" step="0.5" value="${candle2State.low}" oninput="updateCandle2Param('low', this.value)" style="width:100%">
          </div>
          <div>
            <div style="display:flex; justify-content:space-between; font-size:12.5px; color:var(--mut); margin-bottom:4px">
              <span>Цена закрытия (Close):</span><b style="color:${col}">$${candle2State.close.toFixed(1)}</b>
            </div>
            <input type="range" min="65" max="140" step="0.5" value="${candle2State.close}" oninput="updateCandle2Param('close', this.value)" style="width:100%">
          </div>
        </div>
      </div>
    </div>
  `;
}

function updateCandle2Param(param, val){
  candle2State[param] = parseInt(val);
  candle2State.high = Math.max(candle2State.high, candle2State.open, candle2State.close);
  candle2State.low = Math.min(candle2State.low, candle2State.open, candle2State.close);
  renderCandleConstructor2();
}

function checkCandle2Guess(val){
  const fb = document.getElementById('c2_guess_fb');
  if(!fb) return;
  fb.style.display = 'block';
  if(val === 110){
    fb.style.background = 'rgba(34,197,94,.15)';
    fb.style.border = '1px solid var(--ok)';
    fb.innerHTML = '<b>Верно! 🎯</b> У зеленой свечи цена закрытия (Close) всегда находится на верхней границе тела ($110).';
  } else {
    fb.style.background = 'rgba(239,68,68,.15)';
    fb.style.border = '1px solid var(--bad)';
    fb.innerHTML = '<b>Неверно.</b> У зеленой свечи нижняя граница тела — это Open ($95), а верхняя граница — Close ($110).';
  }
}

function generateTradeFeedStep(){
  const list = document.getElementById('c2_feed_list');
  if(!list) return;
  const p = 95000 + Math.floor(Math.random() * 500);
  const q = (Math.random() * 2).toFixed(2);
  const t = `12:01:${Math.floor(Math.random()*50+10)} ➔ Сделка ${q} BTC по $${p.toLocaleString()}<br>`;
  list.innerHTML = t + list.innerHTML;
}



function checkSimulatorLocks(){
  // Локи соответствуют фазе контента: Chaos = Фаза 4 (продакшен-инфраструктура),
  // Альфа/Бета = Фаза 1 (эконометрика). Никаких «симулятор Фазы 2 под локом Фазы 5».
  const isChaosUnlocked = (phaseTestsDone['p4'] || 0) >= 80;
  const isAlphaUnlocked = (phaseTestsDone['p1'] || 0) >= 80;

  const chaosBox = document.getElementById('sim_chaos');
  if(chaosBox){
    if(!isChaosUnlocked){
      const lockOverlay = document.getElementById('chaos_lock_overlay');
      if(!lockOverlay){
        const ov = document.createElement('div');
        ov.id = 'chaos_lock_overlay';
        ov.style.cssText = 'background:rgba(9,13,31,0.92); border:2px solid var(--bad); border-radius:12px; padding:24px; text-align:center; margin:16px 0;';
        ov.innerHTML = `
          <div style="font-size:32px; margin-bottom:8px">🔒</div>
          <h3 style="color:var(--bad); margin:0 0 6px">Лаборатория Chaos Engineering заблокирована</h3>
          <p style="color:var(--mut); font-size:13.5px; max-width:500px; margin:0 auto 14px">
            Для работы с аварийными сценариями биржевого WebSocket и сетевыми сбоями необходимо завершить Фазу 4 (продакшен и инфраструктура) и сдать её аттестационный тест (≥80%).
          </p>
          <button class="btn sm" onclick="go('tests'); startPhaseTest(4);">📝 Перейти к тесту Фазы 4</button>
        `;
        chaosBox.prepend(ov);
      }
    } else {
      const lockOverlay = document.getElementById('chaos_lock_overlay');
      if(lockOverlay) lockOverlay.remove();
    }
  }

  const alphaBox = document.getElementById('sim_alphabeta');
  if(alphaBox){
    if(!isAlphaUnlocked){
      const lockOverlay = document.getElementById('alpha_lock_overlay');
      if(!lockOverlay){
        const ov = document.createElement('div');
        ov.id = 'alpha_lock_overlay';
        ov.style.cssText = 'background:rgba(9,13,31,0.92); border:2px solid var(--bad); border-radius:12px; padding:24px; text-align:center; margin:16px 0;';
        ov.innerHTML = `
          <div style="font-size:32px; margin-bottom:8px">🔒</div>
          <h3 style="color:var(--bad); margin:0 0 6px">Альфа/Бета-декомпозитор заблокирован</h3>
          <p style="color:var(--mut); font-size:13.5px; max-width:500px; margin:0 auto 14px">
            Для математической декомпозиции рыночного риска CAPM необходимо завершить Фазу 1 (эконометрика и бэктестинг) и сдать её тест (≥80%).
          </p>
          <button class="btn sm" onclick="go('tests'); startPhaseTest(1);">📝 Перейти к тесту Фазы 1</button>
        `;
        alphaBox.prepend(ov);
      }
    } else {
      const lockOverlay = document.getElementById('alpha_lock_overlay');
      if(lockOverlay) lockOverlay.remove();
    }
  }
}



