function startRandomChaosScenario(){
  if(typeof CHAOS_SCENARIOS === 'undefined' || !CHAOS_SCENARIOS.length) return;
  const randIdx = Math.floor(Math.random() * CHAOS_SCENARIOS.length);
  const chips = document.querySelectorAll('#sim_chaos .controls .chip');
  const targetChip = chips[randIdx] || null;
  loadChaosScenario(randIdx, targetChip);
}





/* =========================================================================
   ПРИНУДИТЕЛЬНОЕ СОХРАНЕНИЕ ПРОГРЕССА И УВЕДОМЛЕНИЯ (TOAST ENGINE)
   ========================================================================= */

function showToast(message, icon = '💾', duration = 3000){
  let container = document.getElementById('app_toast_container');
  if(!container){
    container = document.createElement('div');
    container.id = 'app_toast_container';
    document.body.appendChild(container);
  }

  const toast = document.createElement('div');
  toast.className = 'app-toast';
  toast.innerHTML = `<span style="font-size:16px">${icon}</span> <span>${message}</span>`;
  container.appendChild(toast);

  setTimeout(() => {
    toast.style.transition = 'all 0.3s ease';
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(10px)';
    setTimeout(() => { if(toast && typeof toast.remove === 'function') toast.remove(); }, 400);
  }, duration);
}

function manualSaveProgress(){
  if(typeof save === 'function'){
    save();
  }
  showToast('Весь прогресс (уроки, SM-2, тесты, симуляторы) сохранён в памяти браузера!', '✅');
}





