/* =========================================================================
   УНИВЕРСАЛЬНЫЙ ДВИЖОК ВСПЛЫВАЮЩИХ ПОДСКАЗОК (UNIVERSAL TOOLTIP ENGINE)
   Мгновенно показывает суть и аналогию любого термина и аббревиатуры при наведении.
   ========================================================================= */

function initTooltipEngine(){
  let tt = document.getElementById('global_app_tooltip');
  if(!tt){
    tt = document.createElement('div');
    tt.id = 'global_app_tooltip';
    tt.style.cssText = 'position:fixed; display:none; z-index:9999999; max-width:320px; width:max-content; min-width:220px; background:#0b112c; border:1.5px solid #06b6d4; border-radius:10px; padding:12px 14px; box-shadow:0 12px 35px rgba(0,0,0,0.9); font-size:12.5px; color:#f8fafc; pointer-events:none; backdrop-filter:blur(10px); transition:opacity 0.12s ease; line-height:1.45; font-family:inherit;';
    document.body.appendChild(tt);

    let hideTimeout = null;

    function showTooltip(target, clientX, clientY){
      if(hideTimeout){ clearTimeout(hideTimeout); hideTimeout = null; }

      let title = '';
      let desc = '';

      if(target.hasAttribute('data-tooltip-term')){
        const key = target.getAttribute('data-tooltip-term');
        const info = (typeof ABBREVIATION_GLOSSARY !== 'undefined') ? (ABBREVIATION_GLOSSARY[key] || ABBREVIATION_GLOSSARY[key.toLowerCase()] || ABBREVIATION_GLOSSARY[key.toUpperCase()]) : null;
        if(info){
          title = info.title || key;
          desc = info.text || '';
        } else if(typeof TERMS !== 'undefined') {
          const found = TERMS.find(t => t.t.toLowerCase().includes(key.toLowerCase()) || key.toLowerCase().includes(t.t.toLowerCase()));
          if(found){
            title = found.t;
            desc = found.d;
          }
        }
      }

      if(!title && (target.classList.contains('term-tag') || target.hasAttribute('data-term-idx'))){
        let idx = target.getAttribute('data-term-idx');
        if(idx === null || idx === undefined || idx === ''){
          const termText = target.textContent.trim().toLowerCase();
          idx = TERMS.findIndex(t => t.t.toLowerCase() === termText || termText.includes(t.t.toLowerCase()));
        } else {
          idx = parseInt(idx);
        }

        if(idx >= 0 && typeof TERMS !== 'undefined' && TERMS[idx]){
          const tObj = TERMS[idx];
          title = tObj.t;
          desc = tObj.d;
        }
      }

      if(!title && target.hasAttribute('data-tooltip')){
        desc = target.getAttribute('data-tooltip');
        title = target.getAttribute('data-tooltip-title') || 'Подсказка';
      }

      if(!desc && target.getAttribute('title')){
        desc = target.getAttribute('title');
        title = 'Подсказка';
      }

      if(!desc) return;

      tt.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:5px; gap:8px">
          <b style="color:#06b6d4; font-size:13px">${title}</b>
          <span style="font-size:10px; background:rgba(6,182,212,.15); color:#06b6d4; padding:2px 6px; border-radius:4px; font-weight:700">Термин</span>
        </div>
        <div style="color:#e2e8f0; line-height:1.45; font-size:12px">
          ${desc}
        </div>
      `;

      tt.style.display = 'block';
      tt.style.opacity = '1';

      const rect = target.getBoundingClientRect();
      let top = (clientY ? clientY + 12 : rect.bottom + 6);
      let left = (clientX ? clientX - 20 : rect.left);

      if(left + 330 > window.innerWidth) left = window.innerWidth - 340;
      if(top + 160 > window.innerHeight) top = rect.top - 140;

      tt.style.top = Math.max(10, top) + 'px';
      tt.style.left = Math.max(10, left) + 'px';
    }

    document.addEventListener('mouseover', (e) => {
      const target = e.target.closest('[data-tooltip-term], .term-tag, [data-term-idx], [data-tooltip]');
      if(target) showTooltip(target, e.clientX, e.clientY);
    });

    document.addEventListener('mousemove', (e) => {
      if(tt.style.display === 'block'){
        const target = e.target.closest('[data-tooltip-term], .term-tag, [data-term-idx], [data-tooltip]');
        if(target){
          let top = e.clientY + 14;
          let left = e.clientX - 10;
          if(left + 330 > window.innerWidth) left = window.innerWidth - 340;
          if(top + 160 > window.innerHeight) top = e.clientY - 140;
          tt.style.top = Math.max(10, top) + 'px';
          tt.style.left = Math.max(10, left) + 'px';
        }
      }
    });

    document.addEventListener('mouseout', (e) => {
      const target = e.target.closest('[data-tooltip-term], .term-tag, [data-term-idx], [data-tooltip]');
      if(target){
        hideTimeout = setTimeout(() => {
          if(tt) tt.style.display = 'none';
        }, 60);
      }
    });
  }
}

// Auto-run tooltip engine immediately and on window load
initTooltipEngine();
if(typeof document !== 'undefined' && typeof document.addEventListener === 'function'){
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', initTooltipEngine);
  } else {
    initTooltipEngine();
  }
}
if(typeof window !== 'undefined' && typeof window.addEventListener === 'function'){
  window.addEventListener('load', initTooltipEngine);
}

/* v12.2: мягкая обёртка для квизов — подсказка по hover, без onclick (не ломает ответ) */
function autoLinkTermsSoft(text){
  if(!text || typeof TERMS === 'undefined') return text || '';
  let res = String(text);
  TERMS.forEach((term, idx) => {
    const escaped = term.t.replace(/[.*+?${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`(?<![а-яА-Яa-zA-Z_0-9])(${escaped})(?![а-яА-Яa-zA-Z_0-9])`, 'gi');
    res = res.replace(regex, `<span class="term-tag" data-term-idx="${idx}" title="Наведите для подсказки">$1</span>`);
  });
  return res;
}

// Enhanced autoLinkTerms that indexes every term for instant tooltips
function autoLinkTerms(text){
  if(!text || typeof TERMS === 'undefined') return text || '';
  let res = text;
  TERMS.forEach((term, idx) => {
    const escaped = term.t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`(?<![а-яА-Яa-zA-Z_0-9])(${escaped})(?![а-яА-Яa-zA-Z_0-9])`, 'gi');
    res = res.replace(regex, `<span class="term-tag" data-term-idx="${idx}" onclick="openTermModal(${idx})" title="Наведите для подсказки">$1</span>`);
  });
  return res;
}





/* =========================================================================
   ПОЛНОЭКРАННЫЙ РЕЖИМ ЧТЕНИЯ УРОКА (FULLSCREEN LESSON READER)
   ========================================================================= */

var currentViewingPhase = 0;
var currentViewingLessonId = 'p0_l1';

function switchPhaseLessons(phaseNum, btn){
  currentViewingPhase = phaseNum;
  if(btn){
    document.querySelectorAll('#lessons .controls .chip').forEach(c => c.classList.remove('active'));
    btn.classList.add('active');
  }
  renderPhaseLessonsView(phaseNum);
}

/* Duplicate renderPhaseLessonsView removed */

function openFullscreenLesson(lessonId){
  currentViewingLessonId = lessonId;
  const l = LESSONS.find(x => x.id === lessonId) || LESSONS[0];
  if(!l) return;

  const modal = document.getElementById('lessonFullscreenReaderModal');
  const titleEl = document.getElementById('reader_lesson_title');
  const phaseBadgeEl = document.getElementById('reader_phase_badge');

  if(titleEl) titleEl.innerHTML = `<b>Урок ${l.num || l.id}:</b> ${l.title}`;
  if(phaseBadgeEl) phaseBadgeEl.innerHTML = `Фаза ${l.phase}`;

  renderLessonDetail(l);

  if(modal){
    modal.style.display = 'flex';
    document.body.style.overflow = 'hidden';
    modal.scrollTo({ top: 0, behavior: 'instant' });
  }
}

function closeFullscreenLessonReader(){
  const modal = document.getElementById('lessonFullscreenReaderModal');
  if(modal){
    modal.style.display = 'none';
    document.body.style.overflow = '';
  }
  // Refresh catalog grid progress
  renderPhaseLessonsView(currentViewingPhase);
}

function navLesson(delta){
  const currentIndex = LESSONS.findIndex(x => x.id === currentViewingLessonId);
  if(currentIndex === -1) return;
  const newIndex = currentIndex + delta;
  if(newIndex >= 0 && newIndex < LESSONS.length){
    openFullscreenLesson(LESSONS[newIndex].id);
  } else {
    showToast(delta > 0 ? 'Вы дошли до последнего урока курса!' : 'Это первый урок курса!', 'ℹ️');
  }
}

// Global Esc key listener to close reader
document.addEventListener('keydown', (e) => {
  if(e.key === 'Escape'){
    const modal = document.getElementById('lessonFullscreenReaderModal');
    if(modal && modal.style.display === 'flex'){
      closeFullscreenLessonReader();
    }
  }
});





