let curBossRound = 0;
let curBossHp = 100;

function loadBossBattle(idx = 0, btn){
  curBossIdx = idx;
  curBossRound = 0;
  const boss = BOSS_SCENARIOS[idx];
  curBossHp = boss.bossHp;

  if(btn){
    document.querySelectorAll('#sim_boss .controls .chip').forEach(c => c.classList.remove('active'));
    btn.classList.add('active');
  }
  window.curBossShields = 3;

  renderBossArena();
}

// E2: щит подсказки — гасит два неверных варианта (3 заряда за бой)
window.useBossShield = function(){
  if((window.curBossShields ?? 0) <= 0){ showToast('🛡 Щиты кончились: осталось полагаться на знания.', '⚠️'); return; }
  const boss = BOSS_SCENARIOS[curBossIdx];
  const round = boss.rounds[curBossRound];
  if(!round) return;
  const btns = document.querySelectorAll('#boss_arena_content .ans');
  let hidden = 0;
  btns.forEach((b, i) => {
    if(i !== round.a && hidden < 2 && b.style.display !== 'none'){
      b.style.display = 'none';
      hidden++;
    }
  });
  if(hidden > 0){
    window.curBossShields--;
    showToast(`🛡 Щит активирован: 2 ложных хода погашены. Осталось щитов: ${window.curBossShields}`, '🛡');
    renderBossArenaShieldLabel();
  }
};
function renderBossArenaShieldLabel(){
  const boss = BOSS_SCENARIOS[curBossIdx];
  const round = boss.rounds[curBossRound];
  if(!round) return;
  // перерисовываем только метку щитов без сброса скрытых кнопок
  const arena = document.getElementById('boss_arena_content');
  if(!arena) return;
  const lbl = arena.querySelector('.boss-shield-lbl');
  if(lbl) lbl.innerHTML = `🛡 Щиты подсказки: <b>${window.curBossShields}</b>`;
}

function renderBossArena(){
  const arena = document.getElementById('boss_arena_content');
  if(!arena) return;

  const boss = BOSS_SCENARIOS[curBossIdx];
  const round = boss.rounds[curBossRound];

  if(curBossHp <= 0 || !round){
    // Victory!
    arena.innerHTML = `
      <div style="text-align:center; padding:20px">
        <div style="font-size:54px; margin-bottom:12px">🏆 ⚔️</div>
        <h2 style="color:var(--ok); font-size:26px; margin:0 0 8px">БОСС ПОВЕРЖЕН! КРИЗИС ПРЕОДОЛЕН!</h2>
        <p style="color:var(--txt); font-size:15px; max-width:550px; margin:0 auto 14px">
          Вы хладнокровно справились с катастрофическим рыночным сценарием <b>«${boss.title}»</b> и защитили средства фонда.
        </p>
        ${boss.debrief ? `<div style="text-align:left; max-width:520px; margin:0 auto 20px; background:rgba(0,0,0,.4); border-left:3px solid var(--acc2); border-radius:8px; padding:12px 16px; font-size:13px; color:var(--txt); line-height:1.6">
          <b style="color:var(--acc2)">📋 Дебрифинг:</b><ul style="margin:6px 0 0; padding-left:18px">${boss.debrief.map(d => `<li>${d}</li>`).join('')}</ul>
        </div>` : ''}
        <button class="btn" style="background:var(--ok); color:#040714; font-weight:800; padding:12px 28px; font-size:15px" onclick="claimBossVictoryReward(${boss.id})">
          🎁 Забрать награду (+$250,000 AUM + Бейдж)
        </button>
      </div>
    `;
    return;
  }

  arena.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:14px">
      <div>
        <span style="font-size:12px; font-weight:800; color:var(--bad); text-transform:uppercase">⚔️ КРИЗИСНЫЙ БОСС-ФАЙТ</span>
        <h3 style="margin:2px 0 0; font-size:20px; color:var(--txt)">${boss.title}</h3>
      </div>
      <div style="text-align:right">
        <div style="font-size:11.5px; color:var(--mut)">Здоровье Черного Лебедя (${curBossHp}% HP):</div>
        <div style="display:flex; gap:3px; justify-content:flex-end; margin-top:3px">
          ${[0,1,2,3,4].map(s => `<div style="width:22px; height:12px; border-radius:3px; background:${curBossHp > s * 20 ? 'var(--bad)' : 'rgba(255,255,255,.1)'}"></div>`).join('')}
        </div>
        <div class="boss-shield-lbl" style="font-size:11.5px; color:var(--warn); margin-top:4px">🛡 Щиты подсказки: <b>${window.curBossShields ?? 3}</b></div>
      </div>
    </div>

    <div style="background:rgba(0,0,0,0.5); padding:14px; border-radius:10px; margin-bottom:18px; border:1px solid rgba(239,68,68,.3); font-size:13.5px; color:var(--txt); line-height:1.5">
      ${boss.desc}
    </div>

    <div style="background:var(--card); border:1.5px solid var(--line); border-radius:12px; padding:18px; margin-bottom:16px">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px">
        <div style="font-size:12px; font-weight:800; color:var(--acc2)">РАУНД ${curBossRound + 1} ИЗ ${boss.rounds.length}:</div>
        <button class="btn sm ghost" style="font-size:11px" onclick="useBossShield()">🛡 Щит (убрать 2 неверных)</button>
      </div>
      <h4 style="margin:0 0 14px; font-size:16px; color:var(--txt); line-height:1.4">${round.q}</h4>
      <div style="display:flex; flex-direction:column; gap:10px">
        ${round.opts.map((opt, oIdx) => `
          <button class="ans" onclick="handleBossAnswer(${oIdx}, ${round.a}, ${round.dmg})" style="padding:12px 16px; font-size:14px">
            ${opt}
          </button>
        `).join('')}
      </div>
    </div>
  `;
}

function handleBossAnswer(chosen, correct, dmg){
  if(chosen === correct){
    curBossHp = Math.max(0, curBossHp - dmg);
    curBossRound++;
    showToast(`⚔️ Критический удар! -${dmg}% HP у кризиса!`, '💥');
    renderBossArena();
  } else {
    showToast('❌ Ошибка! Рыночный шум нанес урон позиции. Попробуйте другой ход.', '⚠️');
  }
}

function claimBossVictoryReward(bossId){
  addFundCapital(250000, 300, 'Победа над боссом кризиса');
  if(typeof simMastery !== 'undefined'){
    simMastery[`boss_${bossId}`] = true;
    if(typeof save === 'function') save();
  }
  loadBossBattle((bossId + 1) % BOSS_SCENARIOS.length);
}

// Hook into Lesson Completion to reward fund AUM
const originalCompleteLessonWithMastery = window.completeLessonWithMastery;
window.completeLessonWithMastery = function(lessonId){
  const wasDone = lessonsDone[lessonId] === 1;
  if(typeof originalCompleteLessonWithMastery === 'function'){
    originalCompleteLessonWithMastery(lessonId);
  } else {
    lessonsDone[lessonId] = 1;
    if(typeof save === 'function') save();
  }
  if(!wasDone){
    addFundCapital(15000, 50, 'Завершение урока');
    dailyQuestsDone.q1 = true;
    localStorage.setItem('cn_daily_quests', JSON.stringify(dailyQuestsDone));
    renderDailyQuests();
  }
};





