function getCurrentExchangeTier(){
  let tier = 0;
  if((phaseTestsDone['p0'] || phaseTestsDone['test_literacy_zero'] || 0) >= 80) tier = 1;
  if((phaseTestsDone['p1'] || 0) >= 80) tier = 2;
  if((phaseTestsDone['p2'] || 0) >= 80) tier = 3;
  if((phaseTestsDone['p3'] || 0) >= 80 && (phaseTestsDone['p4'] || 0) >= 80) tier = 4;
  if((phaseTestsDone['exam_capstone'] || 0) >= 85) tier = 5;
  return EXCHANGE_TIERS[tier];
}

function updateExchangeTiersUI(){
  const tier = getCurrentExchangeTier();
  const hdrBadge = document.getElementById('headerTierBadge');
  const dashName = document.getElementById('dash_tier_name');
  const dashFee = document.getElementById('dash_fee_rate');
  const trackBox = document.getElementById('tier_progress_track_box');
  const achContainer = document.getElementById('achievements_container');
  const trophiesBadge = document.getElementById('trophies_count_badge');

  if(hdrBadge){
    hdrBadge.innerHTML = `🏛️ Учебная комиссия: ${tier.makerFee.split(' ')[1] || '10 bps'} = ${tier.makerFee} · ${tier.shortName} (демо-тариф)`;
  }
  if(dashName) dashName.innerHTML = tier.name;
  if(dashFee) dashFee.innerHTML = `Комиссия: Maker ${tier.makerFee} / Taker ${tier.takerFee}`;

  if(trackBox){
    trackBox.innerHTML = EXCHANGE_TIERS.map(t => {
      const isCurrent = t.tier === tier.tier;
      const isPast = t.tier < tier.tier;
      return `
        <div class="tier-step-box ${isCurrent ? 'active' : ''} ${isPast ? 'completed' : ''}">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px">
            <span style="font-size:11px; font-weight:800; color:var(--acc2); text-transform:uppercase">${t.shortName}</span>
            <span style="font-size:11px; font-weight:700; color:${isCurrent?'var(--ok)':(isPast?'var(--ok)':'var(--mut)')}">
              ${isCurrent ? '● ТЕКУЩИЙ' : (isPast ? '✓ СДАН' : '🔒 ЗАКРЫТ')}
            </span>
          </div>
          <div style="font-weight:700; font-size:13px; color:var(--txt); margin-bottom:4px">${t.makerFee} Maker</div>
          <div style="font-size:11.5px; color:var(--mut); line-height:1.4">${t.perk}</div>
          <div style="font-size:10.5px; color:var(--acc1); margin-top:6px; border-top:1px dashed var(--line); padding-top:4px">
            Условие: ${t.req}
          </div>
        </div>
      `;
    }).join('');
  }

  if(achContainer){
    let unlockedCount = 0;
    achContainer.innerHTML = APP_ACHIEVEMENTS.map(ach => {
      const isUnlocked = ach.condition();
      if(isUnlocked) unlockedCount++;
      return `
        <div class="trophy-card ${isUnlocked ? 'unlocked' : 'locked'}">
          <div class="trophy-icon">${ach.icon}</div>
          <div>
            <div style="display:flex; align-items:center; gap:6px; margin-bottom:2px">
              <b style="font-size:14px; color:var(--txt)">${ach.title}</b>
              ${isUnlocked ? '<span class="badge" style="background:rgba(234,179,8,.2); color:#eab308; font-size:10px">РАЗБЛОКИРОВАНО</span>' : ''}
            </div>
            <div style="font-size:12px; color:var(--mut); line-height:1.4">${ach.desc}</div>
          </div>
        </div>
      `;
    }).join('');

    if(trophiesBadge){
      trophiesBadge.innerHTML = `🏆 Открыто: ${unlockedCount} из ${APP_ACHIEVEMENTS.length} трофеев`;
    }
  }
}

