(function injectMathChip(){
  document.addEventListener('DOMContentLoaded', ()=>{
    const chips=document.querySelectorAll('#lessons .controls .chip');
    let bonusChip=null;
    chips.forEach(c=>{ if(c.textContent.includes('Бонусы')) bonusChip=c; });
    if(bonusChip && !document.getElementById('math_chip')){
      const b=document.createElement('button');
      b.className='chip'; b.id='math_chip';
      b.innerHTML='🧠 Матмышление';
      b.setAttribute('onclick','switchPhaseLessons(7,this)');
      bonusChip.insertAdjacentElement('afterend', b);
    }
  });
})();

function renderMathTestsBox(){
  let h='<div style="margin-top:26px"><div style="font-size:13px;font-weight:800;color:var(--acc1);text-transform:uppercase;margin-bottom:12px">🏁 Финальные тесты факультатива (порог 80%)</div></div>';
  MATH_TESTS.forEach((t,ti)=>{
    const st=mathTestState[ti];
    h+=`<div class="lblock" style="background:#090d1f;border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:16px">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:12px">
        <b style="color:var(--txt);font-size:15px">${t.title}</b>
        <span class="badge" style="${st&&st.passed?'background:rgba(34,197,94,.15); color:var(--ok)':'background:rgba(234,179,8,.15); color:var(--warn)'}">${st?(st.passed?'✓ СДАН ('+st.correct+' из '+t.questions.length+')':'Лучший: '+st.correct+' из '+t.questions.length):'Не сдан'}</span>
      </div>`;
    t.questions.forEach((q,qi)=>{
      h+=`<div style="margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid rgba(255,255,255,.06)">
        <div style="font-size:13px;color:var(--txt);margin-bottom:8px">${qi+1}. ${q.q}</div>`;
      const sh = shuffledOptions(q, qi*17+3+ti*9); /* v12.2: шафл с пер-тестовой солью — эффективные позиции сбалансированы (K=9 подобрано сканом) */
      sh.opts.forEach((o,oi)=>{
        const picked=st&&st.answers[qi];
        let cls='ans';
        if(picked!==undefined){
          if(oi===sh.a) cls+=' ok';
          else if(oi===picked) cls+=' bad';
        }
        h+='<button class="'+cls+'" style="text-align:left;display:block;width:auto;margin-bottom:6px" onclick="answerMathTest('+ti+','+qi+','+oi+')">'+o+'</button>';
      });
      if(st&&st.answers[qi]!==undefined&&sh.explain) h+='<div style="margin-top:8px;font-size:12px;color:var(--mut);background:rgba(6,182,212,.05);border-left:3px solid var(--acc2);padding:8px 10px;border-radius:0 8px 8px 0">'+sh.explain+'</div>';
      h+='</div>';
    });
    h+='<button class="btn sm" onclick="finishMathTest('+ti+')">🏁 Проверить тест</button>';
    h+='</div>';
  });
  return h;
}
function answerMathTest(ti,qi,oi){
  if(!mathTestState[ti]) mathTestState[ti]={answers:{},correct:0,passed:false};
  mathTestState[ti].answers[qi]=oi;
  renderPhaseLessonsView(7);
}
function finishMathTest(ti){
  const t=MATH_TESTS[ti]; const st=mathTestState[ti];
  if(!t||!st){ if (window.LEARN_PLAYER_ACTIVE) { LearnPlayer.onTestResult('Сначала ответь на вопросы.'); } else { alert('Сначала ответь на вопросы.'); } return; }
  let c=0; t.questions.forEach((q,qi)=>{ const sh=shuffledOptions(q, qi*17+3+ti*9); if(st.answers[qi]===sh.a) c++; });
  st.correct=Math.max(st.correct||0,c);
  st.passed = c >= Math.ceil(t.questions.length*0.8);
  save();
  renderPhaseLessonsView(7);
if (window.LEARN_PLAYER_ACTIVE) { LearnPlayer.onTestResult(st.passed?('🎉 Тест сдан: '+c+' из '+t.questions.length):'❌ Не сдано: '+c+' из '+t.questions.length+' (нужно ≥ '+Math.ceil(t.questions.length*0.8)+')'); } else { alert(st.passed?('🎉 Тест сдан: '+c+' из '+t.questions.length):'❌ Не сдано: '+c+' из '+t.questions.length+' (нужно ≥ '+Math.ceil(t.questions.length*0.8)+')'); }
}

