/* ---------- 3. STREAK ---------- */
function p1UpdateStreak(){
  try{
    const qd = dailyQuestsDone || {};
    const allDone = !!(qd.q1 && qd.q2 && qd.q3);
    if(!allDone) { p1RenderStreakBadge(); return; }
    const today = todayStr();
    const last = localStorage.getItem('cn_streak_last') || '';
    if(last === today){ p1RenderStreakBadge(); return; }
    const yest = new Date(Date.now() - 86400000).toDateString();
    streakCount = (last === yest) ? (parseInt(localStorage.getItem('cn_streak_count')||'1',10)+1) : 1;
    localStorage.setItem('cn_streak_count', String(streakCount));
    localStorage.setItem('cn_streak_last', today);
    if(typeof save === 'function') save();
    p1RenderStreakBadge();
    showToast('🔥 Серия дней: ' + streakCount + '! Не прерывай.', '🔥');
  }catch(e){}
}
function p1RenderStreakBadge(){
  const el = $id('quest_streak_num');
  if(el) el.textContent = streakCount;
  const badge = $id('p1_streak_badge');
  if(badge && typeof getRank === 'function') badge.title = 'Ранг серии: ' + getRank(streakCount);
}

/* ---------- 4. TRACKER STATE ---------- */
function noteTermDay(){
  const days = LS.get('cn_term_days', []);
  const t = todayStr();
  if(!days.includes(t)){ days.push(t); LS.set('cn_term_days', days); }
}
function candleParamTouched(field){
  const touched = new Set(LS.get('cn_candle_touched', []));
  touched.add(field);
  const arr = [...touched];
  if(arr.length >= 4){
    LS.set('cn_candle_builds', (LS.get('cn_candle_builds',0)||0) + 1);
    LS.set('cn_candle_touched', []);
  } else {
    LS.set('cn_candle_touched', arr);
  }
}
function lookaheadSnippetTouched(snipIdx){
  const arr = LS.get('cn_look_touched', []);
  if(!arr.includes(snipIdx)){ arr.push(snipIdx); LS.set('cn_look_touched', arr); }
}

