function renderOnboarding(){
  const host = $id('p1_onboarding_host');
  if(!host) return;
  let firstUndone = P1_ONB_STEPS.findIndex(s=>!s.chk());
  if(firstUndone === -1) firstUndone = P1_ONB_STEPS.length;
  const doneCount = firstUndone;
  host.innerHTML =
    '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:12px">' +
      '<div style="display:flex;align-items:center;gap:8px"><span style="font-size:20px">🗺️</span><h3 style="margin:0;font-size:17px;color:var(--txt)">Твой первый маршрут: 5 дней</h3></div>' +
      '<span class="badge" style="background:rgba(6,182,212,.15);color:var(--acc2);font-weight:700">' + Math.min(doneCount,5) + ' / 5</span>' +
    '</div>' +
    P1_ONB_STEPS.map((s,i)=>{
      const isDone = i < firstUndone;
      const isActive = i === firstUndone;
      const cls = 'p1-onb-step ' + (isDone ? 'done' : (isActive ? '' : 'locked'));
      const icon = isDone ? '<div class="p1-onb-num">✓</div>'
        : '<div class="p1-onb-num">' + (i+1) + '</div>';
      const btn = (!isDone && isActive)
        ? '<button class="btn sm" data-p1onb="'+i+'">Начать ➔</button>'
        : (isDone ? '<span class="badge" style="background:rgba(34,197,94,.15);color:var(--ok)">✓ Готово</span>' : '');
      return '<div class="'+cls+'">'+icon+
        '<div style="flex:1"><div style="font-size:11px;font-weight:800;color:var(--mut);text-transform:uppercase">'+s.day+'</div>'+
        '<div style="font-size:13.5px;color:var(--txt);line-height:1.45">'+esc(s.title)+'</div></div>'+btn+'</div>';
    }).join('') +
    '<div style="font-size:12px;color:var(--mut);padding-top:6px">Пропустил день — не страшно. Маршрут ждёт ровно там, где ты остановился.</div>';
  host.querySelectorAll('[data-p1onb]').forEach(b=>{
    b.addEventListener('click', ()=>{ P1_ONB_STEPS[parseInt(b.dataset.p1onb,10)].act(); });
  });
}

/* ---------- 6. MEME SIM ENGINE ---------- */
const meme = { running:false, phase:'idle', m:1, hist:[1], ticks:0, maxTicks:30, timer:null, dumpChance:35 };
function memeChartHTML(){
  const W=420,H=170,N=Math.max(meme.maxTicks+2, meme.hist.length+1);
  const maxM = Math.max.apply(null, meme.hist.concat([1.05]));
  const minM = Math.min.apply(null, meme.hist.concat([0.95]));
  const pts = meme.hist.map((v,i)=>{
    const x = 10 + (i/(N-1))*(W-30);
    const y = H-20 - ((v-minM)/Math.max(maxM-minM,1e-9))*(H-40);
    return x.toFixed(1)+','+y.toFixed(1);
  }).join(' ');
  const lastY = pts.split(' ').pop().split(',')[1];
  const fomo = Math.min(100, Math.round((meme.m-1)*50));
  return '<svg width="100%" height="'+H+'" viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none">' +
    '<line x1="8" y1="'+(H-20)+'" x2="'+(W-8)+'" y2="'+(H-20)+'" stroke="rgba(255,255,255,.15)" stroke-dasharray="4,4"/>' +
    '<polyline points="'+pts+'" fill="none" stroke="#22c55e" stroke-width="2.5"/>' +
    '<circle cx="'+(W-20)+'" cy="'+lastY+'" r="4" fill="#f59e0b"/></svg>' +
    '<div style="font-size:12px;color:var(--mut);margin-top:6px">Рост токена: <b style="color:#22c55e">+'+Math.round((meme.m-1)*100)+'%</b> · FOMO-метр:</div>' +
    '<div style="height:8px;background:rgba(255,255,255,.08);border-radius:99px;overflow:hidden;margin-top:4px">' +
    '<div style="height:100%;width:'+fomo+'%;background:linear-gradient(90deg,#22c55e,#f59e0b,#ef4444)"></div></div>';
}
function memePaintPanel(html){ const p=$id('meme_result'); if(p) p.innerHTML = html; }
function startMemeSim(maxTicksOverride){
  const nameEl=$id('meme_name'), chanceEl=$id('meme_dump');
  meme.dumpChance = chanceEl ? parseInt(chanceEl.value,10)||35 : 35;
  meme.m=1; meme.hist=[1]; meme.ticks=0;
  meme.maxTicks = maxTicksOverride || (26 + Math.floor(Math.random()*20));
  meme.phase='pump'; meme.running=true;
  if(meme.timer) clearInterval(meme.timer);
  const nm = nameEl ? esc(nameEl.value||'KryptoDog') : 'KryptoDog';
  memePaintPanel(
    '<div class="p1-meme-chart" id="meme_chart_box"></div>' +
    '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:10px">' +
      '<button class="btn" id="meme_sell_btn" disabled style="opacity:.5">💰 Продать сейчас</button>' +
      '<button class="btn ghost" id="meme_hold_btn" disabled style="opacity:.5">🙌 Держать до луны</button>' +
    '</div><div id="meme_debrief"></div>');
  meme.timer = setInterval(()=>{
    meme.ticks++;
    let r = Math.random();
    if(r < 0.15){ meme.m *= (1-(0.01+Math.random()*0.03)); }
    else { meme.m *= (1+(0.02+Math.random()*0.05)); }
    if(meme.m<0.05) meme.m=0.05;
    meme.hist.push(meme.m);
    const cb=$id('meme_chart_box'); if(cb) cb.innerHTML = memeChartHTML();
    if(meme.ticks >= meme.maxTicks){
      clearInterval(meme.timer); meme.phase='decision';
      const sb=$id('meme_sell_btn'), hb=$id('meme_hold_btn');
      if(sb){ sb.disabled=false; sb.style.opacity='1'; }
      if(hb){ hb.disabled=false; hb.style.opacity='1'; }
      showToast('🪙 «'+nm+'» на пике! Решай: продать или держать?', '⚡');
    }
  }, 130);
}
function memeRollHold(fromM){
  return (Math.random()*100 < meme.dumpChance)
    ? fromM * (0.12 + Math.random()*0.18)
    : fromM * (1.6 + Math.random()*1.0);
}
function memeDebrief(chosen, mAtDecision){
  const holdFinal = memeRollHold(mAtDecision);
  const sellVal = Math.round(100*(mAtDecision*0.97-100))/100;
  const holdVal = Math.round(100*(holdFinal*0.97-100))/100;
  const dumpHappened = holdFinal < mAtDecision;
  const fmt = v => (v>=0?'+$':'−$')+Math.abs(v).toFixed(2);
  const chosenLine = chosen==='sell'
    ? '<div style="color:#22c55e"><b>Ты продал:</b> '+fmt(sellVal)+' зафиксировано (−3% slippage на тонком стакане)</div>'
    : (dumpHappened
        ? '<div style="color:#ef4444"><b>Ты держал:</b> 💥 ДАМП! Итог '+fmt(holdVal)+'</div>'
        : '<div style="color:#22c55e"><b>Ты держал:</b> 🌙 Луна! Итог '+fmt(holdVal)+'</div>');
  const altLine = chosen==='sell'
    ? (dumpHappened
        ? '<div style="color:#22c55e;font-size:13px">Если бы держал: дамп всё равно случился бы — в этот раз ты угадал.</div>'
        : '<div style="color:#f59e0b;font-size:13px">Если бы держал: луна была бы твоей (+$'+Math.abs(holdVal).toFixed(2)+'). Продажа на пике — цена отказа от FOMO.</div>')
    : (dumpHappened
        ? '<div style="color:#22c55e;font-size:13px">Если бы продал на пике: +$'+sellVal.toFixed(2)+' вместо дампа.</div>'
        : '<div style="color:#f59e0b;font-size:13px">Если бы продал на пике: +$'+sellVal.toFixed(2)+', но луну ты бы пропустил.</div>');
  return '<div style="background:rgba(0,0,0,.3);border:1px solid var(--line);border-radius:12px;padding:14px;margin-top:12px;line-height:1.6;font-size:13.5px;color:var(--txt)">' +
    chosenLine + altLine +
    '<div style="margin-top:10px;padding-top:10px;border-top:1px dashed var(--line);font-size:12.5px;color:var(--mut)">' +
    '🧠 <b style="color:var(--txt)">Урок про FOMO:</b> пока график рос, мозг требовал «не упустить ещё больше». Именно так толпа покупает вершины мемкоинов. ' +
    'Заметь: при вероятности дампа <b>'+meme.dumpChance+'%</b> решение «держать» — это не смелость, а ставка против матожидания, если потенциальный дамп перекрывает рост. ' +
    'Правило Архитектора: решения принимает план ДО входа, а не эмоция НА пике.</div></div>';
}
window.P1_Meme = {
  start: function(maxTicks){ startMemeSim(maxTicks); },
  sell: function(){
    if(meme.phase!=='decision') return;
    meme.phase='done';
    const sb=$id('meme_sell_btn'), hb=$id('meme_hold_btn');
    if(sb) sb.disabled=true; if(hb) hb.disabled=true;
    const d=$id('meme_debrief');
    if(d) d.innerHTML = memeDebrief('sell', meme.m);
  },
  hold: function(){
    if(meme.phase!=='decision') return;
    meme.phase='done';
    const sb=$id('meme_sell_btn'), hb=$id('meme_hold_btn');
    if(sb) sb.disabled=true; if(hb) hb.disabled=true;
    const d=$id('meme_debrief');
    if(d) d.innerHTML = memeDebrief('hold', meme.m);
  }
};

/* ---------- 7. FIRST TRADE ENGINE ---------- */
const ft = { open:false, btc:0, usd:0, vwap:0, feeIn:0, mid:0, halfSpread:0, timer:null };
function ftEnsureBook(){
  if(typeof orderBookState === 'undefined' || !orderBookState || !orderBookState.asks || !orderBookState.asks.length){
    if(typeof resetObBook === 'function') resetObBook();
  }
}
function ftPaintLive(){
  const gross = ft.btc*(ft.mid-ft.vwap), net = gross - ft.feeIn;
  const col = net>=0 ? '#22c55e' : '#ef4444';
  const el=$id('ft_live'); if(!el) return;
  el.innerHTML =
    '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-top:12px">' +
    '<div style="background:rgba(0,0,0,.3);border-radius:10px;padding:10px"><div style="font-size:11px;color:var(--mut)">ЦЕНА СЕЙЧАС</div><div style="font-weight:800">$'+ft.mid.toFixed(2)+'</div></div>' +
    '<div style="background:rgba(0,0,0,.3);border-radius:10px;padding:10px"><div style="font-size:11px;color:var(--mut)">ПОЗИЦИЯ (BTC)</div><div style="font-weight:800">'+ft.btc.toFixed(6)+'</div></div>' +
    '<div style="background:rgba(0,0,0,.3);border-radius:10px;padding:10px"><div style="font-size:11px;color:var(--mut)">ЦЕНА ВХОДА (VWAP)</div><div style="font-weight:800">$'+ft.vwap.toFixed(2)+'</div></div>' +
    '<div style="background:rgba(0,0,0,.3);border-radius:10px;padding:10px"><div style="font-size:11px;color:var(--mut)">PNL ОТКРЫТОЙ ПОЗИЦИИ</div><div style="font-weight:800;color:'+col+'">'+(net>=0?'+':'−')+'$'+Math.abs(net).toFixed(2)+'</div></div>' +
    '</div><div style="font-size:12px;color:var(--mut);margin-top:8px">Цена тикает каждые 0.9 сек. Комиссия входа уже вычтена из PnL.</div>';
}
window.P1_FT = {
  open: function(){
    if(ft.open){ showToast('Сначала закрой открытую позицию', '⚠️'); return; }
    ftEnsureBook();
    if(typeof orderBookState === 'undefined' || !orderBookState.asks){ showToast('Стакан недоступен', '⚠️'); return; }
    const amtEl=$id('ft_amount');
    const amount = Math.min(500, Math.max(10, parseFloat(amtEl ? amtEl.value : 50) || 50));
    let rem=amount, btc=0, usd=0;
    for(const lvl of orderBookState.asks){
      const lvlUsd = lvl.price*lvl.qty;
      const take = Math.min(rem, lvlUsd);
      btc += take/lvl.price; usd += take; rem -= take;
      if(rem <= 1e-9) break;
    }
    ft.btc=btc; ft.usd=usd; ft.vwap=usd/btc;
    ft.feeIn=usd*0.00055;
    ft.mid=(orderBookState.asks[0].price+orderBookState.bids[0].price)/2;
    ft.halfSpread=(orderBookState.asks[0].price-orderBookState.bids[0].price)/2;
    ft.open=true;
    const out=$id('ft_result');
    if(out) out.innerHTML='<div id="ft_live"></div><button class="btn" id="ft_close_btn" style="margin-top:12px;background:var(--bad)">🔒 Закрыть позицию</button>';
    const cb=$id('ft_close_btn'); if(cb) cb.addEventListener('click', window.P1_FT.close);
    ftPaintLive();
    ft.timer=setInterval(()=>{
      ft.mid *= 1 + ((Math.random()-0.5)*0.003 + 0.0002);
      ftPaintLive();
    }, 900);
  },
  close: function(){
    if(!ft.open) return;
    clearInterval(ft.timer); ft.open=false;
    const exitPrice = Math.max(orderBookState.bids[0].price, ft.mid - ft.halfSpread);
    const proceeds = ft.btc*exitPrice;
    const feeOut = proceeds*0.00055;
    const realized = ft.btc*(exitPrice-ft.vwap) - ft.feeIn - feeOut;
    const spreadCost = ft.btc*ft.halfSpread;
    const bps = (realized/ft.usd)*10000;
    const col = realized>=0 ? '#22c55e' : '#ef4444';
    const el=$id('ft_live'); if(!el) return;
    el.innerHTML =
      '<div style="background:rgba(0,0,0,.3);border-radius:12px;padding:16px;line-height:1.7;font-size:13.5px;color:var(--txt)">' +
      '<h4 style="margin:0 0 10px">Итог первого трейда: <span style="color:'+col+'">'+(realized>=0?'+':'−')+'$'+Math.abs(realized).toFixed(2)+' ('+bps.toFixed(1)+' bps)</span></h4>' +
      'Куплено: '+ft.btc.toFixed(6)+' BTC по VWAP $'+ft.vwap.toFixed(2+'').slice(0,9)+'<br>' +
      'Комиссия входа (taker 0.055%): −$'+ft.feeIn.toFixed(2)+'<br>' +
      'Спред-издержка (≈половина спреда): −$'+spreadCost.toFixed(2)+'<br>' +
      'Комиссия выхода (taker 0.055%): −$'+feeOut.toFixed(2)+'<br>' +
      '<div style="margin-top:10px;padding-top:10px;border-top:1px dashed var(--line);font-size:12.5px;color:var(--mut)">' +
      '🧠 <b style="color:var(--txt)">Главный урок:</b> ещё до любого движения цены твоя сделка стартует в минусе на сумму комиссий и спреда. ' +
      'Именно поэтому «купил и быстро продал» почти всегда теряет деньги — стратегия обязана зарабатывать больше издержек.' +
      '</div></div>';
  }
};

