/* --- 1. СИМУЛЯТОР АРБИТРАЖА ('arbitrage') --- */
var arbState = {
  currentSpreadBps: 50,
  totalTrades: 0,
  capital: 10000,
  initialCapital: 10000,
  profit: 0,
  competitors: 3
};

function calcArbitrageSim() {
  const capital = parseFloat(document.getElementById('arb_capital')?.value) || 10000;
  const competitors = parseInt(document.getElementById('arb_competitors')?.value) || 3;
  const spread = parseFloat(document.getElementById('arb_spread')?.value) || 50;

  arbState.capital = capital;
  arbState.initialCapital = capital;
  arbState.currentSpreadBps = spread;
  arbState.competitors = competitors;
  arbState.totalTrades = 0;
  arbState.profit = 0;

  updateArbitrageUI();
}

function executeArbitrageTrade() {
  let slippageFactor = Math.min(1, arbState.competitors / 15);
  let grossBps = arbState.currentSpreadBps * (0.5 + (1 - slippageFactor) * 0.5);

  // Издержки учебной модели: комиссия ДВУХ площадок + проскальзывание на обеих ногах
  const FEE_BPS_PER_LEG = 10;   // ~0.1% taker на каждой бирже
  const SLIP_BPS_PER_LEG = 5;   // проскальзывание исполнения
  const costsBps = FEE_BPS_PER_LEG * 2 + SLIP_BPS_PER_LEG * 2;
  const tradeProfitBps = grossBps - costsBps;

  let competitorErosion = (arbState.competitors + 1) * 0.4;
  arbState.currentSpreadBps = Math.max(0.5, arbState.currentSpreadBps - competitorErosion);

  const profitUsd = (tradeProfitBps / 10000) * arbState.capital;
  arbState.totalTrades++;
  if(profitUsd > 0){
    arbState.profit += profitUsd;
    arbState.capital += profitUsd;
    logArbitrageMessage(`✅ Арбитраж #${arbState.totalTrades}: спред ${grossBps.toFixed(1)} bps − издержки ${costsBps} bps (комиссии+проскальзывание двух площадок) = <b>+$${profitUsd.toFixed(2)}</b>. Спред сузился до <b>${arbState.currentSpreadBps.toFixed(1)} bps</b>.`);
  } else {
    logArbitrageMessage(`⚠️ Арбитраж #${arbState.totalTrades}: спред ${grossBps.toFixed(1)} bps не покрыл издержки ${costsBps} bps — сделка закрылась <b>${profitUsd===0?'в ноль':'в минус $'+Math.abs(profitUsd).toFixed(2)}</b>. Без учёта комиссий и задержек «арбитраж» превращается в убыток.`);
  }

  updateArbitrageUI();

  if(arbState.currentSpreadBps < 1.5) {
    logArbitrageMessage('🚨 <b>ВНИМАНИЕ:</b> Спред практически исчез (< 1.5 bps). Рынок стал эффективным. Арбитражная возможность исчерпана!');
  }
}

function resetArbitrageSim() {
  const spread = parseFloat(document.getElementById('arb_spread')?.value) || 50;
  const competitors = parseInt(document.getElementById('arb_competitors')?.value) || 3;
  
  arbState.currentSpreadBps = spread;
  arbState.totalTrades = 0;
  arbState.capital = parseFloat(document.getElementById('arb_capital')?.value) || 10000;
  arbState.initialCapital = arbState.capital;
  arbState.profit = 0;
  arbState.competitors = competitors;

  updateArbitrageUI();
  logArbitrageMessage('🔄 Рынок сброшен. Первоначальный спред восстановлен.');
}

function updateArbitrageUI() {
  const spreadEl = document.getElementById('arb_current_spread');
  const profitEl = document.getElementById('arb_profit');
  const tradesEl = document.getElementById('arb_trades');
  const capEl = document.getElementById('arb_final_capital');

  if(spreadEl) spreadEl.textContent = arbState.currentSpreadBps.toFixed(1) + ' bps';
  if(profitEl) profitEl.textContent = (arbState.profit >= 0 ? '+' : '') + '$' + arbState.profit.toFixed(2);
  if(tradesEl) tradesEl.textContent = arbState.totalTrades;
  if(capEl) capEl.textContent = '$' + Math.round(arbState.capital).toLocaleString();
}

function logArbitrageMessage(msg) {
  const logBox = document.getElementById('arb_log');
  if(!logBox) return;
  logBox.innerHTML = `<div>${msg}</div>` + logBox.innerHTML;
}


