function initCalendarSim() {
  const grid = document.getElementById('calendar_events_grid');
  if(!grid) return;

  grid.innerHTML = CRYPTO_EVENTS.map((ev, idx) => `
    <div class="tile" onclick="showCalendarEventEffect(${idx})" style="padding:16px; text-align:center; cursor:pointer">
      <div style="font-size:24px; margin-bottom:6px">${ev.effect > 0 ? '📈' : '📉'}</div>
      <h4 style="margin:0 0 4px; font-size:14px; color:var(--txt)">${ev.title}</h4>
      <div style="font-size:11px; color:var(--mut); margin-bottom:6px">${ev.date}</div>
      <div style="font-size:13px; font-weight:800; color:${ev.effect > 0 ? 'var(--ok)' : 'var(--bad)'}">${ev.impact}</div>
    </div>
  `).join('');
}

function showCalendarEventEffect(idx) {
  const event = CRYPTO_EVENTS[idx];
  const resultBox = document.getElementById('calendar_event_result');
  const impactBox = document.getElementById('calendar_price_impact');
  if(!resultBox || !impactBox) return;

  resultBox.innerHTML = `
    <b style="color:var(--txt); font-size:16px">${event.title} (${event.date})</b><br>
    <span style="color:var(--mut); margin-top:4px; display:inline-block">${event.desc}</span>
    <div style="margin-top:8px; padding:8px 10px; border-radius:8px; background:rgba(234,179,8,.08); border-left:3px solid var(--warn); font-size:12px; color:var(--txt)">
      ⚠️ Предупреждение о причинности: цифра показывает, как изменилась цена в выбранном окне ПОСЛЕ события (историческая справка). Это не означает, что событие её вызвало — одновременно действует множество факторов.
    </div>
  `;

  const impactColor = event.effect > 0 ? 'var(--ok)' : 'var(--bad)';
  const impactSign = event.effect > 0 ? '+' : '';
  impactBox.style.color = impactColor;
  impactBox.textContent = `Цена изменилась на ${impactSign}${(event.effect * 100).toFixed(0)}% в выбранном окне после события`;
  
  impactBox.style.transform = 'scale(1.15)';
  setTimeout(() => { impactBox.style.transform = 'scale(1)'; }, 200);
}


/* --- 3. БАЛАНС РИСКА И ДОХОДНОСТИ ('risk_reward') --- */
function updateRiskRewardSim(riskLevel) {
  const risk = parseFloat(riskLevel) || 15;
  const labelEl = document.getElementById('risk_level_label');
  if(labelEl) labelEl.textContent = risk + '%';

  // Иллюстративные сценарии (НЕ прогноз и НЕ гарантия):
  // рост риска расширяет разброс исходов, но не поднимает худший сценарий.
  const base = 5 + (risk * 1.05);
  const spread = risk * 0.9;
  const badCase = Math.round(base - spread);
  const goodCase = Math.round(base + spread);
  const maxDrawdown = risk * 0.82;
  const sharpe = Math.max(0.1, (base - 5) / risk);

  let strategyName, sleepQuality, ruleText;
  if(risk <= 15) {
    strategyName = '🛡️ Консервативная (Low Risk)';
    sleepQuality = '😴 Спокойный и крепкий';
    ruleText = 'Ниже волатильность — обычно уже разброс исходов. Но даже консервативные стратегии могут приносить убытки в отдельные периоды.';
  } else if(risk <= 30) {
    strategyName = '⚖️ Умеренно-сбалансированная';
    sleepQuality = '😐 Приемлемое';
    ruleText = 'Умеренный риск означает умеренные просадки в плохом сценарии — диверсификация и стоп-правила остаются обязательными.';
  } else if(risk <= 45) {
    strategyName = '🔥 Агрессивная волатильная';
    sleepQuality = '😬 Повышенный стресс';
    ruleText = 'Высокая волатильность означает широкий разброс: год может закончиться как большим плюсом, так и глубоким минусом.';
  } else {
    strategyName = '💀 Экстремальная (Казино)';
    sleepQuality = '🚨 Бессонница и тильт';
    ruleText = 'При такой волатильности плохой сценарий уносит значительную часть депозита, а плечо x20+ приближает ликвидацию. Высокий риск НЕ гарантирует высокую доходность.';
  }

  const stratEl = document.getElementById('rr_strategy_name');
  const volEl = document.getElementById('rr_volatility');
  const retEl = document.getElementById('rr_return');
  const ddEl = document.getElementById('rr_max_dd');
  const sharpeEl = document.getElementById('rr_sharpe');
  const sleepEl = document.getElementById('rr_sleep');
  const ruleEl = document.getElementById('rr_rule_text');

  if(stratEl) stratEl.textContent = strategyName;
  if(volEl) volEl.textContent = risk + '%';
  if(retEl) retEl.textContent = badCase + '% … +' + goodCase + '%';
  if(ddEl) {
    ddEl.textContent = '-' + maxDrawdown.toFixed(0) + '%';
    ddEl.style.color = maxDrawdown > 30 ? 'var(--bad)' : (maxDrawdown > 15 ? 'var(--warn)' : 'var(--ok)');
  }
  if(sharpeEl) sharpeEl.textContent = sharpe.toFixed(2) + '*';
  if(sleepEl) sleepEl.textContent = sleepQuality;
  if(ruleEl) ruleEl.textContent = ruleText;

  const noteEl = document.getElementById('rr_note');
  if(noteEl) noteEl.textContent = '* Цифры — иллюстративные сценарии учебной модели, а не прогноз: реальная доходность зависит от стратегии и рынка, высокий риск НЕ гарантирует высокий доход.';
}


