var psychCurrentQuestion = 0;
var psychCorrectCount = 0;

function initPsychologySim() {
  psychCurrentQuestion = 0;
  psychCorrectCount = 0;
  const resEl = document.getElementById('psychology_result');
  if(resEl) resEl.style.display = 'none';
  renderPsychQuestion();
}

function renderPsychQuestion() {
  const container = document.getElementById('psychology_quiz_container');
  if(!container) return;

  if(psychCurrentQuestion >= PSYCHOLOGY_QUIZ.length) {
    showPsychResult();
    return;
  }

  const q = PSYCHOLOGY_QUIZ[psychCurrentQuestion];
  container.innerHTML = `
    <div style="background:var(--card); border:1.5px solid var(--line); border-radius:14px; padding:22px; margin-bottom:16px; box-shadow:var(--shadow)">
      <div style="font-size:12px; font-weight:800; color:var(--acc2); text-transform:uppercase; margin-bottom:8px">Ситуационный тест ${psychCurrentQuestion + 1} из ${PSYCHOLOGY_QUIZ.length}</div>
      <div style="font-size:16px; font-weight:700; color:var(--txt); margin-bottom:16px; line-height:1.45">${q.q}</div>
      <div style="display:flex; flex-direction:column; gap:10px">
        ${q.opts.map((opt, idx) => `
          <button class="ans" onclick="checkPsychAnswer(${idx})" style="text-align:left; padding:12px 16px; font-size:14px">
            ${opt}
          </button>
        `).join('')}
      </div>
      <div id="psych_feedback" style="display:none; margin-top:14px; padding:14px; border-radius:10px; font-size:13.5px; line-height:1.5"></div>
    </div>
  `;
}

function checkPsychAnswer(idx) {
  const q = PSYCHOLOGY_QUIZ[psychCurrentQuestion];
  const fb = document.getElementById('psych_feedback');
  const btns = document.querySelectorAll('#psychology_quiz_container .ans');
  if(!fb) return;

  btns.forEach((btn, i) => {
    btn.disabled = true;
    if(i === q.correct) {
      btn.style.borderColor = 'var(--ok)';
      btn.style.background = 'rgba(34,197,94,.12)';
    } else if(i === idx) {
      btn.style.borderColor = 'var(--bad)';
      btn.style.background = 'rgba(239,68,68,.12)';
    }
  });

  const isCorrect = (idx === q.correct);
  if(isCorrect) psychCorrectCount++;

  fb.style.display = 'block';
  fb.style.background = isCorrect ? 'rgba(34,197,94,.08)' : 'rgba(239,68,68,.08)';
  fb.style.border = isCorrect ? '1.5px solid var(--ok)' : '1.5px solid var(--bad)';
  fb.innerHTML = `
    <div style="color:var(--txt); margin-bottom:10px">${q.explain[idx]}</div>
    <button class="btn sm" onclick="nextPsychQuestion()" style="font-weight:700">
      ${psychCurrentQuestion + 1 < PSYCHOLOGY_QUIZ.length ? 'Следующий вопрос ➔' : 'Посмотреть итог теста ➔'}
    </button>
  `;
}

function nextPsychQuestion() {
  psychCurrentQuestion++;
  renderPsychQuestion();
}

function showPsychResult() {
  const container = document.getElementById('psychology_quiz_container');
  const resultBox = document.getElementById('psychology_result');
  const emoji = document.getElementById('psych_emoji');
  const title = document.getElementById('psych_result_title');
  const desc = document.getElementById('psych_result_desc');

  if(!container || !resultBox) return;
  container.innerHTML = '';
  resultBox.style.display = 'block';

  const score = psychCorrectCount;
  if(score >= 4) {
    if(emoji) emoji.textContent = '🧠';
    if(title) title.textContent = `Психологическая устойчивость: ${score} из 5 (Стоик)`;
    if(desc) desc.textContent = 'Вы обладаете хладнокровием квант-архитектора, отлично контролируете эмоции и умеете действовать по системе без тильта.';
  } else if(score >= 2) {
    if(emoji) emoji.textContent = '🤔';
    if(title) title.textContent = `Психологическая устойчивость: ${score} из 5 (Ученик)`;
    if(desc) desc.textContent = 'Вы понимаете основы, но в моменты сильного стресса можете поддаться FOMO или страху. Торговые чек-листы помогут вам сохранять дисциплину.';
  } else {
    if(emoji) emoji.textContent = '😰';
    if(title) title.textContent = `Психологическая устойчивость: ${score} из 5 (Зона риска)`;
    if(desc) desc.textContent = 'Эмоции пока берут верх над расчетом. Алгоритмическая торговля создана именно для того, чтобы автоматизировать сделки и исключить человеческий фактор.';
  }
}





/* =========================================================================
   АВТОМАТИЧЕСКАЯ НОРМАЛИЗАЦИЯ УРОКОВ И КВИЗОВ
   ========================================================================= */
(function normalizeLessonNumbers(){
  LESSONS.forEach(function(l){
    if(l.num) return;
    const m = l.title.match(/^(\d+\.\d+)\.?\s*(.*)$/);
    if(m){
      l.num = m[1];
      l.title = m[2];
    }
  });
})();

(function normalizeLessonQuizzes(){
  LESSONS.forEach(function(l){
    if(l.quiz || !l.blocks) return;
    const qb = l.blocks.filter(function(b){ return b.type === 'quiz'; })[0];
    if(!qb) return;
    const idx = (qb.a !== undefined) ? qb.a : 0;
    l.quiz = {
      q: qb.q,
      opts: qb.opts,
      a: idx,
      explain: Array.isArray(qb.explain) ? qb.explain[idx] : (qb.explain || '')
    };
    l.blocks = l.blocks.filter(function(b){ return b.type !== 'quiz'; });
  });
})();


