function calcP1LogRet(v){
  const d = Number(v) / 100;
  const need = d / (1 - d);
  const lblDrop = document.getElementById('p1_l2_lbl');
  const out = document.getElementById('p1_l2_out');
  if(lblDrop) lblDrop.textContent = '−' + Number(v).toFixed(0) + '%';
  if(!out) return;
  const logDown = Math.log(1 - d);
  const logUp = Math.log(1 + need);
  const naive = (-d + d) * 100;
  out.innerHTML = `
    <div>Капитал упал на <b style="color:var(--bad)">−${(d*100).toFixed(0)}%</b>. Чтобы вернуться в исходную точку, нужен рост
      <b style="color:var(--ok)">+${(need*100).toFixed(1)}%</b>.</div>
    <div style="margin-top:6px; color:var(--mut)">Наивное сложение процентов дало бы <b>${naive.toFixed(0)}%</b> — и это неверно.</div>
    <div style="margin-top:10px; padding:10px; border-radius:6px; background:rgba(6,182,212,.08)">
      Логарифмические доходности: ln(1−${d.toFixed(2)}) = <b>${logDown.toFixed(4)}</b>, ln(1+${need.toFixed(2)}) = <b>+${logUp.toFixed(4)}</b>.
      Их сумма ровно <b style="color:var(--acc2)">${(logDown+logUp).toFixed(4)}</b> — ноль. Именно поэтому во времени складывают логарифмы, а не проценты.
    </div>`;
}

function calcP1FatTails(sigma){
  const out = document.getElementById('p1_l4_out');
  if(!out) return;
  // хвостовая вероятность нормального распределения (двусторонняя), приближение Чернова/асимптотика
  const p = Math.exp(-sigma * sigma / 2) / (sigma * Math.sqrt(2 * Math.PI)) * 2;
  const daysPerEvent = 1 / p;
  const yearsPerEvent = daysPerEvent / 365;
  const real = { 3: 'около 15–25 раз в год', 5: 'примерно 1–3 раза в год', 10: 'несколько раз за историю рынка (март 2020, май 2021, крах FTX)' }[sigma];
  const theory = yearsPerEvent < 1
    ? `раз в ${daysPerEvent.toFixed(0)} дней`
    : (yearsPerEvent < 1e6 ? `раз в ${yearsPerEvent.toLocaleString('ru-RU', {maximumFractionDigits:0})} лет` : `раз в ${(yearsPerEvent/1e6).toExponential(1)} млн лет`);
  out.innerHTML = `
    <div>📐 <b>Теория (нормальное распределение):</b> движение более ${sigma}σ должно случаться <b style="color:var(--acc2)">${theory}</b>.</div>
    <div style="margin-top:6px">🔥 <b>Реальность крипторынка:</b> <b style="color:var(--bad)">${real}</b>.</div>
    <div style="margin-top:10px; padding:10px; border-radius:6px; background:rgba(239,68,68,.08); color:var(--txt)">
      Вывод: любые расчёты риска «в сигмах» занижают вероятность катастрофы. Считай риск по эмпирическим квантилям и стресс-тестам.
    </div>`;
}

function calcP1Costs(){
  const g = parseFloat((document.getElementById('p1_l8_gross')||{}).value || 5);
  const f = parseFloat((document.getElementById('p1_l8_fee')||{}).value || 5.5);
  const s = parseFloat((document.getElementById('p1_l8_slip')||{}).value || 2);
  const n = parseFloat((document.getElementById('p1_l8_n')||{}).value || 1000);
  const set = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
  set('p1_l8_gross_l', g.toFixed(1) + ' bps');
  set('p1_l8_fee_l', f.toFixed(1) + ' bps');
  set('p1_l8_slip_l', s.toFixed(1) + ' bps');
  set('p1_l8_n_l', n.toFixed(0));
  const net = g - f - s;
  const annual = n * net / 100;
  const out = document.getElementById('p1_l8_out');
  if(!out) return;
  const ok = net > 0;
  out.style.background = ok ? 'rgba(34,197,94,.12)' : 'rgba(239,68,68,.12)';
  out.innerHTML = `
    <div style="color:var(--mut); font-size:11.5px">Чистый результат на сделку</div>
    <div style="font-size:20px; font-weight:800; color:${ok ? 'var(--ok)' : 'var(--bad)'}">${net > 0 ? '+' : ''}${net.toFixed(2)} bps</div>
    <div style="margin-top:6px; font-size:13px">Годовой результат до реинвестирования: <b style="color:${ok ? 'var(--ok)' : 'var(--bad)'}">${annual > 0 ? '+' : ''}${annual.toFixed(1)}%</b></div>
    <div style="margin-top:8px; font-size:12px; color:var(--mut)">
      ${ok ? 'Эдж покрывает издержки. Дальше проверяй устойчивость на Walk-Forward и ёмкость стратегии.'
           : 'Издержки съедают эдж. Такая стратегия зарабатывает бирже, а не тебе: снижай частоту, работай лимитными заявками или ищи более сильный сигнал.'}
    </div>`;
}

function calcP1Overfit(n){
  const out = document.getElementById('p1_l10_out');
  if(!out) return;
  const DAYS = 250;
  let best = -99, bestTotal = 0, positives = 0;
  for(let i = 0; i < n; i++){
    let sum = 0, sumSq = 0;
    for(let d = 0; d < DAYS; d++){
      // случайная дневная доходность, среднее строго 0
      let u = 0;
      for(let k = 0; k < 3; k++) u += Math.random() - 0.5;
      const r = u * 0.02;
      sum += r; sumSq += r * r;
    }
    const mean = sum / DAYS;
    const varr = sumSq / DAYS - mean * mean;
    const sd = Math.sqrt(Math.max(varr, 1e-12));
    const sharpe = (mean / sd) * Math.sqrt(365);
    if(sharpe > 0) positives++;
    if(sharpe > best){ best = sharpe; bestTotal = (Math.exp(sum) - 1) * 100; }
  }
  const expectedMax = Math.sqrt(2 * Math.log(n));
  out.innerHTML = `
    <div>Протестировано вариантов: <b>${n.toLocaleString('ru-RU')}</b>. Реального эджа нет ни у одного — доходности случайны.</div>
    <div style="margin-top:8px; padding:10px; border-radius:6px; background:rgba(124,58,237,.1)">
      🏆 Лучшая «стратегия»: Sharpe = <b style="color:var(--ok)">${best.toFixed(2)}</b>, доходность за год <b style="color:var(--ok)">${bestTotal > 0 ? '+' : ''}${bestTotal.toFixed(1)}%</b>.
      <div style="margin-top:4px; color:var(--mut); font-size:12px">Прибыльными «случайно» оказались ${positives} вариантов из ${n}.</div>
    </div>
    <div style="margin-top:8px; color:var(--mut)">
      Теоретическая планка: при ${n.toLocaleString('ru-RU')} испытаниях ожидаемый максимум Шарпа на чистом шуме ≈ <b style="color:var(--warn)">${expectedMax.toFixed(2)}</b>.
      Твой результат должен уверенно её превышать — иначе это не эдж, а перебор.
    </div>`;
}


