function calcP5Streak(){
  const g = id => document.getElementById(id);
  const wr = parseFloat((g('p5_wr')||{}).value || 55) / 100;
  const n  = parseFloat((g('p5_n')||{}).value || 500);
  const risk = parseFloat((g('p5_risk')||{}).value || 1);
  const cap = parseFloat((g('p5_cap')||{}).value || 6000000);
  const set = (id, v) => { const el = g(id); if(el) el.textContent = v; };
  set('p5_wr_l', (wr*100).toFixed(0) + '%');
  set('p5_n_l', n.toLocaleString('ru-RU'));
  set('p5_risk_l', risk.toFixed(2) + '%');
  set('p5_cap_l', cap.toLocaleString('ru-RU') + ' ₽');

  const q = 1 - wr;
  const streak = Math.log(n) / Math.log(1 / q);
  const streakInt = Math.ceil(streak);
  const lossPct = (1 - Math.pow(1 - risk/100, streakInt)) * 100;
  const lossRub = cap * lossPct / 100;
  // вероятность встретить серию длиной >= streakInt хотя бы раз за год (приближение)
  const pAtLeast = 1 - Math.exp(-n * Math.pow(q, streakInt) * (1 - q));
  const out = document.getElementById('p5_streak_out');
  if(!out) return;
  out.innerHTML = `
    <div style="padding:12px; border-radius:8px; background:rgba(239,68,68,.1)">
      Ожидаемая максимальная серия убытков за год: <b style="color:var(--bad); font-size:17px">${streakInt} подряд</b>
      <div style="color:var(--mut); font-size:12px; margin-top:4px">Вероятность встретить такую серию хотя бы раз: около ${(pAtLeast*100).toFixed(0)}%. Это норма, а не поломка.</div>
    </div>
    <div style="margin-top:10px">
      Просадка от одной такой серии: <b style="color:var(--warn)">−${lossPct.toFixed(1)}%</b>, то есть
      <b style="color:var(--bad)">−${Math.round(lossRub).toLocaleString('ru-RU')} ₽</b> на твоём капитале.
    </div>
    <div style="margin-top:10px; padding:10px; border-radius:6px; background:rgba(6,182,212,.08); color:var(--txt)">
      Посмотри на эту сумму сейчас, в спокойном состоянии. Именно её ты увидишь на экране в тот день, когда со стратегией всё будет в полном порядке.
      Если цифра кажется невыносимой — уменьшай риск на сделку, а не выключай бота потом.
    </div>`;
}

function buildP5Charter(save){
  const g = id => document.getElementById(id);
  const val = (id, d) => { const el = g(id); return el ? el.value : d; };
  const on  = id => { const el = g(id); return el ? el.checked : false; };
  const risk = val('ch_risk', 1), day = val('ch_day', 3), lev = val('ch_lev', 2), dd = val('ch_dd', 18);
  const lines = [];
  lines.push('ТОРГОВЫЙ УСТАВ');
  lines.push('Дата вступления в силу: ' + new Date().toLocaleDateString('ru-RU'));
  lines.push('');
  lines.push('1. ЛИМИТЫ РИСКА');
  lines.push('   1.1. Риск на одну сделку: не более ' + risk + '% капитала.');
  lines.push('   1.2. Лимит убытка за календарный день: ' + day + '%. При достижении торговля останавливается до следующего дня.');
  lines.push('   1.3. Максимальное суммарное плечо по всем позициям: ' + lev + 'x.');
  lines.push('   1.4. Стратегия останавливается для разбора при просадке от пика более ' + dd + '%.');
  lines.push('');
  lines.push('2. ПРАВИЛА ПОВЕДЕНИЯ');
  const map = {
    r1: 'Размер позиции рассчитывается кодом; ручной ввод объёма запрещён.',
    r2: 'При срабатывании дневного лимита убытка торговля прекращается до следующего дня без исключений.',
    r3: 'Превышение установленного плеча блокируется предпроверкой ордера.',
    r4: 'На одной бирже находится не более 20% капитала; остальное — в холодном хранении.',
    r5: 'В систему вносится не более одного изменения за раз; оно вступает в силу со следующего дня.',
    r6: 'Решение об остановке или перезапуске стратегии принимается только на плановом еженедельном разборе.',
    r7: 'Ручное вмешательство в открытые позиции бота запрещено.',
    r8: 'Усреднение убыточных позиций запрещено.',
    r9: 'Каждая сделка и каждое изменение конфигурации фиксируются в журнале с указанием причины.',
    r10: 'Часть прибыли выводится на банковский счёт по расписанию, а не реинвестируется полностью.'
  };
  let k = 1;
  Object.keys(map).forEach(function(id){ if(on('ch_' + id)) lines.push('   2.' + (k++) + '. ' + map[id]); });
  if(k === 1) lines.push('   (не выбрано ни одного правила — устав пуст)');
  lines.push('');
  lines.push('3. ПРАВИЛО ПО УМОЛЧАНИЮ');
  lines.push('   Если ситуация не описана в уставе — не предпринимать никаких действий');
  lines.push('   и вынести вопрос на ближайший плановый разбор.');
  lines.push('');
  lines.push('Подпись: ______________________');

  const out = document.getElementById('p5_charter_out');
  if(out) out.textContent = lines.join('\n');

  if(save){
    const state = { risk: risk, day: day, lev: lev, dd: dd };
    Object.keys(map).forEach(function(id){ state[id] = on('ch_' + id); });
    try {
      localStorage.setItem('cn_charter', JSON.stringify(state));
      if(typeof toast === 'function') toast('📜 Устав сохранён в браузере');
    } catch(e){}
  }
}

function copyP5Charter(){
  const out = document.getElementById('p5_charter_out');
  if(!out) return;
  const text = out.textContent;
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(function(){
      if(typeof toast === 'function') toast('📋 Устав скопирован в буфер обмена');
    });
  }
}

function calcP5Counterparty(){
  const g = id => document.getElementById(id);
  const total = parseFloat((g('cp_total')||{}).value || 6);
  let e1 = parseFloat((g('cp_e1')||{}).value || 0);
  let e2 = parseFloat((g('cp_e2')||{}).value || 0);
  let e3 = parseFloat((g('cp_e3')||{}).value || 0);
  const set = (id, v) => { const el = g(id); if(el) el.textContent = v; };
  set('cp_total_l', total.toFixed(1));
  set('cp_e1_l', e1 + '%'); set('cp_e2_l', e2 + '%'); set('cp_e3_l', e3 + '%');

  const onExchanges = e1 + e2 + e3;
  const cold = Math.max(0, 100 - onExchanges);
  const worst = Math.max(e1, e2, e3);
  const worstRub = total * 1e6 * worst / 100;
  const recovery = worst >= 100 ? Infinity : (1 / (1 - worst/100) - 1) * 100;

  let verdict, color;
  if(onExchanges > 100){ verdict = 'Сумма долей превышает 100% — уменьши распределение по площадкам.'; color = 'var(--bad)'; }
  else if(worst > 20){ verdict = 'Слишком высокая концентрация: у одного контрагента более 20% капитала.'; color = 'var(--bad)'; }
  else if(onExchanges > 40){ verdict = 'На биржах суммарно многовато. Ориентир — не более 30–40% капитала.'; color = 'var(--warn)'; }
  else { verdict = 'Распределение в пределах разумного: крах одной площадки переживаем.'; color = 'var(--ok)'; }

  const out = document.getElementById('p5_cp_out');
  if(!out) return;
  out.innerHTML = `
    <div style="display:flex; gap:14px; flex-wrap:wrap; margin-bottom:10px">
      <div>На биржах: <b style="color:var(--warn)">${onExchanges}%</b></div>
      <div>В холодном хранении: <b style="color:var(--ok)">${cold}%</b></div>
    </div>
    <div style="padding:12px; border-radius:8px; background:rgba(239,68,68,.1)">
      Крах крупнейшей площадки стоит <b style="color:var(--bad); font-size:16px">−${Math.round(worstRub).toLocaleString('ru-RU')} ₽</b> (${worst}% капитала).
      <div style="color:var(--mut); font-size:12px; margin-top:4px">Чтобы вернуться в исходную точку, потребуется заработать ${isFinite(recovery) ? '+' + recovery.toFixed(1) + '%' : 'бесконечность: капитала не останется'} на оставшемся капитале.</div>
    </div>
    <div style="margin-top:10px; padding:10px; border-radius:6px; background:rgba(255,255,255,.04); color:${color}"><b>${verdict}</b></div>`;
}


