/* --- F2: динамические счётчики уроков в чипах каталога --- */
function refreshCatalogChipCounts(){
  const chips=document.querySelectorAll('#lessons .controls .chip');
  const totals={core:[0,0],bonus:[0,0],math:[0,0],academy:[0,0]};
  LESSONS.forEach(l=>{
    let bucket='core';
    if(l.phase===6) bucket='bonus'; else if(l.phase===7) bucket='math'; else if(l.phase===9) bucket='academy';
    totals[bucket][0]+=lessonsDone[l.id]===1?1:0;
    totals[bucket][1]++;
  });
  chips.forEach(chip=>{
    const oc=chip.getAttribute('onclick')||'';
    let m=oc.match(/switchPhaseLessons\((\d+)/);
    if(m){
      const ph=parseInt(m[1]);
      if(ph===6){ chip.textContent=`🎁 Бонусы (${totals.bonus[1]}) · ✓${totals.bonus[0]}`; return; }
      if(ph===7){ chip.textContent=`🧠 Матмышление (${totals.math[1]}) · ✓${totals.math[0]}`; return; }
      if(ph===9){ chip.textContent=`🤖 Академия Freqtrade (${totals.academy[1]}) · ✓${totals.academy[0]}`; return; }
      const ls=LESSONS.filter(l=>l.phase===ph);
      const done=ls.filter(l=>lessonsDone[l.id]===1).length;
      // убираем прежний хвост «· ✓N» если был
      chip.textContent=chip.textContent.split(' · ✓')[0]+` · ✓${done}/${ls.length}`;
    }
  });
  let sumEl=document.getElementById('course_total_counter');
  if(!sumEl && document.querySelector('#lessons .controls')){
    sumEl=document.createElement('span');
    sumEl.id='course_total_counter';
    sumEl.style.cssText='font-size:12px;color:var(--mut);font-weight:700;margin-left:10px';
    document.querySelector('#lessons .controls').appendChild(sumEl);
  }
  if(sumEl) sumEl.innerHTML=`📚 Основной курс: ${totals.core[0]} из ${totals.core[1]} · Бонусы: ${totals.bonus[0]}/${totals.bonus[1]} · Маткурс: ${totals.math[0]}/${totals.math[1]} · Академия: ${totals.academy[0]}/${totals.academy[1]}`;
}

/* --- F4: домашний калькулятор издержек --- */
function renderHomeCostCalc(){
  const box=document.getElementById('home_cost_calc'); if(!box) return;
  box.innerHTML=`<div style="background:#090d1f;border:1px solid var(--line);border-radius:10px;padding:12px;display:grid;gap:8px;font-size:12.5px;color:var(--txt)">
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      <label>Депозит ₽ <input type="number" id="hc_dep" value="100000" min="1000" step="10000" style="width:95px"></label>
      <label>Позиция % от деп. <input type="number" id="hc_pos" value="50" min="1" max="100" style="width:55px"></label>
      <label>Кругов/день <input type="number" id="hc_trades" value="10" min="1" style="width:55px"></label>
      <label>Комиссия стороны bps <input type="number" id="hc_fee" value="5" min="0" style="width:55px"></label>
      <label>Slippage bps <input type="number" id="hc_slip" value="3" min="0" style="width:55px"></label>
      <label>Дней/мес <input type="number" id="hc_days" value="22" min="1" max="31" style="width:50px"></label>
      <button class="btn sm" onclick="calcHomeCosts()">🧮 Считать</button>
    </div>
    <div id="hc_out" style="color:var(--mut)">Заполни параметры — увидишь издержки за месяц и вердикт.</div>
  </div>`;
}
function calcHomeCosts(){
  const g=id=>parseFloat(document.getElementById(id)?.value)||0;
  const dep=g('hc_dep'), posPct=g('hc_pos'), trades=g('hc_trades'), feeBps=g('hc_fee'), slipBps=g('hc_slip'), days=g('hc_days');
  const out=document.getElementById('hc_out'); if(!out) return;
  if(dep<=0||trades<=0||days<=0){ out.innerHTML='<span style="color:var(--bad)">Проверь параметры.</span>'; return; }
  const posSize=dep*posPct/100;
  const perRound=posSize*((feeBps*2+slipBps*2)/10000);
  const month=perRound*trades*days;
  const pct=month/dep*100;
  const verdict=pct>=25?'💀 Стратегия умирает: издержки съедают четверть депозита и больше.':(pct>=10?'⚠️ Опасная зона: издержки давят результат — сокращай частоту или улучшай исполнение.':'✅ Пока переживает свои издержки — но помни про проскальзывание в волатильные дни.');
  out.innerHTML=`За месяц (${Math.round(trades*days)} кругов): издержки ≈ <b style="color:${pct>=25?'var(--bad)':(pct>=10?'var(--warn)':'var(--ok)')}">${Math.round(month).toLocaleString()} ₽</b> — это <b>${pct.toFixed(1)}%</b> депозита.<br><b>${verdict}</b>`;
}

/* --- F5: калькулятор размера позиции по риску (переиспользуемый виджет) --- */
function renderPositionSizer(hostId){
  const host=document.getElementById(hostId); if(!host) return;
  host.innerHTML=`<div style="background:#040714;border:1px solid var(--line);border-radius:10px;padding:14px;display:grid;gap:9px;font-size:12.5px;color:var(--txt)">
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      <label>Депозит ₽ <input type="number" id="${hostId}_dep" value="100000" min="100" step="10000" style="width:100px"></label>
      <label>Риск/сделка % <select id="${hostId}_risk" style="padding:3px"><option value="1">1%</option><option value="2" selected>2%</option></select></label>
      <label>Вход ₽ <input type="number" id="${hostId}_entry" value="97000" min="1" style="width:95px"></label>
      <label>Стоп ₽ <input type="number" id="${hostId}_stop" value="94000" min="1" style="width:95px"></label>
      <label>Плечо x <input type="number" id="${hostId}_lev" value="1" min="1" max="50" style="width:50px"></label>
      <label>Комиссия круг bps <input type="number" id="${hostId}_fee" value="10" min="0" style="width:55px"></label>
    </div>
    <div><button class="btn sm" onclick="calcPositionSizer('${hostId}')">🎯 Рассчитать позицию</button></div>
    <div id="${hostId}_out" style="line-height:1.55">Результат появится здесь.</div>
  </div>`;
}
function calcPositionSizer(hostId){
  const v=id=>parseFloat(document.getElementById(hostId+'_'+id)?.value)||0;
  const dep=v('dep'), riskPct=v('risk')||2, entry=v('entry'), stop=v('stop'), lev=Math.max(1,v('lev')), feeBps=v('fee');
  const out=document.getElementById(hostId+'_out'); if(!out) return;
  if(dep<=0||entry<=0||stop<=0||entry===stop){ out.innerHTML='<span style="color:var(--bad)">Заполни депозит, вход и стоп (вход ≠ стоп).</span>'; return; }
  const riskMoney=dep*riskPct/100;
  const distPct=Math.abs(entry-stop)/entry*100;
  const qtyRisk=riskMoney/(Math.abs(entry-stop));           // объём из риска на единицу
  const qtyFeeCap=(riskMoney)/(posSizeFeePerUnit());        // ограничение по комиссии
  function posSizeFeePerUnit(){ return entry*(feeBps/10000); }
  const qty=qtyRisk;
  const notional=qty*entry;
  const marginNeeded=notional/lev;
  const feeCost=notional*feeBps/10000*2;
  const oversized=marginNeeded>dep*0.5 || feeCost>riskMoney*0.5;
  out.innerHTML=`Допустимый объём позиции: <b style="color:var(--acc2)">${qty.toFixed(6)} ед.</b> (~${Math.round(notional).toLocaleString()} ₽ номинала)<br>
    Риск на сделку: <b>${Math.round(riskMoney).toLocaleString()} ₽ (${riskPct}%)</b> · расстояние до стопа: <b>${distPct.toFixed(2)}%</b><br>
    Маржа при x${lev}: ≈${Math.round(marginNeeded).toLocaleString()} ₽ · комиссия круга ≈${Math.round(feeCost).toLocaleString()} ₽<br>
    ${oversized?'<span style="color:var(--bad)">⚠️ Позиция велика для такого риска/комиссий: уменьши объём, увеличь плечо осознанно или отодвинь стоп.</span>':'<span style="color:var(--ok)">✅ Размер согласован с риском.</span>'}
    <div style="color:var(--mut);margin-top:4px">Формула: объём = риск₽ ÷ |вход−стоп|. Комиссии и гэпы могут съесть часть стопа — закладывай запас.</div>`;
}

