function calcPredArb(){
  const p1=parseFloat(document.getElementById('pa_p1')?.value)||0;
  const p2=parseFloat(document.getElementById('pa_p2')?.value)||0;
  const qty=parseFloat(document.getElementById('pa_qty')?.value)||0;
  const C=parseFloat(document.getElementById('pa_c')?.value)||0;
  const out=document.getElementById('pa_out'); if(!out) return;
  const cost=p1+p2;
  // taker-комиссия кривой: fee = C * 0.06 * p * (1-p) на каждой ноге
  const f1=C*0.06*p1*(1-p1), f2=C*0.06*p2*(1-p2);
  const payout=qty*1;
  const spend=qty*(cost+f1+f2);
  const net=payout-spend;
  out.innerHTML=`Затраты на пакет YES+NO: $${(cost*qty).toFixed(2)} · комиссии кривой: $${((f1+f2)*qty).toFixed(2)}<br>
    Выплата при любом исходе: <b>$${payout.toFixed(2)}</b> → чистый результат: <b style="color:${net>0?'var(--ok)':'var(--bad)'}">${net>=0?'+':''}$${net.toFixed(2)}</b><br>
    ${net>0?'Спред покрывает комиссии — арбитраж есть (пока его не закрыли боты).':'Трение съедает сделку: при спредах меньше 2–3 центов арбитраж умирает.'}`;
}

function checkEoaConfig(){
  const lim=parseFloat(document.getElementById('eoa_limit')?.value)||0;
  const addr=(document.getElementById('eoa_addr')?.value||'').trim();
  const days=parseFloat(document.getElementById('eoa_days')?.value)||0;
  const out=document.getElementById('eoa_out'); if(!out) return;
  let leaks=[];
  if(lim<=0||lim>2000) leaks.push('Лимит трат не задан или слишком велик — скомпрометированный ключ сольёт казну.');
  if(!addr||/example|\.\.\./i.test(addr)) leaks.push('Allowlist содержит плейсхолдер — агент сможет отправить средства ЛЮБОМУ адресу.');
  if(days<=0||days>90) leaks.push('Срок действия не ограничен/завышен — окно атаки растёт.');
  out.innerHTML=leaks.length
    ? `<div style="color:var(--bad);font-weight:700">🚨 Симуляция утечки: конфигурация дырявая.</div><ul style="margin:6px 0 0;padding-left:18px">${leaks.map(x=>'<li>'+x+'</li>').join('')}</ul>`
    : `<span style="color:var(--ok)">✅ Политика выглядит разумно: жёсткий лимит, конкретный адрес, короткое окно.</span>`;
}

function runRestakingContagion(){
  const w1=Math.max(0,parseFloat(document.getElementById('rk_w1')?.value)||0);
  const w2=Math.max(0,parseFloat(document.getElementById('rk_w2')?.value)||0);
  const w3=Math.max(0,parseFloat(document.getElementById('rk_w3')?.value)||0);
  const sum=w1+w2+w3||100;
  const out=document.getElementById('rk_out'); if(!out) return;
  const weights=[w1/sum,w2/sum,w3/sum];
  const avs=[['EigenCloud',0],['Symbiotic',1],['Karak',2]];
  const victim=avs[Math.floor(Math.random()*3)];
  const slashPct=0.08+Math.random()*0.12;           // 8–20% слеша AVS
  const queueStress=Math.random();                   // насколько переполнена очередь вывода
  const lrtDepegBase=slashPct*2;                     // базовый depeg LRT
  const depeg=lrtDepegBase*(1+queueStress*3);        // нелинейность Curve-пула при очереди
  let portfolio=100000, parts=[];
  weights.forEach((w,i)=>{
    let v=portfolio*w;
    if(i===victim[1]) v*= (1-slashPct);
    else v*= (1 - Math.max(0, depeg-0.05)*0.25);     // contagion через общие LRT
    parts.push([victim[1]===i?victim[0]+' ⚡':avs[i][0], v]);
  });
  const total=parts.reduce((s,p)=>s+p[1],0);
  const loss=portfolio-total;
  out.innerHTML=`Slashing удара по <b>${victim[0]}</b>: −${(slashPct*100).toFixed(1)}% залога сервиса. Стресс очереди вывода: ${(queueStress*100).toFixed(0)}% → нелинейный depeg LRT ≈ −${(depeg*100).toFixed(1)}%.<br>
    Итог портфеля: <b style="color:${loss/portfolio<0.03?'var(--warn)':'var(--bad)'}">$${Math.round(total).toLocaleString()}</b> (убыток −$${Math.round(loss).toLocaleString()} / −${(loss/portfolio*100).toFixed(1)}%)<br>
    <span style="color:var(--mut)">Учебная модель: APY 6–8% на LRT включает премию за смарт-контрактный и коррелированный slashing-риск (кейс Kelp DAO: мост ≈$292 млн, отток ~$5,4 млрд, очередь ~14 дней).</span>`;
}

