function parseTaxCsvText(text){
  const rows=text.split(/\r?\n/).map(r=>r.trim()).filter(Boolean);
  let added=0, skipped=0;
  rows.forEach(r=>{
    const cols=r.split(/[,;\t]/).map(c=>c.replace(/^"|"$/g,'').trim());
    if(cols.length<6){ skipped++; return; }
    if(/date|дата/i.test(cols[0]) && isNaN(parseFloat(cols[4]))){ skipped++; return; } // заголовок
    const date=cols[0], rawType=(cols[1]||'').toUpperCase(), asset=cols[2]||'BTC';
    const qty=parseFloat(cols[3]), amount=parseFloat(cols[4]), fee=parseFloat(cols[5])||0;
    if(isNaN(qty)||isNaN(amount)){ skipped++; return; }
    const type=/BUY|ПОКУП/i.test(rawType)?'BUY':(/SELL|ПРОДАЖ/i.test(rawType)?'SELL':null);
    if(!type){ skipped++; return; }
    const nextId=taxTrades.length?Math.max(...taxTrades.map(t=>t.id))+1:1;
    taxTrades.push({id:nextId,date,type,asset,qty,amount,fee});
    added++;
  });
  renderTaxTradesTable(); calcTaxSim();
  alert('Импорт CSV завершён: добавлено '+added+' строк'+(skipped?', пропущено '+skipped:'')+'.');
}
function importTaxCsv(file){
  if(!file){ alert('Файл не выбран.'); return; }
  const reader=new FileReader();               // локальное чтение файла пользователя — это НЕ fetch
  reader.onload=e=>{ try{ parseTaxCsvText(String(e.target.result)); }catch(err){ alert('Ошибка разбора CSV: '+err.message);} };
  reader.readAsText(file,'utf-8');
}

function calcTaxInstitutional(){
  const method=document.getElementById('tx_method')?.value||'fifo';
  const totalIncome=parseFloat(document.getElementById('tx_total_income')?.value)||0;
  const out=document.getElementById('tax_inst_out'); if(!out) return;

  // Пересчёт в рубли по курсам ЦБ: если суммы указаны в USD (опционально), пользователь ведёт таблицу курсов локально.
  const sorted=[...taxTrades].sort((a,b)=>new Date(a.date)-new Date(b.date));
  let gross=0, base=0, avgQueue=[];            // [qty, amount]
  sorted.forEach(tr=>{
    if(tr.type==='BUY'){ avgQueue.push([tr.qty,tr.amount]); }
    else{
      gross+=tr.amount;
      const soldQty=tr.qty;
      if(method==='avg'){
        const totQty=avgQueue.reduce((s,x)=>s+x[0],0);
        const totAmt=avgQueue.reduce((s,x)=>s+x[1],0);
        if(totQty>0){ base+=soldQty*(totAmt/totQty);
          const rem=totQty-soldQty;
          if(rem>0){ const k=rem/totQty; avgQueue=avgQueue.map(x=>[x[0]*k? x[0]:x[0], x[1]*k]); } else avgQueue=[];
          // упрощение учебной модели: пересчёт остатка пропорционально количеству
          const newTot=totAmt-(soldQty*(totAmt/totQty));
          avgQueue=[[rem,newTot]];
        }
      }
    }
  });
  if(method==='fifo'){
    // база уже посчитана основной функцией calcTaxSim — здесь просто берём её логику повторно
    let q=[],costBasis=0,buyFeeC=0;
    sorted.forEach(tr=>{
      if(tr.type==='BUY'){ q.push({qty:tr.qty,costPerUnit:tr.qty>0?tr.amount/tr.qty:0,feeLeft:tr.fee||0}); }
      else{ let rem=tr.qty;
        while(rem>0&&q.length){ const lot=q[0]; const c=Math.min(lot.qty,rem);
          const fp=lot.qty>0?lot.feeLeft*(c/lot.qty):0;
          costBasis+=c*lot.costPerUnit+fp; buyFeeC+=fp;
          lot.qty-=c; lot.feeLeft-=fp; rem-=c; if(lot.qty<=1e-9) q.shift(); }
      }
    });
    base=costBasis+buyFeeC;
  }
  const profit=Math.max(0,gross-base);
  const combined=profit+totalIncome;
  const rate13=Math.min(profit,2400000-totalIncome>0?profit:Math.max(0,2400000-totalIncome));
  // прогрессивная шкала от СОВОКУПНОГО дохода: ≤2,4 млн → 13%, выше → 15%
  let tax;
  if(combined<=2400000) tax=profit*0.13;
  else{
    const withinLow=Math.max(0,2400000-totalIncome);
    tax=withinLow*0.13+(profit-withinLow)*0.15;
  }
  out.innerHTML=`Метод: <b>${method==='fifo'?'FIFO':'Средняя стоимость (учебный расчёт; выбор метода закреплён ст. 282.3 НК РФ — уточняй актуальный порядок)'}</b><br>
    Доход от продаж: ${Math.round(gross).toLocaleString()} ₽ · база (себестоимость+комиссии партий): ${Math.round(base).toLocaleString()} ₽<br>
    Чистая прибыль: <b>${Math.round(profit).toLocaleString()} ₽</b> · совокупный доход учтён: ${Math.round(totalIncome).toLocaleString()} ₽<br>
    НДФЛ к уплате: <b style="color:var(--acc2)">${Math.round(tax).toLocaleString()} ₽</b> (шкала 13%/15% от совокупного дохода)<br>
    <span style="color:var(--mut)">Пересчёт валютных сделок в рубли выполняется по курсу ЦБ на дату сделки — таблицу курсов ведёт пользователь локально.</span>`;
}


/* ===== FINAL PATCH: MATH WIDGETS ENGINE ===== */
const MWG={};
function mwGauss(){var u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);}
function mwF(n,d){if(d===undefined)d=0;return Number(n).toLocaleString('ru-RU',{minimumFractionDigits:d,maximumFractionDigits:d});}
function mwBarsHtml(counts,color){var mx=Math.max.apply(null,counts.concat([1]));
 return '<div style="display:flex;align-items:flex-end;gap:2px;height:110px;margin-top:8px">'+counts.map(function(c){return '<div title="'+c+'" style="flex:1;height:'+Math.max(2,c/mx*105)+'px;background:'+(color||'linear-gradient(180deg,#22c55e,#06b6d4)')+';border-radius:3px 3px 0 0"></div>';}).join('')+'</div>';}
function mwSvgLines(arr,w,h,steps){var all=[];arr.forEach(function(s){all=all.concat(s.pts);});
 var mn=Math.min.apply(null,all),mx=Math.max.apply(null,all),rg=(mx-mn)||1;
 function X(i){return (i/(steps-1))*(w-70)+50;} function Y(v){return h-20-((v-mn)/rg)*(h-35);}
 var out='';
 arr.forEach(function(s){var pp=s.pts.map(function(v,i){return X(i).toFixed(1)+','+Y(v).toFixed(1);}).join(' ');
  out+='<polyline points="'+pp+'" fill="none" stroke="'+s.color+'" stroke-width="'+(s.w||2)+'"'+(s.dash?' stroke-dasharray="6 4"':'')+'/>';});
 out+='<line x1="45" y1="'+(h-20)+'" x2="'+(w-15)+'" y2="'+(h-20)+'" stroke="rgba(255,255,255,.25)"/>';
 return '<svg width="100%" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none" style="background:#040714;border-radius:8px">'+out+'</svg>';}
