/* М16: теория игр — 100 участников */
MATH_WIDGETS['widget_m_igra_s_koordinaciey']=function(box){
 box.innerHTML='<div style="background:rgba(239,68,68,.05);border:1.5px solid var(--bad);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--bad);text-transform:uppercase;margin-bottom:8px">🎮 Ты против 99 участников (раунды координации)</div>'
 +'<div id="m16_price" style="font-size:16px;font-weight:800;color:var(--txt);margin-bottom:6px">Цена: 100.0</div>'
 +'<button class="btn sm" data-a="buy">🟢 Купить</button> <button class="btn sm ghost" data-a="sell">🔴 Продать</button>'
 +' <button class="btn sm ghost" data-a="wait">⏸ Ждать</button>'
 +'<div id="m16_log" style="margin-top:8px;font-size:12px;color:var(--txt);min-height:52px">Твоё решение влияет на цену наравне с решениями остальных 99.</div></div>';
 let price=100,round=0,myPnl=0,pos=0,avg=0,mom=0;
 const log=box.querySelector('#m16_log'),pr=box.querySelector('#m16_price');
 box.querySelectorAll('button[data-a]').forEach(function(b){b.addEventListener('click',function(){
  const a=this.dataset.a;round++;
  let buys=0,sells=0;
  for(let i=0;i<99;i++){const r=Math.random()+mom*0.3;if(r<0.38)buys++;else if(r<0.76)sells++;}
  if(a==='buy')buys++;if(a==='sell')sells++;
  const net=(buys-sells)/99;const delta=net*2.5+mwGauss()*0.4;
  price=Math.max(1,price+delta);mom=delta/2.5;
  if(a==='buy'&&pos<=0){pos=1;avg=price;}
  if(a==='sell'&&pos>=0){pos=-1;avg=price;}
  myPnl=pos*(price-avg);
  pr.innerHTML='Цена: <b>'+price.toFixed(1)+'</b> · раунд '+round+' · покупок '+buys+' / продаж '+sells;
  log.innerHTML='<div>Раунд '+round+': ты «'+a+'» → нетто-поток '+(net>=0?'+':'')+net.toFixed(2)+' → цена '+(delta>=0?'+':'')+delta.toFixed(2)+'</div>'
   +'<div>Твой открытый PnL при позиции '+(pos>0?'лонг':(pos<0?'шорт':'нет'))+': <b style="color:'+(myPnl>=0?'var(--ok)':'var(--bad)')+'">'+myPnl.toFixed(1)+'</b>. Толпа двигает цену — координация решает, кто выйдет в плюс.</div>';});});
};
