/* М28: распределения */
MATH_WIDGETS['widget_m_raspredelenie_rezultatov']=function(box){
 box.innerHTML='<div style="background:rgba(34,197,94,.05);border:1.5px solid var(--ok);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--ok);text-transform:uppercase;margin-bottom:8px">⛰️ Форма распределения результатов</div>'
 +'<button class="btn sm" data-s="calm">🛡 Спокойная</button> <button class="btn sm ghost" data-s="risky">🔥 Рисковая</button>'
 +' <button class="btn sm ghost" data-s="lotto">🎰 Редкие большие</button><div id="m28_out" style="margin-top:8px"></div></div>';
 function gen(s){const a=[];let i;
  if(s==='calm'){for(i=0;i<500;i++)a.push(0.2+0.5*mwGauss());}
  else if(s==='risky'){for(i=0;i<500;i++)a.push(0.2+3*mwGauss());}
  else{for(i=0;i<500;i++)a.push(Math.random()<0.96?-0.5:15);}
  return a;}
 function show(s){const a=gen(s);
  const bins=new Array(20).fill(0);const mn=-6,mx=16;
  a.forEach(function(x){let b=Math.floor((x-mn)/(mx-mn)*bins.length);if(b<0)b=0;if(b>=bins.length)b=bins.length-1;bins[b]++;});
  const mean=a.reduce(function(p,c){return p+c;},0)/a.length;
  const worst=Math.min.apply(null,a);
  document.getElementById('m28_out').innerHTML=mwBarsHtml(bins,s==='lotto'?'#ef4444':null)
   +'<div style="font-size:12.5px;color:var(--txt)">Среднее ≈ <b>'+mean.toFixed(2)+'</b> · худший результат: <b style="color:var(--bad)">'+worst.toFixed(1)+'</b> · σ = '+ (s==='calm'?'~0.5':(s==='risky'?'~3':'смешанная')) +'</div>';}
 box.querySelectorAll('button[data-s]').forEach(function(b){b.addEventListener('click',function(){show(this.dataset.s);});});
 show('calm');
};
/* М29: хвосты */
MATH_WIDGETS['widget_m_asimmetriya_i_hvosty_zachem']=function(box){
 box.innerHTML='<div style="background:rgba(239,68,68,.05);border:1.5px solid var(--bad);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--bad);text-transform:uppercase;margin-bottom:8px">🦈 Одинаковое среднее — кто опаснее?</div>'
 +'<button class="btn sm" id="m29run">🎲 500 сделок каждой</button>'
 +'<div style="margin-top:8px;font-size:12.5px;color:var(--txt)">A: обычно ±10 ₽ вокруг +1 ₽<br>B: обычно +5 ₽, но изредка −79 ₽</div>'
 +'<label style="display:block;font-size:12.5px;color:var(--txt);margin-top:6px"><input type="radio" name="m29" value="a" checked> Опаснее A</label>'
 +'<label style="display:block;font-size:12.5px;color:var(--txt)"><input type="radio" name="m29" value="b"> Опаснее B</label>'
 +'<button class="btn sm ghost" style="margin-top:6px" id="m29ans">Ответить</button>'
 +'<div id="m29_out" style="margin-top:8px;font-size:12.5px;color:var(--txt)"></div></div>';
 box.querySelector('#m29run').addEventListener('click',function(){
  let a=[],b=[],i;for(i=0;i<500;i++){a.push(1+10*mwGauss());b.push(Math.random()<0.96?5:-79);}
  const ma=a.reduce(function(s,x){return s+x;},0)/500,mb=b.reduce(function(s,x){return s+x;},0)/500;
  const bTails=b.filter(function(x){return x<-50;}).length;
  this._d={ma:ma,mb:mb,bMin:Math.min.apply(null,b),tails:bTails};
  document.getElementById('m29_out').innerHTML='Симуляция готова: средние A='+ma.toFixed(2)+' ₽, B='+mb.toFixed(2)+' ₽. Теперь ответь: какая стратегия опаснее для капитала?';});
 box.querySelector('#m29ans').addEventListener('click',function(){
  const d=this._d||(box.querySelector('#m29run')||{})._d;
  const v=(box.querySelector('input[name=m29]:checked')||{value:'a'}).value;
  const out=document.getElementById('m29_out');
  if(!this._d){out.innerHTML='Сначала запусти симуляцию.';return;}
  if(v==='b')out.innerHTML='<span style="color:var(--ok)">✅ Верно! Хвостовые события B ('+this._d.tails+' раз по −79 ₽, минимум '+this._d.bMin.toFixed(0)+' ₽ за 500 сделок) могут уничтожить капитал при «хорошем» среднем.</span>';
  else out.innerHTML='<span style="color:var(--bad)">Неверно. У A разброс есть, но катастрофы нет. B же изредка платит −79 ₽ — это и есть хвостовой риск.</span>';});
};
/* М30: стандартная ошибка */
MATH_WIDGETS['widget_m_standartnaya_oshibka_pochemu_ocenki']=function(box){
 box.innerHTML='<div style="background:rgba(6,182,212,.05);border:1.5px solid var(--acc2);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--acc2);text-transform:uppercase;margin-bottom:8px">📏 SE = σ/√n</div>'
 +'<button class="btn sm" id="m30run">📊 Прогнать 200 выборок для каждого n</button>'
 +'<div id="m30_out" style="margin-top:10px;font-size:12.5px;color:var(--txt)"></div></div>';
 box.querySelector('#m30run').addEventListener('click',function(){
  const sizes=[10,50,100,500,1000];let rows='';
  sizes.forEach(function(n){const means=[];
   for(let r=0;r<200;r++){let s=0;for(let i=0;i<n;i++)s+=20*mwGauss();means.push(s/n);}
   const m=means.reduce(function(a,b){return a+b;},0)/200;
   const se=Math.sqrt(means.reduce(function(a,b){return a+(b-m)*(b-m);},0)/200);
   rows+='<tr><td>'+n+'</td><td>'+se.toFixed(2)+'</td><td>'+(se*Math.sqrt(n)).toFixed(1)+' ≈ σ=20 ✓</td></tr>';});
  document.getElementById('m30_out').innerHTML='<table class="order-book-table" style="width:100%"><tr><th>n</th><th>SE (разброс оценок)</th><th>SE·√n</th></tr>'+rows+'</table><div style="color:var(--mut);margin-top:4px">Больше выборка — уже разброс оценок, но он никогда не ноль.</div>';});
};
/* М31: доверительный интервал */
MATH_WIDGETS['widget_m_doveritelnyy_interval_bez_strashnoy']=function(box){
 box.innerHTML='<div style="background:rgba(124,58,237,.05);border:1.5px solid var(--acc1);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--acc1);text-transform:uppercase;margin-bottom:8px">🎛️ 95% ДИ из 50 выборок (истина = 50)</div>'
 +'<button class="btn sm" id="m31run">🎲 Построить интервалы</button>'
 +'<div id="m31_box" style="position:relative;height:220px;background:#040714;border-radius:8px;margin-top:10px"><div style="position:absolute;left:50%;top:0;bottom:0;width:2px;background:var(--ok)"></div></div>'
 +'<div id="m31_out" style="margin-top:8px;font-size:12.5px;color:var(--txt)"></div></div>';
 box.querySelector('#m31run').addEventListener('click',function(){
  const host=document.getElementById('m31_box');
  host.querySelectorAll('.m31row').forEach(function(r){r.remove();});
  let cov=0;const H=220,n=50;
  for(let i=0;i<50;i++){
   let s=0;for(let j=0;j<n;j++)s+=50+12*mwGauss();
   const m=s/n,se=12/Math.sqrt(n),lo=m-1.96*se,hi=m+1.96*se;
   const ok=lo<=50&&hi>=50;if(ok)cov++;
   const d=document.createElement('div');d.className='m31row';
   d.style.cssText='position:absolute;height:3px;border-radius:2px;background:'+(ok?'rgba(6,182,212,.7)':'#ef4444')+';left:'+((lo-30)/40*100)+'%;width:'+((hi-lo)/40*100)+'%;top:'+(i*4+4)+'px';
   host.appendChild(d);
  }
  document.getElementById('m31_out').innerHTML='Накрыли истину: <b>'+cov+'</b> из 50 ('+(cov*2)+'%). Ожидание ≈ 95%. Красные — «промахи» выборки.';});
};
