MATH_WIDGETS['widget_m_gipoteza_kazhetsya_zdes_est']=function(box){
 const opts={c:['после дня с падением >3%','при объёме выше среднего в 2 раза','в первый час после открытия'],g:['BTC','альты топ-10','мемкоины'],r:['следующий бар зелёный','диапазон дня выше медианы']};
 box.innerHTML='<div style="background:rgba(34,197,94,.05);border:1.5px solid var(--ok);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--ok);text-transform:uppercase;margin-bottom:8px">🔬 Собери проверяемую гипотезу</div>'
 +'<select id="m32c" style="width:100%;padding:5px">'+opts.c.map(function(o){return '<option>'+o+'</option>';}).join('')+'</select>'
 +'<select id="m32g" style="width:100%;padding:5px;margin-top:6px">'+opts.g.map(function(o){return '<option>'+o+'</option>';}).join('')+'</select>'
 +'<select id="m32r" style="width:100%;padding:5px;margin-top:6px">'+opts.r.map(function(o){return '<option>'+o+'</option>';}).join('')+'</select>'
 +'<button class="btn sm" style="margin-top:8px" id="m32go">🧪 Сформулировать</button>'
 +'<div id="m32_out" style="margin-top:10px;font-size:12.5px;color:var(--txt)"></div></div>';
 box.querySelector('#m32go').addEventListener('click',function(){
  const c=document.getElementById('m32c').value,g=document.getElementById('m32g').value,r=document.getElementById('m32r').value;
  document.getElementById('m32_out').innerHTML='<b>H0 (нулевая):</b> вероятность «'+r+'» у '+g+' НЕ отличается от обычной, даже '+c+'.<br><b>H1:</b> отличается.<br><span style="color:var(--mut)">Гипотеза проверяема, если условие, группа и результат измеримы на данных — иначе это не гипотеза, а мнение.</span>';});
};
/* М34: p-value */
function mwErf(x){var s=x<0?-1:1;x=Math.abs(x);var t=1/(1+0.3275911*x);
 var y=1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-0.284496736)*t+0.254829592)*t*Math.exp(-x*x);
 return s*y;}
MATH_WIDGETS['widget_m_p_value_chto_eto']=function(box){
 box.innerHTML='<div style="background:rgba(239,68,68,.05);border:1.5px solid var(--bad);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--bad);text-transform:uppercase;margin-bottom:8px">🎰 Честная монета (эффекта НЕТ)</div>'
 +'<button class="btn sm" id="m34run">🎲 Эксперимент: 100 бросков</button>'
 +' <button class="btn sm ghost" id="m34x20">×20</button>'
 +'<div id="m34_log" style="margin-top:8px;font-size:12px;color:var(--txt);max-height:150px;overflow-y:auto"></div>'
 +'<div id="m34_sum" style="margin-top:6px;font-size:12.5px;color:var(--acc2)"></div></div>';
 let runs=0,sig=0;
 function one(){let h=0;for(let i=0;i<100;i++)if(Math.random()<.5)h++;
  const z=Math.abs(h-50)/5;const p=2*(1-mwErf(z/Math.SQRT2));
  runs++;if(p<0.05)sig++;
  const row=document.createElement('div');
  row.innerHTML='орлов '+h+' → p = <b style="color:'+(p<0.05?'var(--bad)':'var(--mut)')+'">'+p.toFixed(3)+'</b>'+(p<0.05?' ← «ложная тревога»':'');
  const lg=document.getElementById('m34_log');lg.insertBefore(row,lg.firstChild);
  while(lg.children.length>25)lg.removeChild(lg.lastChild);
  document.getElementById('m34_sum').innerHTML='Экспериментов: '+runs+' · p&lt;0.05 случайно: <b>'+sig+'</b> ('+(100*sig/runs).toFixed(1)+'%) — ожидание ~5%. Маленький p случается и без эффекта!';}
 box.querySelector('#m34run').addEventListener('click',one);
 box.querySelector('#m34x20').addEventListener('click',function(){for(let i=0;i<20;i++)one();});
};
/* М36: множественные проверки */
MATH_WIDGETS['widget_m_mnozhestvennye_proverki_esli_dolgo']=function(box){
 box.innerHTML='<div style="background:rgba(239,68,68,.05);border:1.5px solid var(--bad);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--bad);text-transform:uppercase;margin-bottom:8px">🔎 Сколько «открытий» найдётся в шуме?</div>'
 +'<button class="btn sm" data-n="1">1 гипотеза</button> <button class="btn sm ghost" data-n="100">100</button>'
 +' <button class="btn sm ghost" data-n="10000">10 000</button>'
 +'<div id="m36_out" style="margin-top:10px;font-size:13px;color:var(--txt)">Данные случайны — эффекта нет ни в одном тесте.</div></div>';
 box.querySelectorAll('button[data-n]').forEach(function(b){b.addEventListener('click',function(){
  const N=+this.dataset.n;let sig=0;
  for(let i=0;i<N;i++){
   let s1=0,s2=0;for(let j=0;j<30;j++){s1+=mwGauss();s2+=mwGauss();}
   const m1=s1/30,m2=s2/30,v1=1+mwGauss()*0.2,v2=1+mwGauss()*0.2;
   const t=Math.abs(m1-m2)/Math.sqrt((v1+v2)/30);
   if(t>2.0)sig++;
  }
  document.getElementById('m36_out').innerHTML='Проверено гипотез на СЛУЧАЙНЫХ данных: <b>'+N+'</b><br>'
   +'«Красивых» результатов (p&lt;0.05): <b style="color:var(--bad)">'+sig+'</b>'+(sig?' ← все они ЛОЖНЫЕ открытия':'')
   +'<br>Ожидание при α=5%: '+Math.round(N*0.05)+'.<span style="color:var(--mut)"> Чем больше проверяешь, тем больше найдёшь «закономерностей» в шуме.</span>';});});
};
/* М37: корреляция — облако */
MATH_WIDGETS['widget_m_korrelyaciya_dva_ryada_dvizhutsya']=function(box){
 box.innerHTML='<div style="background:rgba(124,58,237,.05);border:1.5px solid var(--acc1);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--acc1);text-transform:uppercase;margin-bottom:8px">🌌 Облако точек при ρ = <span id="m37v">0</span></div>'
 +'<input type="range" id="m37s" min="-100" max="100" value="0" style="width:100%">'
 +'<div id="m37box" style="position:relative;height:180px;background:#040714;border-radius:8px;margin-top:8px"></div>'
 +'<div id="m37r" style="margin-top:6px;font-size:12.5px;color:var(--txt)"></div></div>';
 const draw=function(){const rho=+box.querySelector('#m37s').value/100;box.querySelector('#m37v').textContent=rho.toFixed(2);
  const host=document.getElementById('m37box');host.innerHTML='';
  let sx=0,sy=0,sxy=0,sx2=0,sy2=0,n=70,pts=[];
  for(let i=0;i<n;i++){const x=mwGauss();const y=rho*x+Math.sqrt(Math.max(0,1-rho*rho))*mwGauss();
   pts.push([x,y]);sx+=x;sy+=y;sxy+=x*y;sx2+=x*x;sy2+=y*y;}
  const r=(n*sxy-sx*sy)/Math.sqrt((n*sx2-sx*sx)*(n*sy2-sy*sy));
  pts.forEach(function(p){const d=document.createElement('div');
   d.style.cssText='position:absolute;width:5px;height:5px;border-radius:50%;background:#06b6d4;left:'+(50+p[0]*38)+'%;top:'+(90-p[1]*38)+'%';
   host.appendChild(d);});
  box.querySelector('#m37r').innerHTML='Выборочная корреляция r ≈ <b>'+r.toFixed(2)+'</b>'+(Math.abs(rho)>0?'':' (независимые ряды)');};
 box.querySelector('#m37s').addEventListener('input',draw);draw();
};
/* М38: общая причина */
