 +'<div id="m38w" style="display:none;margin-top:6px;font-size:12.5px;color:var(--mut)"></div></div>';
 const upd=function(){const s=+box.querySelector('#m38s').value/100;
  box.querySelector('#m38r').innerHTML='Наблюдаемая корреляция X↔Y ≈ <b>'+(s).toFixed(2)+'</b>, хотя X не вызывает Y и Y не вызывает X.';};
