/* М39 v2: регрессия (перезапись) */
MATH_WIDGETS['widget_m_regressiya_na_palcah']=function(box){
 var W=380,H=180,X0=-12,X1=12,YMIN=-90,YMAX=90;
 function px(x){return 45+(x-X0)/(X1-X0)*(W-70);} function py(y){return H-16-((y-YMIN)/(YMAX-YMIN))*(H-28);}
 box.innerHTML='<div style="background:rgba(6,182,212,.05);border:1.5px solid var(--acc2);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--acc2);text-transform:uppercase;margin-bottom:8px">🧭 y = 2x + шум · линия по данным vs истина</div>'
 +'<label style="font-size:12.5px;color:var(--txt)">Шум σ: <b id="m39nv">20</b><input type="range" id="m39s" min="0" max="80" value="20" step="5" style="width:100%"></label>'
 +'<div id="m39box" style="margin-top:8px"></div><div id="m39_out" style="margin-top:6px;font-size:12.5px;color:var(--txt)"></div></div>';
 function draw(){
  var noise=+box.querySelector('#m39s').value;document.getElementById('m39nv').textContent=noise;
  var sx=0,sy=0,sxy=0,sxx=0,n=50,pts=[],i;
  for(i=0;i<n;i++){var x=X0+(X1-X0)*Math.random();var y=2*x+mwGauss()*noise;pts.push([x,y]);sx+=x;sy+=y;sxy+=x*y;sxx+=x*x;}
  var b=(n*sxy-sx*sy)/(n*sxx-sx*sx),a=(sy-b*sx)/n;
  var circles='';pts.forEach(function(p){circles+='<circle cx="'+px(p[0]).toFixed(1)+'" cy="'+py(p[1]).toFixed(1)+'" r="3.5" fill="#06b6d4" opacity="0.85"/>';});
  var trueLine='<line x1="'+px(X0).toFixed(1)+'" y1="'+py(2*X0).toFixed(1)+'" x2="'+px(X1).toFixed(1)+'" y2="'+py(2*X1).toFixed(1)+'" stroke="#22c55e" stroke-dasharray="5 4" stroke-width="2"/>';
  var fitLine='<line x1="'+px(X0).toFixed(1)+'" y1="'+py(a+b*X0).toFixed(1)+'" x2="'+px(X1).toFixed(1)+'" y2="'+py(a+b*X1).toFixed(1)+'" stroke="#f59e0b" stroke-width="2.5"/>';
  document.getElementById('m39box').innerHTML='<svg width="100%" viewBox="0 0 '+W+' '+H+'" style="background:#040714;border-radius:8px">'+circles+trueLine+fitLine+'</svg>';
  document.getElementById('m39_out').innerHTML='Оценка по данным: <b style="color:#f59e0b">y = '+a.toFixed(1)+' + '+b.toFixed(2)+'·x</b> · истина: <span style="color:#22c55e">y = 2·x</span>. Больше шум — сильнее оценка гуляет от истины.';}
 box.querySelector('#m39s').addEventListener('input',draw);draw();
};
/* М40: прогноз, факт и остатки */
MATH_WIDGETS['widget_m_oshibka_prognoza_i_ostatki']=function(box){
 var preds=[100,102,99,105,101,98];
 box.innerHTML='<div style="background:rgba(124,58,237,.05);border:1.5px solid var(--acc1);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--acc1);text-transform:uppercase;margin-bottom:8px">📉 Остатки = факт − прогноз</div>'
 +'<button class="btn sm" id="m40run">🎲 Сгенерировать факты</button> <button class="btn sm ghost" id="m40hist">Гистограмма остатков (200)</button>'
 +'<div id="m40_tbl" style="margin-top:8px"></div><div id="m40_out" style="margin-top:8px;font-size:12.5px;color:var(--txt)"></div></div>';
 box.querySelector('#m40run').addEventListener('click',function(){
  var rows='<table class="order-book-table" style="width:100%;font-size:12.5px"><tr><th>#</th><th>Прогноз</th><th>Факт</th><th>Остаток</th></tr>';var res=[];
  preds.forEach(function(p,i){var a=p+mwGauss()*6;var r=a-p;res.push(r);
   rows+='<tr><td>'+(i+1)+'</td><td>'+p.toFixed(0)+'</td><td>'+a.toFixed(1)+'</td><td style="color:'+(r>=0?'var(--ok)':'var(--bad)')+'">'+(r>=0?'+':'')+r.toFixed(1)+'</td></tr>';});
  rows+='</table>';
  document.getElementById('m40_tbl').innerHTML=rows;
  document.getElementById('m40_out').innerHTML='Остатки — это ошибки модели. Если их среднее ≈ 0 и нет структуры, модель честная; структура в остатках = упущенная закономерность.';});
 box.querySelector('#m40hist').addEventListener('click',function(){
  var bins=new Array(15).fill(0);
  for(var i=0;i<200;i++){var r=mwGauss()*6;var b=Math.floor((r+18)/36*15);if(b<0)b=0;if(b>14)b=14;bins[b]++;}
  document.getElementById('m40_out').innerHTML=mwBarsHtml(bins)+'<div style="font-size:11.5px;color:var(--mut)">Распределение ошибок примерно симметрично вокруг нуля.</div>';});
};
/* М41: переобучение */
MATH_WIDGETS['widget_m_pereobuchenie_na_palcah']=function(box){
 box.innerHTML='<div style="background:rgba(239,68,68,.05);border:1.5px solid var(--bad);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--bad);text-transform:uppercase;margin-bottom:8px">🎢 Сложность модели: train ↑ vs test ↓</div>'
 +'<label style="font-size:12.5px;color:var(--txt)">Параметров: <b id="m41v">3</b><input type="range" id="m41s" min="1" max="20" value="3" style="width:100%"></label>'
 +'<div id="m41svg" style="margin-top:6px"></div><div id="m41_out" style="margin-top:6px;font-size:12.5px;color:var(--txt)"></div></div>';
 function qTrain(p){return 55+16*Math.log(p);} function qTest(p){return 52+13*Math.log(p)-Math.max(0,p-4)*2.2;}
 function draw(){var p=+box.querySelector('#m41s').value;document.getElementById('m41v').textContent=p;
  var xs=[],i;for(i=1;i<=20;i++)xs.push(i);
  var tr={pts:xs.map(function(x){return qTrain(x);}),color:'#22c55e'},te={pts:xs.map(function(x){return qTest(x);}),color:'#ef4444'};
  document.getElementById('m41svg').innerHTML=mwSvgLines([tr,te],420,160,xs.length)
   +'<div style="display:flex;justify-content:space-between;font-size:10.5px;color:var(--mut);padding:0 45px 0 50px"><span>1</span><span>5</span><span>10</span><span>20</span></div>';
  var t=qTrain(p),s=qTest(p);
  document.getElementById('m41_out').innerHTML='При '+p+' параметрах: train = '+t.toFixed(0)+'%, новые данные = <b style="color:'+((t-s)>25?'var(--bad)':'var(--warn)')+'">'+s.toFixed(0)+'%</b> · разрыв '+(t-s).toFixed(0)+' п.п.'+(p>7?' ← классическое переобучение!':'');}
 box.querySelector('#m41s').addEventListener('input',draw);draw();
};
/* М42: Train/Validation/Test */
MATH_WIDGETS['widget_m_obuchayuschaya_i_testovaya_vyborka']=function(box){
 box.innerHTML='<div style="background:rgba(6,182,212,.05);border:1.5px solid var(--acc2);border-radius:12px;padding:14px;margin:12px 0">'
 +'<div style="font-size:12px;font-weight:800;color:var(--acc2);text-transform:uppercase;margin-bottom:8px">✂️ Границы выборок (1000 дней)</div>'
 +'<label style="display:block;font-size:12.5px;color:var(--txt)">Train → до <b id="m42t1v">60%</b><input type="range" id="m42t1" min="20" max="80" value="60" style="width:100%"></label>'
 +'<label style="display:block;font-size:12.5px;color:var(--txt)">Validation → до <b id="m42t2v">75%</b><input type="range" id="m42t2" min="30" max="95" value="75" style="width:100%"></label>'
 +'<button class="btn sm" id="m42go" style="margin-top:6px">🚀 Обучить и проверить</button>'
 +'<div id="m42_bar" style="display:flex;height:22px;border-radius:6px;overflow:hidden;margin-top:8px"></div>'
 +'<div id="m42_out" style="margin-top:8px;font-size:12.5px;color:var(--txt)"></div></div>';
 function render(){var t1=+box.querySelector('#m42t1').value,t2=+box.querySelector('#m42t2').value;
  if(t2<t1+10){t2=t1+10;box.querySelector('#m42t2').value=t2;}
  document.getElementById('m42t1v').textContent=t1+'%';document.getElementById('m42t2v').textContent=t2+'%';
  document.getElementById('m42_bar').innerHTML='<div style="width:'+t1+'%;background:#22c55e"></div><div style="width:'+(t2-t1)+'%;background:#f59e0b"></div><div style="flex:1;background:#ef4444"></div>';}
 box.querySelector('#m42t1').addEventListener('input',render);box.querySelector('#m42t2').addEventListener('input',render);
 box.querySelector('#m42go').addEventListener('click',function(){
  var t1=+box.querySelector('#m42t1').value,t2=+box.querySelector('#m42t2').value;
  var train=Math.round(10*t1),val=Math.round(t2-t1),test=100-t2;
  var leak=Math.max(0,(t1-65))*1.5;var smallTest=test<15?4:0;
  var tr=(86+Math.random()*3).toFixed(0),va=(85-leak-Math.random()*2).toFixed(0),te=(84-leak-smallTest-Math.random()*3).toFixed(0);
  var warn='';
  if(leak>0)warn+='<br>⚠️ Слишком большой train относительно истории — модель «зазубрила» старые режимы.';
  if(smallTest)warn+='<br>⚠️ Тестовая часть <15% — результат нестабилен.';
  document.getElementById('m42_out').innerHTML='Train '+train+' дн: '+tr+'% · Validation '+val+' дн: '+va+'% · Test '+test+' дн: <b>'+te+'%</b>'+warn+
   '<br><span style="color:var(--mut)">Порядок во времени не перемешивают: будущее никогда не участвует в обучении.</span>';});
 render();
};

/* ===== FINAL PATCH GLUE: adaptive / beginner / SRS / persistence ===== */
const MATH_ADAPTIVE_TOPICS=[
 {id:'math_probability',title:'Вероятность и серии',nums:['М1','М2','М3','М4','М10']},
 {id:'math_expectation',title:'Среднее и матожидание',nums:['М5','М6','М7','М11','М12','М47']},
 {id:'math_statistics',title:'Выборка и оценки',nums:['М23','М24','М25','М26','М30','М31','М43','М45','М48']},
 {id:'math_distribution',title:'Распределение и хвосты',nums:['М8','М9','М28','М29','М44']},
 {id:'math_hypothesis',title:'Гипотезы и p-value',nums:['М32','М33','М34','М35','М36']},
 {id:'math_correlation',title:'Корреляция и причинность',nums:['М37','М38']},
 {id:'math_regression',title:'Регрессия и остатки',nums:['М39','М40','М46']},
 {id:'math_overfitting',title:'Переобучение и Train/Test',nums:['М41','М42']},
 {id:'math_game_theory',title:'Теория игр рынка',nums:['М13','М14','М15','М16','М17','М18','М19','М20','М21','М22']}
];
function mathTopicOf(num){
 for(const t of MATH_ADAPTIVE_TOPICS){if(t.nums.indexOf(num)>=0)return t.id;}
 return 'math_statistics';
}
