/* =========================================================================
   ПОТОК B — ДОСТРОЙКА МЕТОДИКИ
   B1. Смешанная тренировка дня (системный интерливинг)
   ========================================================================= */
var interleavingStats = load('cn_interleaving_stats', { sessions: 0, best: 0 });

const INTERLEAVING_CAT_LABELS = {
  blockchain: '⛓️ Блокчейн', exchange: '🏦 Биржа', charts: '📊 Графики',
  candles: '🕯️ Свечи', trading: '💹 Трейдинг', risk: '🛡️ Риск', probability: '🎲 Вероятность',
  phase1: '🔬 Фаза 1', phase2: '📈 Фаза 2', phase3: '🏗️ Фаза 3', phase4: '⚖️ Фаза 4', phase5: '🚀 Фаза 5', phase6: '🎓 Бонус-уроки',
  psy_block: '🧠 Психология оператора', freqtrade_academy: '🤖 Академия Freqtrade'
};
function interleavingCatLabel(cat){
  if(INTERLEAVING_CAT_LABELS[cat]) return INTERLEAVING_CAT_LABELS[cat];
  if(typeof MATH_ADAPTIVE_TOPICS !== 'undefined'){ const mt = MATH_ADAPTIVE_TOPICS.find(t => t.id === cat); if(mt) return '∑ ' + mt.title; }
  if(cat && cat.indexOf('glossary_') === 0){
    const c = cat.slice(9);
    return (typeof CATS !== 'undefined' && CATS[c]) ? ('📖 ' + CATS[c][0]) : cat;
  }
  return cat || 'Общее';
}

function buildInterleavingPools(){
  const pools = {};
  // 1. Вопросы из пройденных уроков (реальный прогресс пользователя)
  LESSONS.forEach(l => {
    if(!l || !l.quiz || lessonsDone[l.id] !== 1) return;
    const cat = LESSON_BEGINNER_CAT[l.id] || lessonTopicOf(l) || ('phase' + Math.min(l.phase || 0, 5));
    (pools[cat] = pools[cat] || []).push({
      q: l.quiz.q,
      opts: l.quiz.opts,
      a: l.quiz.a !== undefined ? l.quiz.a : (l.quiz.correctOpt !== undefined ? l.quiz.correctOpt : 0),
      explain: l.quiz.explain || '',
      _cat: cat,
      _src: 'Урок ' + (l.num || l.id),
      _lessonId: l.id
    });
  });
  // 2. Добор из глоссария — чтобы тем было ≥3 даже у новичка
  const glossCats = {};
  TERMS.forEach(t => { if(t) (glossCats[t.c] = glossCats[t.c] || []).push(t); });
  Object.keys(glossCats).forEach(c => {
    const terms = glossCats[c];
    if(terms.length < 4) return;
    pools['glossary_' + c] = terms.map(t => {
      const others = terms.filter(x => x.t !== t.t).sort(() => 0.5 - Math.random()).slice(0, 3);
      const allOpts = [t.t, ...others.map(o => o.t)].sort(() => 0.5 - Math.random());
      return {
        q: `💡 Определение: «${t.d}». О каком понятии речь?`,
        opts: allOpts,
        a: allOpts.indexOf(t.t),
        explain: `Верный ответ: <b>${t.t}</b>. ${t.d}`,
        _cat: 'glossary_' + c,
        _src: 'Глоссарий'
      };
    });
  });
  return pools;
}

function startInterleavingSession(){
  const pools = buildInterleavingPools();
  let cats = Object.keys(pools).filter(c => pools[c].length > 0).sort(() => 0.5 - Math.random());
  // Приоритет категориям из пройденных уроков, затем глоссарий — всего 3–4 темы
  cats.sort((a, b) => (a.indexOf('glossary_') === 0 ? 1 : 0) - (b.indexOf('glossary_') === 0 ? 1 : 0));
  cats = cats.slice(0, 4);
  if(cats.length < 3){ cats = Object.keys(pools).filter(c => pools[c].length > 0).slice(0, 4); }
  if(!cats.length){
    showToast && showToast('Сначала пройди хотя бы пару уроков — тогда соберём смешанную сессию.', '🔀');
    return;
  }
  cats.forEach(c => pools[c].sort(() => 0.5 - Math.random()));

  // Круговое чередование A-B-C-A-B-C: одна и та же тема никогда не идёт дважды подряд
  const qs = [];
  /* v12 P2-7: спейсинг ошибок квизов — возвращаем ошибки 1–30 дней в начало сессии */
  try{
    const ml = JSON.parse(localStorage.getItem('cn_quiz_mistakes') || '[]');
    const now = Date.now(); let cleaned = false;
    for(let i2 = ml.length - 1; i2 >= 0; i2--){
      if((now - ml[i2].ts) / 86400000 > 30){ ml.splice(i2, 1); cleaned = true; }
    }
    if(cleaned) localStorage.setItem('cn_quiz_mistakes', JSON.stringify(ml));
    const dueIds = [];
    for(let i3 = ml.length - 1; i3 >= 0 && dueIds.length < 3; i3--){
      const age = (now - ml[i3].ts) / 86400000;
      if(age < 1) continue;
      const has = Object.keys(pools).some(c => pools[c].some(q => q._lessonId === ml[i3].lessonId));
      if(has) dueIds.push(ml[i3].lessonId);
    }
    dueIds.forEach(lid => {
      Object.keys(pools).forEach(c => {
        const qi = pools[c].findIndex(q => q._lessonId === lid);
        if(qi >= 0){ const q = pools[c].splice(qi, 1)[0]; q._src = '🔁 Повтор ошибки · ' + (q._src || ''); qs.push(q); }
      });
    });
  }catch(e){}
  let i = 0, guard = 0;
  while(qs.length < 12 && guard < 300){
    const c = cats[i % cats.length];
    if(pools[c].length) qs.push(pools[c].pop());
    i++; guard++;
    if(cats.every(c => pools[c].length === 0)) break;
  }

  quiz.qs = qs;
  quiz.total = qs.length;
  quiz.cur = 0;
  quiz.score = 0;
  quiz.results = [];
  quiz.isAdaptive = false;
  quiz.targetTopic = null;
  quiz.mode = 'interleaving';
  quiz.preserveQs = true;

  go('quiz');

  const sb = document.getElementById('quiz_session_banner');
  if(sb){
    sb.innerHTML = `
      <div style="background:linear-gradient(135deg,rgba(124,58,237,.18),rgba(6,182,212,.18)); border:1.5px solid var(--acc2); border-radius:12px; padding:12px 16px; margin-bottom:14px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px">
        <div>
          <span style="font-size:11px; font-weight:800; color:var(--acc2); text-transform:uppercase">🔀 СМЕШАННАЯ СЕССИЯ · ИНТЕРЛИВИНГ</span>
          <div style="font-size:12.5px; color:var(--txt); margin-top:3px">Темы чередуются специально: ${cats.slice(0, 3).map(interleavingCatLabel).join(' → ')}${cats.length > 3 ? ' + ещё ' + (cats.length - 3) : ''}</div>
        </div>
        <button class="btn sm ghost" onclick="setQuizMode('terms', document.getElementById('quiz_mode_terms'))">✕ Завершить</button>
      </div>`;
  }
  document.querySelectorAll('#quiz .controls .chip').forEach(c => c.classList.remove('active'));
  const ilChip = document.getElementById('quiz_mode_interleave');
  if(ilChip) ilChip.classList.add('active');
  renderQuizQuestion();
}

function finishInterleavingSession(box){
  const pct = Math.round((quiz.score / quiz.total) * 100);
  interleavingStats.sessions++;
  interleavingStats.best = Math.max(interleavingStats.best, pct);
  localStorage.setItem('cn_interleaving_stats', JSON.stringify(interleavingStats));

  // Ежедневный квест q4
  if(typeof dailyQuestsDone !== 'undefined' && !dailyQuestsDone.q4){
    dailyQuestsDone.q4 = true;
    localStorage.setItem('cn_daily_quests', JSON.stringify(dailyQuestsDone));
    if(typeof addFundCapital === 'function') addFundCapital(18000, 70, 'Смешанная интерливинг-сессия');
  }

  // Разбор по категориям
  const byCat = {};
  (quiz.results || []).forEach(r => {
    if(!r.cat) return;
    byCat[r.cat] = byCat[r.cat] || { ok: 0, total: 0 };
    byCat[r.cat].total++;
    if(r.ok) byCat[r.cat].ok++;
  });
  const catRows = Object.keys(byCat).map(c => {
    const s = byCat[c];
    const p = Math.round((s.ok / s.total) * 100);
    const col = p >= 80 ? 'var(--ok)' : (p >= 50 ? 'var(--warn)' : 'var(--bad)');
    return `<div style="display:flex; justify-content:space-between; align-items:center; background:#040714; border:1px solid var(--line); border-radius:8px; padding:8px 12px; font-size:13px">
      <span style="color:var(--txt)">${interleavingCatLabel(c)}</span>
      <b style="color:${col}">${s.ok}/${s.total} · ${p}%</b>
    </div>`;
  }).join('');

  const verdict = pct >= 80
    ? 'Отлично! Чередование тем тебе по плечу — мозг уверенно переключается между концептами.'
    : 'Это нормально: смешанные сессии ощущаются труднее блочных, но именно поэтому они сильнее закрепляют материал (эффект «желательной трудности»). Слабые категории выше — повтори их уроки.';

  box.innerHTML = `
    <div style="text-align:center; padding:24px">
      <div style="font-size:44px; margin-bottom:10px">${pct >= 80 ? '🎉' : '🔀'}</div>
      <h2>Интерливинг-сессия завершена!</h2>
      <div style="font-size:24px; font-weight:800; color:${pct >= 80 ? 'var(--ok)' : 'var(--warn)'}; margin:10px 0">${quiz.score} из ${quiz.total} (${pct}%)</div>
      <div style="font-size:13px; color:var(--mut); margin-bottom:16px">Всего смешанных сессий: <b style="color:var(--txt)">${interleavingStats.sessions}</b> · Лучший результат: <b style="color:var(--txt)">${interleavingStats.best}%</b></div>
      <div style="max-width:420px; margin:0 auto 16px; display:flex; flex-direction:column; gap:6px; text-align:left">${catRows}</div>
      <div style="max-width:520px; margin:0 auto 18px; font-size:13px; color:var(--txt); line-height:1.55; background:rgba(124,58,237,.08); border:1px solid var(--acc1); border-radius:10px; padding:12px 16px">${verdict}</div>
      <button class="btn" onclick="startInterleavingSession()">🔄 Ещё одна смешанная сессия</button>
    </div>
  `;
  save();
  updateHeader();
  renderProgressStats();
}

/* =========================================================================
   B2. ПРЕДТЕСТ ПЕРЕД УРОКОМ (pre-test effect)
   Вопросы ДО контента без штрафа к статистике: попытка ответить «вслепую»
   разгоняет последующее кодирование материала.
   ========================================================================= */
var pretestDone = load('cn_pretest_done', {});
var pretestCache = {};

function getPretestQuestions(l){
  if(pretestCache[l.id]) return pretestCache[l.id];
  const qs = [];
  const norm = q => ({
    q: q.q,
    opts: q.opts,
    a: q.a !== undefined ? q.a : (q.correctOpt !== undefined ? q.correctOpt : 0),
    teaser: q.explain || ''
  });
  if(l.quiz) qs.push({ ...norm(l.quiz), src: 'Вопрос этого урока' });
  const cat = (typeof LESSON_BEGINNER_CAT !== 'undefined') ? LESSON_BEGINNER_CAT[l.id] : null;
  const siblings = LESSONS.filter(x => x && x.id !== l.id && x.quiz && (cat ? LESSON_BEGINNER_CAT[x.id] === cat : x.phase === l.phase));
  if(siblings.length){
    const s = siblings[Math.floor(Math.random() * siblings.length)];
    qs.push({ ...norm(s.quiz), src: 'Из соседнего урока: ' + (s.num || s.id) });
  } else if(l.terms && l.terms.length){
    const name = typeof l.terms[0] === 'string' ? l.terms[0] : l.terms[0].ru;
    const idx = findTermIndexByName(name);
    if(idx >= 0){
      const t = TERMS[idx];
      const others = TERMS.filter(x => x.t !== t.t).sort(() => 0.5 - Math.random()).slice(0, 3);
      const allOpts = [t.t, ...others.map(o => o.t)].sort(() => 0.5 - Math.random());
      qs.push({ q: `💡 «${t.d}» — о каком понятии речь?`, opts: allOpts, a: allOpts.indexOf(t.t), teaser: `<b>${t.t}</b>: ${t.d}`, src: 'Глоссарий' });
    }
  }
  pretestCache[l.id] = qs.slice(0, 2);
  return pretestCache[l.id];
}

function renderPretestBlock(l){
  if(typeof pretestDone === 'undefined' || pretestDone[l.id]) return '';
  const qs = getPretestQuestions(l);
  if(!qs.length) return '';
  return `
    <div id="pretest_box_${l.id}" style="background:linear-gradient(135deg,rgba(6,182,212,.12),rgba(124,58,237,.08)); border:1.5px dashed var(--acc2); border-radius:14px; padding:18px 20px; margin-bottom:20px">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; flex-wrap:wrap; gap:8px">
        <span style="font-size:12px; font-weight:800; color:var(--acc2); text-transform:uppercase">🧪 Предтест: разгон памяти (2 вопроса)</span>
        <button class="btn sm ghost" style="font-size:11px" onclick="skipPretest('${l.id}')">Пропустить →</button>
      </div>
      <div style="font-size:12.5px; color:var(--mut); margin-bottom:14px; line-height:1.5">
        Ответь <b style="color:var(--txt)">до</b> изучения материала. Ошибиться — нормально и даже полезно: попытка вспомнить заранее усиливает запоминание (эффект предтестирования). На статистику темы ответы не влияют.
      </div>
      ${qs.map((q, qi) => `
        <div id="pretest_q_${l.id}_${qi}" style="background:#040714; border:1px solid var(--line); border-radius:10px; padding:14px 16px; margin-bottom:12px">
          <div style="font-size:10.5px; color:var(--mut); text-transform:uppercase; font-weight:700; margin-bottom:4px">${q.src || ''}</div>
          <div style="font-size:14px; font-weight:700; color:var(--txt); margin-bottom:10px; line-height:1.45">${q.q}</div>
          <div style="display:flex; flex-direction:column; gap:6px">
            ${q.opts.map((o, oi) => `<button class="ans" style="text-align:left; padding:9px 12px; font-size:13px" onclick="handlePretestAnswer('${l.id}', ${qi}, ${oi})">${o}</button>`).join('')}
          </div>
          <div id="pretest_teaser_${l.id}_${qi}" style="display:none; margin-top:10px; padding:10px 12px; border-radius:8px; font-size:12.5px; background:rgba(6,182,212,.08); border-left:3px solid var(--acc2); color:var(--txt); line-height:1.5"></div>
        </div>
      `).join('')}
      <div id="pretest_finish_${l.id}" style="display:none; text-align:center; margin-top:6px">
        <button class="btn" style="background:var(--ok); color:#040714; font-weight:800" onclick="skipPretest('${l.id}')">🚀 Разогрелся — перейти к уроку</button>
      </div>
    </div>
  `;
}

function handlePretestAnswer(lessonId, qIdx, optIdx){
  const l = LESSONS.find(x => x.id === lessonId);
  if(!l) return;
  const q = getPretestQuestions(l)[qIdx];
  if(!q) return;
  const box = document.getElementById(`pretest_q_${lessonId}_${qIdx}`);
  if(!box) return;
  box.querySelectorAll('.ans').forEach((btn, i) => {
    btn.disabled = true;
    if(i === q.a) btn.classList.add('ok');
    else if(i === optIdx) btn.classList.add('bad');
  });
  const teaser = document.getElementById(`pretest_teaser_${lessonId}_${qIdx}`);
  if(teaser){
    teaser.style.display = 'block';
    teaser.innerHTML = (optIdx === q.a ? '<b>Верно, и это до изучения урока! 🎯</b> ' : '<b>Нормально ошибиться — память уже разогрета.</b> ') + (q.teaser || '');
  }
  // Когда отвечено на все вопросы — показать кнопку перехода к уроку
  const total = getPretestQuestions(l).length;
  let answered = 0;
  for(let i = 0; i < total; i++){
    const b = document.getElementById(`pretest_q_${lessonId}_${i}`);
    if(b && b.querySelector('.ans:disabled')) answered++;
  }
  if(answered >= total){
    const fin = document.getElementById(`pretest_finish_${lessonId}`);
    if(fin) fin.style.display = 'block';
  }
}

function skipPretest(lessonId){
  pretestDone[lessonId] = 1;
  localStorage.setItem('cn_pretest_done', JSON.stringify(pretestDone));
  const l = LESSONS.find(x => x.id === lessonId);
  if(l) renderLessonDetail(l);
}

/* =========================================================================
   B3. МЕТОД ФЕЙНМАНА — ОПЕРАЦИОНАЛИЗАЦИЯ
   Объясни своими словами → сверь с эталоном и чек-листом → самооценка 0–4.
   Самооценка пишется в topicStats; при ≤2 термины урока уходят в SM-2 очередь.
   Текст сохраняется в «портфель объяснений» (вкладка Прогресс).
   ========================================================================= */
var feynmanPortfolio = load('cn_feynman_portfolio', {});

const FEYNMAN_MODEL_ANSWERS_V2 = {
  p0_l1: 'Криптовалюта — это цифровые деньги в открытой общей тетрадке (блокчейне), где каждый перевод проверяется тысячами независимых участников без начальников и банков.',
  p0_l2: 'Адрес — это прозрачный почтовый ящик на улице (номер счета), а приватный ключ — секретный ключ от замка ящика, которым подписывают переводы.',
  p0_l3: 'CEX — биржа с поддержкой и хранением на ее серверах (как банк). DEX — обменник на автомате со смарт-контрактом прямо с личного кошелька.',
  p0_l4: 'Цена покупки (Bid) — максимум от покупателя, цена продажи (Ask) — минимум от продавца. Спред — зазор между ними.',
  p0_l5: 'Свеча — это контейнер, куда упакованы сотни сделок за минуту: первая цена (Open), пик (High), дно (Low) и последняя цена (Close).',
  p0_l6: 'Если закрытие выше открытия — свеча зеленая (рост). Торчащие фитили показывают, куда залетала цена внутри периода.',
  p0_l7: 'Часовая свеча берет цену открытия от 1-й минуты и закрытие от 60-й минуты, а максимум и минимум — за все 60 минут вместе.',
  p0_l8: 'Объём снизу показывает, подтвержден ли рост реальными деньгами или это случайная манипуляция на пустом стакане.',
  p0_l9: 'Плечо — это лупа: оно одинаково увеличивает и прибыль, и убыток. При плече x10 движение цены против тебя на 10% уничтожает залог — это и есть ликвидация.',
  p0_l10: 'Кривая баланса (эквити) должна расти плавно под 45 градусов с минимальными ямами просадок — это главный критерий качества стратегии.'
};

const FEYNMAN_CHECKLISTS = {
  p0_l1: [
    'сказал, что блокчейн — это общая книга записей, копия которой есть у многих участников',
    'упомянул, что нет единого владельца или банка-посредника',
    'сказал, что записи почти невозможно подделать задним числом'
  ],
  p0_l2: [
    'разделил адрес (публичный, можно показывать) и приватный ключ (секретный)',
    'сказал, что ключ подписывает переводы',
    'упомянул, что потеря ключа = потеря доступа к деньгам навсегда'
  ],
  p0_l3: [
    'объяснил, что CEX хранит деньги у себя (как банк)',
    'сказал, что DEX работает через смарт-контракт прямо с твоего кошелька',
    'упомянул компромисс: удобство и поддержка против контроля над ключами'
  ],
  p0_l4: [
    'объяснил Bid (лучшая цена покупателя) и Ask (лучшая цена продавца)',
    'сказал, что спред — это зазор между ними',
    'упомянул, что маркет-ордер «проедает» стакан и платит спред'
  ],
  p0_l5: [
    'перечислил четыре цены свечи: Open, High, Low, Close',
    'сказал, что свеча упаковывает множество сделок за период',
    'объяснил, что тело и фитили показывают разное'
  ],
  p0_l9: [
    'сказал, что плечо — это заёмные деньги, увеличивающие позицию',
    'объяснил, что плечо умножает и прибыль, и убыток одинаково',
    'назвал ликвидацию: принудительное закрытие при нехватке залога',
    'привёл пороги: x10 ликвидируется при −10% против позиции, x25 — при −4%'
  ]
};

function feynmanTopicOf(lessonId){
  const l = LESSONS.find(x => x.id === lessonId);
  if(!l) return 'feynman_general';
  if(l.phase === 7 && typeof mathTopicOf === 'function') return mathTopicOf(l.num);
  if(typeof LESSON_BEGINNER_CAT !== 'undefined' && LESSON_BEGINNER_CAT[lessonId]) return 'beginner_' + LESSON_BEGINNER_CAT[lessonId];
  return 'phase' + (l.phase || 0);
}

function getFeynmanChecklist(lesson){
  if(FEYNMAN_CHECKLISTS[lesson.id]) return FEYNMAN_CHECKLISTS[lesson.id];
  const recap = (lesson.blocks || []).find(b => b.type === 'recap');
  if(recap && recap.points && recap.points.length){
    return recap.points.slice(0, 4).map(p => {
      const short = String(p).replace(/\n/g, ' ').slice(0, 90);
      return `упомянул, что «${short}${String(p).length > 90 ? '…' : ''}»`;
    });
  }
  if(lesson.terms && lesson.terms.length){
    return lesson.terms.slice(0, 3).map(t => `простыми словами раскрыл термин «${typeof t === 'string' ? t : t.ru}»`);
  }
  return ['сформулировал главную мысль урока без сложных терминов', 'привёл бытовой пример или аналогию', 'назвал, зачем это нужно на практике'];
}

// Переопределяем базовый бокс: теперь с эталоном, чек-листом и самооценкой
renderFeynmanBox = function(lesson){
  const modelAns = FEYNMAN_MODEL_ANSWERS_V2[lesson.id] || (function(){
    const concept = (lesson.blocks || []).find(b => b.type === 'concept' && b.level1);
    if(concept) return String(concept.level1).split('\n').filter(x => x.trim()).slice(0, 2).join(' ');
    return 'Суть концепции: своими словами сформулируй 1–2 главных правила без сложных терминов.';
  })();
  const checklist = getFeynmanChecklist(lesson);
  const saved = feynmanPortfolio[lesson.id];

  return `
    <div style="background:rgba(124,58,237,.06); border:1.5px dashed var(--acc1); border-radius:12px; padding:16px 18px; margin:20px 0">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; flex-wrap:wrap; gap:6px">
        <span style="font-size:12px; font-weight:800; color:var(--acc1); text-transform:uppercase">🧑‍🏫 МЕТОД ФЕЙНМАНА: ОБЪЯСНИ СВОИМИ СЛОВАМИ</span>
        ${saved ? `<span class="badge" style="background:rgba(34,197,94,.15); color:var(--ok)">Самооценка: ${saved.score}/4</span>` : '<span style="font-size:11.5px; color:var(--mut)">Объясни, как другу без подготовки</span>'}
      </div>
      <div style="font-size:12.5px; color:var(--txt); margin-bottom:10px">
        Напиши объяснение темы урока так, будто рассказываешь другу, который вообще не в теме. Потом сверься с эталоном и честно оцени себя — это и есть метод Фейнмана.
      </div>
      <div style="font-size:12px; color:var(--acc2); background:rgba(6,182,212,.07); border-left:3px solid var(--acc2); border-radius:6px; padding:9px 12px; margin-bottom:10px; line-height:1.55">
        <b>Шаблон из 3 предложений:</b> ① «Это …» — скажи, что это за вещь одной фразой без жаргона. ② «Работает так: …» — опиши механику на бытовой аналогии. ③ «На практике я …» — скажи, что ты с этим делаешь (когда применяешь, чего избегаешь).
      </div>
      <textarea id="feynman_input_${lesson.id}" rows="3" oninput="window.checkFeynmanForbiddenWords('${lesson.id}')" style="width:100%; background:#040714; border:1px solid rgba(255,255,255,.1); border-radius:8px; padding:10px; color:var(--txt); font-size:13px; font-family:var(--font); box-sizing:border-box" placeholder="Напиши своё простое объяснение...">${saved ? saved.text.replace(/</g, '&lt;') : ''}</textarea>
      <div id="feynman_forbidden_${lesson.id}" style="margin-top:6px; font-size:11.5px; min-height:16px"></div>
      <div style="display:flex; justify-content:space-between; align-items:center; margin-top:8px; flex-wrap:wrap; gap:8px">
        <button class="btn sm" style="background:var(--acc1)" onclick="revealFeynmanCheck('${lesson.id}')">
          ✨ Сверить с эталоном и оценить себя
        </button>
      </div>
      <div id="feynman_model_${lesson.id}" style="display:none; margin-top:12px">
        <div style="padding:12px; background:#040714; border-left:3px solid var(--ok); border-radius:6px; font-size:12.5px; color:var(--txt); line-height:1.5; margin-bottom:10px">
          <b>💡 Эталонное объяснение простыми словами:</b><br>${modelAns}
        </div>
        <div style="padding:12px; background:#040714; border-left:3px solid var(--acc2); border-radius:6px; margin-bottom:10px">
          <div style="font-size:11px; font-weight:800; color:var(--acc2); text-transform:uppercase; margin-bottom:6px">Чек-лист обязательных элементов — отметь, что было в твоём объяснении:</div>
          <ul style="margin:0; padding-left:18px; font-size:12.5px; color:var(--txt); line-height:1.6">
            ${checklist.map(c => `<li>☐ ${c}</li>`).join('')}
          </ul>
        </div>
        <div style="font-size:12.5px; color:var(--txt); margin-bottom:8px"><b>Честная самооценка (0 — совсем не смог, 4 — объяснил всё своими словами):</b></div>
        <div style="display:flex; gap:6px; flex-wrap:wrap">
          ${[0,1,2,3,4].map(s => `<button class="btn sm ${saved && saved.score === s ? '' : 'ghost'}" style="${saved && saved.score === s ? 'background:var(--ok); color:#040714; font-weight:800' : ''}" onclick="submitFeynmanScore('${lesson.id}', ${s})">${s}</button>`).join('')}
        </div>
        <div id="feynman_verdict_${lesson.id}" style="margin-top:10px; font-size:12.5px; color:var(--mut)"></div>
      </div>
    </div>
  `;
};

function revealFeynmanCheck(lessonId){
  const box = document.getElementById('feynman_model_' + lessonId);
  if(box) box.style.display = 'block';
}

function submitFeynmanScore(lessonId, score){
  const ta = document.getElementById('feynman_input_' + lessonId);
  const text = ta ? ta.value.trim() : '';
  if(!text){
    const v = document.getElementById('feynman_verdict_' + lessonId);
    if(v) v.innerHTML = '<span style="color:var(--warn)">Сначала напиши своё объяснение в поле выше — пустая самооценка не считается.</span>';
    return;
  }
  feynmanPortfolio[lessonId] = { text, score, ts: Date.now() };
  localStorage.setItem('cn_feynman_portfolio', JSON.stringify(feynmanPortfolio));

  // (а) запись в topicStats
  const topicId = feynmanTopicOf(lessonId);
  recordTopicResult(topicId, score >= 3); /* v12 P1-2: rolling-окно + mastery консистентны */

  // (б) при самооценке ≤2 — термины урока в SM-2 очередь
  let seeded = 0;
  if(score <= 2){
    const l = LESSONS.find(x => x.id === lessonId);
    ((l && l.terms) || []).forEach(t => {
      const name = typeof t === 'string' ? t : t.ru;
      const idx = findTermIndexByName(name);
      if(idx >= 0 && !srsState[idx]){ srsState[idx] = { interval: 0, ease: 2.5, reps: 0 }; seeded++; }
    });
  }
  save();

  const v = document.getElementById('feynman_verdict_' + lessonId);
  if(v){
    v.innerHTML = score <= 2
      ? `<span style="color:var(--warn)">Принято: ${score}/4. Это сигнал доработать тему: термины урока добавлены в очередь повторений SM-2${seeded ? ` (+${seeded})` : ''} — загляни в Глоссарий завтра.</span>`
      : `<span style="color:var(--ok)">Отлично: ${score}/4! Объяснение сохранено в твоём «портфеле объяснений» на вкладке Прогресс.</span>`;
  }
  if(score >= 3 && typeof addFundCapital === 'function') addFundCapital(5000, 20, 'Метод Фейнмана: уверенное объяснение');
}

function renderFeynmanPortfolio(){
  const box = document.getElementById('feynman_portfolio_box');
  if(!box) return;
  const ids = Object.keys(feynmanPortfolio).sort((a, b) => (feynmanPortfolio[b].ts || 0) - (feynmanPortfolio[a].ts || 0));
  if(!ids.length){ box.innerHTML = ''; return; }
  const rows = ids.slice(0, 12).map(id => {
    const f = feynmanPortfolio[id];
    const l = LESSONS.find(x => x.id === id);
    const col = f.score >= 3 ? 'var(--ok)' : 'var(--warn)';
    return `<div style="background:#040714; border:1px solid var(--line); border-radius:10px; padding:12px 14px">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; flex-wrap:wrap; gap:6px">
        <b style="font-size:13px; color:var(--txt)">${l ? (l.num ? 'Урок ' + l.num + ' · ' : '') + l.title : id}</b>
        <span class="badge" style="background:rgba(34,197,94,.12); color:${col}">${f.score}/4</span>
      </div>
      <div style="font-size:12.5px; color:var(--mut); line-height:1.5; font-style:italic">«${f.text.replace(/</g, '&lt;')}»</div>
    </div>`;
  }).join('');
  box.innerHTML = `
    <div style="background:rgba(255,255,255,.02); border:1px solid var(--line); border-radius:14px; padding:20px; margin-bottom:24px">
      <h3 style="color:var(--txt); margin-bottom:6px">🧑‍🏫 Портфель объяснений (метод Фейнмана)</h3>
      <p style="color:var(--mut); font-size:13px; margin-bottom:16px">Твои объяснения уроков своими словами и честные самооценки. Перечитывай перед сном — это усиливает консолидацию.</p>
      <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(320px,1fr)); gap:10px">${rows}</div>
    </div>`;
}

const _origRenderProgressStatsFeynman = renderProgressStats;
renderProgressStats = function(){
  const r = _origRenderProgressStatsFeynman.apply(this, arguments);
  renderFeynmanPortfolio();
  return r;
};

/* =========================================================================
   B4. РИТУАЛ КОНСОЛИДАЦИИ (NSDR + пост-сессионный протокол)
   После завершения урока: таймер «пустого отдыха» 5–10 минут → напоминание
   об аэробной нагрузке → вечерний дайджест SM-2.
   ========================================================================= */
var consolidationTimerId = null;

function showConsolidationScreen(lessonId, customTitle){
  closeConsolidationScreen();
  const l = lessonId ? LESSONS.find(x => x.id === lessonId) : null;
  const overlay = document.createElement('div');
  overlay.id = 'consolidation_overlay';
  overlay.style.cssText = 'position:fixed; inset:0; background:rgba(2,4,12,.94); z-index:999999; display:flex; justify-content:center; align-items:center; padding:20px; backdrop-filter:blur(10px)';
  overlay.innerHTML = `
    <div style="background:#090d1f; border:2px solid var(--acc2); border-radius:20px; max-width:560px; width:100%; padding:30px; text-align:center; box-shadow:0 20px 60px rgba(0,0,0,.9)">
      <div style="font-size:12px; font-weight:800; color:var(--acc2); text-transform:uppercase; margin-bottom:6px">🧘 Консолидация памяти · 🔥 стрик закреплений: <span id="consol_streak_lbl">0</span></div>
      <h2 style="margin:0 0 8px; font-size:20px; color:var(--txt)">${customTitle ? customTitle : ("Урок «" + (l ? l.title : '') + "» завершён")} — теперь самое важное</h2>
      <div id="consolidation_body"></div>
    </div>`;
  document.body.appendChild(overlay);
  // E4: стрик закреплений (серия дней с консолидацией)
  const today = new Date().toDateString();
  let cs = load('cn_consol_streak', { count: 0, lastDay: '' });
  if(cs.lastDay !== today){
    const yesterday = new Date(Date.now() - 864e5).toDateString();
    cs.count = (cs.lastDay === yesterday) ? cs.count + 1 : 1;
    cs.lastDay = today;
    localStorage.setItem('cn_consol_streak', JSON.stringify(cs));
  }
  const lbl = overlay.querySelector('#consol_streak_lbl');
  if(lbl) lbl.textContent = cs.count + (cs.count === 1 ? ' день' : cs.count < 5 ? ' дня' : ' дней');
  renderConsolidationPhase1();
}

function renderConsolidationPhase1(){
  const body = document.getElementById('consolidation_body');
  if(!body) return;
  body.innerHTML = `
    <p style="font-size:13.5px; color:var(--mut); line-height:1.6; margin:0 0 16px">
      Следующие 5–10 минут мозг «прописывает» изученное в долговременную память.
      Условие одно: <b style="color:var(--txt)">никаких новых стимулов</b> — не открывай мессенджеры и ленты, отведи взгляд от экрана, сиди или лежи в тишине (NSDR-протокол).
    </p>
    <div id="consolidation_timer" style="font-size:46px; font-weight:900; color:var(--acc2); margin:10px 0 16px; font-variant-numeric:tabular-nums">10:00</div>
    <div style="font-size:12px; color:var(--mut); margin-bottom:12px; line-height:1.5; text-align:left">Пока тишина — гиппокамп воспроизводит изученное в <b>SWR-рипплах (sharp-wave ripples)</b> и «прописывает» его в долговременную память. Можно включить метроном дыхания <b>4-4-6</b>: вдох 4 с → пауза 4 с → выдох 6 с (~0.07 Гц).</div>
    <div id="breath_circle_wrap" style="display:none; margin:10px auto 16px; width:180px; height:180px; position:relative">
      <div id="breath_circle" style="position:absolute; inset:30px; border-radius:50%; background:radial-gradient(circle, rgba(6,182,212,.35), rgba(124,58,237,.15)); border:2px solid var(--acc2); transition:transform 1.1s cubic-bezier(.4,0,.2,1)"></div>
      <div style="position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; font-size:13px; font-weight:700; color:var(--txt)"><span id="breath_label">—</span><span id="breath_secs" style="font-size:22px"></span></div>
    </div>
    <div style="display:flex; gap:8px; justify-content:center; flex-wrap:wrap; margin-bottom:10px">
      <button class="btn sm ghost" onclick="setConsolidationMinutes(5)">5 мин</button>
      <button class="btn sm" style="background:var(--acc2)" onclick="setConsolidationMinutes(10)">10 мин</button>
      <button class="btn sm ghost" onclick="setConsolidationMinutes(15)">15 мин</button>
      <button class="btn sm ghost" id="breath_toggle" onclick="toggleConsolidationBreath()">😮💨 дыхание</button>
      <button class="btn sm ghost" id="pinknoise_toggle" onclick="togglePinkNoise()">🔇 розовый шум</button>
    </div>
    <button class="btn" style="background:var(--ok); color:#040714; font-weight:800" onclick="startConsolidationTimer()">▶ Начать паузу</button>
    <div style="margin-top:10px"><button class="btn sm ghost" style="color:var(--mut); font-size:11.5px" onclick="renderConsolidationPhase2()">Пропустить паузу (не рекомендуется) →</button></div>
  `;
  window._consolidationSeconds = 600;
}

function setConsolidationMinutes(m){
  window._consolidationSeconds = m * 60;
  const t = document.getElementById('consolidation_timer');
  if(t) t.textContent = String(m).padStart(2, '0') + ':00';
}

function startConsolidationTimer(){
  if(consolidationTimerId) clearInterval(consolidationTimerId);
  const t = document.getElementById('consolidation_timer');
  consolidationTimerId = setInterval(() => {
    window._consolidationSeconds--;
    const s = Math.max(0, window._consolidationSeconds);
    const mm = Math.floor(s / 60), ss = s % 60;
    if(t) t.textContent = String(mm).padStart(2, '0') + ':' + String(ss).padStart(2, '0');
    if(s <= 0){
      clearInterval(consolidationTimerId);
      consolidationTimerId = null;
      renderConsolidationPhase2();
    }
  }, 1000);
}

// V3-A4b: метроном дыхания 4-4-6 (~0.07 Гц) и розовый шум (опционально, WebAudio)
window._breathOn = false; window._breathTimer = null; window._pinkNoiseSource = null; window._pinkAudioCtx = null;
window.toggleConsolidationBreath = function(){
  window._breathOn = !window._breathOn;
  const wrap = document.getElementById('breath_circle_wrap');
  const tgl = document.getElementById('breath_toggle');
  if(tgl) tgl.textContent = window._breathOn ? '⏸ дыхание' : '😮💨 дыхание';
  if(wrap) wrap.style.display = window._breathOn ? 'block' : 'none';
  if(!window._breathOn){ if(window._breathTimer) clearInterval(window._breathTimer); return; }
  const phases = [['Вдох', 4], ['Пауза', 4], ['Выдох', 6]];
  let pi = 0, sec = phases[0][1];
  function step(){
    if(!window._breathOn) return;
    const lbl = document.getElementById('breath_label');
    const secsEl = document.getElementById('breath_secs');
    const circle = document.getElementById('breath_circle');
    if(lbl) lbl.textContent = phases[pi][0];
    if(secsEl) secsEl.textContent = sec;
    if(circle) circle.style.transform = 'scale(' + (pi === 0 ? 1.45 : pi === 1 ? 1.45 : 1) + ')';
    sec--;
    if(sec < 1){ pi = (pi + 1) % 3; sec = phases[pi][1]; }
  }
  step();
  window._breathTimer = setInterval(step, 1000);
};
window.togglePinkNoise = function(){
  const tgl = document.getElementById('pinknoise_toggle');
  if(window._pinkNoiseSource){
    try{ window._pinkNoiseSource.stop(); }catch(e){}
    window._pinkNoiseSource = null;
    if(tgl) tgl.textContent = '🔇 розовый шум';
    return;
  }
  try{
    window._pinkAudioCtx = window._pinkAudioCtx || new (window.AudioContext || window.webkitAudioContext)();
    const ctx = window._pinkAudioCtx;
    const len = ctx.sampleRate * 4;
    const buffer = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let b0=0,b1=0,b2=0;
    for(let i=0;i<len;i++){
      const w = Math.random()*2-1;
      b0=0.997*b0+0.029*w; b1=0.985*b1+0.032*w; b2=0.95*b2+0.048*w;
      data[i]=(b0+b1+b2+w*0.05)*0.35;
    }
    const src0 = ctx.createBufferSource(); src0.buffer = buffer; src0.loop = true;
    const gain = ctx.createGain(); gain.gain.value = 0.12;
    src0.connect(gain); gain.connect(ctx.destination);
    src0.start();
    window._pinkNoiseSource = src0;
    if(tgl) tgl.textContent = '🔊 розовый шум';
    showToast('Розовый шум включён. Звук всегда опционален.', '🔊');
  }catch(e){ console.log('pink noise unavailable', e); }
};

function renderConsolidationPhase2(){
  if(consolidationTimerId){ clearInterval(consolidationTimerId); consolidationTimerId = null; }
  if(window._breathTimer){ clearInterval(window._breathTimer); window._breathTimer = null; }
  window._breathOn = false;
  if(window._pinkNoiseSource){ try{ window._pinkNoiseSource.stop(); }catch(e){} window._pinkNoiseSource = null; }
  const body = document.getElementById('consolidation_body');
  if(!body) return;
  const due = (typeof getSrsStats === 'function') ? getSrsStats().dueCount : 0;
  body.innerHTML = `
    <div style="text-align:left; font-size:13.5px; color:var(--txt); line-height:1.65">
      <div style="background:rgba(34,197,94,.08); border:1px solid var(--ok); border-radius:10px; padding:12px 14px; margin-bottom:12px">
        <b style="color:var(--ok)">🚶 Шаг 2 — движение.</b> В ближайшие 30 минут дай себе 20–30 минут аэробной нагрузки: прогулка быстрым шагом, велосипед, лёгкий бег. Это заметно усиливает закрепление только что изученного.
      </div>
      <div style="background:rgba(124,58,237,.08); border:1px solid var(--acc1); border-radius:10px; padding:12px 14px; margin-bottom:12px">
        <b style="color:var(--acc1)">🌙 Шаг 3 — вечером.</b> Перед сном повтори карточки SM-2: на сегодня по плану <b>${due}</b> терминов. Сон 7–9 часов завершает консолидацию — без него дневная учёба «смывается».
      </div>
    </div>
    <div style="display:flex; gap:10px; justify-content:center; flex-wrap:wrap">
      <button class="btn" style="background:var(--ok); color:#040714; font-weight:800" onclick="closeConsolidationScreen()">✓ Понял, иду гулять</button>
      <button class="btn ghost" onclick="closeConsolidationScreen(); go('glossary'); if(typeof startSrsReviewSession==='function') startSrsReviewSession()">🧠 Повторить SM-2 сейчас</button>
    </div>
  `;
}

function closeConsolidationScreen(){
  if(consolidationTimerId){ clearInterval(consolidationTimerId); consolidationTimerId = null; }
  const ov = document.getElementById('consolidation_overlay');
  if(ov) ov.remove();
}

// Оборачиваем завершение урока: экран консолидации показывается только при реальном зачёте
// V4-D1: не чаще одного раза за сессию — иначе модалка превращается в спам и её игнорируют
const _origCLM_Consolidation = completeLessonWithMastery;
completeLessonWithMastery = function(id){
  const wasDone = lessonsDone[id] === 1;
  const res = _origCLM_Consolidation.apply(this, arguments);
  try{
    if(!wasDone && lessonsDone[id] === 1 && !window._consolShownThisSession){
      window._consolShownThisSession = true;
      setTimeout(() => showConsolidationScreen(id), 400);
    }
  }catch(e){}
  return res;
};



/* ---------- V4-E2: строгий режим Фазы 0 (toggle, default OFF) ---------- */
function isStrictPhase0(){
  try{ return localStorage.getItem('cn_strict_phase0') === '1'; }catch(e){ return false; }
}
window.toggleStrictPhase0 = function(){
  const on = !isStrictPhase0();
  try{ localStorage.setItem('cn_strict_phase0', on ? '1' : '0'); }catch(e){}
  showToast(on ? 'Строгий режим Фазы 0 ВКЛ: урок N+1 откроется после завершения урока N.' : 'Строгий режим Фазы 0 ВЫКЛ: свободная навигация по урокам.', on ? '🔒' : '🔓', 3500);
  if(typeof renderPhaseLessonsView === 'function' && currentViewingPhase === 0) renderPhaseLessonsView(0);
};
const _origOpenFullscreenV4 = openFullscreenLesson;
openFullscreenLesson = function(lessonId){
  if(isStrictPhase0()){
    const l = LESSONS.find(x => x.id === lessonId);
    if(l && l.phase === 0){
      const seq = LESSONS.filter(x => x.phase === 0);
      const idx = seq.findIndex(x => x.id === lessonId);
      if(idx > 0 && lessonsDone[seq[idx - 1].id] !== 1){
        showToast('🔒 Строгий режим: сначала заверши урок «' + seq[idx - 1].title.slice(0, 48) + '…»', '🔒', 4000);
        window.scrollToLessonCard && window.scrollToLessonCard(seq[idx - 1].id);
        return;
      }
    }
  }
  return _origOpenFullscreenV4.apply(this, arguments);
};
// Визуальный замок на карточках Фазы 0 при включённом строгом режиме
const _origRenderPhaseLessonsV4 = renderPhaseLessonsView;
renderPhaseLessonsView = function(phaseNum){
  _origRenderPhaseLessonsV4.apply(this, arguments);
  try{
    if(phaseNum === 0){
      const jumpBar = document.getElementById('phase_jump_bar');
      if(jumpBar && !document.getElementById('strict_phase0_toggle')){
        jumpBar.insertAdjacentHTML('beforeend',
          '<button id="strict_phase0_toggle" class="btn sm ghost" style="margin-left:auto; font-size:11.5px" onclick="toggleStrictPhase0()"></button>');
      }
      const tgl = document.getElementById('strict_phase0_toggle');
      if(tgl){
        const on = isStrictPhase0();
        tgl.innerHTML = (on ? '🔒 Строгий режим: ВКЛ' : '🔓 Строгий режим: ВЫКЛ');
        tgl.style.borderColor = on ? 'var(--warn)' : 'var(--line)';
        tgl.style.color = on ? 'var(--warn)' : 'var(--mut)';
      }
      if(isStrictPhase0()){
        const seq = LESSONS.filter(x => x.phase === 0);
        let firstOpen = true;
        seq.forEach(l => {
          const card = document.getElementById('lesson_card_' + l.id);
          if(!card) return;
          const locked = lessonsDone[l.id] !== 1 && !firstOpen;
          if(lessonsDone[l.id] !== 1 && firstOpen) firstOpen = false;
          if(locked){
            card.style.opacity = '.55';
            card.style.position = 'relative';
            if(!card.querySelector('.v4-lock-badge')){
              card.insertAdjacentHTML('beforeend',
                '<span class="v4-lock-badge" style="position:absolute; top:8px; right:8px; font-size:15px" title="Откроется после предыдущего урока">🔒</span>');
            }
          }
        });
      }
    }
  }catch(e){}
};

/* ---------- V4-D3: «Сборочный пункт» после каждых 5 завершённых уроков ---------- */
const _origShowConsolV4 = showConsolidationScreen;
showConsolidationScreen = function(lessonId, customTitle){
  _origShowConsolV4.apply(this, arguments);
  try{
    const doneCount = Object.keys(lessonsDone).filter(k => lessonsDone[k] === 1).length;
    if(doneCount > 0 && doneCount % 5 === 0){
      const ov = document.getElementById('consolidation_overlay');
      if(ov && !ov.querySelector('.v4-checkpoint')){
        const card = ov.firstElementChild;
        if(card){
          card.insertAdjacentHTML('afterbegin', `
            <div class="v4-checkpoint" style="background:rgba(6,182,212,.1); border:1.5px dashed var(--acc2); border-radius:12px; padding:12px 16px; margin-bottom:14px; text-align:left">
              <div style="font-size:12px; font-weight:800; color:var(--acc2); text-transform:uppercase; margin-bottom:4px">🧩 Сборочный пункт: пройдено ${doneCount} уроков</div>
              <div style="font-size:12.5px; color:var(--mut); line-height:1.5">Каждые 5 уроков — точка интервального повторения: без него до 60% терминов «стирается» за неделю. 3 минуты SM-2 сейчас дешевле, чем переучивание потом.</div>
              <button class="btn sm" style="background:var(--acc2); margin-top:8px" onclick="closeConsolidationScreen(); go('glossary'); if(typeof startSrsReviewSession==='function') startSrsReviewSession()">▶ Повторить термины (SM-2)</button>
            </div>`);
        }
      }
    }
  }catch(e){}
};

/* ---------- E5: Лестница рангов + наставник ---------- */
// XP за понимание: самообъяснение Фейнмана (один раз на урок)
// V3-A4: фильтр запретных слов-паразитов (объяснение слабо, если жонглирует терминами)
window.FEYNMAN_FORBIDDEN = ['стационарность','матрица','энтропия','корреляция','волатильность','коэффициент','метрика','статистика','распределение','ликвидность','гипотеза','регрессия','модель','алгоритм','тренд','дельта','параметр'];
window.checkFeynmanForbiddenWords = function(lessonId){
  const ta = document.getElementById('feynman_input_' + lessonId);
  const box = document.getElementById('feynman_forbidden_' + lessonId);
  if(!ta || !box) return;
  const text = ta.value.toLowerCase();
  const hits = window.FEYNMAN_FORBIDDEN.filter(w => text.includes(w));
  if(text.trim().length < 5){ box.innerHTML = ''; return; }
  if(hits.length){
    box.innerHTML = '<span style="color:var(--bad)">⚠️ Жаргон-паразит: <u>' + hits.join('</u>, <u>') + '</u>. Для 10-летнего объясняй «на пальцах» без терминов.</span>';
    ta.style.borderColor = 'var(--bad)';
  } else {
    box.innerHTML = '<span style="color:var(--ok)">✓ Чистое объяснение без слов-паразитов.</span>';
    ta.style.borderColor = 'var(--ok)';
  }
};

window.revealFeynmanModel = function(lessonId){
  const el = document.getElementById('feynman_model_' + lessonId);
  if(el) el.style.display = 'block';
  const st = load('cn_feynman_xp', {});
  if(!st[lessonId]){
    const inp = document.getElementById('feynman_input_' + lessonId);
    const wrote = inp && inp.value.trim().length >= 20;
    if(wrote){
      st[lessonId] = true;
      localStorage.setItem('cn_feynman_xp', JSON.stringify(st));
      addFundCapital(5000, 80, 'Самообъяснение по Фейнману');
    } else {
      showToast('✍️ Сначала напиши своё объяснение (≥20 символов) — XP идёт за понимание, а не за клик.', '🧠');
    }
  }
};
const RANK_MENTOR_LINES = [
  'Наставник: «Стажёр учится не терять. Первое правило фонда: выживание важнее доходности».',
  'Наставник: «Аналитик доказывает цифрами. Каждая идея — гипотеза с тестом и издержками».',
  'Наставник: «Алго-трейдер доверяет коду, но проверяет исполнение: kill-switch и мониторинг — твои ноги».',
  'Наставник: «Риск-офицер говорит "нет" красивым стратегиям. Просадка фонда — твоя вина, а не рынка».',
  'Наставник: «Управляющий думает портфелем: корреляции в крах сходятся к единице».',
  'Наставник: «Архитектор строит систему, которая переживает его отпуск. Ты дошёл — теперь учи других».'
];
function renderRankLadder(){
  const box = document.getElementById('rank_ladder');
  if(!box || typeof QUANT_RANKS === 'undefined') return;
  const cur = getCurrentQuantRank();
  const curIdx = QUANT_RANKS.findIndex(r => r.title === cur.title);
  box.innerHTML = '<div style="display:flex; flex-direction:column; gap:6px">' + QUANT_RANKS.map((r, i) => {
    const done = i <= curIdx;
    return `<div style="display:flex; align-items:center; gap:10px; padding:8px 12px; border-radius:8px; background:${i === curIdx ? 'rgba(6,182,212,.1)' : 'transparent'}; border:1px solid ${i === curIdx ? 'var(--acc2)' : 'var(--line)'}; opacity:${done ? 1 : 0.55}">
      <span style="font-size:16px">${done ? '✅' : '🔒'}</span>
      <span style="font-weight:800; color:${r.color}; min-width:230px">${r.title}</span>
      <span style="font-size:12px; color:var(--mut)">AUM от $${r.minAum.toLocaleString()} · ${r.perk}</span>
    </div>`;
  }).join('') + '</div>';
  const mentor = document.getElementById('rank_mentor');
  if(mentor) mentor.textContent = RANK_MENTOR_LINES[Math.min(curIdx, RANK_MENTOR_LINES.length - 1)];
}
(function(){
  const prev = window.updateFundUI;
  window.updateFundUI = function(){
    prev.apply(this, arguments);
    renderRankLadder();
  };
})();

/* =========================================================================
   E3: ПРОГНОЗ ДНЯ (Brier) · E6: ДЕТЕКТИВ + РУЛЕТКА КВЕСТОВ
   ========================================================================= */
const BRIER_QUESTIONS = [
  { q: 'Фандинг BTC перпетуалов сейчас положительный. Значит ли это, что лонгисты платят шортистам?', a: true },
  { q: 'Если z-score спреда пары = +2.5, это сигнал стоп-лосса для mean-reversion стратегии.', a: false },
  { q: 'При плече x10 движение цены на −10% ликвидирует лонг-позицию (без учёта буферов).', a: true },
  { q: 'Корреляция BTC и ETH близкая к +1 гарантирует, что они не упадут одновременно.', a: false },
  { q: 'Комиссия сети Bitcoin зависит от суммы перевода в BTC.', a: false },
  { q: 'По шкале НДФЛ-2025 доход от продажи крипты свыше 2.4 млн ₽/год может облагаться по ставке выше 13%.', a: true },
  { q: 'Непостоянные потери пула 50/50 при росте цены актива вдвое (×2) составляют примерно 5.7%.', a: true },
  { q: 'Full Kelly максимизирует рост капитала и при этом имеет наименьшие просадки.', a: false },
  { q: 'Short call имеет ограниченный максимальный убыток.', a: false },
  { q: 'Seed-фразу из 12 слов невозможно восстановить перебором на современном оборудовании.', a: true },
  { q: 'Биржа обязана хранить 100% клиентских активов в холодных кошельках по закону РФ.', a: false },
  { q: 'Interleaving (чередование тем) улучшает долговременное запоминание по сравнению с блоковым повторением.', a: true },
  { q: 'Walk-forward тест устраняет lookahead bias полностью.', a: false },
  { q: 'Kill-switch должен отменять открытые ордера и подтверждать отмену на бирже.', a: true }
];

function brierDayIdx(offset = 0){
  const day = Math.floor((Date.now() + offset * 864e5) / 864e5);
  return day % BRIER_QUESTIONS.length;
}

function renderBrierBox(){
  const box = document.getElementById('brier_box');
  if(!box) return;
  const st = load('cn_brier', { preds: [] }); // {day, qIdx, p, resolved}
  const today = Math.floor(Date.now() / 864e5);
  // резолвим вчерашние и старше
  let changed = false;
  st.preds.forEach(pr => {
    if(!pr.resolved && pr.day < today){
      pr.resolved = true;
      pr.outcome = BRIER_QUESTIONS[pr.qIdx].a ? 1 : 0;
      pr.score = Math.pow(pr.p - pr.outcome, 2);
      changed = true;
    }
  });
  if(changed) localStorage.setItem('cn_brier', JSON.stringify(st));
  const todays = st.preds.find(pr => pr.day === today);
  const done = st.preds.filter(pr => pr.resolved);
  const week = done.slice(-7);
  const brier = week.length ? (week.reduce((s, p) => s + p.score, 0) / week.length) : null;
  const q = BRIER_QUESTIONS[brierDayIdx()];
  let html = '';
  if(todays){
    html += `<div style="font-size:12.5px; color:var(--txt)">Твой прогноз записан: <b>${Math.round(todays.p * 100)}%</b> «да». Вердикт завтра.</div>`;
  } else {
    html += `
      <div style="font-size:12.5px; color:var(--txt); margin-bottom:8px; line-height:1.5">${q.q}</div>
      <div style="font-size:12px; color:var(--mut)">Насколько ты уверен, что утверждение верно? <b id="brier_p_lbl" style="color:var(--acc2)">50%</b></div>
      <input type="range" id="brier_p" min="5" max="95" step="5" value="50" style="width:100%" oninput="document.getElementById('brier_p_lbl').textContent=this.value+'%'">
      <button class="btn sm" style="margin-top:6px" onclick="submitBrier()">📌 Зафиксировать прогноз</button>`;
  }
  if(brier !== null){
    const grade = brier <= 0.18 ? 'отличная калибровка 🎯' : brier <= 0.30 ? 'нормальная калибровка' : 'переоцениваешь уверенность ⚠️';
    html += `<div style="margin-top:8px; font-size:12.5px; color:var(--txt); border-top:1px dashed var(--line); padding-top:6px">
      Brier за неделю: <b style="color:${brier <= 0.30 ? 'var(--ok)' : 'var(--warn)'}">${brier.toFixed(3)}</b> (${grade}) · прогнозов: ${done.length}
      ${done.filter(p => !p.coach).length >= 7 && brier <= 0.25 ? '<div style="color:var(--ok); font-weight:800; margin-top:2px">🏅 Бейдж «Калиброванный аналитик» заработан!</div>' : ''}
    </div>`;
  } else {
    html += `<div style="margin-top:8px; font-size:11.5px; color:var(--mut)">Brier-скор появится завтра: прогноз сравнивается с вердиктом, (p − исход)².</div>`;
  }
  box.innerHTML = html;
}

function submitBrier(){
  const st = load('cn_brier', { preds: [] });
  const today = Math.floor(Date.now() / 864e5);
  if(st.preds.find(pr => pr.day === today)) return;
  st.preds.push({ day: today, qIdx: brierDayIdx(), p: +document.getElementById('brier_p').value / 100, resolved: false });
  localStorage.setItem('cn_brier', JSON.stringify(st));
  showToast('🎯 Прогноз зафиксирован. Завтра — вердикт и Brier-скор.', '📌');
  renderBrierBox();
}

