/* ---------- V4-C1: генератор эквити-кривых ---------- */
window.runEquityGen = function(){
  const wr = (parseFloat(document.getElementById('eq_wr').value) || 45) / 100;
  const rr = parseFloat(document.getElementById('eq_rr').value) || 2;
  const risk = (parseFloat(document.getElementById('eq_risk').value) || 1) / 100;
  const n = Math.max(20, parseFloat(document.getElementById('eq_n').value) || 200);
  const evPerTrade = wr * rr * risk - (1 - wr) * risk;
  const finals = [];
  const N_TRAJ = 1000;
  const paths = [];
  for(let t = 0; t < N_TRAJ; t++){
    let eq = 1;
    const path = [1];
    for(let i = 0; i < n; i++){
      const win = Math.random() < wr;
      eq *= 1 + (win ? rr * risk : -risk);
      if(eq <= 0.001){ eq = 0.001; path.push(eq); break; }
      path.push(eq);
    }
    finals.push(eq);
    if(t < 120) paths.push(path);
  }
  finals.sort((a,b) => a - b);
  const pctl = q => finals[Math.floor(q * (finals.length - 1))];
  const p5 = pctl(0.05), p50 = pctl(0.5), p95 = pctl(0.95);
  const ruin = finals.filter(x => x <= 0.5).length / finals.length;
  const neg = finals.filter(x => x < 1).length / finals.length;
  // canvas: веер + гистограмма финалов
  const out = document.getElementById('eq_result');
  out.innerHTML = `
    <div style="font-weight:700; margin-bottom:6px">Веер траекторий (120 из 1000):</div>
    <canvas id="eq_fan" width="640" height="240" style="width:100%; background:#040714; border-radius:8px"></canvas>
    <div style="font-weight:700; margin:14px 0 6px">Распределение финалов (1000 траекторий):</div>
    <canvas id="eq_hist" width="640" height="160" style="width:100%; background:#040714; border-radius:8px"></canvas>
    <div style="display:flex; gap:10px; flex-wrap:wrap; margin-top:12px; font-size:13px">
      <span style="background:#040714; border:1px solid var(--line); border-radius:8px; padding:8px 12px">EV на сделку: <b style="color:${evPerTrade > 0 ? 'var(--ok)' : 'var(--bad)'}">${(evPerTrade*100).toFixed(2)}%</b></span>
      <span style="background:#040714; border:1px solid var(--line); border-radius:8px; padding:8px 12px">5-й перцентиль: <b style="color:var(--bad)">${(p5*100-100).toFixed(0)}%</b></span>
      <span style="background:#040714; border:1px solid var(--line); border-radius:8px; padding:8px 12px">Медиана: <b style="color:var(--acc2)">${(p50*100-100).toFixed(0)}%</b></span>
      <span style="background:#040714; border:1px solid var(--line); border-radius:8px; padding:8px 12px">95-й перцентиль: <b style="color:var(--ok)">+${(p95*100-100).toFixed(0)}%</b></span>
      <span style="background:#040714; border:1px solid var(--line); border-radius:8px; padding:8px 12px">P(потерять >50%): <b style="color:var(--bad)">${(ruin*100).toFixed(1)}%</b></span>
      <span style="background:#040714; border:1px solid var(--line); border-radius:8px; padding:8px 12px">P(убыток): <b>${(neg*100).toFixed(1)}%</b></span>
    </div>
    <div style="font-size:12px; color:var(--mut); margin-top:10px">Даже при положительном EV заметная доля траекторий заканчивается в минусе. Размер ставки (риск на сделку) решает, переживёшь ли ты закономерную серию неудач.</div>`;
  // fan
  const cv = document.getElementById('eq_fan');
  const ctx = cv.getContext('2d');
  const w = cv.width, h = cv.height;
  const allMax = Math.max(...paths.map(p => Math.max(...p)), 1.5);
  const allMin = Math.min(...paths.map(p => Math.min(...p)), 0.5);
  const y = v => h - ((v - allMin) / (allMax - allMin)) * (h - 10) - 5;
  ctx.strokeStyle = 'rgba(255,255,255,.25)';
  ctx.setLineDash([4,4]);
  ctx.beginPath(); ctx.moveTo(0, y(1)); ctx.lineTo(w, y(1)); ctx.stroke();
  ctx.setLineDash([]);
  paths.forEach(path => {
    ctx.beginPath();
    const stepX = w / Math.max(...paths.map(p => p.length));
    path.forEach((v, i) => i === 0 ? ctx.moveTo(0, y(v)) : ctx.lineTo(i * stepX, y(v)));
    const fin = path[path.length - 1];
    ctx.strokeStyle = fin >= 1 ? 'rgba(34,197,94,.12)' : 'rgba(239,68,68,.12)';
    ctx.lineWidth = 1;
    ctx.stroke();
  });
  // hist
  const cv2 = document.getElementById('eq_hist');
  const ctx2 = cv2.getContext('2d');
  const hMax = Math.max(p95 * 1.15, 2);
  const hMin = Math.min(p5 * 0.85, 0.5);
  const NB = 40;
  const bins = new Array(NB).fill(0);
  finals.forEach(v => {
    const idx = Math.max(0, Math.min(NB - 1, Math.floor((v - hMin) / (hMax - hMin) * NB)));
    bins[idx]++;
  });
  const bMax = Math.max(...bins);
  const bw = cv2.width / NB;
  bins.forEach((c, i) => {
    const mid = hMin + (i + 0.5) / NB * (hMax - hMin);
    ctx2.fillStyle = mid >= 1 ? 'rgba(34,197,94,.7)' : 'rgba(239,68,68,.7)';
    const bh = (c / bMax) * (cv2.height - 20);
    ctx2.fillRect(i * bw + 1, cv2.height - bh, bw - 2, bh);
  });
  const xz = (1 - hMin) / (hMax - hMin) * cv2.width;
  ctx2.strokeStyle = 'rgba(255,255,255,.5)';
  ctx2.beginPath(); ctx2.moveTo(xz, 0); ctx2.lineTo(xz, cv2.height); ctx2.stroke();
  ctx2.fillStyle = 'rgba(255,255,255,.7)';
  ctx2.font = '11px sans-serif';
  ctx2.fillText('0% (безубыток)', xz + 4, 14);
};

/* ---------- V4-C2: карта корреляций ---------- */
const V4_CORR_ASSETS = ['BTC', 'ETH', 'SOL', 'USDT-фарм', 'S&P 500', 'Золото'];
function v4CorrMatrix(period){
  // синтетические корреляции: базовые уровни + сжатие в кризис
  const base = {
    'BTC':       { 'BTC':1, 'ETH':0.85, 'SOL':0.72, 'USDT-фарм':0.02, 'S&P 500':0.35, 'Золото':0.12 },
    'ETH':       { 'BTC':0.85, 'ETH':1, 'SOL':0.78, 'USDT-фарм':0.03, 'S&P 500':0.33, 'Золото':0.10 },
    'SOL':       { 'BTC':0.72, 'ETH':0.78, 'SOL':1, 'USDT-фарм':0.04, 'S&P 500':0.30, 'Золото':0.08 },
    'USDT-фарм': { 'BTC':0.02, 'ETH':0.03, 'SOL':0.04, 'USDT-фарм':1, 'S&P 500':0.0, 'Золото':0.05 },
    'S&P 500':   { 'BTC':0.35, 'ETH':0.33, 'SOL':0.30, 'USDT-фарм':0.0, 'S&P 500':1, 'Золото':0.15 },
    'Золото':    { 'BTC':0.12, 'ETH':0.10, 'SOL':0.08, 'USDT-фарм':0.05, 'S&P 500':0.15, 'Золото':1 }
  };
  const noise = { '7': 0.18, '30': 0.09, '90': 0.05, '365': 0.03, 'crisis': 0.04 }[period];
  const M = V4_CORR_ASSETS.map(() => []);
  for(let i = 0; i < V4_CORR_ASSETS.length; i++){
    for(let j = 0; j < V4_CORR_ASSETS.length; j++){
      let v = base[V4_CORR_ASSETS[i]][V4_CORR_ASSETS[j]];
      if(i !== j){
        v += (Math.sin(i * 7 + j * 13) * noise);
        if(period === 'crisis'){
          const a = V4_CORR_ASSETS[i], b2 = V4_CORR_ASSETS[j];
          if(a !== 'USDT-фарм' && b2 !== 'USDT-фарм' && a !== 'Золото' && b2 !== 'Золото') v = Math.min(0.97, v * 1.5 + 0.35);
          else if((a === 'USDT-фарм' || b2 === 'USDT-фарм')) v = Math.max(-0.3, v - 0.1);
        }
        if(period === '7') v = Math.max(-1, Math.min(1, v));
      }
      M[i][j] = Math.max(-1, Math.min(1, v));
    }
  }
  return M;
}
window.renderCorrHeatmap = function(){
  const period = document.getElementById('corr_period').value;
  const M = v4CorrMatrix(period);
  const out = document.getElementById('corr_result');
  const cell = v => {
    const r = v > 0 ? Math.round(239 - v * 200) : 239;
    const g = v > 0 ? Math.round(68 + v * 130) : Math.round(68 - v * 40);
    const bg = v >= 0 ? `rgba(34,197,94,${(v * 0.85).toFixed(2)})` : `rgba(239,68,68,${(-v * 0.85).toFixed(2)})`;
    return `<td style="background:${bg}; text-align:center; padding:8px 6px; font-size:12px; font-weight:700; color:var(--txt); border:1px solid #040714">${v.toFixed(2)}</td>`;
  };
  out.innerHTML = `
    <table style="border-collapse:collapse; width:100%; max-width:560px">
      <thead><tr><th style="font-size:11px; color:var(--mut)"></th>${V4_CORR_ASSETS.map(a => `<th style="font-size:11px; color:var(--mut); padding:4px">${a}</th>`).join('')}</tr></thead>
      <tbody>${M.map((row, i) => `<tr><td style="font-size:11px; color:var(--mut); padding-right:6px; white-space:nowrap">${V4_CORR_ASSETS[i]}</td>${row.map(cell).join('')}</tr>`).join('')}</tbody>
    </table>
    <div style="display:flex; gap:8px; align-items:center; margin-top:10px; font-size:11.5px; color:var(--mut)">
      <span>−1</span><div style="width:120px; height:10px; border-radius:5px; background:linear-gradient(90deg, rgba(239,68,68,.85), rgba(255,255,255,.05), rgba(34,197,94,.85))"></div><span>+1</span>
    </div>
    <div style="font-size:12.5px; color:var(--mut); margin-top:10px; line-height:1.6">
      ${period === 'crisis'
        ? '⚡ <b style="color:var(--bad)">Кризисный режим:</b> BTC–ETH–SOL–S&P схлопнулись к 0.85–0.97 — диверсификация внутри крипты исчезла именно тогда, когда была нужна больше всего. Стейбл-фарминг остался около нуля: единственная реальная диверсификация — это кэш и низкая корреляция.'
        : 'Короткие окна шумные: корреляция «плавает». Вывод не в точном числе, а в структуре: криптоактивы движутся единым кластером, стейбл-стратегии и золото живут отдельно. Переключи на «Кризисный месяц» — это главный урок портфельной теории.'}
    </div>`;
};

/* ---------- V4-C3: конструктор дельта-нейтрала ---------- */
window._v4corrInitDone = false;
window.runDeltaNeutral = function(){
  const size = parseFloat(document.getElementById('dn_size').value) || 10000;
  const fundingBps = parseFloat(document.getElementById('dn_funding').value) || 0;
  const days = Math.max(1, parseFloat(document.getElementById('dn_days').value) || 30);
  const move = parseFloat(document.getElementById('dn_move').value) || 0;
  document.getElementById('dn_move_lbl').textContent = (move > 0 ? '+' : '') + move + '%';
  const m = move / 100;
  const spotPnl = size * m;
  const perpPnl = -size * m;
  const fundingIncome = size * (fundingBps / 10000) * 3 * days; // 3 раза в сутки
  const total = spotPnl + perpPnl + fundingIncome;
  const out = document.getElementById('dn_result');
  const fmt$ = v => (v >= 0 ? '+' : '−') + '$' + Math.abs(Math.round(v)).toLocaleString('en-US');
  out.innerHTML = `
    <div style="display:flex; gap:10px; flex-wrap:wrap; font-size:13px">
      <span style="background:#040714; border:1px solid var(--line); border-radius:8px; padding:10px 14px">🟢 Спот-лонг: <b style="color:${spotPnl >= 0 ? 'var(--ok)' : 'var(--bad)'}">${fmt$(spotPnl)}</b></span>
      <span style="background:#040714; border:1px solid var(--line); border-radius:8px; padding:10px 14px">🔴 Перп-шорт: <b style="color:${perpPnl >= 0 ? 'var(--ok)' : 'var(--bad)'}">${fmt$(perpPnl)}</b></span>
      <span style="background:#040714; border:1px solid var(--line); border-radius:8px; padding:10px 14px">💰 Фандинг за ${days} дн.: <b style="color:${fundingIncome >= 0 ? 'var(--ok)' : 'var(--bad)'}">${fmt$(fundingIncome)}</b></span>
      <span style="background:#040714; border:1.5px solid var(--acc2); border-radius:8px; padding:10px 14px">Σ Итог: <b style="color:${total >= 0 ? 'var(--ok)' : 'var(--bad)'}">${fmt$(total)}</b></span>
    </div>
    <div style="margin-top:12px; background:#040714; border-radius:8px; height:14px; overflow:hidden; display:flex">
      <div style="width:50%; background:rgba(34,197,94,.35); transform:scaleX(${Math.min(1, Math.abs(spotPnl) / (size * 0.5) || 0.001)}); transform-origin:${spotPnl >= 0 ? 'right' : 'right'}"></div>
      <div style="width:50%; background:rgba(239,68,68,.35); transform:scaleX(${Math.min(1, Math.abs(perpPnl) / (size * 0.5) || 0.001)}); transform-origin:left"></div>
    </div>
    <div style="font-size:12.5px; color:var(--mut); margin-top:10px; line-height:1.6">
      Ноги гасят друг друга: цена ${move >= 0 ? 'выросла' : 'упала'} на ${Math.abs(move)}%, а рыночный PnL позиции — <b>ноль</b>. Позиция зарабатывает только фандинг: ${fundingBps} bps × 3 раза в сутки × ${days} дн. = ${fmt$(fundingIncome)}.
      ${fundingIncome < 0 ? ' <b style="color:var(--bad)">Фандинг отрицательный для этой стороны — ты платишь, а не получаешь.</b>' : ''}
      Риски, которых не видно на этом идеальном конструкторе: инверсия фандинга, базис, ликвидация шорта при перекосе маржи и комиссии перекладки.
    </div>`;
};

/* ---------- V4-C4: gauge «расстояние до ликвидации» (апгрейд sim_liq) ---------- */
const _origCalcLiqV4 = calcLiquidation;
calcLiquidation = function(){
  _origCalcLiqV4.apply(this, arguments);
  try{ renderLiqGauge(); }catch(e){}
};
function renderLiqGauge(){
  const wrap = document.getElementById('liq_gauge_wrap');
  if(!wrap) return;
  const margin = parseFloat(document.getElementById('liq_margin')?.value) || 0;
  const lev = parseFloat(document.getElementById('liq_lev')?.value) || 1;
  const entry = parseFloat(document.getElementById('liq_entry')?.value) || 0;
  const side = document.getElementById('liq_dir')?.value || 'long';
  const mmr = (parseFloat(document.getElementById('liq_mmr')?.value) || 0.5) / 100;
  if(margin <= 0 || entry <= 0){ wrap.innerHTML = ''; return; }
  const liqPrice = side === 'long' ? entry * (1 - 1/lev + mmr) : entry * (1 + 1/lev - mmr);
  if(!window._liqCurPrice) window._liqCurPrice = entry;
  if(Math.abs(window._liqCurPrice - entry) / entry > 0.5) window._liqCurPrice = entry;
  const cur = window._liqCurPrice;
  // здоровье позиции: 100% при цене входа, 0% при цене ликвидации
  let health;
  if(side === 'long') health = (cur - liqPrice) / (entry - liqPrice);
  else health = (liqPrice - cur) / (liqPrice - entry);
  health = Math.max(0, Math.min(1, health));
  const hpct = Math.round(health * 100);
  const col = hpct > 50 ? '#22c55e' : hpct > 20 ? '#eab308' : '#ef4444';
  const ang = Math.PI * (1 - health); // 0 (лево, 0%) .. PI (право, 100%)
  const nx = 110 + 80 * Math.cos(ang), ny = 105 - 80 * Math.sin(ang);
  const distPct = side === 'long' ? ((cur - liqPrice) / cur * 100) : ((liqPrice - cur) / cur * 100);
  const liquidated = side === 'long' ? cur <= liqPrice : cur >= liqPrice;
  wrap.innerHTML = `
  <div style="background:#040714; border:1px solid var(--line); border-radius:12px; padding:14px 16px">
    <div style="font-size:12px; font-weight:800; color:var(--mut); text-transform:uppercase; margin-bottom:8px">🧭 Спидометр маржи: расстояние до ликвидации</div>
    <div style="display:flex; gap:18px; align-items:center; flex-wrap:wrap">
      <svg width="220" height="120" viewBox="0 0 220 120">
        <path d="M 20 105 A 90 90 0 0 1 200 105" fill="none" stroke="#26304a" stroke-width="14" stroke-linecap="round"/>
        <path d="M 20 105 A 90 90 0 0 1 65 27" fill="none" stroke="#ef4444" stroke-width="14" stroke-linecap="round" opacity=".8"/>
        <path d="M 65 27 A 90 90 0 0 1 110 15" fill="none" stroke="#eab308" stroke-width="14" opacity=".8"/>
        <path d="M 110 15 A 90 90 0 0 1 200 105" fill="none" stroke="#22c55e" stroke-width="14" stroke-linecap="round" opacity=".8"/>
        <line x1="110" y1="105" x2="${nx.toFixed(1)}" y2="${ny.toFixed(1)}" stroke="${col}" stroke-width="4" stroke-linecap="round"/>
        <circle cx="110" cy="105" r="7" fill="${col}"/>
        <text x="24" y="118" font-size="10" fill="#ef4444">0%</text>
        <text x="188" y="118" font-size="10" fill="#22c55e">100%</text>
      </svg>
      <div style="flex:1; min-width:200px">
        <div style="font-size:26px; font-weight:900; color:${col}">${liquidated ? '💥 LIQUIDATED' : hpct + '%'}</div>
        <div style="font-size:12.5px; color:var(--mut); margin:4px 0 10px">${liquidated
          ? 'Позиция уничтожена: цена пересекла уровень ликвидации $' + liqPrice.toFixed(0)
          : 'До ликвидации ($' + liqPrice.toFixed(0) + '): <b style="color:var(--txt)">' + distPct.toFixed(2) + '%</b> цены'}</div>
        <label style="font-size:12px; color:var(--mut)">Текущая цена: <b style="color:var(--acc2)">$${Math.round(cur).toLocaleString('en-US')}</b><br>
        <input type="range" min="${Math.round(side === 'long' ? liqPrice * 0.98 : entry * 0.7)}" max="${Math.round(side === 'long' ? entry * 1.3 : liqPrice * 1.02)}" step="10" value="${Math.round(cur)}" style="width:100%" oninput="window._liqCurPrice=+this.value; renderLiqGauge()"></label>
      </div>
    </div>
    <div style="font-size:11.5px; color:var(--mut); margin-top:6px">Подвигай цену к линии ликвидации: стрелка уходит в красную зону. Плечо x${lev} означает, что хода в ${(100/lev).toFixed(1)}% против позиции достаточно для гибели маржи.</div>
  </div>`;
}

/* ---------- V4-C5: depth-chart (апгрейд sim_ob) ---------- */
const _origRenderObTableV4 = renderObTable;
renderObTable = function(){
  _origRenderObTableV4.apply(this, arguments);
  try{ renderObDepthChart(); }catch(e){}
};
function renderObDepthChart(){
  const cv = document.getElementById('ob_depth_canvas');
  if(!cv || typeof orderBookState === 'undefined') return;
  const ctx = cv.getContext('2d');
  const w = cv.width, h = cv.height;
  ctx.clearRect(0, 0, w, h);
  const asks = orderBookState.asks.slice().sort((a,b) => a.price - b.price);
  const bids = orderBookState.bids.slice().sort((a,b) => b.price - a.price);
  if(!asks.length && !bids.length) return;
  const bestAsk = asks.length ? asks[0].price : null;
  const bestBid = bids.length ? bids[0].price : null;
  const mid = (bestAsk && bestBid) ? (bestAsk + bestBid) / 2 : (bestAsk || bestBid);
  const allPrices = asks.map(a => a.price).concat(bids.map(b => b.price));
  const pMin = Math.min(...allPrices), pMax = Math.max(...allPrices);
  const pad = (pMax - pMin) * 0.06 || 1;
  const x = p => ((p - pMin + pad) / (pMax - pMin + 2 * pad)) * w;
  const maxCum = Math.max(
    asks.reduce((s, a) => s + a.qty, 0),
    bids.reduce((s, b) => s + b.qty, 0), 0.001);
  const y = v => h - (v / maxCum) * (h - 24);
  // bids: кумулятив от центра влево
  let cum = 0;
  ctx.beginPath();
  ctx.moveTo(x(bestBid), h);
  bids.forEach(b => { cum += b.qty; ctx.lineTo(x(b.price), y(cum)); });
  if(bids.length) ctx.lineTo(x(bids[bids.length-1].price) - 8, y(cum));
  ctx.lineTo(x(bids.length ? bids[bids.length-1].price : pMin) - 8, h);
  ctx.closePath();
  ctx.fillStyle = 'rgba(34,197,94,.28)';
  ctx.fill();
  ctx.strokeStyle = 'rgb(34,197,94)';
  ctx.lineWidth = 1.5;
  ctx.stroke();
  // asks: кумулятив от центра вправо
  cum = 0;
  ctx.beginPath();
  ctx.moveTo(x(bestAsk), h);
  asks.forEach(a => { cum += a.qty; ctx.lineTo(x(a.price), y(cum)); });
  if(asks.length) ctx.lineTo(x(asks[asks.length-1].price) + 8, y(cum));
  ctx.lineTo(x(asks.length ? asks[asks.length-1].price : pMax) + 8, h);
  ctx.closePath();
  ctx.fillStyle = 'rgba(239,68,68,.28)';
  ctx.fill();
  ctx.strokeStyle = 'rgb(239,68,68)';
  ctx.stroke();
  // mid price line
  ctx.setLineDash([4, 4]);
  ctx.beginPath();
  ctx.moveTo(x(mid), 0); ctx.lineTo(x(mid), h);
  ctx.strokeStyle = 'rgba(255,255,255,.35)';
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = 'rgba(255,255,255,.6)';
  ctx.font = '11px sans-serif';
  ctx.fillText('bids (покупатели)', 8, 16);
  ctx.fillText('asks (продавцы)', w - 108, 16);
  ctx.fillText('$' + mid.toFixed(0), x(mid) + 4, 14);
}

/* ---------- G-01 «Гонка блоков» ---------- */
var g01State = { culprit: 3, round: 0, score: 0 };
function renderG01(box){
  g01State = { culprit: Math.floor(Math.random() * 8), round: 0, score: 0 };
  box.innerHTML = `
    <div style="background:rgba(34,197,94,.05); border:1.5px solid var(--ok); border-radius:12px; padding:16px; margin-top:12px">
      <div style="font-weight:800; color:var(--ok); margin-bottom:6px">🎮 Гонка блоков</div>
      <div style="font-size:12.5px; color:var(--mut); margin-bottom:10px">Сеть из 8 узлов. Один прислал блок с транзакцией, нарушающей правила протокола (двойная трата). Ты — честный узел. Что делать?</div>
      <div id="g01_net" style="display:flex; gap:6px; margin-bottom:10px"></div>
      <div id="g01_scenario" style="font-size:13px; color:var(--txt); margin-bottom:10px"></div>
      <div style="display:flex; gap:8px; flex-wrap:wrap" id="g01_btns">
        <button class="btn sm" onclick="g01Answer(0)">✅ Принять блок</button>
        <button class="btn sm" style="background:var(--bad)" onclick="g01Answer(1)">🚫 Отвергнуть по правилам</button>
        <button class="btn sm ghost" onclick="g01Answer(2)">⏳ Подождать следующий</button>
      </div>
      <div id="g01_out" style="margin-top:10px; font-size:12.5px"></div>
    </div>`;
  g01DrawNet();
}
function g01DrawNet(){
  const net = document.getElementById('g01_net');
  if(!net) return;
  net.innerHTML = Array.from({length:8}, (_,i) =>
    `<div style="flex:1; text-align:center; padding:8px 2px; border-radius:8px; border:1.5px solid ${i === g01State.culprit ? 'var(--bad)' : 'var(--line)'}; background:#040714">
      <div style="font-size:18px">${i === g01State.culprit ? '🦹' : '🖥️'}</div>
      <div style="font-size:10px; color:var(--mut)">узел ${i+1}</div>
    </div>`).join('');
  const sc = document.getElementById('g01_scenario');
  sc.innerHTML = `Узел <b style="color:var(--bad)">№${g01State.culprit + 1}</b> транслирует блок #842 317, в котором одна и та же монета потрачена дважды. Твой выбор:`;
  document.getElementById('g01_out').innerHTML = '';
}
function _gstat(k){ if(typeof simActionStats !== 'undefined'){ simActionStats[k] = true; if(typeof save === 'function') save(); } }
function g01Answer(choice){
  const out = document.getElementById('g01_out');
  const debrief = `<div style="margin-top:8px; padding:10px; background:#040714; border-left:3px solid var(--acc2); border-radius:6px; font-size:12px; color:var(--mut)">
    <b style="color:var(--txt)">Дебрифинг:</b> узлы не «голосуют» — каждый сам проверяет блок по правилам протокола. Блок с двойной тратой просто не принимается честными узлами, и жуликоватая ветка становится orphan-форком: канонической считается цепочка, которую протокол признаёт действительной (наибольшая суммарная работа при соблюдении всех правил).</div>`;
  if(choice === 1){ _gstat('g01');
    g01State.score++;
    out.innerHTML = `<div style="color:var(--ok); font-weight:700">✅ Верно. Твой узел отверг блок, нарушающий правила — и все честные узлы сделали то же самое независимо.</div>` + debrief;
  } else if(choice === 0){
    out.innerHTML = `<div style="color:var(--bad); font-weight:700">❌ Ошибка. Приняв невалидный блок, твой узел ушёл бы на мёртвую ветку: остальные узлы её не признают, и твои награды в ней обесценятся.</div>` + debrief;
  } else {
    out.innerHTML = `<div style="color:var(--warn); font-weight:700">🟡 Осторожно, но пассивно. Ждать можно — форк разрешится сам, — но важно понимать: ты не «ждёшь голосования», а просто не строишь поверх невалидного блока.</div>` + debrief;
  }
  out.innerHTML += `<div style="margin-top:8px"><button class="btn sm ghost" onclick="renderG01(document.getElementById('widget_g01_blockrace'))">🔄 Новый раунд</button></div>`;
}

/* ---------- G-03 «Ликвидационный коридор» ---------- */
var g03Lev = 10;
function renderG03(box){
  box.innerHTML = `
    <div style="background:rgba(239,68,68,.05); border:1.5px solid var(--bad); border-radius:12px; padding:16px; margin-top:12px">
      <div style="font-weight:800; color:var(--bad); margin-bottom:6px">🎮 Ликвидационный коридор</div>
      <div style="font-size:12.5px; color:var(--mut); margin-bottom:8px">Цена случайно блуждает; справа — стена ликвидации с буфером MMR. Чем больше плечо, тем ближе стена. Ликвидация наступает РАНЬШЕ, чем «плечо × движение», из-за поддерживающей маржи.</div>
      <div style="display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-bottom:8px; font-size:13px">
        <label>Плечо: <b id="g03_lev_lbl" style="color:var(--acc2)">x10</b></label>
        <input type="range" id="g03_lev" min="1" max="25" step="1" value="10" oninput="g03Lev=+this.value; document.getElementById('g03_lev_lbl').textContent='x'+this.value; g03Draw()">
        <button class="btn sm" onclick="g03SimMonth()">📅 Прогнать месяц (50 траекторий)</button>
      </div>
      <canvas id="g03_cv" width="560" height="260" style="width:100%; background:#040714; border-radius:10px"></canvas>
      <div id="g03_stat" style="margin-top:8px; font-size:13px"></div>
    </div>`;
  g03Draw();
}
function g03Draw(paths){
  const cv = document.getElementById('g03_cv');
  if(!cv) return;
  const ctx = cv.getContext('2d');
  ctx.clearRect(0, 0, cv.width, cv.height);
  const midY = cv.height / 2;
  // стена ликвидации: движение против позиции на ~ (1/lev - MMR-буфер)
  const mmr = 0.005;
  const liqDist = Math.max(1/g03Lev - mmr, 0.005);
  const wallX = cv.width - 30;
  const wallY = midY + liqDist * 2400;
  // буфер MMR
  const bufY = midY + (1/g03Lev) * 2400;
  ctx.fillStyle = 'rgba(239,68,68,.15)';
  ctx.fillRect(0, wallY, cv.width, Math.min(bufY - wallY, cv.height));
  ctx.strokeStyle = 'var(--bad)'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(0, wallY); ctx.lineTo(cv.width, wallY); ctx.stroke();
  ctx.fillStyle = '#ef4444'; ctx.font = '11px sans-serif';
  ctx.fillText('стена ликвидации (с буфером MMR)', 8, wallY - 5);
  ctx.fillStyle = '#22c55e';
  ctx.fillText('цена входа', 8, midY - 5);
  ctx.strokeStyle = 'rgba(255,255,255,.25)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(0, midY); ctx.lineTo(cv.width, midY); ctx.stroke();
  if(paths){
    let alive = 0;
    paths.forEach(p => {
      const hit = p.some(v => v >= wallY);
      if(!hit) alive++;
      ctx.strokeStyle = hit ? 'rgba(239,68,68,.35)' : 'rgba(34,197,94,.45)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      p.forEach((v, i) => { const x = 10 + i * (cv.width - 20) / p.length; i ? ctx.lineTo(x, v) : ctx.moveTo(x, v); });
      ctx.stroke();
    });
    const stat = document.getElementById('g03_stat');
    const pct = Math.round(alive / paths.length * 100);
    stat.innerHTML = `Выжило <b style="color:${pct > 70 ? 'var(--ok)' : 'var(--bad)'}">${pct}%</b> траекторий при плече x${g03Lev}. ` +
      (pct < 50 ? 'Больше половины путей доходят до стены даже без «плохого» рынка — чистая геометрия волатильности.' : 'Коридор шире, но хвостовые траектории всё равно пробивают стену.');
  } else {
    // одна траектория
    ctx.strokeStyle = 'var(--acc2)'; ctx.lineWidth = 2;
    let y = midY; ctx.beginPath(); ctx.moveTo(10, y);
    for(let i = 1; i < 90; i++){ y += (Math.random() - 0.5) * 18; ctx.lineTo(10 + i * (cv.width - 20) / 90, y); }
    ctx.stroke();
    document.getElementById('g03_stat').innerHTML = '<span style="color:var(--mut)">Нажми «Прогнать месяц», чтобы увидеть статистику выживания, а не один счастливый путь.</span>';
  }
}
function g03SimMonth(){ _gstat('g03');
  const cv = document.getElementById('g03_cv');
  const midY = cv.height / 2;
  const paths = [];
  for(let k = 0; k < 50; k++){
    const p = []; let y = midY;
    for(let i = 0; i < 90; i++){ y += (Math.random() - 0.5) * 18; p.push(y); }
    paths.push(p);
  }
  g03Draw(paths);
}

/* ---------- G-10 «Келли-веер» ---------- */
function renderG10(box){
  box.innerHTML = `
    <div style="background:rgba(124,58,237,.05); border:1.5px solid var(--acc1); border-radius:12px; padding:16px; margin-top:12px">
      <div style="font-weight:800; color:var(--acc1); margin-bottom:6px">🎮 Келли-веер: 1000 траекторий</div>
      <div style="font-size:12.5px; color:var(--mut); margin-bottom:8px">Монте-Карло для серии ставок (p=55%, выплата 1:1, 252 ставки). Медианы и полосы 10–90 перцентиля. Формула честного trade-off: <code>g(k·f*)/g(f*) = 2k − k²</code> → Half Kelly = 75% роста, Quarter = 43.75% роста.</div>
      <button class="btn sm" onclick="g10Run()">▶ Запустить симуляцию</button>
      <canvas id="g10_cv" width="560" height="300" style="width:100%; background:#040714; border-radius:10px; margin-top:8px"></canvas>
      <div id="g10_stat" style="margin-top:8px; font-size:12.5px"></div>
    </div>`;
}
function g10Run(){ _gstat('g10');
  const cv = document.getElementById('g10_cv');
  const ctx = cv.getContext('2d');
  ctx.clearRect(0, 0, cv.width, cv.height);
  const variants = [
    { k: 1.0,  label: 'Full Kelly',    color: '#ef4444' },
    { k: 0.5,  label: 'Half Kelly',    color: '#f59e0b' },
    { k: 0.25, label: 'Quarter Kelly', color: '#22c55e' }
  ];
  const N = 200, T = 252, pWin = 0.55;
  let statsHtml = '<div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(170px,1fr)); gap:8px">';
  const maxLog = 3.2;
  variants.forEach(v => {
    const logs = [];
    const snaps = [];
    for(let s = 0; s < N; s++){
      let eq = 1, peak = 1, maxDD = 0;
      const path = [];
      for(let t = 0; t < T; t++){
        eq *= (Math.random() < pWin) ? (1 + v.k) : (1 - v.k);
        if(eq > peak) peak = eq;
        const dd = 1 - eq / peak;
        if(dd > maxDD) maxDD = dd;
        path.push(Math.log(eq));
      }
      logs.push({ end: Math.log(eq), maxDD: maxDD });
      snaps.push(path);
    }
    // перцентильные полосы
    const bands = [];
    for(let t = 0; t < T; t++){
      const col = snaps.map(s => s[t]).sort((a, b) => a - b);
      bands.push([col[Math.floor(N*0.1)], col[Math.floor(N*0.5)], col[Math.floor(N*0.9)]]);
    }
    const yOf = lv => cv.height - 12 - (lv + 1.2) / (maxLog + 1.2) * (cv.height - 24);
    ctx.fillStyle = v.color + '22';
    ctx.beginPath();
    bands.forEach((b, t) => { const x = 8 + t * (cv.width - 16) / T; t ? ctx.lineTo(x, yOf(b[2])) : ctx.moveTo(x, yOf(b[2])); });
    for(let t = T - 1; t >= 0; t--){ ctx.lineTo(8 + t * (cv.width - 16) / T, yOf(bands[t][0])); }
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = v.color; ctx.lineWidth = 2;
    ctx.beginPath();
    bands.forEach((b, t) => { const x = 8 + t * (cv.width - 16) / T; t ? ctx.lineTo(x, yOf(b[1])) : ctx.moveTo(x, yOf(b[1])); });
    ctx.stroke();
    const ddShare = Math.round(logs.filter(l => l.maxDD > 0.5).length / N * 100);
    const med = bands[T-1][1];
    statsHtml += `<div style="background:#040714; border-radius:8px; padding:8px 10px; border:1.5px solid ${v.color}">
      <div style="font-weight:800; color:${v.color}; font-size:12.5px">${v.label}</div>
      <div style="font-size:11.5px; color:var(--mut)">Медиана капитала: <b style="color:var(--txt)">×${Math.exp(med).toFixed(1)}</b></div>
      <div style="font-size:11.5px; color:var(--mut)">Просадка &gt;50% у: <b style="color:${ddShare > 30 ? 'var(--bad)' : 'var(--ok)'}">${ddShare}%</b> траекторий</div>
      <div style="font-size:11px; color:var(--mut)">Рост: ${(2*v.k - v.k*v.k)*100 | 0}% от Full Kelly</div>
    </div>`;
  });
  statsHtml += '</div><div style="margin-top:6px; color:var(--mut); font-size:12px">Quarter Kelly сохраняет 43.75% скорости роста (2·0.25 − 0.25²), но почти обнуляет шанс пережить просадку >50%. Именно это — предмет выбора, а не «больше/меньше удачи».</div>';
  document.getElementById('g10_stat').innerHTML = statsHtml;
}

/* ---------- G-14 «FIFO-очередь налогов» ---------- */
var g14Lots = [];
function renderG14(box){
  g14Lots = [ {qty: 1, price: 5000000}, {qty: 1, price: 7000000} ];
  box.innerHTML = `
    <div style="background:rgba(6,182,212,.05); border:1.5px solid var(--acc2); border-radius:12px; padding:16px; margin-top:12px">
      <div style="font-weight:800; color:var(--acc2); margin-bottom:6px">🎮 FIFO-очередь налогов</div>
      <div style="font-size:12.5px; color:var(--mut); margin-bottom:8px">Покупки — вагончики в очереди. Продажа забирает вагоны СЛЕВА (FIFO). Налог — по полной шкале НДФЛ-2025: 13% ≤2.4 млн ₽, 15% до 5 млн, 18% до 20 млн, 20% до 50 млн, 22% свыше.</div>
      <div style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:10px; font-size:13px; align-items:center">
        <button class="btn sm" onclick="g14Buy()">➕ Купить 1 BTC (цена случайная 4–11 млн ₽)</button>
        <button class="btn sm" style="background:var(--acc1)" onclick="g14Sell()">💰 Продать 1 BTC за 9,000,000 ₽</button>
        <button class="btn sm ghost" onclick="g14Lots=[]; g14Draw()">🔄 Сброс</button>
      </div>
      <div id="g14_queue" style="display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap"></div>
      <div id="g14_out" style="font-size:12.5px"></div>
    </div>`;
  g14Draw();
}
function g14Buy(){
  g14Lots.push({ qty: 1, price: 4000000 + Math.floor(Math.random() * 70) * 100000 });
  g14Draw();
}
function g14Tax2025(base){
  const steps = [ [2400000, 0.13], [5000000, 0.15], [20000000, 0.18], [50000000, 0.20], [Infinity, 0.22] ];
  let tax = 0, prev = 0;
  for(const [lim, rate] of steps){
    if(base <= prev) break;
    tax += (Math.min(base, lim) - prev) * rate;
    prev = lim;
  }
  return Math.round(tax);
}
function _gstat14(){ _gstat('g14'); }
function g14Sell(){ _gstat('g14');
  if(!g14Lots.length){ document.getElementById('g14_out').innerHTML = '<span style="color:var(--bad)">Очередь пуста — продавать нечего.</span>'; return; }
  const lot = g14Lots.shift();
  const sellPrice = 9000000, fee = 10000;
  const base = sellPrice - lot.price - fee;
  const taxFifo = g14Tax2025(Math.max(base, 0));
  const avg = g14Lots.length ? Math.round(g14Lots.reduce((s,l) => s + l.price, 0) / (g14Lots.length + 1) ) : lot.price;
  const baseAvg = sellPrice - avg - fee;
  document.getElementById('g14_out').innerHTML = `
    <div style="background:#040714; border-radius:8px; padding:10px; border-left:3px solid var(--ok)">
      Забран лот за <b>${lot.price.toLocaleString('ru-RU')} ₽</b>. База FIFO: 9,000,000 − ${lot.price.toLocaleString('ru-RU')} − 10,000 = <b style="color:var(--ok)">${base.toLocaleString('ru-RU')} ₽</b>;
      НДФЛ: <b>${taxFifo.toLocaleString('ru-RU')} ₽</b> (${base <= 2400000 ? '13%' : 'ступень выше'}).
      <div style="margin-top:6px; color:var(--mut); font-size:12px">Если бы считали «по средней» (${avg.toLocaleString('ru-RU')} ₽), база была бы ${baseAvg.toLocaleString('ru-RU')} ₽ — метод меняет налог, поэтому 418-ФЗ фиксирует FIFO.</div>
    </div>`;
  g14Draw();
}
function g14Draw(){
  const q = document.getElementById('g14_queue');
  if(!q) return;
  q.innerHTML = g14Lots.length
    ? g14Lots.map((l, i) => `<div style="background:#040714; border:1.5px solid ${i === 0 ? 'var(--ok)' : 'var(--line)'}; border-radius:8px; padding:6px 10px; font-size:12px">🚃 1 BTC<br><span style="color:var(--mut)">${l.price.toLocaleString('ru-RU')} ₽</span>${i === 0 ? '<br><span style="color:var(--ok); font-size:10px">← продастся первым</span>' : ''}</div>`).join('')
    : '<div style="color:var(--mut); font-size:12px">Очередь пуста. Добавь покупку.</div>';
}

/* ---------- G-15 «Строитель крепости хранения» ---------- */
function renderG15(box){
  box.innerHTML = `
    <div style="background:rgba(245,158,11,.05); border:1.5px solid var(--warn); border-radius:12px; padding:16px; margin-top:12px">
      <div style="font-weight:800; color:var(--warn); margin-bottom:6px">🎮 Строитель крепости хранения</div>
      <div style="font-size:12.5px; color:var(--mut); margin-bottom:8px">Распредели 6,000,000 ₽. Правила крепости: не более 20% на одного контрагента; суммарно на площадках (CEX-A + CEX-B + DeFi) не более 40%.</div>
      <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(130px,1fr)); gap:8px; font-size:13px">
        <label>🧊 Холодный кошелёк<br><input type="number" id="g15_cold" value="66" min="0" max="100" style="width:70px"> %</label>
        <label>🏦 CEX-A<br><input type="number" id="g15_cexa" value="14" min="0" max="100" style="width:70px"> %</label>
        <label>🏦 CEX-B<br><input type="number" id="g15_cexb" value="12" min="0" max="100" style="width:70px"> %</label>
        <label>🌀 DeFi-протокол<br><input type="number" id="g15_defi" value="8" min="0" max="100" style="width:70px"> %</label>
      </div>
      <div style="display:flex; gap:8px; margin-top:10px; flex-wrap:wrap">
        <button class="btn sm" onclick="g15Check()">🛡️ Проверить крепость</button>
        <button class="btn sm ghost" onclick="g15Scenario('cexa')">🔥 Сценарий: CEX-A заморожена</button>
        <button class="btn sm ghost" onclick="g15Scenario('defi')">🔥 Сценарий: взлом DeFi</button>
      </div>
      <div id="g15_out" style="margin-top:10px; font-size:12.5px"></div>
    </div>`;
}
function g15Read(){
  return {
    cold: +(document.getElementById('g15_cold').value || 0),
    cexa: +(document.getElementById('g15_cexa').value || 0),
    cexb: +(document.getElementById('g15_cexb').value || 0),
    defi: +(document.getElementById('g15_defi').value || 0)
  };
}
function g15Check(){ _gstat('g15');
  const v = g15Read();
  const out = document.getElementById('g15_out');
  const sum = v.cold + v.cexa + v.cexb + v.defi;
  const errs = [];
  if(sum !== 100) errs.push(`Сумма долей ${sum}% ≠ 100%`);
  [['CEX-A', v.cexa], ['CEX-B', v.cexb], ['DeFi', v.defi]].forEach(([n, x]) => {
    if(x > 20) errs.push(`${n}: ${x}% > лимита 20% на контрагента`);
  });
  if(v.cexa + v.cexb + v.defi > 40) errs.push(`На площадках суммарно ${v.cexa + v.cexb + v.defi}% > 40%`);
  if(errs.length){
    out.innerHTML = `<div style="color:var(--bad); font-weight:700">❌ Крепость не выдерживает проверку:</div><ul style="margin:6px 0 0; padding-left:18px; color:var(--bad); font-size:12.5px">${errs.map(e => `<li>${e}</li>`).join('')}</ul>`;
  } else {
    out.innerHTML = `<div style="color:var(--ok); font-weight:700">✅ Крепость соответствует правилам 5.7: ни один контрагент не уносит больше 20%, площадки суммарно ≤ 40%.</div>`;
  }
}
function g15Scenario(kind){
  const v = g15Read();
  const total = 6000000;
  const frozen = kind === 'cexa' ? v.cexa : v.defi;
  const name = kind === 'cexa' ? 'CEX-A' : 'DeFi-протокол';
  const avail = total * (100 - frozen) / 100;
  document.getElementById('g15_out').innerHTML = `
    <div style="background:#040714; border-radius:8px; padding:10px; border-left:3px solid var(--bad)">
      <b>${name} недоступен на месяц.</b> Заморожено: <b style="color:var(--bad)">${(total * frozen / 100).toLocaleString('ru-RU')} ₽ (${frozen}%)</b>.<br>
      Доступный капитал: <b style="color:${frozen <= 20 ? 'var(--ok)' : 'var(--bad)'}">${avail.toLocaleString('ru-RU')} ₽</b>.
      <div style="margin-top:6px; color:var(--mut); font-size:12px">${frozen <= 20 ? 'Лимит 20% сработал: жизнь и обязательства не парализованы — в этом и смысл крепости.' : 'Доля выше лимита 20%: месяц без этой суммы бьёт по планам. Перераспредели.'}</div>
    </div>`;
}

