/* ---------- C7'. Радар компетенций ---------- */
const COMPETENCY_AXES = [
  { key: 'blockchain', label: 'Блокчейн', cats: ['infra'], lessons: ['p0_l1', 'p0_l2', 'p0_l3'] },
  { key: 'exchange', label: 'Биржа и ордера', cats: ['trading'], lessons: ['p0_l4', 'p0_l9', 'p0_l10', 'p0_l16'] },
  { key: 'charts', label: 'Графики', cats: ['metrics'], lessons: ['p0_l6', 'p0_l7', 'p0_l8'] },
  { key: 'risk', label: 'Риск', cats: ['risk'], lessons: ['p0_l12', 'p0_l13', 'p0_l14', 'p0_l15'] },
  { key: 'quant', label: 'Вероятность и матстат', cats: ['quant'], lessons: ['p1_l1', 'p1_l2', 'p1_l3', 'p1_l4'] },
  { key: 'infra', label: 'Инфраструктура', cats: ['infra'], lessons: ['p0_l17', 'p0_l18', 'p0_l19', 'p0_l20'] },
  { key: 'law', label: 'Право РФ', cats: ['ru'], lessons: ['p4_l1', 'p4_l2', 'p4_l3'] }
];

function computeCompetencies(){
  const done = (typeof lessonCheckState !== 'undefined' ? lessonCheckState : {}) || {};
  return COMPETENCY_AXES.map(ax => {
    let doneCnt = 0, total = ax.lessons.length;
    ax.lessons.forEach(id => { if(done[id] && (done[id].done || done[id].checked || done[id])) doneCnt++; });
    // ошибочные попытки по категории снижают уверенность
    let errPenalty = 0;
    if(typeof beginnerCategoryErrors !== 'undefined' && beginnerCategoryErrors){
      ax.cats.forEach(c => {
        const e = beginnerCategoryErrors[c];
        if(e && e.attempts > 0) errPenalty += (e.errors / e.attempts) * 0.4;
      });
    }
    const lessonScore = total ? doneCnt / total : 0;
    const quizBonus = (typeof topicStats !== 'undefined' && topicStats[ax.key]) ? Math.min(0.3, (topicStats[ax.key].correct || 0) / 30) : 0;
    return Math.max(0, Math.min(1, lessonScore + quizBonus - errPenalty));
  });
}

function renderCompetencyRadar(){
  const host = document.getElementById('competency_radar_box');
  if(!host || !host.isConnected) return;
  host.innerHTML = '';
  const cv = document.createElement('canvas');
  cv.width = 360; cv.height = 320;
  cv.style.cssText = 'width:100%; max-width:360px; margin:0 auto; display:block; background:#040714; border-radius:10px';
  host.appendChild(cv);
  const ctx = cv.getContext('2d');
  const cx = cv.width / 2, cy = cv.height / 2 + 6, R = 108;
  const n = COMPETENCY_AXES.length;
  const vals = computeCompetencies();
  const angle = i => -Math.PI / 2 + (i / n) * Math.PI * 2;
  // сетка
  for(let ring = 1; ring <= 4; ring++){
    ctx.strokeStyle = 'rgba(148,163,184,.18)';
    ctx.beginPath();
    for(let i = 0; i <= n; i++){
      const a = angle(i % n), r = R * ring / 4;
      const x = cx + Math.cos(a) * r, y = cy + Math.sin(a) * r;
      if(i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  // оси и подписи
  ctx.font = '11px sans-serif';
  COMPETENCY_AXES.forEach((ax, i) => {
    const a = angle(i);
    ctx.strokeStyle = 'rgba(148,163,184,.25)';
    ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + Math.cos(a) * R, cy + Math.sin(a) * R); ctx.stroke();
    ctx.fillStyle = '#cbd5e1';
    const lx = cx + Math.cos(a) * (R + 34), ly = cy + Math.sin(a) * (R + 16);
    ctx.textAlign = Math.abs(Math.cos(a)) < 0.3 ? 'center' : (Math.cos(a) > 0 ? 'left' : 'right');
    ctx.fillText(ax.label, lx, ly);
    ctx.fillStyle = 'rgba(34,197,94,.9)';
    ctx.fillText(Math.round(vals[i] * 100) + '%', lx, ly + 12);
  });
  // целевой контур выпускника (90%)
  ctx.strokeStyle = 'rgba(234,179,8,.65)';
  ctx.setLineDash([5, 4]);
  ctx.beginPath();
  for(let i = 0; i <= n; i++){
    const a = angle(i % n), r = R * 0.9;
    const x = cx + Math.cos(a) * r, y = cy + Math.sin(a) * r;
    if(i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.stroke();
  ctx.setLineDash([]);
  // полигон пользователя
  ctx.fillStyle = 'rgba(6,182,212,.25)';
  ctx.strokeStyle = '#22d3ee';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for(let i = 0; i <= n; i++){
    const a = angle(i % n), r = R * vals[i % n];
    const x = cx + Math.cos(a) * r, y = cy + Math.sin(a) * r;
    if(i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fill(); ctx.stroke();
  ctx.fillStyle = '#eab308';
  ctx.font = '10px sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText('- - цель «выпускник» (90%)', 8, cv.height - 8);
}

