function fnv1a(str){
  let h = 0x811c9dc5;
  for(let i = 0; i < str.length; i++){
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}
function mulberry32(seed){
  let a = seed >>> 0;
  return function(){
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function nextShuffleSalt(){
  let s = parseInt(localStorage.getItem('cn_shuffle_salt') || '0', 10) + 1;
  try{ localStorage.setItem('cn_shuffle_salt', String(s)); }catch(e){}
  return s;
}
// Возвращает {opts, a, explain} с переставленными вариантами; explain-массив переставляется синхронно
function shuffledOptions(q, salt){
  if(!q || !q.opts || q.opts.length < 2) return { opts: q.opts, a: (q.a !== undefined ? q.a : 0), explain: q.explain };
  const correct = q.a !== undefined ? q.a : (q.correctOpt !== undefined ? q.correctOpt : 0);
  const rng = mulberry32(fnv1a(String(q.q || '')) ^ ((salt || 0) * 0x9e3779b9));
  const idx = q.opts.map((_, i) => i);
  for(let i = idx.length - 1; i > 0; i--){
    const j = Math.floor(rng() * (i + 1));
    const tmp = idx[i]; idx[i] = idx[j]; idx[j] = tmp;
  }
  return {
    opts: idx.map(i => q.opts[i]),
    a: idx.indexOf(correct),
    explain: Array.isArray(q.explain) ? idx.map(i => q.explain[i]) : q.explain
  };
}


;

/* =========================================================================
   V3-A2: ЖУРНАЛ КОГНИТИВНЫХ ОШИБОК (Mistake Tracker)
   Классификация причины каждой ошибки → профиль в Прогрессе → влияние
   на адаптивный банк (доминирующий тип меняет подбор вопросов).
   ========================================================================= */
const MISTAKE_TYPES = [
  { id:'concept',  label:'🧩 Концептуальная', desc:'не понял саму идею' },
  { id:'calc',     label:'🧮 Расчётная', desc:'идея понятна, обсчитался' },
  { id:'lookahead',label:'🕳 Look-ahead/выжившего', desc:'подглядел будущее или красивую выборку' },
  { id:'impulse',  label:'🎢 Импульс', desc:'паника, FOMO, «выбрал наугад»' }
];
window._mistakeSeq = 0;
window.offerMistakeClassification = function(contextKey){
  const uid = 'mcl_' + (++window._mistakeSeq) + '_' + Math.random().toString(36).slice(2,7);
  (window._mistakeCtx = window._mistakeCtx || {})[uid] = contextKey;
  return `<div id="${uid}" style="margin-top:10px; padding:10px 12px; border:1px dashed var(--warn); border-radius:8px">
    <div style="font-size:11.5px; color:var(--warn); font-weight:700; margin-bottom:6px">📓 Журнал ошибок: в чём была причина? (делает тренировку умнее)</div>
    <div style="display:flex; flex-wrap:wrap; gap:6px">` +
    MISTAKE_TYPES.map(t => `<button class="btn sm ghost" style="font-size:11.5px" onclick="window.recordMistake('${uid}','${t.id}')" title="${t.desc}">${t.label}</button>`).join('') +
    `</div></div>`;
};
window.recordMistake = function(uid, typeId){
  const box = document.getElementById(uid);
  const ctx = (window._mistakeCtx || {})[uid] || 'unknown';
  let log = [];
  try{ log = JSON.parse(localStorage.getItem('cn_mistakes') || '[]'); }catch(e){}
  log.push({ t: typeId, ts: Date.now(), ctx });
  try{ localStorage.setItem('cn_mistakes', JSON.stringify(log.slice(-500))); }catch(e){}
  if(box) box.innerHTML = `<span style="font-size:12px; color:var(--ok)">✓ записано: ${MISTAKE_TYPES.find(t=>t.id===typeId).label}</span>`;
  if(document.getElementById('progress') && document.getElementById('progress').classList.contains('active-view')) renderMistakeJournal();
  showToast('📓 Тип ошибки записан — журнал обновлен', '📓');
};
window.getMistakeProfile = function(){
  let log = [];
  try{ log = JSON.parse(localStorage.getItem('cn_mistakes') || '[]'); }catch(e){}
  const counts = {}; MISTAKE_TYPES.forEach(t => counts[t.id] = 0);
  log.forEach(m => { if(counts[m.t] !== undefined) counts[m.t]++; });
  let dominant = null, max = 0;
  MISTAKE_TYPES.forEach(t => { if(counts[t.id] > max){ max = counts[t.id]; dominant = t.id; } });
  return { counts, dominant, total: log.length };
};
window.renderMistakeJournal = function(){
  const box = document.getElementById('mistake_journal');
  if(!box) return;
  const prof = getMistakeProfile();
  if(prof.total === 0){
    box.innerHTML = '<div style="color:var(--mut); font-size:13px">Пока пусто: при неверном ответе приложение предложит классифицировать причину. Это deliberately-честная практика: ошибки → данные → персональная тренировка.</div>';
    return;
  }
  const maxC = Math.max(...Object.values(prof.counts));
  const domT = prof.dominant ? MISTAKE_TYPES.find(t=>t.id===prof.dominant) : null;
  box.innerHTML = MISTAKE_TYPES.map(t => {
    const c = prof.counts[t.id];
    const pct = maxC ? Math.round(c / maxC * 100) : 0;
    return `<div style="display:flex; align-items:center; gap:10px; margin-bottom:6px">
      <span style="min-width:190px; font-size:12.5px; color:var(--txt)">${t.label}</span>
      <div style="flex:1; background:#040714; border-radius:6px; height:14px; overflow:hidden">
        <div style="width:${pct}%; height:100%; background:${t.id===prof.dominant?'var(--warn)':'var(--acc1)'}"></div>
      </div>
      <span style="min-width:30px; text-align:right; font-size:12.5px; color:var(--acc2); font-weight:700">${c}</span>
    </div>`;
  }).join('') +
  `<div style="font-size:12.5px; color:var(--mut); margin-top:8px">Всего классифицировано: ${prof.total}. ${domT ? 'Доминирует тип <b style="color:var(--warn)">' + domT.label + '</b> — адаптивная тренировка подстроена под него.' : ''}</div>` + _mistakeRecentRows();
};
/* v12 P1-5: последние контексты ошибок с кнопками перехода к источнику */
function _mistakeRecentRows(){
  try{
    const _esc = x => String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    const log = JSON.parse(localStorage.getItem('cn_mistakes') || '[]');
    const seen = {}; const rows = [];
    for(let i = log.length - 1; i >= 0 && rows.length < 6; i--){
      const m = log[i];
      if(!m || !m.ctx || m.ctx === 'unknown' || seen[m.ctx]) continue;
      seen[m.ctx] = 1;
      let nav = '';
      if(m.ctx.indexOf('lesson:') === 0){
        nav = '<button class="btn sm ghost" style="font-size:10.5px;padding:2px 8px" onclick="v10GoLesson(\'' + _esc(m.ctx.slice(7)) + '\')">📘 к уроку</button>';
      } else if(m.ctx.indexOf('ptest:') === 0){
        const ph = parseInt(m.ctx.slice(6), 10);
        if(!isNaN(ph)) nav = '<button class="btn sm ghost" style="font-size:10.5px;padding:2px 8px" onclick="switchPhaseTest(' + ph + ')">🎓 к тесту фазы</button>';
      }
      const tLab = (MISTAKE_TYPES.find(t => t.id === m.t) || {}).label || m.t;
      rows.push('<div style="display:flex;align-items:center;gap:8px;margin-top:6px;font-size:12px;color:var(--mut);flex-wrap:wrap"><span style="flex:1;min-width:200px">' + new Date(m.ts).toLocaleDateString() + ' · ' + tLab + ' · <code style="color:var(--acc2)">' + _esc(m.ctx) + '</code></span>' + nav + '</div>');
    }
    if(!rows.length) return '';
    return '<div style="margin-top:10px;border-top:1px dashed var(--line);padding-top:8px"><b style="font-size:12.5px;color:var(--txt)">Последние контексты ошибок — разберись в источнике:</b>' + rows.join('') + '</div>';
  }catch(e){ return ''; }
}

/* хук на рендер прогреса */
const _origRenderProgressStats = renderProgressStats;
renderProgressStats = function(){ _origRenderProgressStats.apply(this, arguments); renderMistakeJournal(); };

/* ---------- хуки неверных ответов (урок / тренажёр / аттестация) ---------- */
const _origLessonQuiz = handleLessonQuizAnswer;
handleLessonQuizAnswer = function(lessonId, selectedIdx, correctIdx){
  _origLessonQuiz.apply(this, arguments);
  if(selectedIdx !== correctIdx){
    const fb = document.getElementById('lquiz_fb_' + lessonId);
    if(fb) fb.innerHTML += window.offerMistakeClassification('lesson:' + lessonId);
  }
};
const _origCheckQuiz = checkQuizAnswer;
checkQuizAnswer = function(optIdx){
  const q = quiz.qs[quiz.cur];
  const qa = (q && q._sv && q._svCur === quiz.cur + '_' + quiz._shuffleSalt) ? q._sv.a : (q ? q.a : 0);
  _origCheckQuiz.apply(this, arguments);
  if(optIdx !== qa){
    const fb = document.getElementById('quiz_feedback');
    if(fb) fb.innerHTML += window.offerMistakeClassification('trainer:' + (q && q.topic ? q.topic : 'mixed'));
  }
};
const _origPhaseAnswer = checkPhaseTestAnswer;
checkPhaseTestAnswer = function(phaseNum, qIdx, optIdx){
  const test = phaseNum === 6 ? CAPSTONE_EXAM : (typeof PHASE_TESTS !== 'undefined' ? PHASE_TESTS.find(t=>t.phase===phaseNum) : null);
  const q = (window._ptView && window._ptView[phaseNum]) ? window._ptView[phaseNum][qIdx] : (test ? test.questions[qIdx] : null);
  _origPhaseAnswer.apply(this, arguments);
  if(q && q.a !== undefined && optIdx !== q.a){
    const expBox = document.getElementById('ptest_exp_' + phaseNum + '_' + qIdx);
    if(expBox) expBox.innerHTML += window.offerMistakeClassification('ptest:' + phaseNum + ':' + qIdx);
  }
};

/* ---------- влияние доминирующего типа на адаптивный банк ---------- */
/* numeric-вопросы доступны в банке адаптивной тренировки */
const ADAPTIVE_NUMERIC = [
  { topic:'risk_management', type:'numeric', q:'Полный Келли f* = 20%. Quarter Kelly — доля капитала (в %)?', answer:5, absTol:0.25, unit:'%', explain:'Quarter Kelly = f*/4 = 5%.' },
  { topic:'statistics', type:'numeric', q:'Стратегия: win rate 55%, профит +3%, убыток −3%. Ожидание на сделку (в %)?', answer:0.3, absTol:0.1, unit:'%', explain:'E = 0.55×3 − 0.45×3 = 0.3% — тонкое, но положительное.' },
  { topic:'statistics', type:'numeric', q:'Sharpe: доходность 24%, волатильность 16%, Rf 4%.', answer:1.25, absTol:0.06, unit:'', explain:'(24 − 4) / 16 = 1.25.' },
  { topic:'market_microstructure', type:'numeric', q:'Лучший бид 500, исполнение продажи 499.5. Slippage (bps)?', answer:1, absTol:0.2, unit:'bps', explain:'0.5/500 = 1 bps.' },
  { topic:'math_skew', type:'numeric', q:'Последовательность +20%, −20%. Итог (в %)?', answer:-4, absTol:0.3, unit:'%', explain:'1.2×0.8 = 0.96 → −4%: драг волатильности.' },
  { topic:'accounting', type:'numeric', q:'Куплено 1 лот за 200 000 ₽, продан за 250 000 ₽. НДФЛ 13% (в ₽)?', answer:6500, tolPct:2, unit:'₽', explain:'50 000 × 0.13 = 6 500 ₽.' }
];
if(typeof ADAPTIVE_QUESTION_BANK !== 'undefined') ADAPTIVE_QUESTION_BANK.push(...ADAPTIVE_NUMERIC);

const MISTAKE_STRATEGY = {
  concept:  'Профиль: концептуальные ошибки → вернись к уровню «Объясни просто» и Фейнману.',
  calc:     'Профиль: расчётные ошибки → в сессию добавлены числовые задачи с открытым вводом.',
  lookahead:'Профиль: look-ahead/выжившего → проверяй TRAIN/OOS/HOLDOUT на каждом графике.',
  impulse:  'Профиль: импульсивные ответы → перед кликом проговори причину вслух.'
};
window.applyMistakeBias = function(){
  const prof = getMistakeProfile();
  if(prof.dominant && prof.counts[prof.dominant] >= 3){
    if(prof.dominant === 'calc' && window.quiz && quiz.qs){
      const numPool = ADAPTIVE_NUMERIC.filter(q => q.type === 'numeric');
      if(numPool.length && !quiz.qs.some(q => q.type === 'numeric')){
        quiz.qs[quiz.qs.length - 1] = numPool[Math.floor(Math.random() * numPool.length)];
      }
    }
    /* v12 P1-6: контентные реакции вместо только toast */
    if(prof.dominant === 'concept' && window.quiz && quiz.qs && quiz.qs.length){
      const _wt = weakestTopicId();
      const pool = ((typeof ADAPTIVE_QUESTION_BANK !== 'undefined' ? ADAPTIVE_QUESTION_BANK : []) || []).filter(q => q.topic === _wt);
      if(pool.length){
        const add = pool.slice().sort(() => .5 - Math.random()).slice(0, 2);
        quiz.qs.splice(Math.max(1, quiz.qs.length - 1), 0, ...add);
        quiz.total = quiz.qs.length;
      }
    }
    if(prof.dominant === 'lookahead' && window.quiz && quiz.qs && quiz.qs.length){
      const pool = ((typeof ADAPTIVE_QUESTION_BANK !== 'undefined' ? ADAPTIVE_QUESTION_BANK : []) || []).filter(q => q.topic === 'look_ahead_bias');
      if(pool.length){
        quiz.qs.splice(Math.max(1, quiz.qs.length - 1), 0, pool[Math.floor(Math.random() * pool.length)]);
        quiz.total = quiz.qs.length;
      }
    }
    if(prof.dominant === 'impulse'){
      window._impulsePause = true; /* renderQuizQuestion включит паузу 5 секунд */
    }
    setTimeout(() => showToast('📓 ' + MISTAKE_STRATEGY[prof.dominant], '📓'), 700);
  }
};
/* v12 P1-6: слабейшая тема курса для контентных реакций */
function weakestTopicId(){
  try{
    const merged = (typeof QUANT_TOPICS !== 'undefined' ? QUANT_TOPICS : [])
      .concat(typeof MATH_ADAPTIVE_TOPICS !== 'undefined' ? MATH_ADAPTIVE_TOPICS : [], typeof EXTRA_ADAPTIVE_TOPICS !== 'undefined' ? EXTRA_ADAPTIVE_TOPICS : []);
    if(!merged.length) return null;
    return merged.slice().sort(function(a,b){ return _bayesErrOf(b.id) - _bayesErrOf(a.id); })[0].id;
  }catch(e){ return null; }
}
/* оборачиваем строителей адаптивной/смешанной сессии */
if(typeof startAdaptiveWorkout === 'function'){
  const _origAW = startAdaptiveWorkout;
  startAdaptiveWorkout = function(){ _origAW.apply(this, arguments); applyMistakeBias(); };
}
if(typeof startInterleavingSession === 'function'){
  const _origIL = startInterleavingSession;
  startInterleavingSession = function(){ _origIL.apply(this, arguments); applyMistakeBias(); };
}

/* ---------- numeric-поддержка в тренажёре (renderQuizQuestion) ---------- */
const _origRenderQuizQ = renderQuizQuestion;
renderQuizQuestion = function(){
  const q = (window.quiz && quiz.qs) ? quiz.qs[quiz.cur] : null;
  if(q && q.type === 'numeric'){
    const box = document.getElementById('quizBox');
    if(box){
      box.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px; flex-wrap:wrap; gap:8px">
        <span style="font-size:12px; font-weight:700; color:var(--mut)">Вопрос ${quiz.cur + 1} из ${quiz.total}</span>
        <span style="color:var(--warn); font-weight:700; font-size:12px">🔥 Серия: ${quizStreak}</span>
      </div>
      <div style="font-size:15px; font-weight:700; color:var(--txt); margin-bottom:8px; line-height:1.5">${q.q}</div>
      <div style="font-size:11.5px; color:var(--acc2); margin-bottom:12px">🧮 Открытый ввод (допуск ${q.absTol !== undefined ? '±' + q.absTol + ' ' + (q.unit || '') : '±' + (q.tolPct || 2) + '%'})</div>
      <div style="display:flex; gap:10px; align-items:center; flex-wrap:wrap">
        <input id="quiz_num_in" type="text" inputmode="decimal" placeholder="число" style="width:150px; background:#040714; border:1px solid var(--acc2); border-radius:8px; padding:9px 12px; color:var(--txt); font-size:14.5px; font-weight:700">
        <span style="color:var(--mut); font-size:13.5px">${q.unit || ''}</span>
        <button class="btn sm" onclick="checkQuizNumeric()">Проверить</button>
      </div>
      <div id="quiz_feedback" style="display:none; margin-top:14px; padding:12px; border-radius:10px; font-size:13px"></div>
      <div style="margin-top:16px; text-align:right">
        <button class="btn sm ghost" id="quiz_next_btn" style="display:none" onclick="nextQuizQuestion()">Следующий вопрос →</button>
      </div>`;
    }
    return;
  }
  _origRenderQuizQ.apply(this, arguments);
  /* v12 P1-6: пауза 5 секунд перед ответом при профиле impulse */
  if(window._impulsePause){
    window._impulsePause = false;
    const ibtns = document.querySelectorAll('#quiz_ans_btns .ans');
    if(ibtns.length){
      ibtns.forEach(b => b.disabled = true);
      const inote = document.createElement('div');
      inote.style.cssText = 'margin-top:10px;padding:9px 13px;border-radius:8px;font-size:12.5px;color:var(--warn);background:rgba(245,158,11,.08);border:1px dashed var(--warn)';
      inote.textContent = '⏸ Пауза (профиль импульсивных ответов): выдохни и проговори причину выбора вслух.';
      const ansBox = document.getElementById('quiz_ans_btns');
      if(ansBox && ansBox.parentNode) ansBox.parentNode.insertBefore(inote, ansBox.nextSibling);
      let left = 5;
      const iv = setInterval(() => {
        left--;
        if(left <= 0){ clearInterval(iv); ibtns.forEach(b => b.disabled = false); inote.remove(); }
        else inote.textContent = '⏸ Кнопки откроются через ' + left + ' с…';
      }, 1000);
    }
  }
};
window.checkQuizNumeric = function(){
  const q = quiz.qs[quiz.cur];
  if(!q || q.type !== 'numeric') return;
  const inp = document.getElementById('quiz_num_in');
  const fb = document.getElementById('quiz_feedback');
  if(!inp || !fb) return;
  const val = parseFloat(String(inp.value).replace(/\\s/g, '').replace(',', '.'));
  if(isNaN(val)){ showToast('Введи число.', '🧮'); return; }
  const tol = q.absTol !== undefined ? q.absTol : Math.abs(q.answer) * (q.tolPct || 2) / 100;
  const ok = Math.abs(val - q.answer) <= tol;
  inp.disabled = true;
  (quiz.results = quiz.results || []).push({ cat: q._cat || null, src: q._src || null, ok });
  if(ok){ quiz.score++; quizStreak++; } else { quizStreak = 0; }
  fb.style.display = 'block';
  fb.style.background = ok ? 'rgba(34,197,94,.15)' : 'rgba(239,68,68,.15)';
  fb.style.border = '1px solid ' + (ok ? 'var(--ok)' : 'var(--bad)');
  fb.innerHTML = (ok ? '<b>Верно! 🎯</b> ' : '<b>Ошибка! ❌</b> ') + (q.explain || q.solution || '');
  if(!ok) fb.innerHTML += window.offerMistakeClassification('trainer-num:' + (q.topic || 'numeric'));
  if(q.topic) recordTopicResult(q.topic, ok);
  else if(quiz.isAdaptive && quiz.targetTopic) recordTopicResult(quiz.targetTopic, ok);
  save();
  updateHeader();
  renderProgressStats();
  const nextBtn = document.getElementById('quiz_next_btn');
  if(nextBtn) nextBtn.style.display = 'inline-block';
};

;

/* =========================================================================
   V3-A6: ТРЕНАЖЁР — 3 УРОВНЯ МАСТЕРСТВА + ДО/ПОСЛЕ ПРЕ-КВИЗ (learning gain)
   ========================================================================= */
window.quizLevel = 1;
window.setQuizLevel = function(lvl, btn){
  window.quizLevel = lvl;
  document.querySelectorAll('#quiz_level_row .chip').forEach(c => c.classList.remove('active'));
  if(btn) btn.classList.add('active');
  startQuiz();
};
/* уровни влияют на генерацию блица по терминам */
const _origStartQuizA6 = startQuiz;
startQuiz = function(){
  if(quiz.preserveQs){ _origStartQuizA6.apply(this, arguments); return; }
  const lvl = window.quizLevel || 1;
  if(quizMode !== 'terms' && lvl !== 1){
    quiz.score = 0; quiz.cur = 0; quiz.qs = []; quiz._shuffleSalt = nextShuffleSalt();
    quiz.mode = 'standard'; quiz.isAdaptive = false; quiz.targetTopic = null;
    const sb = document.getElementById('quiz_session_banner'); if(sb) sb.innerHTML = '';
    let pool = quizMode === 'cases' ? [...QUIZ_CASES] : quizMode === 'legal' ? [...QUIZ_LEGAL] : [...QUIZ_CALC];
    const len = lvl === 2 ? Math.min(10, pool.length) : Math.min(15, pool.length);
    quiz.qs = pool.sort(() => 0.5 - Math.random()).slice(0, len);
    quiz.total = quiz.qs.length;
    renderQuizQuestion();
    return;
  }
  if(quizMode !== 'terms'){ _origStartQuizA6.apply(this, arguments); return; }
  quiz.mode = 'standard'; quiz.isAdaptive = false; quiz.targetTopic = null;
  const sb = document.getElementById('quiz_session_banner'); if(sb) sb.innerHTML = '';
  quiz.score = 0; quiz.cur = 0; quiz.total = 10; quiz.qs = [];
  quiz._shuffleSalt = nextShuffleSalt();
  const shuffled = [...TERMS].sort(() => 0.5 - Math.random()).slice(0, 10);
  quiz.qs = shuffled.map(t => {
    const others = TERMS.filter(x => x.t !== t.t).sort(() => 0.5 - Math.random()).slice(0, 3);
    if(lvl === 1){
      const allOpts = [t.t, ...others.map(o => o.t)].sort(() => 0.5 - Math.random());
      return { q: `💡 Определение: «${t.d}». О каком понятии речь?`, opts: allOpts, a: allOpts.indexOf(t.t), explain: `Верный ответ: <b>${t.t}</b> (${CATS[t.c][0]}). ${t.d}` };
    }
    if(lvl === 2){
      const allOpts = [t.t, ...others.map(o => o.t)].sort(() => 0.5 - Math.random());
      return { q: `🎭 Бытовая аналогия: «${t.a}». Какой это термин?`, opts: allOpts, a: allOpts.indexOf(t.t), explain: `Верный ответ: <b>${t.t}</b> (${CATS[t.c][0]}). ${t.d}` };
    }
    const defOpts = [t.d, ...others.map(o => o.d)].sort(() => 0.5 - Math.random());
    return { q: `🏛 Термин: «${t.t}». Выбери верное определение.`, opts: defOpts, a: defOpts.indexOf(t.d), explain: `Эталон: ${t.d}` };
  });
  quiz.total = quiz.qs.length;
  renderQuizQuestion();
};

/* ---------- до/после пре-квиз (3 вопроса) ---------- */
window._prepost = null;
window.startSessionWithPrecheck = function(launchFn, pool){
  const qs = [...pool].sort(() => 0.5 - Math.random()).slice(0, 3).filter(q => q.opts && q.opts.length);
  if(qs.length < 3){ launchFn(); return; }
  window._prepost = { qs, pre: 0, answered: 0, launchFn };
  showPrePostModal('pre');
};
window.showPrePostModal = function(stage){
  const st = window._prepost;
  const old = document.getElementById('prepost_modal');
  if(old) old.remove();
  const modal = document.createElement('div');
  modal.id = 'prepost_modal';
  modal.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,.88); z-index:120000; display:flex; justify-content:center; align-items:center; padding:14px; backdrop-filter:blur(6px)';
  const isPre = stage === 'pre';
  modal.innerHTML = `
    <div style="background:#090d1f; border:2px solid var(--acc2); border-radius:16px; max-width:560px; width:100%; padding:22px; max-height:90vh; overflow-y:auto">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px">
        <h3 style="margin:0; font-size:17px; color:var(--txt)">${isPre ? '📋 Входной опрос (3 вопроса)' : '📋 Контрольный опрос (те же 3 вопроса)'}</h3>
        ${isPre ? '<button class="btn sm ghost" onclick="window.finishPrePost(true)">Пропустить</button>' : ''}
      </div>
      <div style="font-size:12.5px; color:var(--mut); margin-bottom:14px; line-height:1.5">${isPre ? 'Ответь честно «как есть» — это не экзамен. После сессии сравним Δ до/после, чтобы увидеть прирост.' : 'Финал: те же вопросы — покажем честный прирост Δ.'}</div>
      <div id="prepost_body"></div>
      <div id="prepost_delta" style="display:none; margin-top:12px"></div>
      <div style="text-align:right; margin-top:14px"><button class="btn sm" id="prepost_next" style="display:none" onclick="window.finishPrePost()">${isPre ? 'Начать сессию →' : 'Готово'}</button></div>
    </div>`;
  document.body.appendChild(modal);
  st.answered = 0;
  const body = modal.querySelector('#prepost_body');
  body.innerHTML = st.qs.map((q, qi) => {
    const sv = (typeof shuffledOptions === 'function') ? shuffledOptions(q, qi * 17 + 3) : q;
    return `<div style="margin-bottom:14px">
      <div style="font-size:13.5px; font-weight:700; color:var(--txt); margin-bottom:6px">${qi + 1}. ${q.q}</div>
      <div id="prepost_opts_${qi}" style="display:flex; flex-direction:column; gap:5px">
        ${sv.opts.map((o, oi) => `<button class="ans sm" style="text-align:left; font-size:12.5px; padding:7px 10px" onclick="window.answerPrePost(${qi}, ${oi}, ${sv.a})">${o}</button>`).join('')}
      </div>
    </div>`;
  }).join('');
  if(!isPre){
    const delta = modal.querySelector('#prepost_delta');
    delta.style.display = 'block';
    delta.innerHTML = `<div style="font-size:13px; color:var(--txt)">До: ${st.pre}/3 · после: <b id="prepost_post_cnt">0</b>/3</div>`;
  }
};
window.answerPrePost = function(qi, oi, correct){
  const st = window._prepost;
  const box = document.getElementById('prepost_opts_' + qi);
  if(!box || st._answered && st._answered[qi]) return;
  st._answered = st._answered || {};
  st._answered[qi] = true;
  st.answered++;
  box.querySelectorAll('button').forEach((b, bi) => {
    b.disabled = true;
    if(bi === correct) b.classList.add('ok'); else if(bi === oi) b.classList.add('bad');
  });
  const stage = document.querySelector('#prepost_modal h3').textContent.includes('Входной') ? 'pre' : 'post';
  if(oi === correct){ if(stage === 'pre') st.pre++; else st.post = (st.post || 0) + 1; }
  const pc = document.getElementById('prepost_post_cnt');
  if(pc) pc.textContent = st.post || 0;
  if(st.answered >= st.qs.length){
    const nxt = document.getElementById('prepost_next');
    if(nxt) nxt.style.display = 'inline-block';
    if(stage === 'post'){
      const delta = (st.post || 0) - st.pre;
      const dl = document.getElementById('prepost_delta');
      dl.innerHTML = `<div style="font-size:14px; color:var(--txt); font-weight:700">Δ до/после: <span style="color:${delta >= 0 ? 'var(--ok)' : 'var(--bad)'}">${delta >= 0 ? '+' : ''}${delta}</span> — ${delta > 0 ? 'прирост зафиксирован, сессия сработала.' : delta === 0 ? 'база устойчива; точки роста — в журнале ошибок.' : 'похоже на усталость — перерыв или повторное извлечение.'}</div>`;
      if(delta > 0) showToast('📈 Δ до/после: +' + delta + ' — прирост зафиксирован!', '📈');
    }
  }
};
window.finishPrePost = function(skip){
  const st = window._prepost;
  const modal = document.getElementById('prepost_modal');
  if(modal) modal.remove();
  if(skip){ window._prepost = null; return; }
  const stageWasPre = !st.postCalled;
  st.postCalled = true;
  if(stageWasPre && st.launchFn){
    const qs = st.qs;
    const fn = st.launchFn;
    fn();
    quiz._prepost = qs;
    quiz._prepostPre = st.pre;
  }
};
/* оборачиваем запуск смешанной и адаптивной сессий */
if(typeof startInterleavingSession === 'function'){
  const _il = startInterleavingSession;
  startInterleavingSession = function(){
    window.startSessionWithPrecheck(() => _il(), typeof ADAPTIVE_QUESTION_BANK !== 'undefined' ? ADAPTIVE_QUESTION_BANK.filter(q => q.opts) : []);
  };
}
if(typeof startAdaptiveWorkout === 'function'){
  const _aw = startAdaptiveWorkout;
  startAdaptiveWorkout = function(){
    window.startSessionWithPrecheck(() => _aw(), typeof ADAPTIVE_QUESTION_BANK !== 'undefined' ? ADAPTIVE_QUESTION_BANK.filter(q => q.opts) : []);
  };
}
/* пост-опрос в конце сессии */
const _origRQA6 = renderQuizQuestion;
renderQuizQuestion = function(){
  if(quiz && quiz.qs && quiz.cur >= quiz.total && quiz._prepost && quiz._prepost.length){
    const qs = quiz._prepost; const pre = quiz._prepostPre;
    quiz._prepost = null;
    _origRQA6.apply(this, arguments);
    setTimeout(() => {
      window._prepost = { qs, pre, answered: 0, postCalled: true, launchFn: null };
      showPrePostModal('post');
    }, 400);
    return;
  }
  _origRQA6.apply(this, arguments);
};

;

