  box.innerHTML = `<div style="background:rgba(234,179,8,.05); border:1.5px solid var(--warn); border-radius:12px; padding:16px; margin:16px 0">
    <div style="font-size:12px; font-weight:800; color:var(--warn); text-transform:uppercase; margin-bottom:8px">🔐 Разложи 12 слов по местам хранения</div>
    ${!st.done ? `<div style="font-size:12px; color:var(--mut); margin-bottom:10px">1) Кликни слово. 2) Кликни «⬇ положить» у места. Размещено: ${totalPlaced}/12.</div>
    <div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:12px">${wordsHtml || '<span style="color:var(--mut); font-size:12px">Все слова размещены.</span>'}</div>` : ''}
    ${spotsHtml}
    ${!st.done && totalPlaced === 12 ? `<button class="btn" style="background:var(--acc2); margin-top:6px" onclick="window._v4seed.done=true; renderV4SeedGame(document.getElementById('widget_v4_seed'))">🔒 Проверить хранилище</button>` : ''}
    ${resultHtml}
    ${st.done ? `<button class="btn sm ghost" style="margin-top:10px" onclick="window._v4seed=null; renderV4SeedGame(document.getElementById('widget_v4_seed'))">↺ Сыграть ещё раз</button>` : ''}
  </div>`;
