(function patchPsyWidgets(){
  const prev = window.renderPhase0Widget;
  window.renderPhase0Widget = function(widgetId){
    if(PSY_WIDGET_IDS.indexOf(widgetId) !== -1){
      const box = document.getElementById(widgetId);
      if(box && !box.dataset.rendered){
        box.dataset.rendered = '1';
        window['PSY_render_' + widgetId](box);
      }
      return;
    }
    return prev(widgetId);
  };
})();
