/* ---------- Детекторы W3: стакан 1–4, свечи 5–6, фандинг 9–10 ---------- */
function obStats(ob){
  const bestBid = ob.bids[0][0], bestAsk = ob.asks[0][0];
  const mid = (bestBid + bestAsk) / 2;
  const spreadBps = (bestAsk - bestBid) / mid * 10000;
  let bidVol = 0, askVol = 0;
  ob.bids.forEach(x => { if(x[0] >= mid * 0.995) bidVol += x[1]; });
  ob.asks.forEach(x => { if(x[0] <= mid * 1.005) askVol += x[1]; });
  // толстая стена: объём уровня в 4+ раза больше медианы соседей
  const all = ob.bids.slice(0, 20).map(x => ['bid', x[0], x[1]]).concat(ob.asks.slice(0, 20).map(x => ['ask', x[0], x[1]]));
  const vols = all.map(x => x[2]).slice().sort((a, b) => a - b);
  const med = vols[Math.floor(vols.length / 2)] || 0;
  let wall = null;
  const wallMult = (window.V10WallMult ? window.V10WallMult(all, med) : 4); /* v10/Д14-ДЕФ-5: адаптивный порог стены */
  all.forEach(x => { if(med > 0 && x[2] >= med * wallMult && (!wall || x[2] > wall[2])) wall = x; });
  return { mid: mid, spreadBps: spreadBps, bidVol: bidVol, askVol: askVol, wall: wall, med: med };
}

