function liveTaskHTML(t){
  const ready = !!LIVE.data[t.src];
  if(ready){ try{ t._frozen = t.answer(); }catch(e){ t._frozen = null; } } /* v10/ДЕФ-4: эталон заморожен при показе */
  return '<div style="background:var(--card);border:1px solid var(--acc2);border-radius:12px;padding:14px 16px;margin-bottom:10px">' +
    '<div style="font-weight:800;font-size:13px;color:var(--txt);margin-bottom:6px">✍️ Задание: ' + t.title + '</div>' +
    '<div style="font-size:11.5px;color:var(--mut);margin-bottom:8px">' + t.hint + '</div>' +
    (ready
      ? '<div style="display:flex;gap:8px;align-items:center">' +
          '<input id="live_task_in_' + t.id + '" type="number" step="any" placeholder="ответ' + (t.unit ? ', ' + t.unit : '') + '" style="flex:1;max-width:180px;background:#040714;border:1px solid var(--line);border-radius:8px;padding:8px 10px;color:var(--txt);font-family:var(--mono)">' +
          '<button class="btn sm" onclick="liveTaskCheck(\'' + t.id + '\')">Проверить</button>' +
        '</div><div id="live_task_fb_' + t.id + '" style="margin-top:8px"></div>'
      : '<div style="font-size:12px;color:var(--mut)">Нужны данные: подключи источник «' + LIVE_SOURCES[t.src].name + '».</div>') +
  '</div>';
}

window.LIVE_TASKS = LIVE_TASKS;
function liveTaskCheck(id){
  const t = LIVE_TASKS.find(x => x.id === id);
  const inp = document.getElementById('live_task_in_' + id);
  const fb = document.getElementById('live_task_fb_' + id);
  if(!t || !inp || !fb) return;
  const val = parseFloat(String(inp.value).replace(',', '.'));
  if(!isFinite(val)){
    fb.innerHTML = '<div style="font-size:12px;color:var(--warn)">Введи число.</div>';
    return;
  }
  const truth = (t._frozen != null && isFinite(t._frozen)) ? t._frozen : t.answer(); /* v10/ДЕФ-4 */
  const tol = Math.abs(truth) * 0.2;
  const ok = Math.abs(val - truth) <= Math.max(tol, Math.abs(truth) * 0.001 + 1e-9);
  const obs = COACH.collect().filter(o => o.src === t.src)[0];
  fb.innerHTML = ok
    ? '<div style="font-size:12.5px;color:var(--ok);line-height:1.55">✅ Верно: ' + (Math.round(truth * 1000) / 1000) + ' ' + t.unit + '. Считаешь живой рынок как аппарат — допуск ±20%.</div>' +
      (obs ? '<div style="margin-top:8px">' + coachCardHTML(obs) + '</div>' : '')
    : '<div style="font-size:12.5px;color:var(--bad);line-height:1.55">❌ Не сходится. Эталон сейчас: ' + (Math.round(truth * 1000) / 1000) + ' ' + t.unit + ' (допуск ±20%). Пересчитай или сверься с панелью — и попробуй ещё раз.</div>';
  if(ok && typeof COACH !== 'undefined'){
    COACH.markSeen('task_' + id);
  }
}
window.liveTaskCheck = liveTaskCheck;

