(function hookLessonLive(){
  const orig = window.openFullscreenLesson;
  if(typeof orig !== 'function') return;
  window.openFullscreenLesson = function(id){
    const r = orig.apply(this, arguments);
    setTimeout(() => {
      try{
        if(!LESSON_LIVE_MAP[id]) return;
        if(!(typeof lessonsDone === 'object' && lessonsDone[id] === 1)) return;
        if(document.getElementById('lesson_live_box')) return;
        const modal = document.getElementById('lessonFullscreenReaderModal');
        if(!modal) return;
        const anchor = modal.querySelector('.lblock.quiz, .lblock.recap') || modal.querySelector('.lblock');
        if(anchor) anchor.insertAdjacentHTML('afterend', lessonLiveButtonHTML(id));
      }catch(e){}
    }, 150);
    return r;
  };
  // после completeLessonWithMastery кнопка появляется сразу, без переоткрытия
  const origComplete = window.completeLessonWithMastery;
  if(typeof origComplete === 'function'){
    window.completeLessonWithMastery = function(id){
      const r = origComplete.apply(this, arguments);
      setTimeout(() => {
        try{
          if(!LESSON_LIVE_MAP[id] || document.getElementById('lesson_live_box')) return;
          const modal = document.getElementById('lessonFullscreenReaderModal');
          if(!modal) return;
          const anchor = modal.querySelector('.lblock.quiz, .lblock.recap') || modal.querySelector('.lblock');
          if(anchor) anchor.insertAdjacentHTML('afterend', lessonLiveButtonHTML(id));
        }catch(e){}
      }, 400);
      return r;
    };
  }
})();

