/* ---------- классификатор: словарь + наивный Байес ---------- */
function newsWordCounts(){
  try{ return JSON.parse(localStorage.getItem('cn_news_word_counts') || '{}'); }catch(e){ return {}; }
}
function classifyNewsType(text, categories){
  const t = ((text || '') + ' ' + (categories || []).join(' ')).toLowerCase().replace(/ё/g, 'е');
  let best = null, bestScore = 0;
  const scores = {};
  Object.keys(NEWS_TYPES).forEach(k => {
    let s = (categories || []).reduce((sum, c) => sum + (c.toLowerCase().includes(k) ? 2 : 0), 0);
    NEWS_TYPES[k].w.forEach(w => { if(t.includes(w)) s += 1; });
    const wc = newsWordCounts();
    Object.keys(wc).forEach(word => { if(t.includes(word) && wc[word][k]) s += wc[word][k].n * 0.4; });
    scores[k] = s;
    if(s > bestScore){ best = k; bestScore = s; }
  });
  const total = Object.values(scores).reduce((a, b) => a + b, 0);
  return { type: best, score: bestScore, confident: bestScore >= 2, confidence: total ? Math.round(bestScore / total * 100) : 0, scores: scores };
}
window.classifyNewsType = classifyNewsType;

/* ---------- извлечение чисел ---------- */
function newsExtract(text){
  const out = { money: '', percents: [], dates: [] };
  const money = text.match(/\$\s?[\d,.]+\s?(млн|млрд|тыс)?/);
  if(money) out.money = money[0].replace(/\s+/g, ' ');
  const pc = text.match(/\d+([,.]\d+)?%/g);
  if(pc) out.percents = pc;
  const d = text.match(/(\d{1,2} [а-яА-Я]+ \d{4})|(\d{4}-\d{2}-\d{2})|(в \d{4} году)/);
  if(d) out.dates = [d[0]];
  return out;
}
window.newsExtract = newsExtract;

/* ---------- 7 шаблонов карточек (написаны человеком) ---------- */
