/* =========================================================================
   N4 · Гейтинг и таймер внимания: лента открывается после уроков 2.1–2.2,
   анти-FUD после 0.18; таймер чтения 10 мин → карточка П6 «тяга к движению»
   ========================================================================= */

/* ---------- гейтинг ---------- */
function newsGateCheck(){
  // если LESSONS не содержит id — гейт снимается (безопасный fallback)
  const need = ['p2_l1', 'p2_l2'];
  const missing = need.filter(id => !(typeof lessonsDone === 'object' && lessonsDone[id] === 1));
  const antiNeed = ['p0_l18'];
  const antiMissing = antiNeed.filter(id => !(typeof lessonsDone === 'object' && lessonsDone[id] === 1));
  return {
    open: missing.length === 0,
    missing: missing,
    antiOpen: antiMissing.length === 0,
    antiMissing: antiMissing
  };
}
window.newsGateCheck = newsGateCheck;

/* ---------- таймер внимания ---------- */
const NEWS_TIMER_KEY = 'cn_news_timer';
function newsTimerGet(){
  try{ return JSON.parse(localStorage.getItem(NEWS_TIMER_KEY) || '{"elapsed":0,"started":null}'); }catch(e){ return { elapsed: 0, started: null }; }
}
function newsTimerSave(st){
  try{ localStorage.setItem(NEWS_TIMER_KEY, JSON.stringify(st)); }catch(e){}
}
let newsTimerId = null;
function newsTimerStart(){
  if(newsTimerId) return;
  newsTimerId = setInterval(function(){
    const st = newsTimerGet();
    if(!st.started) st.started = Date.now();
    st.elapsed += 30;
    newsTimerSave(st);
    const el = document.getElementById('news_attention_banner');
    if(st.elapsed >= 600 && !el){ // 10 минут = 600 сек
      const view = document.getElementById('live');
      if(view && view.classList.contains('active') && sessionStorage.getItem('cn_live_sub') === 'news'){
        const coachCol = document.getElementById('live_coach_col');
        if(coachCol){
          coachCol.insertAdjacentHTML('afterbegin',
            '<div id="news_attention_banner" style="background:rgba(245,158,11,.1);border:1px solid var(--warn);border-radius:12px;padding:12px 16px;margin-bottom:12px">' +
              '<div style="font-weight:800;font-size:12.5px;color:var(--warn);margin-bottom:4px">🧘 Тяга к движению растёт — 10 минут ленты</div>' +
              '<div style="font-size:12px;color:var(--txt);line-height:1.55;margin-bottom:8px">Длинная лента кормит тягу к движению: информационный поток кажется обязательным, а 90% заголовков — шум. Остаточная привычка: фиксируй понятные и закрывай.</div>' +
              '<div style="display:flex;gap:8px">' +
                '<button class="btn sm ghost" onclick="newsTimerDismiss()">Закрыть ленту</button>' +
                '<button class="btn sm ghost" onclick="newsTimerDismiss(this)">Записать в журнал</button>' +
              '</div>' +
            '</div>');
        }
      }
    }
    const lbl = document.getElementById('news_timer_lbl');
    if(lbl){
      const m = Math.floor(st.elapsed / 60);
      lbl.textContent = '⏱ лента: ' + m + ' мин';
      if(m >= 10) lbl.style.color = 'var(--warn)';
    }
  }, 30000);
}
window.newsTimerStart = newsTimerStart;

function newsTimerDismiss(btn){
  const el = document.getElementById('news_attention_banner');
  if(el) el.remove();
  const st = newsTimerGet();
  st.elapsed = 0; st.started = Date.now();
  newsTimerSave(st);
  if(btn && btn.textContent.includes('журнал')){
    if(typeof showToast === 'function') showToast('📝 Отмечено: тяга к движению зафиксирована до следующего раза', '🧘');
    else alert('Записано в журнальные заметки');
  }
  const lbl = document.getElementById('news_timer_lbl');
  if(lbl){ lbl.textContent = '⏱ лента: 0 мин'; lbl.style.color = ''; }
}
window.newsTimerDismiss = newsTimerDismiss;

/* старт/стоп таймера при переходе на субвкладку «Новости» */
(function patchNewsSwitchForTimer(){
  const prev = window.newsSwitchSub;
  window.newsSwitchSub = function(id){
    prev(id);
    if(id === 'news'){
      const st = newsTimerGet();
      if(!st.started){ st.started = Date.now(); newsTimerSave(st); }
      newsTimerStart();
    } else if(newsTimerId){
      clearInterval(newsTimerId);
      newsTimerId = null;
    }
  };
})();

/* ---------- патч renderNewsView: гейтинг + таймер-лейбл + скрытие анти-FUD ---------- */
(function patchNewsViewForGate(){
  const prev = window.renderNewsView;
  window.renderNewsView = function(){
    const g = newsGateCheck();
    if(!g.open){
      return '<div style="background:var(--card);border:1px dashed var(--line);border-radius:12px;padding:20px;text-align:center">' +
        '<div style="font-size:32px;margin-bottom:8px">🔒</div>' +
        '<div style="font-weight:800;font-size:14px;color:var(--txt);margin-bottom:6px">Лента новостей откроется после уроков</div>' +
        '<div style="font-size:12.5px;color:var(--mut);line-height:1.6;margin-bottom:10px">Сначала пройди: ' + g.missing.map(id => '«' + id.replace('p', '').replace('_l', '.') + '»').join(' и ') + ' — там объясняется, как читать информационный поток без ущерба.</div>' +
        '<button class="btn sm" onclick="go(\'lessons\')">🎓 К урокам</button>' +
      '</div>';
    }
    let html = prev();
    // лейбл таймера в заголовок
    html = html.replace('📰 Лента новостей</div>', '📰 Лента новостей</div><div id="news_timer_lbl" style="font-size:11px;color:var(--mut)"></div>');
    // если antiFud не открыт — показываем замок вместо упражнения
    if(!g.antiOpen){
      html = html.replace('🛡️ Анти-FUD / анти-хайп', '🔒 Анти-FUD');
    }
    return html;
  };
})();

/* =========================================================================
   M1 · AI-НАСТАВНИК «М.» — клиент, гейт тарифа «Макс», панель в уроке
   ========================================================================= */

/* ---------- тариф ---------- */
function mentorTier(){
  try{ return localStorage.getItem('cn_tier_override') || window.__TIER__ || 'demo'; }catch(e){ return 'demo'; }
}
function mentorIsMax(){
  return mentorTier() === 'max';
}
window.mentorTier = mentorTier;
window.mentorIsMax = mentorIsMax;

/* ---------- лимит 30 действий/день ---------- */
const MENTOR_LIMIT = 30;
function mentorUsageToday(){
  const key = 'cn_mentor_usage';
  const today = new Date().toISOString().slice(0, 10);
  try{
    const st = JSON.parse(localStorage.getItem(key) || '{}');
    if(st.day !== today) return { day: today, n: 0 };
    return st;
  }catch(e){ return { day: today, n: 0 }; }
}
function mentorLimitReached(){
  return mentorUsageToday().n >= MENTOR_LIMIT;
}
window.mentorLimitReached = mentorLimitReached;
window.MENTOR_LIMIT = MENTOR_LIMIT;

/* ---------- клиент ---------- */
const MENTOR = {
  deviceId: (function(){
    let id = null;
    try{ id = localStorage.getItem('cn_mentor_device'); }catch(e){}
    if(!id){
      id = 'dev-' + Math.random().toString(36).slice(2, 10);
      try{ localStorage.setItem('cn_mentor_device', id); }catch(e){}
    }
    return id;
  })(),
  mock: (function(){
    return new URLSearchParams(location.search).get('mockai') === '1';
  })(),
  countUsed(){
    const today = new Date().toISOString().slice(0, 10);
    const st = mentorUsageToday();
    if(st.day === today) st.n++;
    else { st.day = today; st.n = 1; }
    try{ localStorage.setItem('cn_mentor_usage', JSON.stringify(st)); }catch(e){}
  },
  buildLessonText(lessonId, maxChars){
    maxChars = maxChars || 6000;
    try{
      const l = LESSONS.find(x => x.id === lessonId);
      if(!l) return '';
      const parts = [];
      (l.blocks || []).forEach(b => {
        if(b.type === 'concept'){
          ['level1','level2','level3','level4','analogy'].forEach(k => { if(b[k]) parts.push(b[k]); });
        } else if(b.type === 'recap' && b.points){
          parts.push(b.points.join('\n'));
        }
      });
      let text = 'Урок «' + (l.title || '') + '» (id ' + l.id + '):\n' + parts.join('\n\n');
      if(text.length > maxChars) text = text.slice(0, maxChars) + '\n…';
      return text;
    }catch(e){ return ''; }
  },
  filter(text){
    const banned = ['покупай', 'продавай', 'цена вырастет', 'будет рост', 'рекомендую открыть позицию', 'сигнал к покупке', 'сигнал к продаже'];
    const clean = String(text || '');
    for(const b of banned){
      if(clean.toLowerCase().includes(b.toLowerCase())){
        return 'Здесь я останусь при материале урока: давай разберём то, что в нём есть.';
      }
    }
    return clean;
  },
  base(){
    try{ return localStorage.getItem('cn_mentor_api_base') || ''; }catch(e){ return ''; }
  },
  async ask(action, lessonId, payload){
    if(mentorLimitReached()) throw new Error('limit');
    if(!navigator.onLine) throw new Error('offline');
    const text = this.buildLessonText(lessonId);
    if(this.mock){
      this.countUsed();
      return Promise.resolve(this.mockAnswer(action, lessonId, payload));
    }
    const r = await fetch(this.base() + '/api/mentor/ask', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: action, lessonId: lessonId, lessonText: text, deviceId: this.deviceId, payload: payload })
    });
    if(r.status === 429) throw new Error('limit');
    if(!r.ok) throw new Error('HTTP ' + r.status);
    const d = await r.json();
    this.countUsed();
    return { text: this.filter(d.text), json: d.json };
  },
  mockAnswer(action, lessonId, payload){
    const mk = (text, json) => ({ text: text, json: json });
    if(action === 'feynman'){
      const v = (payload && payload.explanation || '').trim();
      const verdict = !v ? 'missed' : v.length > 40 ? 'understood' : 'partial';
      /* v10/ДЕФ-22: демо-вердикт честно помечен — он проверяет длину, а не понимание */
      return mk('', { verdict: verdict, demo: true, gaps: verdict === 'understood' ? [] : ['добавь конкретный пример из урока'], advice: '🎭 ДЕМО-вердикт (правило «длина >40 символов», не ИИ): переформулируй через «как будто» из раздела аналогий.' });
    }
    if(action === 'rephrase'){
      const kind = (payload && payload.kind) || 'simpler';
      return mk('Перефраз («' + kind + '»): суть — раздираем сложное на плоские слова без потери смысла.', null);
    }
    if(action === 'socratic'){
      return mk('Хорошо. Тогда такой вопрос: ' + ((payload && payload.step || 1) < 3 ? 'какое условие делает это правилом, а не исключением?' : 'Итог из материала: правило срабатывает, когда выполнено условие.'), null);
    }
    if(action === 'tasker'){
      return mk('', { story: 'Новая задача: маржа $2 000, плечо ×5. При каком движении против позиции ликвидация?', params: { leverage: 5 } });
    }
    if(action === 'hint'){
      return mk('Ступень ' + (payload && payload.step || 1) + ': смотри на величины, которые сравниваются, а не на итоговое число.', null);
    }
    if(action === 'critique'){
      return mk('', { falsifiable: { verdict: 'warn', note: 'нет формального критерия' }, data_needed: { verdict: 'ok', note: 'дневные свечи достаточно' }, edge_source: { verdict: 'warn', note: 'не показано, почему преимущество не удача' }, capacity: { verdict: 'ok', note: 'лимита объёма хватит' }, regime_risk: { verdict: 'fail', note: 'режим тренда сломает' }, summary: 'есть проверяемость, но преимущество не проработано' });
    }
    if(action === 'revise'){
      return mk('', { loopholes: [{ quote: payload && payload.quote || 'по возможности', why_vague: 'нет числа рядом', fix_suggestion: 'укажи конкретный порог: «не более 2% на сделку»' }], solid: ['есть kill_criteria с порогом'] });
    }
    if(action === 'diagnose'){
      return mk('', { trap_type: 'concept', personal_note: 'Эта ошибка повторяется у тебя в смежных понятиях.', review_pointer: 'Определение bid/ask в уроке 0.4' });
    }
    if(action === 'spar'){
      const st = (payload && payload.stage) || 1;
      return mk(st === 1 ? 'Сильная сторона: ликвидность BTC реально выше остальных.' : (st === 2 ? 'Контраргумент: низкая просадка ≠ низкий риск хвостов.' : 'Класс: проверяемое. Но концентрация мнения — опасность спарринга.'), null);
    }
    if(action === 'explain'){
      const kind = (payload && payload.kind) || 'simpler';
      const sel = (payload && payload.selection) || '';
      return mk('Объяснение («' + kind + '»): ' + (sel ? sel.slice(0, 60) + ' — это про то, что урок учит осторожности с деньгами.' : 'Перефраз простыми словами.'), null);
    }
    return mk('М. не придумал ответа.', null);
  }
};
window.MENTOR = MENTOR;

/* ---------- апселл ---------- */
function mentorUpsellModal(){
  if(sessionStorage.getItem('mentor_upsell_closed')) return;
  const modal = document.createElement('div');
  modal.id = 'mentor_upsell_modal';
  modal.style.cssText = 'position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(0,0,0,.85);z-index:100000;display:flex;justify-content:center;align-items:center;padding:16px;backdrop-filter:blur(6px)';
  modal.innerHTML = '<div style="background:#090d1f;border:2px solid var(--acc2);border-radius:16px;max-width:420px;padding:24px">' +
    '<h3 style="margin:0 0 8px;font-size:17px;color:var(--txt)">🤖 Наставник М.</h3>' +
    '<div style="font-size:13px;color:var(--txt);line-height:1.6;margin-bottom:18px">AI-разбор уроков доступен на тарифе «Макс». Отвечает только по материалу открытого урока — без прогнозов и рекомендаций.</div>' +
    '<div style="display:flex;gap:10px;justify-content:flex-end">' +
      '<button class="btn sm ghost" onclick="sessionStorage.setItem(\'mentor_upsell_closed\',\'1\');document.getElementById(\'mentor_upsell_modal\').remove()">Позже</button>' +
      '<button class="btn sm" onclick="sessionStorage.setItem(\'mentor_upsell_closed\',\'1\');document.getElementById(\'mentor_upsell_modal\').remove()">Перейти на Макс</button>' +
    '</div></div>';
  document.body.appendChild(modal);
}
window.mentorUpsellModal = mentorUpsellModal;

/* ---------- панель ---------- */
function mentorPanelHTML(){
  return '<div id="mentor_panel" style="position:fixed;top:0;right:0;width:380px;max-width:96vw;height:100vh;background:var(--bg);border-left:1px solid var(--line);z-index:1000002;box-shadow:-10px 0 40px rgba(0,0,0,.5);display:flex;flex-direction:column">' +
    '<div style="padding:14px 18px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center">' +
      '<div style="display:flex;align-items:center;gap:10px">'+kryptikAvatar('neutral',48)+'<div><div style="font-weight:800;font-size:15px;color:var(--txt)">Криптик</div><div id="kryptik_panel_status" style="font-size:11.5px;color:var(--mut);font-style:italic">'+kryptikSay('hint_used')+'</div></div></div>' +
      '<button class="btn sm ghost" id="mentor_settings_btn" title="Настройки наставника" onclick="mentorSettingsRender()" style="margin-right:8px">⚙️</button>' +
      '<button class="btn sm ghost" onclick="mentorClosePanel()">✕</button>' +
    '</div>' +
    '<div style="padding:14px 18px;overflow-y:auto;flex:1" id="mentor_panel_body"></div>' +
    '<div style="padding:10px 18px;border-top:1px solid var(--line);font-size:10px;color:var(--mut);line-height:1.4">Вопросы обрабатываются ИИ Cloudflare без привязки к личности. Лимит: ' + MENTOR_LIMIT + ' действий/день.</div>' +
  '</div>';
}
window.mentorPanelHTML = mentorPanelHTML;

function mentorOpenPanel(lessonId){
  if(!mentorIsMax()){
    mentorUpsellModal();
    return;
  }
  let panel = document.getElementById('mentor_panel');
  if(!panel){
    const wrapper = document.createElement('div');
    wrapper.innerHTML = mentorPanelHTML();
    panel = wrapper.firstElementChild;
    document.body.appendChild(panel);
    const st = document.createElement('style');
    st.id = 'mentor_style';
    st.textContent = '@media (max-width:480px){ #mentor_panel{ width:100vw !important; right:0 !important; left:0 !important; top:auto !important; bottom:0 !important; height:75vh !important; border-left:none !important; border-top:1px solid var(--line) !important } }';
    document.head.appendChild(st);
  }
  const body = document.getElementById('mentor_panel_body');
  if(body){
    body.innerHTML = '<div style="font-size:12px;color:var(--mut);margin-bottom:10px">Урок: ' + (lessonId || 'общий') + '</div><div id="mentor_actions" style="display:flex;flex-direction:column;gap:7px"></div><div id="mentor_result" style="margin-top:12px"></div>';
  }
  window._mentorLessonId = lessonId;
  if(typeof window.renderMentorActions === 'function') window.renderMentorActions();
}
window.mentorOpenPanel = mentorOpenPanel;

function mentorClosePanel(){
  const p = document.getElementById('mentor_panel');
  if(p) p.remove();
}
window.mentorClosePanel = mentorClosePanel;

/* ---------- кнопка 🤖 М. в уроке ---------- */
(function hookMentorInLesson(){
  const orig = window.openFullscreenLesson;
  if(typeof orig !== 'function') return;
  window.openFullscreenLesson = function(id){
    const r = orig.apply(this, arguments);
    setTimeout(() => {
      try{
        if(document.getElementById('mentor_entry_btn')) return;
        const modal = document.getElementById('lessonFullscreenReaderModal');
        if(!modal) return;
        const btn = document.createElement('button');
        btn.id = 'mentor_entry_btn';
        btn.className = 'btn sm ghost';
        btn.style.cssText = 'font-size:11.5px;padding:4px 10px;white-space:nowrap';
        btn.innerHTML = '🤖 М.';
        btn.onclick = () => mentorOpenPanel(id);
        const first = modal.querySelector('div, h1, h2');
        if(first && first.parentNode) first.parentNode.insertBefore(btn, first.nextSibling);
        else modal.insertBefore(btn, modal.firstChild);
      }catch(e){}
    }, 120);
    return r;
  };
})();

/* =========================================================================
   M2 · F1 Проверка Фейнмана (JSON-вердикт) + F2 «Объясни иначе»
   ========================================================================= */

/* ---------- рендер списка действий в панели ---------- */
window.renderMentorActions = function(){
  const lessonId = window._mentorLessonId;
  const idWrapEl = document.getElementById('mentor_actions');
  if(!idWrapEl) return;
  const list = [
    { id: 'feynman', label: '🧑‍🏫 Проверка Фейнмана', need: 'feynman_input_' + lessonId },
    { id: 'rephrase', label: '🔄 Объясни иначе' },
    { id: 'socratic', label: '🤔 Сократов режим' },
    { id: 'tasker', label: '✍️ Генератор задач' }
  ];
  idWrapEl.innerHTML = list.map(a =>
    '<button class="btn sm" style="text-align:left;justify-content:flex-start;font-size:12.5px" onclick="mentorRun(\'' + a.id + '\')">' + a.label + '</button>'
  ).join('');
};

function mentorRun(action){
  const lessonId = window._mentorLessonId;
  if(!lessonId) return;
  // если панель не открыта — открываем
  if(!document.getElementById('mentor_panel')) mentorOpenPanel(lessonId);
  const out = document.getElementById('mentor_result');
  if(!out) return;
  if(action === 'feynman') mentorF1(lessonId, out);
  else if(action === 'rephrase') mentorF2(lessonId, out);
  else if(action === 'socratic') mentorF3(lessonId, out);
  else if(action === 'tasker') mentorF4(lessonId, out);
}
window.mentorRun = mentorRun;

/* ---------- F1: проверка Фейнмана ---------- */
window.mentorF1 = function(lessonId, out){
  const ta = document.getElementById('feynman_input_' + lessonId);
  const explanation = ta ? ta.value : '';
  /* v10.1 (ревью, мелкое 1): вердикт ИИ идёт в innerHTML — экранируем advice/gaps
     (sanitizeJsonDeep режет только <script>/on*=, iframe и javascript: прошли бы) */
  const escV = (window.V10 && V10.escHtml) ? V10.escHtml : (s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])));
  out.innerHTML = '<div style="font-size:12px;color:var(--mut)">🤖 Разбираю объяснение…</div>';
  MENTOR.ask('feynman', lessonId, { explanation: explanation }).then(r => {
    /* v10.1 (ревью, мелкое 2): мёртвый фолбэк JSON.parse(r.text) удалён — r.text уже
       санитизирован и не парсится; структурированный ответ живёт в r.json (AI1-контракт) */
    const verdict = r.json || null;
    if(!verdict || !verdict.verdict){
      out.innerHTML = '<div style="font-size:12.5px;color:var(--warn)">Наставник задумался, попробуй ещё раз.</div>';
      return;
    }
    const color = verdict.verdict === 'understood' ? 'var(--ok)' : verdict.verdict === 'partial' ? 'var(--warn)' : 'var(--bad)';
    const label = verdict.verdict === 'understood' ? 'понял' : verdict.verdict === 'partial' ? 'частично' : 'пропущено';
    out.innerHTML = '<div style="border-left:4px solid ' + color + ';padding:8px 12px;margin-bottom:10px;background:#040714;border-radius:6px">' +
      '<div style="font-weight:800;color:' + color + ';margin-bottom:6px">' + label.toUpperCase() + '</div>' +
      '<div style="font-size:11px;color:var(--mut);margin-bottom:6px">' + escV(verdict.advice || '') + '</div>' +
      (verdict.gaps && verdict.gaps.length ? '<div style="font-size:12px;color:var(--txt)">Пробелы: ' + verdict.gaps.map(g => escV(g)).join(' · ') + '</div>' : '') +
    '</div>';
    // сохраняем в cn_feynman_ai
    try{
      const st = JSON.parse(localStorage.getItem('cn_feynman_ai') || '{}');
      st[lessonId] = { verdict: verdict.verdict, gaps: verdict.gaps || [], ts: Date.now() };
      localStorage.setItem('cn_feynman_ai', JSON.stringify(st));
    }catch(e){}
  }).catch(e => {
    out.innerHTML = '<div style="font-size:12.5px;color:var(--warn)">' + (e.message === 'limit' ? '🕐 Дневной лимит исчерпан.' : 'Наставник не отвечает — повтори позже.') + '</div>';
  });
};

/* ---------- F2: три переупаковки ---------- */
window.mentorF2 = function(lessonId, out){
  const kinds = [ { id: 'simpler', label: 'Проще' }, { id: 'example', label: 'Пример из жизни' }, { id: 'shorter', label: 'Короче' } ];
  out.innerHTML = '<div style="display:flex;flex-direction:column;gap:6px">' + kinds.map(k =>
    '<button class="btn sm ghost" style="font-size:12px;text-align:left" data-kind="' + k.id + '">' + k.label + '</button>'
  ).join('') + '</div><div id="mentor_f2_out" style="margin-top:8px"></div>';
};
window.mentorF2do = function(lessonId, kind){
  const out = document.getElementById('mentor_f2_out');
  if(!out) return;
  out.innerHTML = '<div style="font-size:12px;color:var(--mut)">🤖 Переупаковываю…</div>';
  MENTOR.ask('rephrase', lessonId, { kind: kind }).then(r => {
    out.innerHTML = '<div style="padding:10px 12px;background:#040714;border-left:3px solid var(--acc2);border-radius:6px;font-size:12.5px;color:var(--txt);line-height:1.55">' +
      '<div style="font-size:10px;color:var(--acc2);text-transform:uppercase;font-weight:800;margin-bottom:4px">перефраз от наставника</div>' + r.text + '</div>';
  }).catch(e => {
    out.innerHTML = '<div style="font-size:12.5px;color:var(--warn)">' + (e.message === 'limit' ? '🕐 Лимит исчерпан.' : 'Наставник не отвечает.') + '</div>';
  });
};



/* =========================================================================
   M3 · F3 Сократов режим (3 ступени) + F4 Генератор задач (правду считает КОД)
   ========================================================================= */

/* ---------- F3: Сократов ---------- */
window.mentorF3 = function(lessonId, out){
  window._mentorSocStep = 0;
  window._mentorSocHistory = [];
  if(!document.getElementById('mentor_soc_in')){
    out.innerHTML = '<input type="text" id="mentor_soc_in" style="background:#040714;border:1px solid var(--line);border-radius:6px;padding:8px;color:var(--txt);width:100%;font-size:12.5px;margin-bottom:8px" placeholder="Твой вопрос/понимание...">' +
      '<button class="btn sm" data-soc="1">Ответить</button><div id="mentor_soc_out" style="margin-top:10px"></div>';
    const btn = out.querySelector('button[data-soc]');
    if(btn) btn.onclick = () => window.mentorF3step(lessonId);
  }
};
window.mentorF3step = function(lessonId){
  const inEl = document.getElementById('mentor_soc_in');
  const outEl = document.getElementById('mentor_soc_out');
  if(!inEl || !outEl) return;
  const val = (inEl.value || '').trim();
  const step = ++window._mentorSocStep;
  const isDone = /не знаю/i.test(val) && step >= 3;
  MENTOR.ask('socratic', lessonId, { question: val, step: step, giveUp: isDone }).then(r => {
    const color = isDone ? 'var(--ok)' : 'var(--acc2)';
    outEl.innerHTML += '<div style="padding:10px 12px;background:#040714;border-left:3px solid ' + color + ';border-radius:6px;font-size:12.5px;color:var(--txt);margin-top:8px">' + r.text + '</div>';
    if(inEl) inEl.value = '';
    if(isDone) window._mentorSocHistory = [];
  }).catch(e => {
    outEl.innerHTML += '<div style="font-size:12.5px;color:var(--warn);margin-top:8px">' + (e.message === 'limit' ? '🕐 Лимит.' : 'Не отвечает.') + '</div>';
  });
};

/* ---------- F4: генератор задач — правду считает КОД ---------- */
window.mentorF4 = function(lessonId, out){
  const lesson = LESSONS.find(x => x.id === lessonId);
  const nq = lesson && lesson.numericQuiz;
  if(!nq){
    out.innerHTML = '<div style="font-size:12px;color:var(--mut)">✍️ В этом уроке нет параметризуемой числовой задачи — генератор скрыт.</div>';
    return;
  }
  out.innerHTML = '<div style="font-size:12px;color:var(--mut)">✍️ Модель пишет новую формулировку, код считает эталон…</div>';
  MENTOR.ask('tasker', lessonId, { example: { q: nq.q, answer: nq.answer } }).then(r => {
    let gen = null;
    try{ gen = r.json || JSON.parse(r.text); }catch(e){ gen = null; }
    if(!gen || !gen.story || !gen.params){
      out.innerHTML = '<div style="font-size:12.5px;color:var(--warn)">Генератор не собрал задачу — попробуй ещё раз.</div>';
      return;
    }
    const truth = mentorCompute(nq, gen.params);
    if(truth == null || !isFinite(truth)){
      out.innerHTML = '<div style="font-size:12.5px;color:var(--warn)">Эта формула не параметризуется в коде — генератор для урока скрыт.</div>';
      return;
    }
    window._mentorTaskTruth = truth;
    window._mentorTaskTol = nq.absTol != null ? nq.absTol : (nq.tolPct != null ? nq.tolPct : 0.5);
    out.innerHTML = '<div style="font-size:12.5px;color:var(--txt);padding:10px 12px;background:#040714;border-radius:6px;margin-bottom:8px;line-height:1.55">' + gen.story + '</div>' +
      '<input type="number" id="mentor_task_in" step="any" style="background:#040714;border:1px solid var(--line);border-radius:6px;padding:8px;color:var(--txt);width:100%;font-size:12.5px;margin-bottom:8px" placeholder="Твой ответ"> ' +
      '<button class="btn sm" data-task="1">Проверить</button>' +
      '<div id="mentor_task_fb" style="margin-top:8px"></div>';
    const btn = out.querySelector('button[data-task]');
    if(btn) btn.onclick = () => mentorTaskCheck();
  }).catch(e => {
    out.innerHTML = '<div style="font-size:12.5px;color:var(--warn)">' + (e.message === 'limit' ? '🕐 Лимит.' : 'Генератор не отвечает.') + '</div>';
  });
};

window.mentorCompute = function(nq, params){
  if(params.leverage != null) return 100 / params.leverage;
  if(params.p != null && params.b != null) return (params.p - (1 - params.p) / params.b) * 100;
  return null;
};

function mentorTaskCheck(){
  const inp = document.getElementById('mentor_task_in');
  const fb = document.getElementById('mentor_task_fb');
  if(!inp || !fb || window._mentorTaskTruth == null) return;
  const val = parseFloat(inp.value);
  const tol = window._mentorTaskTol || 0.5;
  const ok = Math.abs(val - window._mentorTaskTruth) <= tol;
  fb.innerHTML = ok
    ? '<div style="font-size:12.5px;color:var(--ok)">✅ Верно: ' + (Math.round(window._mentorTaskTruth * 1000) / 1000) + '. Эталон считал код — модель только оформила условие.</div>'
    : '<div style="font-size:12.5px;color:var(--bad)">❌ Эталон: ' + (Math.round(window._mentorTaskTruth * 1000) / 1000) + ' (допуск ' + tol + '). Пересчитай.</div>';
}
window.mentorTaskCheck = mentorTaskCheck;

/* =========================================================================
   M4 · H1 Универсальная подсказка «🤖 Подскажи» в каждом тренажёре (3 ступени)
   + счётчик cn_hints (название ответа НИКОГДА не попадает в подсказку)
   ========================================================================= */

function hintGetCount(lessonId){
  try{ return JSON.parse(localStorage.getItem('cn_hints') || '{}')[lessonId] || 0; }catch(e){ return 0; }
}
function hintAddCount(lessonId){
  try{
    const wc = JSON.parse(localStorage.getItem('cn_hints') || '{}');
    wc[lessonId] = (wc[lessonId] || 0) + 1;
    localStorage.setItem('cn_hints', JSON.stringify(wc));
  }catch(e){}
}
window.hintGetCount = hintGetCount;

function mentorHintStepRender(lessonId, step, out){
  const lesson = LESSONS.find(x => x.id === lessonId);
  const nq = lesson && lesson.numericQuiz;
  // даю модели контекст без эталонного ответа (не включаем answer!)
  const example = nq ? { q: nq.q, unit: nq.unit } : null;
  return MENTOR.ask('hint', lessonId, { step: step, title: lesson ? lesson.title : '', example: example }).then(r => {
    // дополн. фильтр: удаляем условные числа, совпадающие с эталонным ответом (H1 момент)
    let txt = r.text;
    if(nq && nq.answer != null){
      const ansStr = String(Math.round(nq.answer * 1000) / 1000);
      if(txt.includes(ansStr)){
        txt = txt.replace(new RegExp(ansStr.replace(/[.]/g, '[.]'), 'g'), '[скрыто]').replace('[скрыто]', '[скрыто по экономике подсказок]');
      }
    }
    hintAddCount(lessonId);
    const titles = { 1: 'на что смотреть', 2: 'какая идея работает', 3: 'разбор соседнего примера' };
    return '<div style="padding:10px 12px;background:#040714;border-left:3px solid var(--warn);border-radius:6px;font-size:12.5px;color:var(--txt);margin-top:8px"><div style="font-size:10px;color:var(--warn);text-transform:uppercase;font-weight:800;margin-bottom:4px">подсказка ' + step + '/' + ' 3: ' + (titles[step] || '') + '</div>' + txt + '</div>';
  }).catch(e => {
    return '<div style="font-size:12.5px;color:var(--warn)">' + (e.message === 'limit' ? '🕐 Лимит.' : 'Подсказок нет — панель откроется.') + '</div>';
  });
}

/* в каждом тренажёре-виджете: хелпер вставляет кнопку «🤖 Подскажи» */
function mentOrHintBtnHTML(lessonId, widgetEl){
  // одна точка правки: все widgets в catalog mount
  return '<button class="btn sm ghost mentor-hint-btn" style="font-size:11px;padding:4px 10px;margin-top:8px" onclick="mentorHint(\'' + lessonId + '\')">🤖 Подскажи</button>';
}
window.mentorHintBtnHTML = mentOrHintBtnHTML;

function mentorHint(lessonId){
  if(!mentorIsMax()){
    mentorUpsellModal();
    return;
  }
  window._mentorHintSteps = (window._mentorHintSteps || {});
  const step = window._mentorHintSteps[lessonId] || 1;
  let panel = document.getElementById('mentor_panel');
  if(!panel){
    mentorOpenPanel(lessonId);
    panel = document.getElementById('mentor_panel');
  }
  if(!panel) return;
  const widgetBtns = document.querySelectorAll('.mentor-hint-btn');
  if(widgetBtns.length) widgetBtns[0].remove();
  const out = document.getElementById('mentor_result');
  if(!out) return;
  out.innerHTML = '<div style="font-size:12px;color:var(--mut)">🤖 Подскажу…</div>';
  mentorHintStepRender(lessonId, step, out).then(html => {
    out.innerHTML = html + '<div id="mentor_widget_hint" style="margin-top:10px"></div>';
    window._mentorHintSteps[lessonId] = Math.min(3, step + 1);
    const total = hintGetCount(lessonId);
    const hintTotal = document.getElementById('mentor_widget_hint');
    if(hintTotal){
      hintTotal.innerHTML = '<div style="font-size:11.5px;color:var(--mut)">Подсказок использовано по уроку: <b>' + total + '</b>' +
        (total > 2 ? ' — бейдж мастерства не будет выдан' : ' (для бейджа мастерства: ≤2)') + '</div>';
    }
  });
}
window.mentorHint = mentorHint;

/* вставляем кнопку в каждом виджете при открытии урока */
(function patchLessonWidgetHints(){
  const orig = window.openFullscreenLesson;
  if(typeof orig !== 'function') return;
  window.openFullscreenLesson = function(id){
    const r = orig.apply(this, arguments);
    setTimeout(() => {
      try{
        if(!MISTAKE_TYPES) return; // no-op fallback
        const modal = document.getElementById('lessonFullscreenReaderModal');
        if(!modal) return;
        // в каждый виджет (interactive) в хэлпере — добавляем кнопку hint
        const widgets = modal.querySelectorAll('.lblock.widget-block, .lblock.interactive, [id^="widget"]');
        widgets.forEach(w => {
          if(w.querySelector('.mentor-hint-btn')) return;
          const btn = document.createElement('button');
          btn.className = 'btn sm ghost mentor-hint-btn';
          btn.style.cssText = 'font-size:11px;padding:4px 10px;margin:8px auto;display:block';
          btn.innerHTML = '🤖 Подскажи';
          btn.onclick = () => mentorHint(id);
          w.appendChild(btn);
        });
      }catch(e){}
    }, 150);
    // второй проход: подсказки в виджетах после полной отрисовки урока
    setTimeout(() => {
      try{
        const modal = document.getElementById('lessonFullscreenReaderModal');
        if(!modal) return;
        modal.querySelectorAll('[id^="widget_"]').forEach(w => {
          if(w.querySelector('.mentor-hint-btn')) return;
          w.insertAdjacentHTML('beforeend', mentOrHintBtnHTML(id, w));
        });
      }catch(e){}
    }, 800);
    return r;
  };
})();

/* =========================================================================
   M5 · H2 Критик гипотез (5 измерений JSON) + H3 Ревизор устава (словарный скан)
   ========================================================================= */

/* ---------- H2: критик гипотез ---------- */
function mentorCritique(lessonId, hypothesisText){
  if(!mentorIsMax()){ mentorUpsellModal(); return Promise.resolve('<div>Гейт</div>'); }
  return MENTOR.ask('critique', lessonId, { hypothesis: hypothesisText }).then(r => {
    let data = null;
    try{ data = r.json || JSON.parse(r.text); }catch(e){ data = null; }
    if(!data){ return '<div style="font-size:12.5px;color:var(--warn)">Критик задумался — повтори позже.</div>'; }
    const dims = [
      ['falsifiable', 'Проверяемость'],
      ['data_needed', 'Данные'],
      ['edge_source', 'Преимущество'],
      ['capacity', 'Ёмкость'],
      ['regime_risk', 'Режимный риск']
    ];
    const icon = v => v === 'ok' ? '✅' : v === 'warn' ? '⚠️' : '❌';
    let html = '<div style="margin-top:8px">' + dims.map(([k, title]) => {
      const row = data[k];
      if(!row) return '';
      return '<div style="border-left:2px solid ' + (row.verdict === 'ok' ? 'var(--ok)' : row.verdict === 'warn' ? 'var(--warn)' : 'var(--bad)') + ';padding-left:8px;margin-bottom:6px;font-size:11.5px">' +
        '<b>' + icon(row.verdict) + ' ' + title + '</b> — ' + (row.note || '') + '</div>';
    }).join('') + '<div style="font-size:11px;color:var(--mut);margin-top:6px">' + (data.summary || '') + '</div></div>';
    return html;
  }).catch(e => '<div style="font-size:12.5px;color:var(--warn)">' + (e.message === 'limit' ? '🕐 Лимит.' : 'Не отвечает.') + '</div>');
}
window.mentorCritique = mentorCritique;

/* ---------- H3: ревизор устава — словарный скан КОДОМ, модель только по потемам ---------- */
function mentorRevise(lessonId, charterText){
  if(!mentorIsMax()){ mentorUpsellModal(); return Promise.resolve('<div>Гейт</div>'); }
  // 1) словарный скан — код, не модель
  const vagueMarkers = ['обычно', 'крупн', 'значительн', 'по возможности', 'примерно', 'иногда', 'около', 'в основном', 'достаточно'];
  const lines = charterText.split('\n');
  const flagged = [];
  lines.forEach((ln, i) => {
    const lower = ln.toLowerCase();
    const hit = vagueMarkers.find(m => lower.includes(m)) || (ln.replace(/[\d%\.\s:$]/g, '').length > 10 && !/\d/.test(ln));
    if(hit) flagged.push({ line: i + 1, text: ln });
  });
  // 2) модель получает только flagged + всё же весь текст (как в ТЗ)
  return MENTOR.ask('revise', lessonId, { flagged: flagged, full: charterText }).then(r => {
    let data = null;
    try{ data = r.json || JSON.parse(r.text); }catch(e){ data = null; }
    if(!data){ return '<div style="font-size:12.5px;color:var(--warn)">Ревизор задумался — повтори позже.</div>'; }
    let html = '<div style="margin-top:8px">' +
      (data.loopholes && data.loopholes.length ? data.loopholes.map(l =>
        '<div style="border-left:2px solid var(--warn);padding-left:8px;margin-bottom:8px;font-size:11.5px">' +
          '<b>«' + (l.quote || '') + '»</b> — ' + (l.why_vague || '') + '<br>➜ ' + (l.fix_suggestion || '') +
        '</div>').join('') : '<div style="font-size:11.5px;color:var(--ok)">расплывчатых маркеров не найдено</div>') +
      (data.solid && data.solid.length ? '<div style="font-size:11px;color:var(--ok);margin-top:6px">✅ ' + data.solid.join(' · ') + '</div>' : '') +
    '</div>';
    return html;
  }).catch(e => '<div style="font-size:12.5px;color:var(--warn)">' + (e.message === 'limit' ? '🕐 Лимит.' : 'Ревизор не отвечает.') + '</div>');
}
window.mentorRevise = mentorRevise;

