    '<input type="text" id="mentor_spare_in" style="background:#040714;border:1px solid var(--line);border-radius:6px;padding:8px;color:var(--txt);width:100%;font-size:12.5px;margin-bottom:8px" placeholder="Убеждение, например: «ETH оказалась сильнее BTC за счёт L2»">' +
    '<button class="btn sm" onclick="mentorSparStep()">Дальше</button>' +
    '<div id="mentor_spare_out" style="margin-top:10px"></div>';
  if(document.getElementById('mentor_spare_in')) document.getElementById('mentor_spare_in').onclick = () => {};
