function mentorSparStep(){
  const lessonId = window._mentorLessonId || 'sparring';
  const stage = window._mentorSparStage || 1;
  const inEl = document.getElementById('mentor_spare_in');
  const outEl = document.getElementById('mentor_spare_out');
  const belief = inEl ? (inEl.value || '').trim() : '';
  if(belief && !window._mentorSparBelief) window._mentorSparBelief = belief;
  const prompt = window._mentorSparBelief;
  MENTOR.ask('spar', lessonId, { stage: stage, belief: prompt }).then(r => {
    const colors = ['var(--ok)', 'var(--warn)', 'var(--acc2)'];
    const titles = ['сильная сторона (Steelman)', 'контраргументы (Attack)', 'класс убеждения (Check)'];
    if(outEl){
      outEl.innerHTML += '<div style="padding:10px 12px;background:#040714;border-left:3px solid ' + colors[stage - 1] + ';border-radius:6px;font-size:12.5px;color:var(--txt);margin-top:8px">' +
        '<div style="font-size:10px;color:' + colors[stage - 1] + ';text-transform:uppercase;font-weight:800;margin-bottom:4px">стадия ' + stage + '/3: ' + titles[stage - 1] + '</div>' + r.text + '</div>';
    }
    if(stage < 3){
      window._mentorSparStage = stage + 1;
      const nextBtn = document.querySelector('#mentor_result button[onclick^=mentorSparStep]');
      if(nextBtn) nextBtn.textContent = 'Дальше: стадия ' + (stage + 1) + '/3';
      //
    } else {
      // финал: сохраняем только факт прохождения
      try{ localStorage.setItem('cn_sparring_done', JSON.stringify({ t: Date.now(), belief: window._mentorSparBelief.slice(0, 80) })); }catch(e){}
      const done = document.createElement('div');
      done.id = 'mentor_spar_done';
      done.style.cssText = 'font-size:11px;color:var(--ok);margin-top:8px';
      done.textContent = 'Сегодняшним финал нейтрален — класс убеждения записан (не стежётся)';
      document.getElementById('mentor_spare_out').appendChild(done);
    }
    if(inEl) inEl.value = '';
  }).catch(e => {
    if(outEl) outEl.innerHTML += '<div style="font-size:12.5px;color:var(--warn);margin-top:8px">' + (e.message === 'limit' ? '🕐 Лимит.' : 'Спарринг не отвечает.') + '</div>';
  });
}
window.mentorSparStep = mentorSparStep;

