/* Криптик */
const KRYPTIK_LINES={error_generic:['Логично. Неправильно, но логично.','Ну-ну. Все через это проходили.','Дальше будет проще. Или нет.'],error_concept:['Идея не дошла. Перечитай уровень 1.','База хромает. Вернись к определению.'],error_arithmetic:['Калькулятор изобрели для таких случаев.','Посчитай ещё раз. Медленно.'],win_easy:['Приемлемо.','Так и держи.','Не расслабляйся.'],win_hard:['Вот это уже интересно.','Заслуженно.'],hint_used:['Подсказал. Дальше сам.','Смотри сюда. Дальше сам.'],limit_reached:['На сегодня всё. Завтра продолжим.','Мозгу нужен отдых. Это тоже урок.'],tour_start:['Я Криптик. Покажу где что лежит. 30 секунд — и ты в деле.'],tour_end:['Разобрался? Хорошо. Дальше сам.'],streak_3:['Три дня подряд. Уже неплохо.'],streak_7:['Неделя. Не сорвись.'],boss_win:['Босс повержен. Следующий сложнее.'],boss_lose:['Проигрыш — это данные. Попробуй иначе.'],boss_hit:['Попал. Ещё разок так же.','Хороший ход. Видел и лучше. Но хороший.','Кризис пошатнулся. Дави.','Так держать. Босс не бессмертный.','Годно. Продолжай.'],boss_miss:['Мимо. Соберись.','Ой. То есть нет.','Неверно. Босс рад — не радуй его.','Не этот вариант. Думай.','Страйк. Следующий ход — точнее.']};
function kryptikSay(c){const p=KRYPTIK_LINES[c];return p?p[Math.floor(Math.random()*p.length)]:''}
window.kryptikSay=kryptikSay;
function kryptikCls(e){return 'k-'+(/^(neutral|happy|doubt|surprise)$/.test(e)?e:'neutral')}
function kryptikAvatar(e,s){s=s||40;return '<span class="kryptik '+kryptikCls(e)+'" role="img" aria-label="Криптик — наставник"><svg width="'+s+'" height="'+s+'" viewBox="0 0 40 40"><circle cx="20" cy="20" r="17" fill="#1A2332" stroke="#38BDF8" stroke-width="1.5"/><circle class="k-eye-l" cx="14" cy="16" r="3" fill="#38BDF8"/><circle class="k-eye-r" cx="26" cy="16" r="3" fill="#38BDF8"/><path class="k-mouth" d="M13 25 Q20 25 27 25" fill="none" stroke="#94A3B8" stroke-width="1.5" stroke-linecap="round"/><line x1="20" y1="3" x2="20" y2="8" stroke="#7C3AED" stroke-width="1.5"/><circle cx="20" cy="3" r="2" fill="#7C3AED"/></svg></span>'}
(function(){const say=function(e,l){const p=document.getElementById('mentor_panel');if(!p)return;const a=p.querySelector('.kryptik');if(a)a.className='kryptik '+kryptikCls(e);const st=document.getElementById('kryptik_panel_status');if(st)st.textContent=l};const orig=MENTOR.ask.bind(MENTOR);MENTOR.ask=function(a,l,p){say('surprise','Смотрю…');return orig(a,l,p).then(function(r){let e='neutral',t='Готово.';if(a==='feynman'){let v=null;try{v=r.json||JSON.parse(r.text)}catch(x){}if(v&&v.verdict==='understood'){e='happy';t=kryptikSay('win_easy')}else if(v){e='doubt';t=kryptikSay('error_generic')}}else if(a==='hint')t=kryptikSay('hint_used');say(e,t);return r},function(err){say('doubt',err&&err.message==='limit'?kryptikSay('limit_reached'):'Связь шумит. Повтори.');throw err})}})();
function kryptikRow(e,sz,line,cls){return '<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">'+kryptikAvatar(e,sz)+'<div style="font-size:12.5px;font-style:italic;'+cls+'">'+line+'</div></div>'}
function kryptikQuizMark(id){const fb=document.getElementById(id);if(fb)fb.innerHTML=kryptikRow('doubt',32,kryptikSay('error_generic'),'color:var(--txt)')+fb.innerHTML}
function kryptikWrap(n,f){const o=window[n];if(typeof o==='function')window[n]=function(){o.apply(this,arguments);f.apply(null,arguments)}}
kryptikWrap('checkQuizAnswer',function(i){const q=window.quiz&&quiz.qs?quiz.qs[quiz.cur]:null;const a=q?(q._sv&&q._svCur===quiz.cur+'_'+quiz._shuffleSalt?q._sv.a:q.a):-1;if(q&&i!==a)kryptikQuizMark('quiz_feedback')});
kryptikWrap('handleLessonQuizAnswer',function(id,s,c){if(s!==c)kryptikQuizMark('lquiz_fb_'+id)});
kryptikWrap('handleBossAnswer',function(c,cor){const t=c===cor?curBossHp<=0?kryptikSay('boss_win'):kryptikSay('boss_hit'):kryptikSay('boss_miss');setTimeout(function(){showToast(t,'🤖')},900)});
window.kryptikTourHook=function(tip,st,n){if(tip)tip.insertAdjacentHTML('afterbegin',kryptikRow(st===0?'surprise':'neutral',44,st===0?kryptikSay('tour_start'):st===n-1?kryptikSay('tour_end'):kryptikSay('hint_used'),'color:#E2E8F0'))};
window.coachMarketEmotion=function(o){const t=(o.title||'').toLowerCase(),f=window.LIVE&&LIVE.data&&LIVE.data.fng?LIVE.data.fng.current.value:null;if(o.id==='fng_shift')return /нервнее/.test(t)?'doubt':'happy';return /экстремальн|дорого/.test(t)||f!==null&&(f<25||f>75)?'surprise':'neutral'};
const SQ_CAT={phish:'Фишинг',contract:'Контракты',pig:'Инвест. схемы',deepfake:'Deepfake',sim:'SIM/2FA',ext:'Расширения',mix:'Комплекс'};
