function renderQuestCard(){var c=document.getElementById('quest_card_in_sims');if(!c)return;var gate=typeof lessonsDone==='object'&&lessonsDone.p0_l20===1,p=null;try{p=JSON.parse(localStorage.getItem('sq_progress')||'null')}catch(x){}var h='<h3>🕵️ Квест «Криптик против Мошенника»</h3><p style="color:var(--mut);font-size:13px">7 эпизодов против Ската. Сохрани виртуальные 5000 USDT + 0.1 BTC + NFT.</p>';if(!gate){h+='<span class="badge" style="border-color:var(--mut);color:var(--mut)">🔒 Заверши урок 0.20 «Безопасность», чтобы открыть квест</span>'}else{h+='<button class="btn" onclick="qGo()">'+(p&&p.done&&p.done.length?'▶ Продолжить':'🕵️ Начать квест')+'</button>';if(p&&p.done&&p.done.length)h+=' <button class="btn ghost sm" onclick="qWipe()">🔄 С начала</button>'}c.innerHTML=h}
