function pqPick(d,ci){if(PQ_S.d!==d||PQ_S.done)return;const day=PQ[d-1],c=day[6][ci],ok=c[1]===1;PQ_S.cap+=c[2];PQ_S.emo+=ok?1:-1;if(ok)PQ_S.right++;else{PQ_S.wrong++;PQ_S.pat[day[4]]=(PQ_S.pat[day[4]]||0)+1}PQ_S.last=(ok?'<div class="sq-sys">✅ '+day[5]+'</div>':'<div class="sq-sys" style="border-color:var(--bad)">❌ '+(c[2]?'−'+Math.abs(c[2]).toLocaleString('ru-RU')+' ₽. ':'')+day[5]+'</div>')+'<div class="sq-sys" style="border-color:var(--acc2)">'+ (window.kryptikAvatar?kryptikAvatar(ok?'happy':'doubt',32):'') +'<b>Криптик:</b> «'+(ok?(window.kryptikSay?kryptikSay('win_easy'):'Принято.'):'Логично. Неправильно, но логично.')+'»</div>';PQ_S.d++;if(PQ_S.d>7){PQ_S.done=true}pqSave();pqRender()}
function pqRender(){const box=document.getElementById('pq_box');if(!box)return;let h='<button class="btn ghost sm" onclick="pqBack()">← К квестам</button>';
if(PQ_S.done){const total=PQ_S.right+PQ_S.wrong,pats=Object.keys(PQ_S.pat).sort(function(a,b){return PQ_S.pat[b]-PQ_S.pat[a]}),main=pats[0]||'—';h+='<h2 style="font-size:17px;margin:10px 0">📊 Семь дней: ты против себя</h2>'+pqHud()+'<div class="sq-sys">'+(window.kryptikAvatar?kryptikAvatar(PQ_S.right>=6?'happy':'doubt',40):'')+'<div><b>Решений по уставу: '+PQ_S.right+' из '+(total||7)+'</b><div style="font-size:12px;color:var(--mut)">Поддался голосу: '+PQ_S.wrong+' · Самая частая ловушка: '+main+'</div></div></div><div class="sq-sys"><b>Паттерн:</b> '+(PQ_S.wrong===0?'Чистая неделя. Дисциплина — твой режим по умолчанию.':'Ты склонен к паттерну «'+main+'». Запомни: неопределённость — не сигнал к действию, а сигнал к проверке фактов (П1).')+'</div><div style="margin-top:10px"><button class="btn" onclick="pqWipe()">🔄 Пройти заново</button><button class="btn ghost sm" onclick="pqBack()">← К квестам</button></div>';if(!PQ_S.best||PQ_S.right>PQ_S.best.right)PQ_S.best={right:PQ_S.right,cap:PQ_S.cap};pqSave();box.innerHTML=h;return}
const d=PQ_S.d,day=PQ[d-1];h+=pqHud()+'<h2 style="font-size:16px;margin:6px 0">📅 День '+d+' · '+PQ_D[d-1]+' · '+day[0]+'</h2>'+(PQ_S.last||'')+'<div class="sq-sys">'+day[1]+'</div><div class="sq-msg" style="border-color:var(--acc2);background:rgba(124,58,237,.08)">🗣 <i>«'+day[2].replace(/^«|»$/g,'')+'»</i></div><div style="margin-top:10px">';day[6].forEach(function(c,ci){h+='<button class="sq-opt" onclick="pqPick('+d+','+ci+')"><b>'+'ABCD'[ci]+'</b> · '+c[0]+'</button>'});h+='</div><div style="font-size:11px;color:var(--mut);margin-top:6px">Связь: '+day[3]+'</div>';box.innerHTML=h}
function pqWipe(){try{localStorage.removeItem('cn_psy_quest')}catch(x){};PQ_S={d:1,cap:1000000,emo:0,right:0,wrong:0,pat:{},done:false,last:'',best:PQ_S.best};pqSave();pqRender()}
function renderPsyQuestCard(){const c=document.getElementById('psyquest_card_in_sims');if(!c)return;let all=true;for(let i=1;i<=8;i++)if(!(typeof lessonsDone==='object'&&lessonsDone['ps_l'+i]===1))all=false;let p=null;try{p=JSON.parse(localStorage.getItem('cn_psy_quest')||'null')}catch(x){}let h='<h3>🧠 Квест «Семь дней: ты против себя»</h3><p style="color:var(--mut);font-size:13px">Неделя с работающим ботом. Враг — внутренний голос. Сохрани капитал и устав.</p>';if(!all){h+='<span class="badge" style="border-color:var(--mut);color:var(--mut)">🔒 Заверши все уроки П1–П8, чтобы открыть квест</span>'}else{h+='<button class="btn" onclick="pqGo()">'+(p&&p.d>1?'▶ Продолжить':'🧠 Начать неделю')+'</button>';if(p&&p.best)h+=' <span style="font-size:12px;color:var(--mut)">Лучший: '+p.best.right+'/7</span>'}c.innerHTML=h}
window.PQNS={go:pqGo,wipe:pqWipe,pick:pqPick,renderCard:renderPsyQuestCard};
/* Сценарий: [тип(0=штатный,1=авария), заголовок, старт%, события[], признак, разбор, [выборы]].
   Выбор: [текст, верно, потеря %]. */
const PNC=[
[0,'Флеш-крэш',0,['−2%','−7%','−12%','−17.6%'],'Биржа отвечает, бот работает, стопы на месте, историческая просадка −14%.','Рынок падает — инфраструктура цела. Стопы работают сами. П1: факт поломки отсутствует.',[
['Ничего не делать — штатная волатильность',1,0],['Закрыть всё руками на дне',0,-14],['Удвоить позицию «отобьюсь»',0,-20],['Написать в чат «что происходит?!»',0,-2]]],
[1,'Каскад ликвидаций',0,['Лонг x3, до ликвидации 4%','Kill-switch не сработал','Биржа отвечает медленно','До ликвидации 1.2%'],'Kill-switch завис, ордера не исполняются — это авария, не рынок.','Автоматика сломана — действуем руками немедленно. П5: кризис по белому списку = действие.',[
['Ждать: автоликвидация подстрахует',0,-100],['Закрыть позицию вручную через API сейчас',1,0],['Увеличить залог, «дожмём»',0,-60],['Перезапустить бота и ждать',0,-30]]],
[1,'Выводы заморожены',0,['Вывод: «временно приостановлен»','Анонса нет, статус молчит','Чаты полны паники','Другие подтверждают проблему'],'Инфраструктурный сбой без объяснений — авария.','Фиксируем факт, проверяем статус, готовим перевод активов. П5.',[
['Ждать «само рассосётся» неделями',0,-40],['Скриншот + статус + план перевода на запасную площадку',1,0],['Продать всё на панике дёшево',0,-25],['Писать гневно в чаты',0,-5]]],
[0,'Регуляторный шок',0,['Новость: «запрет крипты»','Рынок −30% за день','Твои позиции −18%','Бот продолжает работать'],'Это рыночное движение, не сбой. Бот и стопы работают.','Ничего не делаем сегодня. Завтра сверим, меняются ли правила именно для твоих инструментов. П1.',[
['Продать весь портфель по дну',0,-30],['Ничего сегодня. Завтра — проверить свои инструменты',1,0],['Добавить «на просадке»',0,-18],['Уйти из крипты навсегда',0,-22]]],
[0,'Отскок без сигнала',0,['Рынок упал −40%','Отскок +25% от дна','Все кричат «дно пройдено!»','Твоя стратегия сигнала НЕ даёт'],'Давление «упускаешь!» — не сигнал стратегии. Ловушка FOMO.','Нет сигнала стратегии — нет сделки. Ждём свой сигнал. П3.',[
['Войти на отскоке, пока не ушло',0,-20],['Нет сигнала — не вхожу. Жду',1,0],['Войти наполовину депозита',0,-12],['Купить «на все деньги»',0,-35]]]];

const PNC_F=[1,'Полный коллапс',0,['Рынок −35%, всё одновременно','Биржа тормозит, телефон звонит','Kill-switch молчит, ликвидация близко','Чаты в истерике'],'Комплекс: и рынок, и инфраструктура.','Экзамен. Действуем только по фактам: инфраструктурную часть — руками, рыночную — не трогаем. П1 + П5.',[
['Паниковать и закрыть всё подряд',0,-45],['Факты отдельно от паники: инфраструктуру чиню руками, рынок не трогаю',1,0],['Ждать, пока всё «утрясётся»',0,-50],['Добавить залог и молиться',0,-55]]];

let PN={order:[],i:0,t:0,cap:500000,saved:0,results:[],done:false,hard:false,best:null,tmr:null};
try{const p=JSON.parse(localStorage.getItem('cn_panic_progress')||'null');if(p&&p.order&&p.order.length===6&&!p.done)PN=p}catch(x){}
function pnSave(){try{localStorage.setItem('cn_panic_progress',JSON.stringify(PN))}catch(x){}}
function pnShuffle(){const o=[0,1,2,3,4];for(let i=o.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));const t=o[i];o[i]=o[j];o[j]=t}o.push(5);return o}
function pnGo(){go('panicquest');pnRender()}
function pnBack(){go('quests')}
function pnWipe(hard){pnStop();PN={order:pnShuffle(),i:0,t:0,cap:500000,saved:0,results:[],done:false,hard:!!hard,best:PN.best,tmr:null};pnSave();pnRender()}
function pnStop(){if(PN.tmr){clearInterval(PN.tmr);PN.tmr=null}}
function pnScen(){return PN.i<5?PNC[PN.order[PN.i]]:PNC_F}
function pnTick(){PN.t++;const sc=pnScen();const ev=sc[3][Math.min(PN.t,sc[3].length-1)];const el=document.getElementById('pn_ev');if(el)el.textContent=ev;const tm=document.getElementById('pn_time');if(tm)tm.textContent='⏱ 00:0'+PN.t+'0';if(PN.hard&&PN.t>=6){pnPick(PN.i,0)}pnSave()}
function pnPanic(){const sc=pnScen();return Math.min(95,20+PN.t*12+(sc[0]===1?20:0))}
function pnEmoji(){const p=pnPanic();return p<35?'😐':p<60?'😟':p<85?'😨':'😱'}
function pnRender(){const box=document.getElementById('pn_box');if(!box)return;pnStop();let h='<button class="btn ghost sm" onclick="pnBack()">← К квестам</button>';
if(PN.done){const ok=PN.results.filter(function(r){return r===1}).length,tot=PN.results.length,pct=Math.round(ok/tot*100);h+='<h2 style="font-size:17px;margin:10px 0">🚨 Итог кризиса</h2><div class="sq-assets"><span>💼 '+PN.cap.toLocaleString('ru-RU')+' ₽</span><span>✅ '+ok+'/'+tot+'</span><span>'+(pct>=80?'😌':pct>=50?'😐':'😰')+'</span></div><div class="sq-sys">'+(window.kryptikAvatar?kryptikAvatar(pct>=80?'happy':'doubt',40):'')+'<div><b>Выдержано: '+pct+'%</b><div style="font-size:12px;color:var(--mut)">'+(pct>=80?'Паника проиграла. Дисциплина победила.':'Паника выигрывала раунды. Повтори через неделю.')+'</div></div></div><div class="sq-sys"><b>Профиль:</b> '+(PN.results[0]===0?'Склонен действовать на рыночной панике — запомни: падение цены ≠ сбой инфраструктуры.':PN.results.slice(1,5).indexOf(0)>=0?'Путаешь штатное и аварийное. Штатное = бот+стопы работают = НЕ трогай. Авария = сломано = действуй.':'Чисто. Отличаешь штатный кризис от аварии.')+'</div><div style="margin-top:10px"><button class="btn" onclick="pnWipe(false)">🔄 Заново</button>'+(PN.best?' <button class="btn ghost sm" onclick="pnWipe(true)">⚡ Хардкор (60 сек на решение)</button>':'')+'<button class="btn ghost sm" onclick="pnBack()">← К квестам</button></div>';if(!PN.best||pct>PN.best)PN.best=pct;pnSave();box.innerHTML=h;return}
const sc=pnScen(),isF=PN.i>=5,ev=sc[3][Math.min(PN.t,sc[3].length-1)],pn=pnPanic();
h+='<div class="sq-assets"><span>💼 '+PN.cap.toLocaleString('ru-RU')+' ₽</span><span id="pn_time">⏱ 00:00</span><span>'+pnEmoji()+' '+pn+'%</span></div>';
h+='<h2 style="font-size:16px;margin:6px 0">'+(isF?'🚨 ФИНАЛ · ':'🚨 Сценарий '+(PN.i+1)+'/6 · ')+sc[1]+'</h2>';
h+='<div class="sq-sys" style="border-color:'+(sc[0]===1?'var(--bad)':'#38BDF8')+'">📉 Событие: <span id="pn_ev">'+ev+'</span></div>';
h+='<div class="sq-sys" style="font-size:12.5px"><b>Признак:</b> '+sc[4]+'</div>';
h+='<div style="margin-top:8px">';sc[6].forEach(function(c,ci){h+='<button class="sq-opt" onclick="pnPick('+PN.i+','+ci+')"><b>'+'ABCD'[ci]+'</b> · '+c[0]+'</button>'});h+='</div>';
if(PN.i>0)h+='<div style="font-size:11px;color:var(--mut);margin-top:4px">Пройдено: '+PN.i+'/6 · Сохранено: '+PN.cap.toLocaleString('ru-RU')+' ₽</div>';
box.innerHTML=h;PN.tmr=setInterval(pnTick,3000)}
function pnPick(i,ci){if(PN.i!==i||PN.done)return;pnStop();const sc=pnScen(),c=sc[6][ci],ok=c[1]===1;const loss=Math.round(PN.cap*Math.abs(c[2])/100);PN.cap-=loss;PN.results.push(ok?1:0);PN.last='<div class="sq-sys" style="border-color:'+(ok?'var(--ok,#22C55E)':'var(--bad)')+'">'+(ok?'✅ ':'❌ ')+(loss?'−'+loss.toLocaleString('ru-RU')+' ₽. ':'')+sc[5]+'</div><div class="sq-sys">'+(window.kryptikAvatar?kryptikAvatar(ok?'happy':'doubt',32):'')+'<b>Криптик:</b> «'+(ok?(window.kryptikSay?kryptikSay('win_easy'):'Принято.'):'Логично. Неправильно, но логично.')+'»</div>';PN.i++;PN.t=0;if(PN.i>=6)PN.done=true;pnSave();pnRender()}
function renderPanicCard(){const c=document.getElementById('panic_card_in_sims');if(!c)return;let all=true;for(let i=1;i<=5;i++)if(!(typeof lessonsDone==='object'&&lessonsDone['ps_l'+i]===1))all=false;let p=null;try{p=JSON.parse(localStorage.getItem('cn_panic_progress')||'null')}catch(x){}let h='<h3>🚨 Симулятор паники</h3><p style="color:var(--mut);font-size:13px">6 кризисов: научись отличать «рынок падает» от «инфраструктура сломана». В 90% случаев правильно — ничего не делать.</p>';if(!all){h+='<span class="badge" style="border-color:var(--mut);color:var(--mut)">🔒 Заверши уроки П1–П5, чтобы открыть</span>'}else{h+='<button class="btn" onclick="pnGo()">'+(p&&p.i>0&&!p.done?'▶ Продолжить':'🚨 Начать')+'</button>';if(p&&p.best!=null)h+=' <span style="font-size:12px;color:var(--mut)">Лучший: '+p.best+'%</span>'}c.innerHTML=h}
window.PNNS={go:pnGo,wipe:pnWipe,pick:pnPick,renderCard:renderPanicCard};
/* Квест «Маржин-колл» — экзамен по сайзингу (Фаза 3).
   Раунд: [название, ситуация, move%, wick%, гэп(0/1)]. */
const MC_R=[
['Зелёный понедельник','Стратегия дала сигнал в лонг. Рынок спокоен, волатильность низкая.',4,1,0],
['Тренд продолжается','Второй сигнал подряд. В чатах уже скриншоты прибылей.',6,2,0],
['Эйфория','Третья зелёная неделя чувств. Все вокруг «гуру». Ты тоже так думаешь?',3,3,0],
['Первая красная','Без новостей. Просто резкая красная свеча посреди дня.',-8,10,0],
['Пила','Рынок ходит туда-сюда. Сигнал был, но цена пилит.',-2,6,0],
['Отскок','Продавцы выдохлись. Цена возвращается.',5,4,0],
['Новостной шок','Крупный заголовок. Свеча пролетает стопы за секунды. Гэп.',-12,15,1],
['Тишина после бури','Рынок зализывает раны. Слабый плюс.',2,1,0],
['Ночной фитиль','Ночью цена ныряет и возвращается. Свеча закроется в плюс. Вопрос — доживёшь ли ты до закрытия.',1,22,0],
['Нормализация','Последняя сделка серии. Рынок снова обычный.',4,2,0]];
const MC_LEV=[1,2,3,5,10],MC_STK=[10,25,50,100];
let MC={r:0,cap:100000,peak:100000,dd:0,liq:0,hist:[],done:false,best:null,lev:2,stk:25,stop:1};
try{const p=JSON.parse(localStorage.getItem('cn_margin_progress')||'null');if(p&&typeof p.r==='number'&&!p.done)MC=Object.assign(MC,p)}catch(x){}
function mcSave(){try{localStorage.setItem('cn_margin_progress',JSON.stringify(MC))}catch(x){}}
function mcGo(){go('marginquest');mcRender()}
function mcBack(){go('quests')}
function mcWipe(){MC={r:0,cap:100000,peak:100000,dd:0,liq:0,hist:[],done:false,best:MC.best,lev:2,stk:25,stop:1};mcSave();mcRender()}
function mcSet(k,v){MC[k]=v;mcRender()}
function mcRound(){return MC_R[MC.r]}
function mcTrade(){if(MC.done||MC.r>=10)return;const rd=mcRound(),move=rd[2],wick=rd[3],gap=rd[4]===1;
const stake=Math.round(MC.cap*MC.stk/100),lev=MC.lev;
let pnl,liqd=false,note='';
if(lev*wick>=100&&(!MC.stop||gap)){liqd=true;pnl=-stake;note=gap?'Стоп не успел — гэп. Ликвидация.':'Фитиль достал до ликвидации раньше стопа.';}
else if(move<0){const lossPct=MC.stop?Math.min(Math.abs(move),3)*lev:Math.abs(move)*lev;pnl=-Math.round(stake*lossPct/100);if(lossPct>=100){liqd=true;pnl=-stake}note=MC.stop&&!gap?'Стоп сработал: −3% × плечо вместо полного хода.':''}
else{pnl=Math.round(stake*lev*move/100);if(lev*wick>=100&&MC.stop){pnl=-Math.round(stake*3*lev/100);note='Фитиль выбил стоп по пути вверх.'}}
MC.cap+=pnl;if(liqd)MC.liq++;if(MC.cap<0)MC.cap=0;
if(MC.cap>MC.peak)MC.peak=MC.cap;const dd=Math.round((1-MC.cap/MC.peak)*100);if(dd>MC.dd)MC.dd=dd;
MC.hist.push({pnl:pnl,liqd:liqd});MC.r++;if(MC.r>=10||MC.cap<=0)MC.done=true;
MC.last={pnl:pnl,liqd:liqd,note:note,rd:rd};mcSave();mcRender()}
function mcGrade(){if(MC.cap<=0)return['💀 Маржин-колл','Ты не дошёл до конца серии. Стратегия была рабочая — размер позиции её убил.'];
if(MC.dd>50)return['😰 Дорогое обучение','Выжил, но просадка съела половину счёта. Отыгрывать −50% нужно +100%.'];
if(MC.cap>=105000&&MC.dd<=30)return['🏆 Профи','Плюс при контролируемой просадке. Келли бы одобрил.'];
if(MC.cap>=100000&&MC.dd<=30)return['✅ Дисциплина окупается','Скучный результат — это и есть результат.'];
return['😐 Прошёл, но нервно','Финиш около нуля с лишними переживаниями. Урежь размер — получишь сон.']}
function mcRender(){const box=document.getElementById('mc_box');if(!box)return;let h='<button class="btn ghost sm" onclick="mcBack()">← К квестам</button>';
if(MC.done){const g=mcGrade();const ok=MC.cap>0;
h+='<h2 style="font-size:17px;margin:10px 0">💥 Итог серии</h2><div class="sq-assets"><span>💼 '+MC.cap.toLocaleString('ru-RU')+' ₽</span><span>📉 max DD −'+MC.dd+'%</span><span>💥 ликвидаций: '+MC.liq+'</span></div>';
h+='<div class="sq-sys" style="border-color:'+(ok?'var(--ok,#22C55E)':'var(--bad)')+'">'+(window.kryptikAvatar?kryptikAvatar(ok?'happy':'doubt',40):'')+'<div><b>'+g[0]+'</b><div style="font-size:12.5px;color:var(--mut)">'+g[1]+'</div></div></div>';
h+='<div class="sq-sys" style="font-size:12.5px"><b>Эталон (x2 · 20% · стоп):</b> те же 10 сделок → ~106 900 ₽, просадка −2%. Скучно? Именно. Размер позиции решает больше, чем сигнал. Урок 3.2.</div>';
h+='<div style="margin-top:10px"><button class="btn" onclick="mcWipe()">🔄 Новая серия</button><button class="btn ghost sm" onclick="mcBack()">← К квестам</button></div>';
const score=MC.cap;if(!MC.best||score>MC.best)MC.best=score;mcSave();box.innerHTML=h;return}
const rd=mcRound(),ddPct=Math.round((1-MC.cap/MC.peak)*100);
const emo=MC.cap<=0?'💀':ddPct<15?'😐':ddPct<35?'😟':ddPct<60?'😨':'😱';
h+='<div class="sq-assets"><span>💼 '+MC.cap.toLocaleString('ru-RU')+' ₽</span><span>Сделка '+(MC.r+1)+'/10</span><span>📉 −'+ddPct+'%</span><span>'+emo+'</span></div>';
if(MC.last){const L=MC.last;h+='<div class="sq-sys" style="border-color:'+(L.pnl>=0?'var(--ok,#22C55E)':'var(--bad)')+'">'+(L.liqd?'💥 ЛИКВИДАЦИЯ: −':(L.pnl>=0?'✅ +':'❌ −'))+Math.abs(L.pnl).toLocaleString('ru-RU')+' ₽'+(L.note?' · '+L.note:'')+'</div><div class="sq-sys">'+(window.kryptikAvatar?kryptikAvatar(L.pnl>=0?'happy':'doubt',32):'')+'<b>Криптик:</b> «'+(L.liqd?'Позиция была правильная. Размер — нет.':L.pnl>=0?(window.kryptikSay?kryptikSay('win_easy'):'Принято.'):'Рынок не должен решать за тебя, сколько ты потеряешь.')+'»</div>'}
h+='<h2 style="font-size:16px;margin:8px 0">Сделка '+(MC.r+1)+' · '+rd[0]+(rd[4]?' ⚡':'')+'</h2><div class="sq-sys">'+rd[1]+'</div>';
h+='<div class="sq-sys" style="font-size:12.5px"><b>Плечо:</b> '+MC_LEV.map(function(l){return '<button class="btn ghost sm" style="'+(MC.lev===l?'border-color:var(--acc,#38BDF8);color:#fff':'')+'" onclick="mcSet(\'lev\','+l+')">x'+l+'</button>'}).join(' ')+'</div>';
h+='<div class="sq-sys" style="font-size:12.5px"><b>Доля капитала:</b> '+MC_STK.map(function(v){return '<button class="btn ghost sm" style="'+(MC.stk===v?'border-color:var(--acc,#38BDF8);color:#fff':'')+'" onclick="mcSet(\'stk\','+v+')">'+v+'%</button>'}).join(' ')+'</div>';
h+='<div class="sq-sys" style="font-size:12.5px"><b>Стоп −3%:</b> <button class="btn ghost sm" style="'+(MC.stop?'border-color:var(--acc,#38BDF8);color:#fff':'')+'" onclick="mcSet(\'stop\',1)">вкл</button> <button class="btn ghost sm" style="'+(!MC.stop?'border-color:var(--acc,#38BDF8);color:#fff':'')+'" onclick="mcSet(\'stop\',0)">выкл</button></div>';
const stake=Math.round(MC.cap*MC.stk/100);
h+='<div style="font-size:12px;color:var(--mut);margin:6px 0">Ставка: '+stake.toLocaleString('ru-RU')+' ₽ с плечом x'+MC.lev+' → ход 1% цены = '+(MC.lev)+'% ставки. Ликвидация при ходе против: '+Math.ceil(100/MC.lev)+'%.</div>';
h+='<button class="btn" onclick="mcTrade()">📈 Открыть сделку</button>';
box.innerHTML=h}
function renderMarginCard(){const c=document.getElementById('margin_card_in_sims');if(!c)return;let all=true;for(let i=1;i<=6;i++)if(!(typeof lessonsDone==='object'&&lessonsDone['p3_l'+i]===1))all=false;let p=null;try{p=JSON.parse(localStorage.getItem('cn_margin_progress')||'null')}catch(x){}let h='<h3>💥 Квест «Маржин-колл»</h3><p style="color:var(--mut);font-size:13px">10 сделок. Рабочая стратегия. Единственный вопрос — сколько ставишь. Плечо, доля капитала, стоп: настрой сам и доживи до конца серии.</p>';if(!all){h+='<span class="badge" style="border-color:var(--mut);color:var(--mut)">🔒 Заверши уроки 3.1–3.6, чтобы открыть</span>'}else{h+='<button class="btn" onclick="mcGo()">'+(p&&p.r>0&&!p.done?'▶ Продолжить':'💥 Начать серию')+'</button>';if(p&&p.best!=null)h+=' <span style="font-size:12px;color:var(--mut)">Лучший: '+p.best.toLocaleString('ru-RU')+' ₽</span>'}c.innerHTML=h}
window.MCNS={go:mcGo,wipe:mcWipe,trade:mcTrade,set:mcSet,renderCard:renderMarginCard};
/* Квест «Кривая-обманщица» — аудит бэктестов (Фаза 2).
   Кейс: [название, метрики, методика, подвох-разбор, честная(0/1), точки кривой] */
const CV_C=[
['«Снайпер v3»','+340% за год · Sharpe 3.8 · DD −4% · 212 сделок','Сигнал по закрытию свечи, входим по цене открытия той же свечи. Параметры стандартные.','Look-ahead: на момент открытия свечи её закрытие ещё не существует. В реале сигнал появится на свечу позже — и вся доходность испарится.',0,'0,30 10,28 20,24 30,22 40,18 50,15 60,12 70,9 80,6 90,4 100,2'],
['«Грааль-47»','+512% за 2 года · Sharpe 5.2 · DD −2% · 480 сделок','47 параметров. Оптимизированы перебором 12 000 комбинаций на всей доступной истории. OOS-период не выделялся.','Оверфиттинг: 47 ручек, подкрученных под прошлое, описывают прошлое идеально и будущее — никак. Без OOS-проверки это кривая памяти, а не стратегии.',0,'0,30 10,27 20,25 30,21 40,19 50,14 60,12 70,8 80,6 90,3 100,1'],
['«Топ-50 Моментум»','+180% за год · Sharpe 2.4 · DD −11% · 96 сделок','Вселенная: топ-50 монет по капитализации на сегодня. Тест на истории 3 лет.','Survivorship bias: сегодняшний топ-50 — это выжившие. Монеты, умершие за 3 года, из теста исключены заранее. В реале ты купишь и будущих покойников.',0,'0,30 10,26 20,23 30,20 40,17 50,15 60,11 70,9 80,7 90,5 100,3'],
['«Скальпер-1400»','+96% за год · Sharpe 2.9 · DD −3% · 1400 сделок','Средний профит на сделку 0.3%. Комиссии и проскальзывание не учитывались для чистоты эксперимента.','Edge 0.3% при комиссии 0.1% туда-обратно и спреде — съедается издержками. 1400 сделок × издержки = гарантированный минус в реале.',0,'0,30 10,27 20,25 30,22 40,20 50,17 60,15 70,12 80,10 90,7 100,5'],
['«Три недели чуда»','+64% за 3 недели · Sharpe 4.1 · DD 0% · 9 сделок','Период теста: 3 недели. 9 сделок, все прибыльные. Автор просит удвоить депозит.','Малая выборка: 9 сделок — это шум, а не статистика. Sharpe на 9 наблюдениях не значит ничего. Нужны десятки сделок и разные рыночные режимы.',0,'0,30 20,26 40,20 60,14 80,8 100,2'],
['«Нормализация Плюс»','+150% за год · Sharpe 2.7 · DD −6% · 150 сделок','Признаки нормализованы по минимуму и максимуму всего ряда данных, затем подаются в модель.','Утечка в препроцессинге: min/max всего ряда содержат будущее. Нормализовать можно только по данным, доступным на момент решения (скользящее окно).',0,'0,30 10,27 20,24 30,21 40,18 50,16 60,13 70,10 80,8 90,5 100,3'],
['«Отбор Лучших»','+210% за год · Sharpe 3.1 · DD −5% · 130 сделок','Проверено 300 гипотез. Показана самая устойчивая из них. Остальные результаты не сохранились.','Data snooping: из 300 случайных идей одна всегда выглядит гениальной. Без поправки на множественное тестирование это лотерейный билет, а не открытие.',0,'0,30 10,28 20,23 30,20 40,17 50,14 60,11 70,9 80,6 90,4 100,2'],
['«Скучная Стабильная»','+31% за год · Sharpe 1.3 · DD −12% · 68 сделок','Walk-forward оптимизация. Комиссии заложены ×2 от реальных. Отдельный OOS-период 6 месяцев, не участвовал в подборе параметров.','Честная методика: walk-forward, завышенные издержки, невиданный OOS. Скучные цифры — признак того, что их не рисовали. Такие стратегии запускают.',1,'0,30 10,29 20,28 30,29 40,27 50,28 60,26 70,27 80,25 90,24 100,22']];
let CV={order:[],i:0,dep:1000000,ok:0,bad:0,killed:0,hist:[],done:false,best:null};
try{const p=JSON.parse(localStorage.getItem('cn_curve_progress')||'null');if(p&&p.order&&p.order.length===8&&!p.done)CV=p}catch(x){}
function cvSave(){try{localStorage.setItem('cn_curve_progress',JSON.stringify(CV))}catch(x){}}
function cvShuffle(){const o=[0,1,2,3,4,5,6,7];for(let i=o.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));const t=o[i];o[i]=o[j];o[j]=t}return o}
function cvGo(){go('curvequest');cvRender()}
function cvBack(){go('quests')}
function cvWipe(){CV={order:cvShuffle(),i:0,dep:1000000,ok:0,bad:0,killed:0,hist:[],done:false,best:CV.best};cvSave();cvRender()}
function cvCase(){return CV_C[CV.order[CV.i]]}
function cvSvg(pts){const a=pts.split(' ').map(function(p){const xy=p.split(',');return(+xy[0])*2.2+','+(+xy[1])});return '<svg viewBox="0 0 220 40" preserveAspectRatio="none" style="width:100%;height:64px;background:rgba(56,189,248,.05);border-radius:8px" aria-label="Кривая доходности"><polyline points="'+a.join(' ')+'" fill="none" stroke="#38BDF8" stroke-width="1.5"/></svg>'}
function cvPick(launch){if(CV.done||CV.i>=8)return;const c=cvCase(),honest=c[4]===1;let ok,loss=0;
if(launch&&honest){ok=true;CV.ok++}
else if(launch&&!honest){ok=false;loss=Math.min(150000,CV.dep);CV.dep-=loss;CV.bad++}
else if(!launch&&honest){ok=false;CV.killed++}
else{ok=true;CV.ok++}
CV.hist.push(ok?1:0);
CV.last='<div class="sq-sys" style="border-color:'+(ok?'var(--ok,#22C55E)':'var(--bad)')+'">'+(ok?'✅ Верно. ':'❌ ')+(loss?'−'+loss.toLocaleString('ru-RU')+' ₽. ':'')+c[3]+'</div><div class="sq-sys">'+(window.kryptikAvatar?kryptikAvatar(ok?'happy':'doubt',32):'')+'<b>Криптик:</b> «'+(ok?(window.kryptikSay?kryptikSay('win_easy'):'Принято.'):(honest?'Ты зарезал единственную честную. Красивых кривых бояться — тоже крайность.':'Красивая кривая — заявление, не доказательство.'))+'»</div>';
CV.i++;if(CV.i>=8)CV.done=true;cvSave();cvRender()}
function cvRender(){const box=document.getElementById('cv_box');if(!box)return;let h='<button class="btn ghost sm" onclick="cvBack()">← К квестам</button>';
if(CV.done){const pct=Math.round(CV.hist.filter(function(x){return x===1}).length/8*100);
const verdict=CV.bad===0&&CV.killed===0?'🏛 Инвесткомитет':CV.bad===0?'🛡 Осторожный':CV.bad<=2?'🎲 Оптимист':'🙏 Вера в грааль';
const vtxt=CV.bad===0&&CV.killed===0?'Ни одной отравленной в проде, честная запущена. Так держится фонд.':CV.bad===0?'Отравленных не пропустил, но зарезал честную. Паранойя дешевле наивности, но тоже стоит денег.':CV.bad<=2?'Пропустил отравленные в прод. Рынок выставил счёт: смотри методику, не кривую.':'Ты запускаешь всё красивое. Это не инвесткомитет, это казино.';
h+='<h2 style="font-size:17px;margin:10px 0">📉 Итог заседания</h2><div class="sq-assets"><span>💼 '+CV.dep.toLocaleString('ru-RU')+' ₽</span><span>✅ '+CV.ok+'</span><span>💀 пропущено: '+CV.bad+'</span><span>🗑 зарезано честных: '+CV.killed+'</span></div>';
h+='<div class="sq-sys" style="border-color:'+(CV.bad===0?'var(--ok,#22C55E)':'var(--bad)')+'">'+(window.kryptikAvatar?kryptikAvatar(CV.bad===0?'happy':'doubt',40):'')+'<div><b>'+verdict+' · '+pct+'%</b><div style="font-size:12.5px;color:var(--mut)">'+vtxt+'</div></div></div>';
h+='<div class="sq-sys" style="font-size:12.5px"><b>Правило:</b> красивый бэктест — заявление, а не доказательство. Доказательство — методика: OOS-период, комиссии, честная вселенная, размер выборки. Уроки 2.5–2.6.</div>';
h+='<div style="margin-top:10px"><button class="btn" onclick="cvWipe()">🔄 Новое заседание</button><button class="btn ghost sm" onclick="cvBack()">← К квестам</button></div>';
if(!CV.best||pct>CV.best)CV.best=pct;cvSave();box.innerHTML=h;return}
const c=cvCase();
h+='<div class="sq-assets"><span>💼 '+CV.dep.toLocaleString('ru-RU')+' ₽</span><span>Кейс '+(CV.i+1)+'/8</span><span>💀 '+CV.bad+'</span></div>';
if(CV.last)h+=CV.last;
h+='<h2 style="font-size:16px;margin:8px 0">Стратегия '+c[0]+'</h2>';
h+=cvSvg(c[5]);
h+='<div class="sq-sys" style="font-size:12.5px"><b>Метрики:</b> '+c[1]+'</div>';
h+='<div class="sq-sys" style="font-size:12.5px"><b>Методика:</b> '+c[2]+'</div>';
h+='<div style="margin-top:8px"><button class="btn" onclick="cvPick(true)">🚀 Запустить в прод</button> <button class="btn ghost" onclick="cvPick(false)">🗑 В мусорку</button></div>';
box.innerHTML=h}
function renderCurveCard(){const c=document.getElementById('curve_card_in_sims');if(!c)return;let all=true;for(let i=1;i<=6;i++)if(!(typeof lessonsDone==='object'&&lessonsDone['p2_l'+i]===1))all=false;let p=null;try{p=JSON.parse(localStorage.getItem('cn_curve_progress')||'null')}catch(x){}let h='<h3>📉 Квест «Кривая-обманщица»</h3><p style="color:var(--mut);font-size:13px">8 бэктестов с красивыми кривыми. 7 с подвохом, 1 честная. Решай, что пойдёт в прод — и не угробь депозит.</p>';if(!all){h+='<span class="badge" style="border-color:var(--mut);color:var(--mut)">🔒 Заверши уроки 2.1–2.6, чтобы открыть</span>'}else{h+='<button class="btn" onclick="cvGo()">'+(p&&p.i>0&&!p.done?'▶ Продолжить':'📉 Начать заседание')+'</button>';if(p&&p.best!=null)h+=' <span style="font-size:12px;color:var(--mut)">Лучший: '+p.best+'%</span>'}c.innerHTML=h}
window.CVNS={go:cvGo,wipe:cvWipe,pick:cvPick,renderCard:renderCurveCard};
