let FM={order:[],i:0,picks:[],loss:0,right:0,done:false,last:'',best:null};
try{const p=JSON.parse(localStorage.getItem('cn_first_progress')||'null');if(p&&p.order&&p.order.length===8&&!p.done){FM=Object.assign(FM,p)}}catch(x){}
function fmSave(){try{localStorage.setItem('cn_first_progress',JSON.stringify(FM))}catch(x){}}
function fmShuffle(){const o=[0,1,2,3,4,5,6,7];for(let i=o.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));const t=o[i];o[i]=o[j];o[j]=t}return o}
function fmGo(){go('firstquest');fmRender()}
function fmBack(){go('quests')}
function fmWipe(){FM={order:fmShuffle(),i:0,picks:[],loss:0,right:0,done:false,last:'',best:FM.best};fmSave();fmRender()}
function fmStep(){return FM_D[FM.order[FM.i]]}
function fmPick(idx){if(FM.done)return;const c=fmStep(),o=c[2][idx],lvl=o[1],loss=o[2];
FM.picks.push({step:FM.order[FM.i],opt:idx,lvl:lvl});FM.loss+=loss;if(lvl===0)FM.right++;
FM.last='<div class="sq-sys" style="border-color:'+(lvl===0?'var(--ok,#22C55E)':lvl===1?'#EAB308':'var(--bad)')+'">'+(lvl===0?'✅ ':lvl===1?'🟡 −'+loss.toLocaleString('ru-RU')+' ₽. ':'❌ −'+loss.toLocaleString('ru-RU')+' ₽. ')+o[3]+'</div><div class="sq-sys">'+(window.kryptikAvatar?kryptikAvatar(lvl===0?'happy':lvl===1?'neutral':'doubt',32):'')+'<b>Криптик:</b> «'+(lvl===0?'База работает. Так держать.':lvl===1?'Могло быть хуже. Но могло быть и лучше.':'Классика новичка. Запомни цену этого урока.')+'»</div>';
FM.i++;if(FM.i>=8)FM.done=true;fmSave();fmRender()}
function fmRender(){const box=document.getElementById('fm_box');if(!box)return;
let h='<button class="btn ghost sm" onclick="fmBack()">← К квестам</button>';
if(FM.done){const left=100000-FM.loss,grade=FM.loss<=10000?['🌱 Первый месяц без потерь','База усвоена: ты не сделал ни одной классической ошибки новичка. Так держать.']:FM.loss<=30000?['📚 Дорогой, но полезный месяц','Несколько уроков оплачены. Главное — они усвоены, а не повторены.']:FM.loss<=60000?['💸 Заплатил за обучение','Рынок взял плату. Вопрос — усвоил ли ты урок, или заплатишь ещё раз.']:['🔥 Классический новичок','Все ловушки собраны. Перечитай уроки 0.1–0.20 — они дешевле, чем рынок.'];
h+='<h2 style="font-size:17px;margin:10px 0">🌱 Итог первого месяца</h2><div class="sq-assets"><span>Осталось: '+left.toLocaleString('ru-RU')+' ₽</span><span>📉 потери: '+FM.loss.toLocaleString('ru-RU')+' ₽</span><span>✅ верных: '+FM.right+'/8</span></div>';
h+='<div class="sq-sys" style="border-color:'+(FM.loss<=30000?'var(--ok,#22C55E)':'var(--bad)')+'">'+(window.kryptikAvatar?kryptikAvatar(FM.loss<=30000?'happy':'doubt',40):'')+'<div><b>'+grade[0]+'</b><div style="font-size:12.5px;color:var(--mut)">'+grade[1]+'</div></div></div>';
const fails=FM.picks.filter(p=>p.lvl===2);
if(fails.length){h+='<div class="sq-sys" style="font-size:12.5px"><b>Где ты заплатил:</b><ul style="margin:6px 0 0 16px;padding:0">'+fails.map(p=>'<li style="margin:4px 0"><b>'+FM_D[p.step][0]+':</b> '+FM_D[p.step][2][p.opt][3]+'</li>').join('')+'</ul></div>'}
else h+='<div class="sq-sys" style="font-size:12.5px"><b>Где ты заплатил:</b> нигде. Ноль классических ошибок — редкость для первого месяца.</div>';
h+='<div class="sq-sys" style="font-size:12.5px"><b>Правило первого месяца:</b> рынок не прощает базовых ошибок, но щедро платит за базовую дисциплину. Уроки 0.1–0.20.</div>';
h+='<div style="margin-top:10px"><button class="btn" onclick="fmWipe()">🔄 Пройти заново</button><button class="btn ghost sm" onclick="fmBack()">← К квестам</button></div>';
const score=Math.max(0,100-Math.round(FM.loss/1000));if(!FM.best||score>FM.best)FM.best=score;fmSave();box.innerHTML=h;return}
const c=fmStep();
h+='<div class="sq-assets"><span>Шаг '+(FM.i+1)+'/8</span><span>💼 '+(100000-FM.loss).toLocaleString('ru-RU')+' ₽</span><span>✅ '+FM.right+'</span></div>';
if(FM.last)h+=FM.last;
h+='<h2 style="font-size:16px;margin:8px 0">'+c[0]+'</h2><div class="sq-sys">'+c[1]+'</div>';
c[2].forEach(function(o,idx){h+='<button class="btn ghost" style="display:block;width:100%;text-align:left;margin:6px 0;font-size:13px" onclick="fmPick('+idx+')">'+o[0]+'</button>'});
box.innerHTML=h}
function renderFirstCard(){const c=document.getElementById('first_card_in_sims');if(!c)return;let all=true;for(let i=1;i<=20;i++)if(!(typeof lessonsDone==='object'&&lessonsDone['p0_l'+i]===1))all=false;let p=null;try{p=JSON.parse(localStorage.getItem('cn_first_progress')||'null')}catch(x){}let h='<h3>🌱 Квест «Первые деньги»</h3><p style="color:var(--mut);font-size:13px">100 000 ₽ и ноль опыта. 8 решений первого месяца: от первого депозита до плеча x20. Пройди месяц без классических ошибок новичка.</p>';if(!all){h+='<span class="badge" style="border-color:var(--mut);color:var(--mut)">🔒 Заверши уроки 0.1–0.20, чтобы открыть</span>'}else{h+='<button class="btn" onclick="fmGo()">'+(p&&p.i>0&&!p.done?'▶ Продолжить месяц':'🌱 Начать месяц')+'</button>';if(p&&p.best!=null)h+=' <span style="font-size:12px;color:var(--mut)">Лучший: '+p.best+'/100</span>'}c.innerHTML=h}
window.FMNS={go:fmGo,wipe:fmWipe,pick:fmPick,renderCard:renderFirstCard};
