/* =========================================================================
   Д14 · Адаптивные пороги: стена и свежесть — «необычное для текущего часа»
   ========================================================================= */
const WallStats = { vols: [], FRESH_DEFAULT: 60 };
window.V10WallMult = function(all, med){
  try{
    /* перцентиль 90 внутри окна последних снимков (в памяти) + ночная поправка */
    const h = new Date().getHours();
    const nightAdj = (h >= 1 && h <= 6) ? 0.8 : 1.2; // ночью «толстая» стена тоньше
    if(WallStats.vols.length > 12){
      const sorted = WallStats.vols.slice(-120).slice().sort((a, b) => a - b);
      const p90 = sorted[Math.floor(sorted.length * 0.9)] || med * 4;
      const mult = Math.max(2.5, Math.min(8, p90 / (med || 1)));
      return Math.round(mult * nightAdj * 10) / 10;
    }
  }catch(e){}
  return 4;
};
window.V10FreshSec = function(){
  const h = new Date().getHours();
  /* ночью стакан меняется медленнее — порог свежести мягче */
  return (h >= 1 && h <= 6) ? 110 : WallStats.FRESH_DEFAULT;
};
/* копим распределение объёмов уровней для адаптивного порога */
Bus.on('SNAPSHOT', () => {
  try{
    const ob = LIVE.data.orderbook;
    if(ob && ob.bids && ob.asks){
      const all = ob.bids.slice(0, 20).concat(ob.asks.slice(0, 20)).map(x => x[1]);
      WallStats.vols = WallStats.vols.concat(all).slice(-240);
    }
  }catch(e){}
});

