/* =========================================================================
   Д7 · Перевод наблюдения в язык риска R: ёмкость, рента, P(ликвидация)
   ========================================================================= */
const RiskHint = {
  inR(obs){
    try{
      const src = obs.src;
      let line = '';
      if(src === 'orderbook'){
        const ob = LIVE.data.orderbook;
        if(!ob) return '';
        const st = (typeof obStats === 'function') ? obStats(ob) : null;
        if(!st) return '';
        const price = st.mid;
        const capUsd = (st.bidVol + st.askVol) * price;
        const fund = LIVE.data.funding;
        const rentDay = fund ? (fund.rate * 3 * 100) : null;
        line = 'R: ёмкость ближних уровней ~$' + Math.round(capUsd / 1000) + ' тыс' +
          (rentDay != null ? ' · рента фандинга ~' + (rentDay >= 0 ? '+' : '') + rentDay.toFixed(2) + '%/день' : '') +
          ' · вход рынком платит спред ' + st.spreadBps.toFixed(1) + ' б.п.';
      } else if(src === 'funding'){
        const f = LIVE.data.funding;
        if(!f) return '';
        line = 'R: удержание позиции платит ' + (f.rate * 3 * 100).toFixed(2) + '% в день → за неделю ' + (f.rate * 21 * 100).toFixed(1) + '% — это минус к любому ожиданию, до стопа и тейка.';
      } else if(src === 'klines'){
        const kl = LIVE.data.klines;
        if(!kl || !kl.candles || kl.candles.length < 24) return '';
        const c = kl.candles[kl.candles.length - 1].c;
        const hrs = kl.candles.slice(-48);
        /* v10.1 (приём у эксперта): ход ОТ close (как будто вошли по закрытию), не полный диапазон h−l */
        const liqAt = lev => {
          const dist = 100 / lev;
          const hits = hrs.filter(x => {
            const lowMove = (x.l - x.c) / x.c * 100, highMove = (x.h - x.c) / x.c * 100;
            return Math.abs(lowMove) >= dist || Math.abs(highMove) >= dist;
          }).length;
          return Math.round(hits / hrs.length * 100);
        };
        line = 'R: при плече ×3 ход против входа касался дистанции ликвидации у ' + liqAt(3) + '% часов; при ×5 — у ' + liqAt(5) + '%. Ликвидация ближе, чем кажется.';
      }
      return line
        ? '<div style="margin-top:8px;background:rgba(124,58,237,.08);border-left:3px solid var(--acc2);border-radius:6px;padding:7px 10px;font-size:11.5px;color:var(--txt);line-height:1.5;font-family:var(--mono)">' + line + '</div>'
        : '';
    }catch(e){ return ''; }
  }
};
