/* =========================================================================
   Д5 · «Объясни своими словами» на живой карточке (Feynman-on-live)
   ========================================================================= */
const FEYN_MARKERS = {
  ob_spread: ['спред', 'ликвид'], ob_imbalance: ['дисбаланс', 'перевес', 'заявок'],
  ob_wall: ['стен', 'спуфинг', 'отмен'], ob_fresh: ['снимок', 'свеж'],
  candle_body: ['тело', 'тени', 'диапазон'], candle_volume: ['объём', 'участн'],
  funding_rate: ['фандинг', 'платят', 'длинн', 'коротк'], funding_extreme: ['фандинг', 'перегр', 'хрупк'],
  fng_zone: ['страх', 'жадност', 'настроен'], fng_shift: ['неделю', 'настроен', 'сменил'],
  btc_fees: ['комисси', 'очеред', 'блок'], btc_dominance: ['доля', 'капитализ'],
  diff_wall_gone: ['сняли', 'отмени', 'спуфинг'], diff_wall_new: ['стен', 'появил'],
  diff_spread_jump: ['спред', 'расширил', 'волатил'], diff_funding_flip: ['инверс', 'знак', 'развернул'],
  diff_imbalance_shift: ['дисбаланс', 'сместил', 'перевес'],
  cvd_divergence: ['дельт', 'агресс', 'дивергенц'], regime_mix: ['режим', 'тренд', 'боковик']
};
const FORECAST_WORDS = /вырастет|вырастет|упадёт|упадет|покупай|продавай|купи|продай|сигнал к|входить сейчас|будет рост|будет падение/i;
function feynCheckLive(obsId, text){
  const t = String(text || '').trim();
  const res = { ok: false, msg: '' };
  if(t.length < 60){ res.msg = 'Слишком коротко — объясни хотя бы парой предложений (60+ символов): что число значит и чего НЕ значит.'; return res; }
  if(FORECAST_WORDS.test(t)){ res.msg = 'В объяснении появился прогноз («вырастет/упадёт/покупай…»). Карточка — про механику, а не про будущее. Убери прогноз и объясни, что число описывает прямо сейчас.'; return res; }
  const markers = FEYN_MARKERS[obsId] || [];
  const low = t.toLowerCase();
  const hits = markers.filter(m => low.includes(m));
  if(markers.length && !hits.length){
    res.msg = 'Не хватает опорных понятий этого наблюдения: ' + markers.slice(0, 3).join(', ') + '. Попробуй через них.';
    return res;
  }
  res.ok = true;
  res.msg = 'Принято: механика без прогноза, опорные понятия на месте' + (hits.length ? ' (' + hits.join(', ') + ')' : '') + '. Записано в журнал Фейнмана.';
  return res;
}
window.feynCheckLive = feynCheckLive;
function feynLiveHTML(obs){
  const done = V10.liveFeynJournal && V10.liveFeynJournal[obs.id];
  return '<div style="margin-top:8px;background:rgba(34,197,94,.06);border:1px dashed var(--ok);border-radius:10px;padding:9px 11px">' +
    '<div style="font-size:10.5px;font-weight:800;color:var(--ok);text-transform:uppercase;margin-bottom:5px">🗣 Объясни своими словами</div>' +
    '<textarea id="feyn_live_' + obs.id + '" data-v10val rows="2" style="width:100%;background:#040714;border:1px solid var(--line);border-radius:8px;padding:7px;color:var(--txt);font-size:12px;resize:vertical" placeholder="Своими словами: что это число значит, чего оно НЕ значит…"></textarea>' +
    '<div style="display:flex;gap:6px;margin-top:5px;flex-wrap:wrap">' +
      '<button class="btn sm ghost" style="font-size:11px" onclick="feynLiveCommit(\'' + obs.id + '\')">Проверить (детерминированно)</button>' +
      '<button class="btn sm ghost" style="font-size:11px" onclick="feynLiveAI(\'' + obs.id + '\')">🤖 Проверить с ИИ</button>' +
    '</div>' +
    '<div id="feyn_live_fb_' + obs.id + '" style="font-size:11.5px;margin-top:5px;line-height:1.5">' + (done ? '<span style="color:var(--ok)">✓ уже объяснял(а) ранее</span>' : '') + '</div>' +
  '</div>';
}
window.feynLiveHTML = feynLiveHTML;
window.feynLiveCommit = function(obsId){
  const ta = document.getElementById('feyn_live_' + obsId);
  const fb = document.getElementById('feyn_live_fb_' + obsId);
  if(!ta || !fb) return;
  const r = feynCheckLive(obsId, ta.value);
  fb.innerHTML = '<span style="color:' + (r.ok ? 'var(--ok)' : 'var(--warn)') + '">' + (r.ok ? '✅ ' : '⚠️ ') + r.msg + '</span>';
  if(r.ok){
    V10.liveFeynJournal = V10.liveFeynJournal || {};
    V10.liveFeynJournal[obsId] = { ts: Date.now(), text: ta.value.slice(0, 400) };
    try{ localStorage.setItem('cn_live_feynman', JSON.stringify(V10.liveFeynJournal)); }catch(e){}
    V10.metrics.feynLive = (V10.metrics.feynLive || 0) + 1;
  }
};
window.feynLiveAI = function(obsId){
  const ta = document.getElementById('feyn_live_' + obsId);
  const fb = document.getElementById('feyn_live_fb_' + obsId);
  if(!ta || !fb) return;
  const det = (typeof COACH_DETECTORS !== 'undefined') ? COACH_DETECTORS.find(d => d.id === obsId) : null;
  fb.innerHTML = '<span style="color:var(--mut)">🤖 ИИ проверяет объяснение…</span>';
  MENTOR.ask('feynman', 'live:' + obsId, { explanation: ta.value, context: det ? det.run && '' : '', meaning: det ? '' : '' }).then(r => {
    const v = r.json;
    if(v && v.verdict){
      const col = v.verdict === 'understood' ? 'var(--ok)' : v.verdict === 'partial' ? 'var(--warn)' : 'var(--bad)';
      fb.innerHTML = '<span style="color:' + col + '">' + (v.verdict === 'understood' ? '✅ Понял(а)' : v.verdict === 'partial' ? '🟡 Частично' : '❌ Есть пробелы') + (v.advice ? ' — ' + v.advice : '') + (v.demo ? ' <b>[ДЕМО]</b>' : '') + '</span>';
      if(v.verdict === 'understood'){
        V10.liveFeynJournal = V10.liveFeynJournal || {};
        V10.liveFeynJournal[obsId] = { ts: Date.now(), text: ta.value.slice(0, 400) };
        try{ localStorage.setItem('cn_live_feynman', JSON.stringify(V10.liveFeynJournal)); }catch(e){}
      }
    } else {
      fb.innerHTML = '<span style="color:var(--mut)">' + (r.text || 'ИИ не ответил структурно — используй детерминированную проверку.') + '</span>';
    }
  }).catch(() => { fb.innerHTML = '<span style="color:var(--warn)">ИИ недоступен — детерминированная проверка работает всегда.</span>'; });
};
try{ V10.liveFeynJournal = JSON.parse(localStorage.getItem('cn_live_feynman') || '{}'); }catch(e){ V10.liveFeynJournal = {}; }

/* =========================================================================
   Д6 · Brier-калибровка на количественных LIVE_TASKS (фикс БГ-2: st.recs)
   ========================================================================= */
const LiveLearn = {
  st: { recs: [] },
  load(){
    try{ this.st = JSON.parse(localStorage.getItem('cn_live_brier') || '{"recs":[]}'); }catch(e){ this.st = { recs: [] }; }
    if(!this.st.recs) this.st.recs = [];
    return this.st;
  },
  save(){ try{ localStorage.setItem('cn_live_brier', JSON.stringify(this.st)); }catch(e){} },
  record(taskId, p, ok){
    this.load();
    const score = Math.pow(p - (ok ? 1 : 0), 2);
    this.st.recs.push({ t: Date.now(), task: taskId, p: p, ok: ok ? 1 : 0, score: score });
    if(this.st.recs.length > 200) this.st.recs = this.st.recs.slice(-200);
    this.save();
    V10.metrics.liveBrierN = this.st.recs.length;
  },
  summary(){
    this.load();
    if(!this.st.recs.length) return null;
    const brier = this.st.recs.reduce((s, r) => s + r.score, 0) / this.st.recs.length;
    const hit = this.st.recs.filter(r => r.ok === 1).length;
    return { n: this.st.recs.length, brier: brier, hit: hit, bad: brier > 0.4, worse: brier > 0.25 };
  },
  /* reliability: пары (p, факт) по корзинам 40-60-80 */
  reliability(){
    this.load();
    const bins = {};
    this.st.recs.forEach(r => {
      const k = r.p <= 0.5 ? '≤50%' : r.p <= 0.7 ? '50–70%' : '70%+';
      (bins[k] = bins[k] || []).push(r);
    });
    return Object.keys(bins).map(k => {
      const arr = bins[k];
      return { bin: k, n: arr.length, p: arr.reduce((s, r) => s + r.p, 0) / arr.length, fact: arr.reduce((s, r) => s + r.ok, 0) / arr.length };
    });
  },
  assignRemedy(){
    const s = this.summary();
    if(!s || !s.bad) return '';
    /* авто-назначение уроков Фазы М: ищем реальные уроки про вероятность/калибровку */
    let lid = null;
    try{
      if(typeof LESSONS !== 'undefined'){
        const l = LESSONS.find(x => /вероятн|калибров|brier|кромвел/i.test(x.title || '')) ||
                  LESSONS.find(x => /риск|психолог/i.test(x.title || ''));
        if(l) lid = l.id;
      }
    }catch(e){}
    return '<div style="margin-top:6px;font-size:11.5px;color:var(--warn);background:rgba(245,158,11,.08);border-radius:8px;padding:7px 10px">⚠️ Brier ' + s.brier.toFixed(3) + ' — заметно хуже случайности. Уверенность опережает точность.' +
      (lid ? ' Назначено: урок «' + lid + '» — <button class="btn sm ghost" style="font-size:10.5px;padding:2px 8px" onclick="v10GoLesson(\'' + lid + '\')">открыть</button>' : ' Назначено: модуль о вероятностях (Фаза М).') + '</div>';
  }
};
V10.LiveLearn = LiveLearn;

/* уверенность перед ответом (40/60/80) инжектится в каждую живую задачу */
PatchReg.once('livelearn-ui', () => {
  const prevCol = window.renderLiveCoachCol;
  if(typeof prevCol !== 'function') return;
  window.renderLiveCoachCol = function(){
    prevCol();
    const col = document.getElementById('live_coach_col');
    if(!col) return;
    LIVE_TASKS.forEach(t => {
      if(!LIVE.data[t.src]) return;
      const inp = document.getElementById('live_task_in_' + t.id);
      if(!inp || inp.parentElement.querySelector('.v10conf')) return;
      inp.insertAdjacentHTML('afterend',
        '<div class="v10conf" style="margin-top:6px;font-size:11px;color:var(--mut)">Насколько уверен(а) в ответе? ' +
        [40, 60, 80].map(p => '<label style="margin-right:8px;cursor:pointer"><input type="radio" name="conf_' + t.id + '" value="' + (p / 100) + '" ' + (p === 60 ? 'checked' : '') + ' style="accent-color:var(--acc2)"> ' + p + '%</label>').join('') +
        '</div>');
    });
    const s = LiveLearn.summary();
    if(s){
      const anchor = col.querySelector('.v10conf');
      if(anchor){
        anchor.insertAdjacentHTML('afterend',
          '<div id="livelearn_summary" style="font-size:11.5px;color:var(--acc2);background:rgba(124,58,237,.07);border-radius:8px;padding:7px 10px;margin-top:8px">📊 Калибровка на живых задачах: ' + s.hit + '/' + s.n + ' верно · Brier <b>' + s.brier.toFixed(3) + '</b> ' +
          (s.bad ? '(>0.40 — хуже случайности)' : s.worse ? '(>0.25 — выше порога бейджа «Калиброванный аналитик»)' : '(≤0.25 — целевая зона)') + '</div>' + LiveLearn.assignRemedy());
      }
    }
  };
  window.renderLiveCoachCol.__v10wrapped = true;
});
PatchReg.once('livelearn-check', () => {
  const orig = window.liveTaskCheck;
  if(typeof orig !== 'function') return;
  window.liveTaskCheck = function(id){
    const t = LIVE_TASKS.find(x => x.id === id);
    const inp = document.getElementById('live_task_in_' + id);
    if(!t || !inp) return orig(id);
    const sel = document.querySelector('input[name="conf_' + id + '"]:checked');
    const p = sel ? +sel.value : 0.6;
    const val = parseFloat(String(inp.value).replace(',', '.'));
    if(!isFinite(val)) return orig(id);
    /* ДЕФ-4-совместимо: эталон заморожен при показе */
    const truth = (t._frozen != null && isFinite(t._frozen)) ? t._frozen : t.answer();
    const tol = Math.max(Math.abs(truth) * 0.2, Math.abs(truth) * 0.001 + 1e-9);
    const ok = Math.abs(val - truth) <= tol;
    LiveLearn.record(id, p, ok);
    const r = orig(id);
    const fb = document.getElementById('live_task_fb_' + id);
    if(fb){
      fb.insertAdjacentHTML('beforeend', '<div style="font-size:11px;color:var(--mut);margin-top:4px">🎯 Калибровка: уверенность ' + Math.round(p * 100) + '% при ' + (ok ? 'верном' : 'неверном') + ' ответе → Brier ' + Math.pow(p - (ok ? 1 : 0), 2).toFixed(3) + ' (учтено в сводке выше)</div>');
      CardState.saveLearn(id, fb.innerHTML);
    }
    return r;
  };
  window.liveTaskCheck.__v10wrapped = true;
});

