/* =========================================================================
   Д3/Н9 · RegimeMix: детектор «Режим рынка» + гейтинг с объяснением
   (без ложных ссылок на Конституцию — ссылка только на Правило 4 по делу)
   ========================================================================= */
const RegimeMix = {
  current: null,
  history: [],
  compute(){
    const kl = LIVE.data.klines, f = LIVE.data.funding, fng = LIVE.data.fng, ob = LIVE.data.orderbook;
    if(!kl || !kl.candles || kl.candles.length < 24) return null;
    const cs = kl.candles.slice(-24);
    const bodies = cs.map(c => Math.abs(c.c - c.o) / Math.max(0.0001, c.h - c.l));
    const greens = cs.filter(c => c.c > c.o).length;
    const avgBody = bodies.reduce((a, b) => a + b, 0) / bodies.length;
    /* наклон: сравниваем среднюю цену первых 12 и последних 12 свечей */
    const mid = arr => arr.reduce((s, c) => s + c.c, 0) / arr.length;
    const slope = (mid(cs.slice(12)) - mid(cs.slice(0, 12))) / mid(cs) * 100;
    let spreadBps = null, imbalance = null;
    if(ob){
      const st = (typeof obStats === 'function') ? obStats(ob) : null;
      if(st){ spreadBps = st.spreadBps; imbalance = st.bidVol + st.askVol > 0 ? st.bidVol / (st.bidVol + st.askVol) : 0.5; }
    }
    let score = 0, why = [];
    if(Math.abs(slope) > 0.8){ score += 2; why.push('наклон цены ' + (slope > 0 ? '+' : '') + slope.toFixed(2) + '% за полсуток'); }
    if(greens >= 16 || greens <= 8){ score += 1; why.push(greens + ' направленных свечей из 24'); }
    if(avgBody > 0.6){ score += 1; why.push('среднее тело ' + Math.round(avgBody * 100) + '% диапазона'); }
    if(spreadBps != null && spreadBps > 12){ score = Math.max(0, score - 2); why.push('спред ' + spreadBps.toFixed(1) + ' б.п. — ликвидность тонкая'); }
    const fngV = fng && fng.current ? fng.current.value : null;
    if(fngV != null && (fngV > 75 || fngV < 25)) why.push('сентимент ' + fngV + ' — экстремальная зона');
    let regime;
    if(spreadBps != null && spreadBps > 20 && avgBody > 0.75) regime = 'crisis';
    else if(score >= 3) regime = 'trend';
    else regime = 'range';
    const res = { regime: regime, score: score, slope: slope, greens: greens, avgBody: avgBody, spreadBps: spreadBps, imbalance: imbalance, why: why.slice(0, 3), ts: Date.now() };
    this.current = res;
    if(!this.history.length || this.history[this.history.length - 1].regime !== regime){
      this.history.push({ regime: regime, ts: Date.now() });
      if(this.history.length > 200) this.history = this.history.slice(1);
      if(this.history.length > 1) Bus.pub('REGIME_CHANGE', res);
    }
    return res;
  },
  RU: { trend: 'Тренд (направленное движение)', range: 'Боковик (пила)', crisis: 'Кризисная ликвидность' },
  advise(r){
    if(!r) return '';
    if(r.regime === 'range'){
      return 'Гейтинг учебный, не запрет: в боковике импульсный вход «на пробой» чаще всего покупает ложный вынос — цена возвращается в диапазон. Это не цензура входа, а объяснение, почему вероятность сценария «пробой продолжится» тут ниже, чем «возврат к середине».';
    }
    if(r.regime === 'trend'){
      return 'В тренде работает другое правило: контртрендовые входы «против наклона» платят за преждевременность. Режимы меняются — перед сменой наклон выравнивается первым (следи за slope).';
    }
    return 'Кризисная ликвидность: спред и волатильность таковы, что исполнение unpredictably дорого. Учебный вывод: в такие часы рулит не стратегия входа, а размер позиции и kill-switch.';
  },
  card(){
    const r = this.compute();
    if(!r) return '';
    const mapSim = { trend: 'sim_alphabeta', range: 'sim_corr', crisis: 'sim_killswitch' };
    return '<div class="coach-card" id="coach_card_regime_mix" style="background:var(--card);border:1.5px solid var(--acc2);border-radius:12px;padding:14px 16px;margin-bottom:10px">' +
      '<div style="font-weight:800;font-size:13.5px;color:var(--txt)">🧭 Режим рынка: ' + this.RU[r.regime] + ' <span style="font-size:10px;color:var(--mut);font-weight:600">(детерминированная оценка: наклон ' + (r.slope > 0 ? '+' : '') + r.slope.toFixed(2) + '%, зелёных ' + r.greens + '/24, тело ' + Math.round(r.avgBody * 100) + '%)</span></div>' +
      '<div style="font-size:12.5px;color:var(--txt);line-height:1.55;margin-top:8px"><b>Почему:</b> ' + (r.why.length ? r.why.map(esc).join(' · ') : 'признаков выраженного режима мало — данные нейтральны') + '</div>' +
      '<div style="font-size:12.5px;color:var(--txt);line-height:1.55;margin-top:6px"><b>Гейтинг (объясняющий):</b> ' + this.advise(r) + '</div>' +
      '<div style="font-size:11px;color:var(--mut);margin-top:6px">Ссылка по теме — Правило 4 Конституции: оценивай любую стратегию минимум на трёх бенчмарках и в разных режимах, иначе «работает» окажется подгонкой под один режим.</div>' +
      '<div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap">' +
        '<button class="btn sm" style="font-size:11px" onclick="goToLessonSim(\'' + mapSim[r.regime] + '\')">🚀 Тренажёр под этот режим</button>' +
        '<button class="btn sm ghost" style="font-size:11px" onclick="regimeToLab(\'' + r.regime + '\')">🧪 Показать в лаборатории режимов</button>' +
      '</div></div>';
  }
};
window.regimeToLab = function(regime){
  try{
    const map = { trend: 'bull', range: 'chop', crisis: 'flash_crash' };
    if(typeof setMarketRegime === 'function'){
      window.go('sims');
      setTimeout(() => {
        const chip = document.querySelector('#market_regime_controls .chip');
        setMarketRegime(map[regime], document.querySelector('.chip[onclick*="' + map[regime] + '"]'));
        const desc = document.getElementById('market_regime_desc');
        if(desc){
          desc.scrollIntoView({ block: 'center', behavior: 'smooth' });
          desc.style.transition = 'box-shadow .3s';
          desc.style.boxShadow = '0 0 0 3px var(--acc2)';
          setTimeout(() => { desc.style.boxShadow = 'none'; }, 2400);
        }
      }, 400);
    }
  }catch(e){}
};
window.regimeToLab = window.regimeToLab;
V10.RegimeMix = RegimeMix;
window.RegimeMix = RegimeMix;

/* =========================================================================
   Д8 · «Кит или Шум»: учебный радар с симуляционными входами
   ========================================================================= */
const WhaleLab = {
  panel(){
    return '<div class="coach-card" style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px 16px;margin-bottom:10px">' +
      '<div style="font-weight:800;font-size:13px;color:var(--txt)">🐋 Радар «Кит или Шум» <span style="font-size:10px;color:var(--warn);font-weight:600">· симуляционные входы, не ончейн-фид</span></div>' +
      '<div style="font-size:11.5px;color:var(--mut);margin:5px 0 8px">Кластеры сделок и пробуждение спящих монет — ончейн-данные. Здесь они вводятся руками как учебные гипотезы, а радар считает, похож ли расклад на крупного игрока.</div>' +
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">' +
        '<label style="font-size:11px;color:var(--txt)">Кластеры сделок (0–10)<input id="whale_cl" data-v10val type="range" min="0" max="10" value="3" style="width:100%;accent-color:var(--acc2)" oninput="whaleScore()"></label>' +
        '<label style="font-size:11px;color:var(--txt)">Спящие монеты сдвинулись (0–10)<input id="whale_dorm" data-v10val type="range" min="0" max="10" value="1" style="width:100%;accent-color:var(--acc2)" oninput="whaleScore()"></label>' +
        '<label style="font-size:11px;color:var(--txt)">Всплеск объёма ×<span id="whale_vox_v">1.0</span><input id="whale_vox" data-v10val type="range" min="0" max="40" value="10" style="width:100%;accent-color:var(--acc2)" oninput="whaleScore()"></label>' +
        '<label style="font-size:11px;color:var(--txt)">Стены в стакане (0–10)<input id="whale_wall" data-v10val type="range" min="0" max="10" value="2" style="width:100%;accent-color:var(--acc2)" oninput="whaleScore()"></label>' +
        '<label style="font-size:11px;color:var(--txt);display:flex;align-items:center;gap:6px;margin-top:4px"><input id="whale_mm" data-v10val type="checkbox" style="accent-color:var(--acc2)" onchange="whaleScore()"> ММ-пересечение (адрес известного маркет-мейкера)</label>' +
        '<label style="font-size:11px;color:var(--txt);display:flex;align-items:center;gap:6px;margin-top:4px"><input id="whale_mev" data-v10val type="checkbox" style="accent-color:var(--acc2)" onchange="whaleScore()"> MEV-sandwich паттерн в кластере</label>' +
      '</div>' +
      '<div id="whale_out" style="margin-top:8px;font-size:12px;line-height:1.5"></div>' +
      '<div style="display:flex;gap:6px;margin-top:6px"><button class="btn sm" style="font-size:11px" onclick="goToLessonSim(\'sim_whale\')">🚀 Открыть тренажёр sim_whale</button></div>' +
    '</div>';
  },
  score(){
    const cl = +document.getElementById('whale_cl').value;
    const dm = +document.getElementById('whale_dorm').value;
    const vx = +document.getElementById('whale_vox').value / 10;
    const wl = +document.getElementById('whale_wall').value;
    const mm = document.getElementById('whale_mm').checked ? 1 : 0;
    const mev = document.getElementById('whale_mev').checked ? 1 : 0;
    /* v10.1 (приём у эксперта): веса факторов как в ончейн-аналитике — масштаб/скорость/возраст + ММ/MEV */
    const raw = cl * 3.0 + dm * 2.5 + Math.min(vx, 4) * 5.5 + wl * 2.2 + mm * 12 + mev * 8;
    const s = Math.min(100, Math.round(raw));
    const verdict = s >= 70 ? 'похоже на крупного участника (учебная оценка)' :
                    s >= 40 ? 'смешанная картина: и толпа, и кто-то крупный' :
                    'больше похоже на шум розницы';
    document.getElementById('whale_vox_v').textContent = vx.toFixed(1);
    document.getElementById('whale_out').innerHTML =
      '<b style="color:' + (s >= 70 ? 'var(--warn)' : s >= 40 ? 'var(--acc2)' : 'var(--mut)') + '">Скоринг: ' + s + '/100 — ' + verdict + '.</b><br>' +
      'Веса: кластеры 30% · приток/скорость 22% · возраст сна 20% · объём 20% · ММ +12 · MEV +8. ' +
      'Проверь себя: кластеры без объёма = шум; объём без кластеров = розница; кластеры + объём + ММ = учебный профиль «кита». Все входы здесь твои гипотезы, не данные блокчейна.';
  }
};
