function normKlinesOKXv10(d){
  return { source: 'okx', ts: Date.now(),
    candles: (d.data || []).slice().reverse().map(c => ({ t: +c[0], o: +c[1], h: +c[2], l: +c[3], c: +c[4], v: +c[5] })) };
}
PatchReg.once('extra-sources', () => {
  if(!window.LIVE_SOURCES) return;
  LIVE_SOURCES.klines_eth = {
    name: 'Свечи ETH/USDT · 1ч', icon: '🔷', path: '/api/live/klines_eth',
    direct: () => liveFetchJSON('https://www.okx.com/api/v5/market/candles?instId=ETH-USDT&bar=1H&limit=48').then(normKlinesOKXv10)
  };
  LIVE_SOURCES.klines_sol = {
    name: 'Свечи SOL/USDT · 1ч', icon: '🟣', path: '/api/live/klines_sol',
    direct: () => liveFetchJSON('https://www.okx.com/api/v5/market/candles?instId=SOL-USDT&bar=1H&limit=48').then(normKlinesOKXv10)
  };
});
const Corr = {
  cache: null, ts: 0,
  async rolling(){
    if(this.cache && Date.now() - this.ts < 3 * 60e3) return this.cache;
    try{
      const kl = LIVE.data.klines, ke = LIVE.data.klines_eth;
      if(!kl || !ke) return null;
      const btc = kl.candles.slice(-31), eth = ke.candles.slice(-31);
      const mapE = {}; eth.forEach(c => { mapE[c.t] = c.c; });
      const x = [], y = [];
      for(let i = 1; i < btc.length; i++){
        const et = mapE[btc[i].t];
        if(et == null || mapE[btc[i - 1].t] == null) continue;
        x.push((btc[i].c - btc[i - 1].c) / btc[i - 1].c);
        y.push((et - mapE[btc[i - 1].t]) / mapE[btc[i - 1].t]);
      }
      if(x.length < 10) return null;
      let res = null;
      try{ res = await V10.heavyCalc.run('corr', { x: x, y: y }); }catch(e){}
      if(res == null){
        const n = x.length;
        let sx = 0, sy = 0, sxx = 0, syy = 0, sxy = 0;
        for(let i = 0; i < n; i++){ sx += x[i]; sy += y[i]; sxx += x[i] * x[i]; syy += y[i] * y[i]; sxy += x[i] * y[i]; }
        const num = n * sxy - sx * sy, den = Math.sqrt((n * sxx - sx * sx) * (n * syy - sy * sy)) || 1;
        res = num / den;
      }
      this.cache = { r: res, n: x.length, ts: Date.now() };
      return this.cache;
    }catch(e){ return null; }
  },
  panel(){
    const ke = LIVE.data.klines_eth, ks = LIVE.data.klines_sol, kb = LIVE.data.klines;
    if(!ke && !ks) return '';
    const chg = k => {
      if(!k || !k.candles || k.candles.length < 2) return null;
      const a = k.candles[Math.max(0, k.candles.length - 25)], b = k.candles[k.candles.length - 1];
      return (b.c - a.c) / a.c * 100;
    };
    const cb = chg(kb), ce = chg(ke), csol = chg(ks);
    let html = '<div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px 16px;margin-bottom:12px">' +
      '<div style="font-size:11px;font-weight:800;color:var(--mut);text-transform:uppercase;margin-bottom:8px">📊 BTC · ETH' + (ks ? ' · SOL' : '') + ' — риск-он/риск-офф</div>' +
      '<div style="display:flex;gap:10px;flex-wrap:wrap;font-size:12.5px;font-family:var(--mono)">' +
        (cb != null ? '<span>BTC <b style="color:' + (cb >= 0 ? 'var(--ok)' : 'var(--bad)') + '">' + (cb >= 0 ? '+' : '') + cb.toFixed(1) + '%</b></span>' : '') +
        (ce != null ? '<span>ETH <b style="color:' + (ce >= 0 ? 'var(--ok)' : 'var(--bad)') + '">' + (ce >= 0 ? '+' : '') + ce.toFixed(1) + '%</b></span>' : '') +
        (csol != null ? '<span>SOL <b style="color:' + (csol >= 0 ? 'var(--ok)' : 'var(--bad)') + '">' + (csol >= 0 ? '+' : '') + csol.toFixed(1) + '%</b></span>' : '') +
      '</div>';
    if(cb != null && ce != null){
      const riskOn = ce > cb ? 'risk-on: альт сильнее биткоина' : 'risk-off: биткоин держит лучше альтов';
      html += '<div style="font-size:11.5px;color:var(--mut);margin-top:5px">Относительная сила: ' + riskOn + (csol != null ? (csol > ce ? ' · SOL лидер (максимальный аппетит)' : '') : '') + '</div>';
    }
    html += '<div id="corr_line" style="font-size:11.5px;color:var(--txt);margin-top:6px;font-family:var(--mono)">Корреляция BTC↔ETH (30×1ч): считаю…</div>' +
      '<div style="font-size:10px;color:var(--mut);margin-top:4px">Честная rolling-корреляция по реальным свечам. Низкая корреляция ≠ альфа — Правило 4 Конституции.</div></div>';
    this.rolling().then(c => {
      const el = document.getElementById('corr_line');
      if(el && c) el.innerHTML = 'Корреляция BTC↔ETH (30×1ч): <b>' + c.r.toFixed(2) + '</b> на ' + c.n + ' парах';
      else if(el) el.textContent = 'Корреляция BTC↔ETH: мало совместных свечей — накопи историю (≥10 совпадающих часов).';
    });
    return html;
  }
};
V10.Corr = Corr;
window.Corr = Corr;

