/* =========================================================================
   Д11/М4 · Петля «новость → цена»: классификация → вопрос → факт через N мин
   ========================================================================= */
const NewsReaction = {
  KEY: 'cn_news_loop',
  pending(){ try{ return JSON.parse(localStorage.getItem(this.KEY) || '[]'); }catch(e){ return []; } },
  save(list){ try{ localStorage.setItem(this.KEY, JSON.stringify(list.slice(-12))); }catch(e){} },
  schedule(item, cls){
    const list = this.pending();
    if(list.length >= 12) list.shift();
    list.push({ t: Date.now(), checkAt: Date.now() + 15 * 60e3, title: String(item.title || '').slice(0, 80), type: cls.type, asked: false, resolved: false });
    this.save(list);
    Bus.pub('NEWS_LOOP_SCHEDULED', { title: item.title });
  },
  /* фиксирует фактическую реакцию цены и возвращает вопрос-калибровку */
  tick(){
    const list = this.pending();
    let changed = false;
    const kl = LIVE.data.klines;
    list.forEach(p => {
      if(!p.asked && Date.now() >= p.checkAt && kl && kl.candles && kl.candles.length >= 2){
        p.asked = true;
        p.priceThen = kl.candles[kl.candles.length - 1].c;
        changed = true;
        try{
          MENTOR.ask('explain', 'news_loop', {
            selection: 'Новость: «' + p.title + '» классифицирована как ' + p.type + '. Объясни МЕХАНИКУ, через какой канал новость такого типа обычно влияет на цену (ликвидность, потоки, регуляторный риск) — и подчеркни, что это не прогноз направления.'
          }).then(r => {
            p.explained = r.text.slice(0, 600);
            this.save(list);
          }).catch(() => {});
        }catch(e){}
      }
      if(p.asked && !p.resolved && p.priceThen && kl && kl.candles && kl.candles.length >= 2){
        const now = kl.candles[kl.candles.length - 1].c;
        const mins = (Date.now() - p.t) / 60e3;
        if(mins >= 30){
          p.resolved = true;
          p.priceNow = now;
          p.move = (now - p.priceThen) / p.priceThen * 100;
          changed = true;
        }
      }
    });
    if(changed) this.save(list);
    const open = list.find(p => p.asked && !p.resolved && !p.quizzed);
    if(open && open.explained){
      open.quizzed = true;
      this.save(list);
      Bus.pub('NEWS_LOOP_QUESTION', open);
      return open;
    }
    return null;
  },
  card(){
    const p = this.pending().filter(x => x.resolved).slice(-1)[0];
    if(!p) return '';
    return '<div class="coach-card" style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:13px 15px;margin-bottom:10px">' +
      '<div style="font-weight:800;font-size:13px;color:var(--txt)">🔁 Петля «новость → цена»</div>' +
      '<div style="font-size:12px;color:var(--txt);margin-top:5px;line-height:1.5">«' + esc(p.title) + '» · тип: ' + p.type + '</div>' +
      '<div style="font-size:12px;color:var(--mut);margin-top:4px">Факт: с момента наблюдения цена ' + (p.move >= 0 ? 'выросла на ' : 'упала на ') + Math.abs(p.move).toFixed(2) + '%. Заголовок ≠ движение: реакция могла прийти с задержкой или не прийти вовсе.</div>' +
      (p.explained ? '<div style="font-size:11.5px;color:var(--txt);margin-top:6px;border-left:3px solid var(--acc2);padding-left:8px">' + p.explained + '</div>' : '') +
    '</div>';
  }
};
V10.NewsReaction = NewsReaction;
