/* =========================================================================
   Д9 (приём у эксперта liveEduVariant): сложность меняет ВОЛАТИЛЬНОСТЬ и
   экстремумы учебных сценариев, а не только seed — «стены толще, хвосты дикие»
   ========================================================================= */
PatchReg.once('edu-difficulty', () => {
  if(!window.LIVE || typeof LIVE.useEducational !== 'function') return;
  const origEdu = LIVE.useEducational.bind(LIVE);
  LIVE.useEducational = function(){
    const r = origEdu();
    try{
      const d = V10.eduDiff();
      if(d > 1){
        const scale = 0.6 + d * 0.45; /* ×1.5 при d=2, ×1.95 при d=3 */
        const kl = LIVE.data.klines;
        if(kl && kl.candles){
          kl.candles = kl.candles.map(c => {
            const mid = (c.o + c.c) / 2;
            const stretch = t => mid + (t - mid) * scale;
            return { t: c.t, o: c.o, c: c.c, h: stretch(c.h), l: stretch(c.l), v: c.v * (0.7 + d * 0.35) };
          });
        }
        const ob = LIVE.data.orderbook;
        if(ob && ob.bids && ob.asks){
          const bump = (rows, idx, mult) => { if(rows[idx]) rows[idx][1] = rows[idx][1] * mult; };
          bump(ob.bids, 7, 1 + d * 0.8);
          bump(ob.asks, 5, 1 + d * 0.6);
        }
      }
    }catch(e){}
    return r;
  };
  LIVE.useEducational.__v10wrapped = true;
});

console.info('%cКриптоНавигатор v10 · COACH-контур загружен', 'color:#06B6D4;font-weight:bold');
