/* ===== learn_player_stage3: Этап 3 — платформенный слой (начало) ===== */
/* =========================================================================
   КРИПТОНАВИГАТОР v12.5 · ЭТАП 3 · Learn Home, программа курса, якоря,
   поиск, конспект, недавние. Продолжение того же IIFE (learn_player_js).
   ПАТЧ-ПЛАН ЭТАПА 3 §0: НОЛЬ правок существующих функций — только чтение
   глобалов и новые LS-ключи cn_learn_recent / cn_learn_notes /
   cn_learn_syllabus. Красные линии ТЗ §0.1 соблюдены.
   ========================================================================= */

/* ============================== УТИЛИТЫ ЭТАПА 3 ============================== */
var LP3_TEST_IDS = (typeof TEST_BANK_IDS !== 'undefined' && TEST_BANK_IDS && TEST_BANK_IDS.length) ?
  TEST_BANK_IDS.slice() :
  ['p0', 'p1', 'p2', 'p3', 'p4', 'p5', 'p8', 'capstone', 'math_core', 'math_stats', 'math_final_map', 'literacy', 'psy_cum'];
var LP3_NOTES_MAX = 500;
var _lp3UndoNote = null; // заметка для «Вернуть» после удаления (undo-тост без confirm())

function lp3SyllabusState(){
  var s = lpLS_get('cn_learn_syllabus', {});
  return (s && typeof s === 'object') ? s : {};
}
function lp3SyllabusSet(patch){
  var s = lp3SyllabusState();
  Object.keys(patch || {}).forEach(function(k){ s[k] = patch[k]; });
  lpLS_set('cn_learn_syllabus', s);
}
function lp3DateFmt(ts){
  try{
    var d = new Date(ts || Date.now());
    return d.toLocaleDateString('ru-RU', { day: 'numeric', month: 'short' }) + ' ' +
      ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2);
  }catch(e){ return ''; }
}

/* ---------- Формула «Курс %» — дословная реплика renderProgressStats
   (v12.4, строки 22121–22136). Расхождение с вкладкой «Прогресс» = баг
   приёмки №1 (патч-план §1.1). totalTests=6 — константа приложения,
   реплицируется как есть (§9 риски: не «чинить»). ---------- */
function learnCoursePct(){
  var totalLessons = coreLessonList().length;
  var doneLessons = coreLessonsDoneCount();
  var totalTerms = TERMS.length;
  var doneTerms = Object.values(learned).filter(function(x){ return x === 1; }).length;
  var totalTests = 6; /* константа приложения (22022-контур) — так считает вкладка «Прогресс» */
  var passedTests = 0, _k;
  for(_k in phaseTestsDone){
    if(Object.prototype.hasOwnProperty.call(phaseTestsDone, _k) && _k !== 'exam_capstone' && phaseTestsDone[_k] >= 80) passedTests++;
  }
  var capstoneScore = phaseTestsDone['exam_capstone'] || 0;
  var capstonePassed = capstoneScore >= 85;
  return Math.round(
    ((doneLessons / totalLessons) * 0.40 +
     (doneTerms / totalTerms) * 0.20 +
     (passedTests / totalTests) * 0.25 +
     (capstonePassed ? 0.15 : (capstoneScore / 100) * 0.15)) * 100
  );
}

/* ---------- Фазы (числовой порядок 0–9, §1.2–§1.3) ----------
   ⚠️ PHASES содержит фазу 8 после фазы 4 (сплайс 42760) — программа
   строится в ЧИСЛОВОМ порядке, заголовки — из PHASES по .p. */
function lp3PhaseNums(){
  var set = {};
  LESSONS.forEach(function(l){ if(typeof l.phase === 'number') set[l.phase] = true; });
  return Object.keys(set).map(function(x){ return parseInt(x, 10); }).sort(function(a, b){ return a - b; });
}
function lp3PhaseTitle(ph){
  try{
    var p = PHASES.find(function(x){ return x.p === ph; });
    if(p && p.title) return String(p.title);
  }catch(e){}
  var n = LESSONS.filter(function(l){ return l.phase === ph; }).length;
  return 'Фаза ' + ph + (n ? ' · ' + n + ' уроков' : ''); /* фолбэк §1.3 */
}
function lp3PhaseShort(ph){
  var t = lp3PhaseTitle(ph);
  return t.length > 34 ? t.slice(0, 33) + '…' : t;
}
function lp3PhaseCounts(ph){
  var ls = LESSONS.filter(function(l){ return l.phase === ph; });
  var done = 0;
  ls.forEach(function(l){ if(isDone(l.id)) done++; });
  return { done: done, total: ls.length };
}
function lp3PhasePct(ph){
  var c = lp3PhaseCounts(ph);
  return c.total ? Math.round(c.done / c.total * 100) : 0;
}
function lp3NextUnpassed(){
  for(var i = 0; i < LESSONS.length; i++){ if(!isDone(LESSONS[i].id)) return LESSONS[i]; }
  return null;
}
function lp3FirstUnpassedBank(){
  for(var i = 0; i < LP3_TEST_IDS.length; i++){
    var id = LP3_TEST_IDS[i];
    var r = null;
    try{ r = resolveBank(id); }catch(e){}
    if(!r || r.kind === 'diag') continue; // диагностики не считаются «несданными»
    if(!testBadgeFor(id)) return id;
  }
  return null;
}

/* ============================== ТЕМА ДЛЯ КОРНЕЙ ЭТАПА 3 ============================== */
function lp3SyncThemeEl(el){
  if(!el) return;
  el.setAttribute('data-lp-theme', lpLS_get('cn_learn_theme', 'app'));
  el.setAttribute('data-font', String(lpLS_get('cn_learn_font', 19)));
}

/* ============================== СОСТОЯНИЕ ХАБА ============================== */
var H = { active: false, root: null, entryEl: null, savedOverflow: '' };
var _lp3ReturnHome = false; // закрытие плеера → возврат в хаб (from:'home', §3 инвариант)

/* ============================== LEARN HOME (P1) ============================== */
var Home = {
  open: function(){
    if(H.active) return;
    if(S.active) return; /* взаимоисключаемость с окном урока (патч-план §3) */
    /* точка входа для возврата фокуса; body/пустота → фолбэк на «🎓» при закрытии */
    H.entryEl = (document.activeElement instanceof HTMLElement && document.activeElement !== document.body) ?
      document.activeElement : null;
    H.savedOverflow = document.body.style.overflow || '';
    var root = document.createElement('div');
    root.className = 'learn-home-root';
    root.setAttribute('role', 'dialog');
    root.setAttribute('aria-label', 'Моё обучение');
    lp3SyncThemeEl(root);
    root.innerHTML = lp3HomeHtml();
    document.body.appendChild(root);
    document.body.style.overflow = 'hidden';
    H.root = root; H.active = true;
    root.addEventListener('keydown', lp3HomeKeydown, true);
    root.addEventListener('click', lp3HomeClick);
    root.addEventListener('input', lp3HomeInput, false);
    var si = root.querySelector('.lp3-search-in');
    if(si) si.focus();
  },
  close: function(silent){
    if(!H.active) return;
    if(H.root){ H.root.remove(); H.root = null; }
    H.active = false;
    document.body.style.overflow = H.savedOverflow || '';
    if(!silent){
      /* фокус на точку входа; если она устарела (контент перерисован) — на кнопку «🎓» шапки */
      var tgt = (H.entryEl && document.body.contains(H.entryEl)) ? H.entryEl : document.getElementById('lp_header_btn');
      if(tgt){ try{ tgt.focus(); }catch(e){} }
    }
    H.entryEl = null;
  }
};

function lp3HomeHtml(){
  var h = '<div class="lp3-top">' +
    '<div class="lp3-brand">🎓 Моё обучение</div>' +
    '<div class="lp3-top-right" style="display:flex;gap:6px;align-items:center">' +
    '<button type="button" class="lp-btn sm ghost" data-lp3-act="fsdown" aria-label="Уменьшить шрифт" title="A−">A−</button>' +
    '<button type="button" class="lp-btn sm ghost" data-lp3-act="fsup" aria-label="Увеличить шрифт" title="A+">A+</button>' +
    '<button type="button" class="lp-btn icon ghost" data-lp3-act="close" aria-label="Закрыть Моё обучение" title="Закрыть (Esc)">✕</button>' +
    '</div></div>';
  h += '<div class="lp3-body"><div class="lp3-col">';
  h += '<div class="lp3-search"><span aria-hidden="true">🔍</span>' +
    '<input type="search" class="lp3-search-in" value="" placeholder="Поиск по курсу: уроки, термины, аббревиатуры… (Ctrl+K)" aria-label="Поиск по курсу"></div>';
  h += '<div class="lp3-search-out" style="display:none" aria-live="polite"></div>';
  h += lp3ContinueHtml();
  h += '<div class="lp3-grid2">' + lp3BookmarksHtml() + lp3RecentHtml() + '</div>';
  h += lp3ProgramHtml();
  h += lp3ProgressHtml();
  h += lp3TestsHtml();
  h += lp3CardsHtml();
  h += lp3NotesSectionHtml();
  h += '</div></div>';
  return h;
}

/* ---------- «▶ Продолжить» — свежее из cn_learn_pos / cn_learn_test ---------- */
function lp3ContinueData(){
  var pos = lpLS_get('cn_learn_pos', null);
  var dr = testDraftGet();
  var posD = (pos && pos.lessonId && lessonById(pos.lessonId)) ? { kind: 'lesson', ts: pos.ts || 0, pos: pos } : null;
  var drD = (dr && dr.testId && resolveBank(dr.testId)) ? { kind: 'test', ts: dr.updatedTs || 0, draft: dr } : null;
  if(posD && drD) return drD.ts > posD.ts ? { main: drD, alt: posD } : { main: posD, alt: drD };
  if(posD) return { main: posD, alt: null };
  if(drD) return { main: drD, alt: null };
  return null;
}
function lp3ContinueHtml(){
  var h = '<section class="lp3-sec"><div class="lp3-sec-h">▶ Продолжить</div>';
  var d = lp3ContinueData();
  if(!d){
    var l0 = lp3NextUnpassed();
    if(!l0){
      h += '<div class="lp3-card lp3-big main" style="cursor:default"><span class="t">🏅 Курс пройден полностью — все ' + LESSONS.length + ' уроков отмечены!</span>' +
        '<span class="m">Повторяй материал через тесты и карточки.</span></div>';
    } else {
      h += '<button type="button" class="lp3-card lp3-big main" data-lp3-open="' + attr(l0.id) + '">' +
        '<span class="k">▶ Начать первый непройденный урок</span>' +
        '<span class="t">Урок ' + esc(l0.num || '') + ' · ' + esc(l0.title) + '</span>' +
        '<span class="m">Фаза ' + esc(l0.phase) + ' · ≈' + parseTimeEst(l0) + ' мин</span></button>';
    }
    return h + '</section>';
  }
  var m = d.main, html = '';
  if(m.kind === 'lesson'){
    var l = lessonById(m.pos.lessonId);
    var stepsN = buildLessonSteps(l).length;
    var si = Math.min(m.pos.stepIdx || 0, stepsN - 1);
    html += '<button type="button" class="lp3-card lp3-big main" data-lp3-open="' + attr(l.id) + '" data-lp3-open-step="' + si + '">' +
      '<span class="k">▶ Продолжить урок</span>' +
      '<span class="t">Урок ' + esc(l.num || '') + ' · ' + esc(l.title) + '</span>' +
      '<span class="m">шаг ' + (si + 1) + ' из ' + stepsN + ' · Фаза ' + esc(l.phase) + '</span></button>';
  } else {
    var rb = resolveBank(m.draft.testId);
    var a = (m.draft && rb.kind === 'math') ? Object.keys(m.draft.touched || {}).length :
      (Object.keys((m.draft && m.draft.answers) || {}).length + Object.keys((m.draft && m.draft.numeric) || {}).length);
    html += '<button type="button" class="lp3-card lp3-big main" data-lp3-test="' + attr(m.draft.testId) + '">' +
      '<span class="k">▶ Продолжить попытку</span>' +
      '<span class="t">' + esc(rb.title) + '</span>' +
      '<span class="m">отвечено ' + a + ' из ' + rb.questions.length + '</span></button>';
  }
  if(d.alt){
    if(d.alt.kind === 'lesson'){
      var l2 = lessonById(d.alt.pos.lessonId);
      html += '<div class="lp3-alt-row"><button type="button" class="lp3-card" data-lp3-open="' + attr(l2.id) + '" data-lp3-open-step="' + Math.min(d.alt.pos.stepIdx || 0, buildLessonSteps(l2).length - 1) + '">' +
        '<span class="t">✎ Черновик урока: ' + esc(l2.num || '') + ' · ' + esc(l2.title) + '</span>' +
        '<span class="m">шаг ' + ((d.alt.pos.stepIdx || 0) + 1) + '</span></button></div>';
    } else {
      var rb2 = resolveBank(d.alt.draft.testId);
      var a2 = (rb2.kind === 'math') ? Object.keys(d.alt.draft.touched || {}).length :
        (Object.keys(d.alt.draft.answers || {}).length + Object.keys(d.alt.draft.numeric || {}).length);
      html += '<div class="lp3-alt-row"><button type="button" class="lp3-card" data-lp3-test="' + attr(d.alt.draft.testId) + '">' +
        '<span class="t">🏁 Незавершённая попытка: ' + esc(rb2.title) + '</span>' +
        '<span class="m">отвечено ' + a2 + ' из ' + rb2.questions.length + '</span></button></div>';
    }
  }
  return h + html + '</section>';
}

/* ---------- Закладки + Недавние ---------- */
function lp3BookmarksHtml(){
  var bms = lpLS_get('cn_learn_bookmarks', []);
  var h = '<section class="lp3-sec"><div class="lp3-sec-h">🔖 Закладки (' + bms.length + ')</div>';
  if(!bms.length){ h += '<div class="lp3-empty">Закладок пока нет — поставь 🔖 в шапке плеера на нужном шаге.</div>'; }
  else {
    bms.forEach(function(b, i){
      h += '<button type="button" class="lp3-card" data-lp3-bm="' + i + '">' +
        '<span class="t">' + esc(b.lessonTitle || b.lessonId) + '</span>' +
        '<span class="m">шаг ' + ((b.stepIdx || 0) + 1) + ' · ' + esc(b.stepTitle || '') + '</span></button>';
    });
  }
  return h + '</section>';
}
function lp3RecentHtml(){
  var rec = lpLS_get('cn_learn_recent', []);
  var h = '<section class="lp3-sec"><div class="lp3-sec-h">🕘 Недавние</div>';
  var rows = [];
  (rec || []).forEach(function(r){
    var l = lessonById(r.lessonId);
    if(l) rows.push(l);
  });
  if(!rows.length){ h += '<div class="lp3-empty">История пуста — открой любой урок через программу ниже.</div>'; }
  else {
    rows.forEach(function(l){
      h += '<button type="button" class="lp3-card" data-lp3-open="' + attr(l.id) + '">' +
        '<span class="t">Урок ' + esc(l.num || '') + ' · ' + esc(l.title) + '</span>' +
        '<span class="m">Фаза ' + esc(l.phase) + (isDone(l.id) ? ' · ✓ пройден' : '') + '</span></button>';
    });
  }
  return h + '</section>';
}

/* ---------- Программа курса (аккордеон, LS-раскрытие) ---------- */
function lp3ProgramHtml(){
  var syll = lp3SyllabusState();
  var openPh = (typeof syll.phase === 'number') ? syll.phase : 0;
  var curId = S.active ? S.lessonId : null;
  var h = '<section class="lp3-sec" id="lp3_program_sec"><div class="lp3-sec-h">📚 Программа курса</div>';
  lp3PhaseNums().forEach(function(ph){
    var c = lp3PhaseCounts(ph);
    var isOpen = ph === openPh;
    h += '<div class="lp3-ph' + (isOpen ? ' open' : '') + '">';
    h += '<button type="button" class="lp3-ph-h" data-lp3-ph="' + ph + '" aria-expanded="' + isOpen + '">' +
      '<span class="t">' + esc(lp3PhaseTitle(ph)) + '</span>' +
      '<span class="m">' + c.done + ' / ' + c.total + '</span></button>';
    h += '<div class="lp3-ph-bar" aria-hidden="true"><i style="width:' + lp3PhasePct(ph) + '%"></i></div>';
    if(isOpen){
      h += '<div class="lp3-ph-list">';
      LESSONS.forEach(function(l){
        if(l.phase !== ph) return;
        var done = isDone(l.id);
        h += '<button type="button" class="lp3-les' + (done ? ' done' : '') + (l.id === curId ? ' current' : '') + '" data-lp3-open="' + attr(l.id) + '"' + (l.id === curId ? ' aria-current="true"' : '') + '>' +
          '<span class="ck">' + (done ? '✓' : '') + '</span>' +
          '<span class="t">Урок ' + esc(l.num || '') + ' · ' + esc(l.title) + '</span>' +
          '<span class="m">≈' + parseTimeEst(l) + ' мин</span></button>';
      });
      h += '</div>';
    }
    h += '</div>';
  });
  return h + '</section>';
}

/* ---------- Прогресс: две разные метрики с явными подписями (§1.2) ---------- */
function lp3ProgressHtml(){
  var allDone = 0;
  LESSONS.forEach(function(l){ if(isDone(l.id)) allDone++; });
  var pct = learnCoursePct();
  var doneTerms = 0;
  try{ doneTerms = Object.values(learned).filter(function(x){ return x === 1; }).length; }catch(e){}
  var passedTests = 0, _k;
  try{
    for(_k in phaseTestsDone){
      if(Object.prototype.hasOwnProperty.call(phaseTestsDone, _k) && _k !== 'exam_capstone' && phaseTestsDone[_k] >= 80) passedTests++;
    }
  }catch(e){}
  var cap = 0;
  try{ cap = phaseTestsDone['exam_capstone'] || 0; }catch(e){}
  var h = '<section class="lp3-sec"><div class="lp3-sec-h">📈 Прогресс</div>' +
    '<div class="lp3-pct"><b>' + pct + '%</b><span>курс пройден — та же формула, что на вкладке «Прогресс»: уроки фаз 0–5 · 40%, термины · 20%, тесты · 25%, капстоун · 15%</span></div>' +
    '<div class="lp3-total"><b>' + allDone + ' из ' + LESSONS.length + '</b> уроков курса <span>(все фазы 0–9, включая матфакультатив и Академию — другая метрика, не «Курс %»)</span></div>';
  lp3PhaseNums().forEach(function(ph){
    var c = lp3PhaseCounts(ph);
    h += '<div class="lp3-prow"><span class="t">' + esc(lp3PhaseShort(ph)) + '</span>' +
      '<span class="bar"><i style="width:' + lp3PhasePct(ph) + '%"></i></span>' +
      '<span class="m">' + c.done + '/' + c.total + '</span></div>';
  });
  h += '<div class="lp3-pmini">термины: <b>' + doneTerms + ' из ' + TERMS.length + '</b> · тесты сдано (порог 80%): <b>' + passedTests + ' из 6</b> · капстоун: <b>' + cap + '%</b> (порог 85%)</div>';
  return h + '</section>';
}

/* ---------- Тесты и экзамены (обрамление bankMeta Этапа 2) ---------- */
function lp3TestsHtml(){
  var h = '<section class="lp3-sec"><div class="lp3-sec-h">🏁 Тесты и экзамены</div><div class="lp3-tests">';
  LP3_TEST_IDS.forEach(function(id){
    var m = null;
    try{ m = bankMeta(id); }catch(e){}
    if(!m) return;
    h += '<button type="button" class="lp3-test" data-lp3-test="' + attr(id) + '">' +
      '<span class="t">' + esc(m.r.title) + (m.r.diag ? ' <span class="learn-badge">🔬 диагностика</span>' : '') + '</span>' +
      '<span class="m">' + m.draftInfo + m.total + ' вопр.' + (m.req ? ' · порог ' + m.req : '') + '<br>' + m.state + '</span></button>';
  });
  return h + '</div></section>';
}

/* ---------- Карточки (сводка cn_learn_fc + вход в последнюю колоду) ---------- */
function lp3CardsHtml(){
  var store = lpLS_get('cn_learn_fc', {});
  var decks = 0, known = 0, totalC = 0, lastId = null, lastTs = 0;
  Object.keys(store).forEach(function(lid){
    var e = store[lid];
    if(!e || !e.cards) return;
    decks++;
    Object.keys(e.cards).forEach(function(k){
      totalC++;
      if(e.cards[k] === 1) known++;
    });
    if((e.ts || 0) >= lastTs){ lastTs = e.ts || 0; lastId = lid; }
  });
  var h = '<section class="lp3-sec"><div class="lp3-sec-h">🗂 Карточки для повторения</div>';
  if(!decks){
    h += '<div class="lp3-empty">Колод ещё нет — пройди урок и нажми «🗂 Карточки» на финале или в шапке плеера.</div>';
  } else {
    h += '<div class="lp3-fc-sum">колод: <b>' + decks + '</b> · карточек: <b>' + totalC + '</b> · доля «знал»: <b>' + (totalC ? Math.round(known / totalC * 100) : 0) + '%</b></div>';
    var ll = lastId ? lessonById(lastId) : null;
    if(ll){
      h += '<button type="button" class="lp3-card" data-lp3-fc="' + attr(ll.id) + '">' +
        '<span class="t">🗂 Открыть последнюю колоду</span>' +
        '<span class="m">Урок ' + esc(ll.num || '') + ' · ' + esc(ll.title) + '</span></button>';
    }
  }
  return h + '</section>';
}

/* ============================== ХАБ: СОБЫТИЯ ============================== */
function lp3HomeClick(e){
  var b = e.target.closest('[data-lp3-act]');
  if(b){
    var act = b.getAttribute('data-lp3-act');
    if(act === 'close'){ Home.close(); return; }
    if(act === 'fsdown'){ adjustFont(-1); return; }
    if(act === 'fsup'){ adjustFont(1); return; }
  }
  if(lp3NoteActionClick(e)) return; /* конспект: переход/комментарий/удаление/undo/копирование */
  var ph = e.target.closest('[data-lp3-ph]');
  if(ph){
    var v = parseInt(ph.getAttribute('data-lp3-ph'), 10);
    var cur = lp3SyllabusState().phase;
    lp3SyllabusSet({ phase: (cur === v ? -1 : v) }); // -1 = все свернуты
    lp3RerenderHome();
    return;
  }
  var bm = e.target.closest('[data-lp3-bm]');
  if(bm){
    var b2 = lpLS_get('cn_learn_bookmarks', [])[parseInt(bm.getAttribute('data-lp3-bm'), 10)];
    if(b2){ lp3OpenFromHome(b2.lessonId, b2.stepIdx); }
    return;
  }
  var o = e.target.closest('[data-lp3-open]');
  if(o){
    var stepRaw = o.getAttribute('data-lp3-open-step');
    var stepIdx = stepRaw === null || stepRaw === '' ? undefined : parseInt(stepRaw, 10);
    lp3OpenFromHome(o.getAttribute('data-lp3-open'), isNaN(stepIdx) ? undefined : stepIdx);
    return;
  }
  var t = e.target.closest('[data-lp3-test]');
  if(t){ lp3OpenTestFromHome(t.getAttribute('data-lp3-test')); return; }
  var fc = e.target.closest('[data-lp3-fc]');
  if(fc){ lp3OpenFcFromHome(fc.getAttribute('data-lp3-fc')); return; }
  var sr = e.target.closest('[data-lp3-sr]');
  if(sr){ lp3SearchJump(sr.getAttribute('data-lp3-sr'), sr.getAttribute('data-lp3-sr-bi')); return; }
}
function lp3HomeInput(e){
  if(!e.target.classList || !e.target.classList.contains('lp3-search-in')) return;
  lp3HomeSearchRender(e.target.value);
}
function lp3HomeKeydown(e){
  if(e.key === 'Escape'){
    e.stopPropagation(); e.preventDefault();
    Home.close();
    return;
  }
  if((e.ctrlKey || e.metaKey) && (e.code === 'KeyK' || String(e.key).toLowerCase() === 'k' || String(e.key).toLowerCase() === 'к')){
    e.preventDefault(); e.stopPropagation();
    var si = H.root && H.root.querySelector('.lp3-search-in');
    if(si){ si.focus(); si.select(); }
    return;
  }
  if(e.key === 'Tab'){
    /* фокус-трап хаба (§12.8) */
    var list = H.root ? H.root.querySelectorAll('button:not([disabled]), [href], input:not([disabled]), select, textarea:not([disabled]), [tabindex]:not([tabindex="-1"])') : [];
    var f = Array.prototype.filter.call(list, function(el){ return el.offsetParent !== null || el === document.activeElement; });
    if(!f.length) return;
    var first = f[0], last = f[f.length - 1];
    if(e.shiftKey && document.activeElement === first){ e.preventDefault(); last.focus(); }
    else if(!e.shiftKey && document.activeElement === last){ e.preventDefault(); first.focus(); }
  }
}
function lp3RerenderHome(){
  if(!H.root) return;
  var body = H.root.querySelector('.lp3-body');
  if(!body) return;
  var st = body.scrollTop;
  var q = H.root.querySelector('.lp3-search-in');
  var qv = q ? q.value : '';
  var tmp = document.createElement('div');
  tmp.innerHTML = lp3HomeHtml();
  var nb = tmp.querySelector('.lp3-body');
  body.innerHTML = nb ? nb.innerHTML : '';
  body.scrollTop = st;
  var q2 = H.root.querySelector('.lp3-search-in');
  if(q2){
    q2.value = qv;
    if(qv) lp3HomeSearchRender(qv);
  }
}
function lp3OpenFromHome(lessonId, stepIdx){
  Home.close(true);
  _lp3ReturnHome = true;
  LearnPlayer.open(lessonId, typeof stepIdx === 'number' ? stepIdx : undefined);
}
function lp3OpenTestFromHome(testId){
  Home.close(true);
  _lp3ReturnHome = true;
  LearnPlayer.openTest(testId, 'home');
}
function lp3OpenFcFromHome(lessonId){
  Home.close(true);
  _lp3ReturnHome = true;
  LearnPlayer.openFlashcards(lessonId);
}
/* ============================== ПОИСК (P5, ТЗ §12.4) ==============================
   Ленивый индекс из живых массивов (LESSONS/TERMS/ABBREVIATION_GLOSSARY);
   контент заморожен — инвалидация не нужна. blockIndex — для перехода на шаг. */
var _lp3Idx = null;

function lp3Strip(s){
  return String(s === undefined || s === null ? '' : s).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}
function lp3SearchIndex(){
  if(_lp3Idx) return _lp3Idx;
  var idx = [];
  LESSONS.forEach(function(l){
    var push = function(text, weight, blockIndex){
      var s = lp3Strip(text);
      if(!s) return;
      idx.push({ type: 'lesson', id: l.id, phase: l.phase, num: String(l.num || ''), title: String(l.title || ''),
        blockIndex: (blockIndex === undefined ? 0 : blockIndex), text: s, w: weight });
    };
    push(l.num, 100, 0);
    push(l.title, 100, 0);
    push(l.lead, 80, 0);
    (l.terms || []).forEach(function(t){
      if(typeof t === 'string'){
        push(t, 90, 0);
        var def = '';
        try{ var tr = TERMS_RAW.find(function(x){ return x.t === t; }); def = tr ? (tr.d || '') : ''; }catch(e){}
        push(def, 70, 0);
      } else if(t && t.ru){ push(t.ru, 90, 0); push(t.desc || '', 70, 0); }
    });
    (l.blocks || []).forEach(function(b, bi){
      if(!b) return;
      if(typeof b.level1 === 'string') push(b.level1, 60, bi);
      if(typeof b.level2 === 'string') push(b.level2, 60, bi);
      if(b.type === 'recap' && b.points) b.points.forEach(function(p){ push(p, 50, bi); });
    });
  });
  (typeof TERMS !== 'undefined' ? TERMS : []).forEach(function(t){
    if(!t || !t.t) return;
    idx.push({ type: 'term', term: t, w: 95,
      text: [t.t, t.d, t.a, t.w].map(function(x){ return lp3Strip(x); }).filter(Boolean).join(' · ') });
  });
  try{
    var AG = ABBREVIATION_GLOSSARY;
    Object.keys(AG).forEach(function(k){
      var e = AG[k] || {};
      idx.push({ type: 'abbr', key: k, title: lp3Strip(e.title || k), w: 95, text: lp3Strip(e.text || '') });
    });
  }catch(e){}
  _lp3Idx = idx;
  return idx;
}
function lp3Hay(it){
  if(it._low !== undefined) return it._low;
  var s;
  if(it.type === 'term'){ s = [it.term.t, it.term.d, it.term.a, it.term.w].map(function(x){ return String(x || ''); }).join(' '); }
  else if(it.type === 'abbr'){ s = it.key + ' ' + it.title + ' ' + it.text; }
  else { s = it.text; /* каждая запись урока — отдельное поле: pos обязан быть позицией в text (иначе фрагмент нарезается мимо) */ }
  it._low = s.toLowerCase();
  return it._low;
}
function lp3Search(q){
  q = String(q || '').toLowerCase().trim();
  if(q.length < 2) return { query: q, results: [] };
  var idx = lp3SearchIndex();
  var res = [];
  for(var i = 0; i < idx.length; i++){
    var it = idx[i];
    var p = lp3Hay(it).indexOf(q);
    if(p < 0) continue;
    res.push({ it: it, pos: p, score: it.w - Math.min(p, 60) * 0.15 });
  }
  res.sort(function(a, b){ return b.score - a.score; });
  /* дедупликация: у уроков — лучшее вхождение на (урок, blockIndex); всего ≤30 */
  var seen = {}, out = [];
  for(var j = 0; j < res.length && out.length < 30; j++){
    var r = res[j], key;
    if(r.it.type === 'lesson') key = 'L' + r.it.id + '#' + r.it.blockIndex;
    else if(r.it.type === 'term') key = 'T' + r.it.term.t;
    else key = 'A' + r.it.key;
    if(seen[key]) continue;
    seen[key] = 1;
    out.push(r);
  }
  return { query: q, results: out };
}
function lp3Frag(text, pos, q){
  var from = Math.max(0, pos - 42), to = Math.min(text.length, pos + q.length + 84);
  var frag = (from > 0 ? '…' : '') + text.slice(from, to) + (to < text.length ? '…' : '');
  var escd = esc(frag);
  var idx = escd.toLowerCase().indexOf(q);
  if(idx >= 0){
    escd = escd.slice(0, idx) + '<mark>' + escd.slice(idx, idx + q.length) + '</mark>' + escd.slice(idx + q.length);
  }
  return escd;
}
function lp3SearchResultsHtml(q){
  var r = lp3Search(q);
  if(!r.results.length){
    return '<div class="lp3-sr-none">' + (q.trim().length < 2 ?
      'Введите минимум 2 символа — ищу по урокам, терминам и аббревиатурам.' :
      'Ничего не найдено; попробуй другое слово. Индекс: уроки (название/lead/теория/выводы), глоссарий, аббревиатуры.') + '</div>';
  }
  var h = '';
  r.results.forEach(function(x, i){
    var it = x.it;
    if(it.type === 'lesson'){
      h += '<button type="button" class="lp3-sr" data-lp3-sr="' + attr(it.id) + '" data-lp3-sr-bi="' + it.blockIndex + '">' +
        '<span class="h">Урок ' + esc(it.num) + ' · ' + esc(it.title) + ' — Фаза ' + esc(it.phase) + '</span>' +
        '<span class="f">' + lp3Frag(it.text, x.pos, r.query) + '</span></button>';
    } else if(it.type === 'term'){
      var t = it.term;
      h += '<div class="lp3-sr" style="cursor:default">' +
        '<span class="h">📖 Термин: ' + esc(t.t) + '</span>' +
        '<span class="f">' + esc(t.d || '') + '</span>' +
        (t.a ? '<span class="lp3-sub">💡 Аналогия: ' + esc(t.a) + '</span>' : '') +
        (t.w ? '<span class="lp3-sub">⚠ Почему важно: ' + esc(t.w) + '</span>' : '') + '</div>';
    } else {
      h += '<div class="lp3-sr" style="cursor:default">' +
        '<span class="h">🔤 ' + esc(it.key) + ' — ' + esc(it.title) + '</span>' +
        '<span class="f">' + esc(it.text) + '</span></div>';
    }
  });
  return h;
}
/* переиспользуемый рендер результатов в хабе */
function lp3HomeSearchRender(q){
  if(!H.root) return;
  var out = H.root.querySelector('.lp3-search-out');
  if(!out) return;
  if(String(q || '').trim().length < 2){ out.style.display = 'none'; out.innerHTML = ''; return; }
  out.style.display = '';
  out.innerHTML = '<div class="lp3-sec"><div class="lp3-sec-h">🔎 Результаты поиска</div>' + lp3SearchResultsHtml(q) + '</div>';
}
/* переход из поиска: хаб закрывается → плеер на шаге совпадения (blockIndex → stepIdx) */
function lp3StepForBlock(l, blockIndex){
  try{
    var steps = buildLessonSteps(l);
    for(var i = 0; i < steps.length; i++){
      if(steps[i].blockIndex === blockIndex) return i;
    }
  }catch(e){}
  return undefined;
}
function lp3SearchJump(lessonId, blockIndexRaw){
  var l = lessonById(lessonId);
  if(!l) return;
  var bi = parseInt(blockIndexRaw, 10);
  var stepIdx = isNaN(bi) ? undefined : lp3StepForBlock(l, bi);
  lp3OpenFromHome(lessonId, stepIdx);
}

/* Поиск из открытого плеера: Ctrl+K → оверлей внутри корня плеера */
function lp3SearchOverlayToggle(){
  if(!S.root) return;
  var ex = S.root.querySelector('.learn-overlay[data-ov="lp3search"]');
  if(ex){ ex.remove(); return; }
  var ov = document.createElement('div');
  ov.className = 'learn-overlay'; ov.setAttribute('data-ov', 'lp3search');
  ov.innerHTML = '<div class="learn-sheet">' +
    '<h3>🔎 Поиск по курсу</h3>' +
    '<div class="lp3-search" style="margin-bottom:12px"><span aria-hidden="true">🔍</span>' +
    '<input type="search" class="lp3-search-in" placeholder="Уроки, термины, аббревиатуры…" aria-label="Поиск по курсу"></div>' +
    '<div class="lp3-ov-results" style="max-height:46vh;overflow-y:auto"></div>' +
    '<div style="margin-top:12px;text-align:right"><button type="button" class="lp-btn" data-lp3-close-search>Закрыть (Esc)</button></div></div>';
  ov.addEventListener('click', function(e){
    if(e.target === ov || e.target.closest('[data-lp3-close-search]')){ ov.remove(); return; }
    var sr = e.target.closest('[data-lp3-sr]');
    if(sr){
      ov.remove();
      var l = lessonById(sr.getAttribute('data-lp3-sr'));
      if(!l) return;
      var bi = parseInt(sr.getAttribute('data-lp3-sr-bi'), 10);
      var stepIdx = isNaN(bi) ? undefined : lp3StepForBlock(l, bi);
      if(S.active && S.lessonId === l.id && typeof stepIdx === 'number'){ renderStep(stepIdx); return; }
      LearnPlayer.open(l.id, stepIdx);
    }
  });
  var inp = ov.querySelector('.lp3-search-in');
  var out = ov.querySelector('.lp3-ov-results');
  inp.addEventListener('input', function(){
    var q = inp.value;
    out.innerHTML = String(q || '').trim().length < 2 ? '' : lp3SearchResultsHtml(q);
  });
  S.root.appendChild(ov);
  inp.focus();
}

/* ============================== SYLLABUS (P3, ТЗ §12.2) ==============================
   Вкладки левой панели: «Шаги | Программа | Конспект»; активная вкладка и
   раскрытая фаза — LS cn_learn_syllabus. */
var _lp3PanelTab = (function(){ var t = lp3SyllabusState().tab; return (t === 'program' || t === 'notes') ? t : 'steps'; })();

function lp3SetPanelTab(tab, opts){
  _lp3PanelTab = (tab === 'program' || tab === 'notes') ? tab : 'steps';
  lp3SyllabusSet({ tab: _lp3PanelTab });
  if(!S.root) return;
  var map = S.root.querySelector('.learn-map');
  if(!map) return;
  if(TS.active){ if(!(opts && opts.keepTest)) renderTestMap(); else lp3EnsureTabs(); }
  else if(!FC.active){ renderMap(); }
  else lp3EnsureTabs();
}
function lp3EnsureTabs(){
  if(!S.root) return;
  var map = S.root.querySelector('.learn-map');
  if(!map) return;
  var old = map.querySelector('.lp3-tabs');
  if(old) old.remove();
  if(FC.active) return; // в режиме карточек панель не отвлекаем
  var el = document.createElement('div');
  el.className = 'lp3-tabs';
  var def = [['steps', 'Шаги'], ['program', 'Программа'], ['notes', 'Конспект']];
  el.innerHTML = def.map(function(d){
    return '<button type="button" class="lp-btn' + (_lp3PanelTab === d[0] ? ' on' : ' ghost') + '" data-lp3-tab="' + d[0] + '"' +
      (_lp3PanelTab === d[0] ? ' aria-current="true"' : '') + '>' + d[1] +
      (d[0] === 'notes' && lp3NotesGet().length ? '<span class="lp3-note-count">' + lp3NotesGet().length + '</span>' : '') +
      '</button>';
  }).join('');
  map.insertBefore(el, map.firstChild);
}
/* Программа внутри плеера: дерево Фаза → уроки, текущий урок подсвечен */
function lp3MapProgram(){
  if(!S.root) return;
  var map = S.root.querySelector('.learn-map');
  if(!map) return;
  var syll = lp3SyllabusState();
  var openPh = (typeof syll.phase === 'number') ? syll.phase : (lessonById(S.lessonId) || {}).phase;
  if(typeof openPh !== 'number') openPh = 0;
  var curId = S.lessonId;
  var h = '';
  lp3PhaseNums().forEach(function(ph){
    var c = lp3PhaseCounts(ph);
    var isOpen = ph === openPh;
    h += '<div class="lp3-ph' + (isOpen ? ' open' : '') + '">';
    h += '<button type="button" class="lp3-ph-h" data-lp3-mph="' + ph + '" aria-expanded="' + isOpen + '">' +
      '<span class="t" style="font-size:12.5px">' + esc(lp3PhaseShort(ph)) + '</span>' +
      '<span class="m">' + c.done + '/' + c.total + '</span></button>';
    if(isOpen){
      h += '<div class="lp3-ph-list" style="padding:0 4px 8px">';
      LESSONS.forEach(function(l){
        if(l.phase !== ph) return;
        var done = isDone(l.id);
        h += '<button type="button" class="lp3-les' + (done ? ' done' : '') + (l.id === curId ? ' current' : '') + '" data-lp3-mopen="' + attr(l.id) + '"' + (l.id === curId ? ' aria-current="true"' : '') + '>' +
          '<span class="ck" style="flex-basis:18px;height:18px">' + (done ? '✓' : '') + '</span>' +
          '<span class="t" style="font-size:11.5px">Урок ' + esc(l.num || '') + ' · ' + esc(l.title) + '</span></button>';
      });
      h += '</div>';
    }
    h += '</div>';
  });
  map.innerHTML = '<div class="learn-map-h">Программа курса</div>' + h;
}
function lp3PanelClick(e){
  var an = e.target.closest('[data-lp3-act="lp3anchor"]');
  if(an){
    var al = lessonById(S.lessonId);
    if(al) lp3OpenProgramAt(al.phase);
    return;
  }
  var tab = e.target.closest('[data-lp3-tab]');
  if(tab){ lp3SetPanelTab(tab.getAttribute('data-lp3-tab')); return; }
  var mph = e.target.closest('[data-lp3-mph]');
  if(mph){
    var v = parseInt(mph.getAttribute('data-lp3-mph'), 10);
    var cur = lp3SyllabusState().phase;
    lp3SyllabusSet({ phase: (cur === v ? -1 : v) });
    lp3SetPanelTab(_lp3PanelTab, { keepTest: true });
    return;
  }
  var mo = e.target.closest('[data-lp3-mopen]');
  if(mo){
    var id = mo.getAttribute('data-lp3-mopen');
    if(id === S.lessonId){ return; } // уже открыт
    LearnPlayer.open(id); // обёртка вернёт вкладку на «Шаги» (P3.3)
    return;
  }
  if(lp3NoteActionClick(e)) return;
}

/* ============================== ЯКОРЯ (P4, ТЗ §12.3) ============================== */
function lp3UpdateAnchor(){
  if(!S.root) return;
  var a = S.root.querySelector('.lp3-anchor');
  if(!a) return;
  var l = S.active ? lessonById(S.lessonId) : null;
  if(!l || TS.active || FC.active){ a.style.display = 'none'; return; }
  var c = lp3PhaseCounts(l.phase);
  a.style.display = '';
  a.innerHTML = 'Фаза ' + l.phase + ': ' + c.done + '/' + c.total;
  a.title = 'Прогресс фазы по lessonsDone — открыть программу курса';
}
function lp3OpenProgramAt(ph){
  lp3SyllabusSet({ phase: ph });
  lp3SetPanelTab('program');
  if(S.root) S.root.setAttribute('data-map-open', '1'); // на мобильных выдвижная панель откроется
}

/* ---------- Финал урока: «Фаза пройдена на X%» + CTA «в курсе» +
   рекомендация адаптивной тренировки (≥3 ошибок в квизе урока) ---------- */
function lp3CourseFinaleHtml(l){
  var h = '';
  var c = lp3PhaseCounts(l.phase);
  h += '<div style="text-align:center;margin-top:14px;color:var(--mut);font-size:calc(var(--lp-fs) - 4px);line-height:1.5">' +
    'Фаза ' + esc(l.phase) + ' пройдена на <b style="color:var(--txt)">' + lp3PhasePct(l.phase) + '%</b> (' + c.done + ' из ' + c.total + ' уроков · по lessonsDone)</div>';
  var nxt = lp3NextUnpassed();
  h += '<div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:10px">';
  if(nxt){
    h += '<button type="button" class="lp-btn primary" onclick="LearnPlayer.open(\'' + attr(nxt.id) + '\')">▸ Следующий непройденный урок курса: ' + esc(nxt.title) + ' <span class="learn-badge">в курсе</span></button>';
  } else {
    var bank = lp3FirstUnpassedBank();
    h += '<span class="learn-badge" style="background:rgba(34,197,94,.18);color:var(--ok)">🏅 Курс пройден полностью</span>';
    h += bank ?
      '<button type="button" class="lp-btn primary" onclick="LearnPlayer.openTest(\'' + bank + '\')">▸ К тестам</button>' :
      '<button type="button" class="lp-btn primary" onclick="LearnPlayer.openHome()">🎓 Моё обучение</button>';
  }
  h += '</div>';
  /* Рекомендация (ТЗ §11.9 соблюдено: ADAPTIVE_QUESTION_BANK не трогаем —
     только ссылка на существующий запуск): ≥3 неверных попыток в квизе урока */
  var att = 0;
  try{ att = S.quizAttempts[l.id] || 0; }catch(e){}
  if(att >= 3){
    h += '<div class="learn-card warn" style="max-width:560px;margin:16px auto 0;padding:14px 18px;text-align:left">' +
      '<div style="font-weight:800;margin-bottom:6px">🔄 Квиз дался непросто (' + att + ' неверных попыток)</div>' +
      '<div style="font-size:calc(var(--lp-fs) - 5px);color:var(--mut);line-height:1.55;margin-bottom:10px">Запусти адаптивную тренировку — она подберёт вопросы по слабым темам из существующего банка и закрепит материал.</div>' +
      '<button type="button" class="lp-btn primary" onclick="LearnPlayer._goAdaptive()">🔄 Пройти адаптивную тренировку по этой теме</button></div>';
  }
  return h;
}
/* Переход к адаптивной тренировке: плеер закрывается (prepost-модалка z 120000
   остаётся под плеером — закрываем ДО запуска), затем существующий контур:
   window.startAdaptiveWorkout() сам делает go('quiz') и подбор тем. */
function lp3GoAdaptive(){
  try{ closePlayer(); }catch(e){}
  try{
    if(typeof window.startAdaptiveWorkout === 'function'){ window.startAdaptiveWorkout(); return; }
  }catch(e){ console.warn('[LearnPlayer3] adaptive fail', e); }
  try{ if(typeof go === 'function') go('quiz'); }catch(e2){}
}
/* ============================== КОНСПЕКТ (P6, ТЗ §12.5) ==============================
   LS cn_learn_notes = [{id, lessonId, stepIdx, quote≤500, note, ts}] ≤500;
   дубликаты «тот же lessonId+quote» не создаются (обновляется ts). */
function lp3NotesGet(){
  var a = lpLS_get('cn_learn_notes', []);
  return Array.isArray(a) ? a : [];
}
function lp3NotesSet(a){
  lpLS_set('cn_learn_notes', (Array.isArray(a) ? a : []).slice(0, LP3_NOTES_MAX));
}
function lp3AddNote(quote){
  var arr = lp3NotesGet();
  var ex = null;
  for(var i = 0; i < arr.length; i++){
    if(arr[i].lessonId === S.lessonId && arr[i].quote === quote){ ex = arr[i]; break; }
  }
  if(ex){ ex.ts = Date.now(); toast('Цитата уже в конспекте — обновлена', '📝'); }
  else {
    arr.unshift({ id: 'n' + Date.now() + Math.floor(Math.random() * 100), lessonId: S.lessonId,
      stepIdx: S.idx || 0, quote: quote, note: '', ts: Date.now() });
    if(arr.length > LP3_NOTES_MAX) arr = arr.slice(0, LP3_NOTES_MAX);
    toast('Добавлено в конспект 📝', '📝');
  }
  lp3NotesSet(arr);
  lp3RerenderNotesPanels();
}
function lp3NoteDelete(id){
  var arr = lp3NotesGet();
  var idx = -1;
  for(var i = 0; i < arr.length; i++){ if(arr[i].id === id){ idx = i; break; } }
  if(idx < 0) return;
  _lp3UndoNote = { note: arr[idx], at: Date.now() };
  arr.splice(idx, 1);
  lp3NotesSet(arr);
  lp3RerenderNotesPanels();
  setTimeout(function(){
    if(_lp3UndoNote && Date.now() - _lp3UndoNote.at >= 9000){ _lp3UndoNote = null; lp3RerenderNotesPanels(); }
  }, 9200);
}
function lp3NoteUndo(){
  if(!_lp3UndoNote) return;
  var arr = lp3NotesGet();
  arr.unshift(_lp3UndoNote.note);
  lp3NotesSet(arr);
  _lp3UndoNote = null;
  lp3RerenderNotesPanels();
  toast('Заметка восстановлена', '📝');
}

/* Плавающая кнопка «＋ В конспект» — только в .learn-content режима урока */
var _lp3Fab = null;
function lp3HideFab(){ if(_lp3Fab){ _lp3Fab.remove(); _lp3Fab = null; } }
function lp3SelectionUp(){
  lp3HideFab();
  try{
    if(!S.active || !S.lessonId || TS.active || FC.active || H.active) return;
    var sel = window.getSelection();
    if(!sel || sel.isCollapsed || sel.rangeCount === 0) return;
    var text = String(sel).replace(/\s+/g, ' ').trim();
    if(text.length < 3) return;
    var an = sel.anchorNode;
    if(!an) return;
    var el = an.nodeType === 1 ? an : an.parentNode;
    if(!el || !el.closest) return;
    var content = S.root ? S.root.querySelector('.learn-content') : null;
    if(!content || !content.contains(el)) return;
    if(el.closest('input, textarea, select, pre, code, .learn-top, .learn-bottom, .learn-map')) return;
    var range = sel.getRangeAt(0);
    var rect = range.getBoundingClientRect();
    if(!rect || (!rect.width && !rect.height)) return;
    var fab = document.createElement('button');
    fab.type = 'button';
    fab.id = 'lp3_note_fab';
    fab.textContent = '＋ В конспект';
    fab.setAttribute('aria-label', 'Добавить выделенное в конспект');
    fab.style.left = Math.max(8, Math.min(window.innerWidth - 160, rect.left + rect.width / 2 - 66)) + 'px';
    fab.style.top = Math.max(8, rect.top - 44) + 'px';
    fab.addEventListener('mousedown', function(ev){ ev.preventDefault(); ev.stopPropagation(); });
    fab.addEventListener('click', function(ev){
      ev.stopPropagation();
      var q = String(window.getSelection()).replace(/\s+/g, ' ').trim().slice(0, 500);
      if(q) lp3AddNote(q);
      try{ window.getSelection().removeAllRanges(); }catch(e2){}
      lp3HideFab();
    });
    document.body.appendChild(fab);
    _lp3Fab = fab;
  }catch(e){ /* выделение вне шага — игнор */ }
}
document.addEventListener('mouseup', lp3SelectionUp, true);
document.addEventListener('scroll', function(){ lp3HideFab(); }, true);
document.addEventListener('selectionchange', function(){
  var sel = window.getSelection();
  if(!sel || sel.isCollapsed) lp3HideFab();
});

/* Панель конспекта (вкладка левой панели + раздел Learn Home) */
function lp3NotesPanelHtml(){
  var arr = lp3NotesGet();
  var h = '';
  if(_lp3UndoNote){
    h += '<div class="lp3-undo"><span>Заметка удалена</span>' +
      '<button type="button" class="lp-btn sm" data-lp3-note-undo>↩ Вернуть</button></div>';
  }
  if(!arr.length){
    h += '<div class="lp3-empty">Заметок нет. Выдели текст в шаге урока — появится кнопка «＋ В конспект».</div>';
    return h;
  }
  h += '<div style="display:flex;justify-content:flex-end;margin-bottom:8px">' +
    '<button type="button" class="lp-btn sm" data-lp3-notes-copy>📋 Скопировать всё (markdown)</button></div>';
  var order = [], groups = {};
  arr.forEach(function(n){
    if(!groups[n.lessonId]){ groups[n.lessonId] = []; order.push(n.lessonId); }
    groups[n.lessonId].push(n);
  });
  order.forEach(function(lid){
    var l = lessonById(lid);
    h += '<div class="lp3-ng"><div class="lp3-ng-h">' +
      (l ? ('Урок ' + esc(l.num || '') + ' · ' + esc(l.title) + ' <span style="color:var(--mut)">· Фаза ' + esc(l.phase) + '</span>') : esc(lid)) +
      '</div>';
    groups[lid].forEach(function(n){
      h += '<div class="lp3-note" data-nid="' + attr(n.id) + '">' +
        '<button type="button" class="lp3-note-q" data-lp3-note-open="' + attr(n.id) + '" title="Перейти к шагу">«' + esc(n.quote.length > 150 ? n.quote.slice(0, 149) + '…' : n.quote) + '»</button>' +
        (n.note ? '<div class="lp3-note-c">' + esc(n.note) + '</div>' : '') +
        '<div class="lp3-note-meta"><span>' + lp3DateFmt(n.ts) + ' · шаг ' + ((n.stepIdx || 0) + 1) + '</span>' +
        '<span style="display:inline-flex;gap:4px">' +
        '<button type="button" class="lp-btn sm ghost" data-lp3-note-edit="' + attr(n.id) + '" aria-label="Комментарий" title="Комментарий ✎">✎</button>' +
        '<button type="button" class="lp-btn sm ghost" data-lp3-note-del="' + attr(n.id) + '" aria-label="Удалить заметку" title="Удалить 🗑">🗑</button>' +
        '</span></div></div>';
    });
    h += '</div>';
  });
  return h;
}
function lp3MapNotes(){
  if(!S.root) return;
  var map = S.root.querySelector('.learn-map');
  if(!map) return;
  map.innerHTML = '<div class="learn-map-h">📝 Конспект · ' + lp3NotesGet().length + '</div>' +
    '<div style="padding:0 8px 40px">' + lp3NotesPanelHtml() + '</div>';
}
function lp3NotesSectionHtml(){
  return '<section class="lp3-sec"><div class="lp3-sec-h">📝 Конспект (' + lp3NotesGet().length + ')</div>' + lp3NotesPanelHtml() + '</section>';
}
function lp3RerenderNotesPanels(){
  if(S.active && S.root && !FC.active){
    if(TS.active){ if(_lp3PanelTab === 'notes') renderTestMap(); else lp3EnsureTabs(); }
    else if(_lp3PanelTab === 'notes') renderMap();
    else lp3EnsureTabs();
  }
  if(H.active) lp3RerenderHome();
}
/* Общие обработчики карточек заметок (панель плеера + хаб) */
function lp3NoteActionClick(e){
  var no = e.target.closest('[data-lp3-note-open]');
  if(no){ lp3NoteJump(no.getAttribute('data-lp3-note-open')); return true; }
  var ne = e.target.closest('[data-lp3-note-edit]');
  if(ne){ lp3NoteEditInline(ne.getAttribute('data-lp3-note-edit')); return true; }
  var nd = e.target.closest('[data-lp3-note-del]');
  if(nd){ lp3NoteDelete(nd.getAttribute('data-lp3-note-del')); return true; }
  var nc = e.target.closest('[data-lp3-notes-copy]');
  if(nc){ copyText(lp3NotesMarkdown(), 'Конспект скопирован (markdown)'); return true; }
  var nu = e.target.closest('[data-lp3-note-undo]');
  if(nu){ lp3NoteUndo(); return true; }
  var ns = e.target.closest('[data-lp3-note-save]');
  if(ns){ lp3NoteSaveInline(ns.getAttribute('data-lp3-note-save')); return true; }
  var nx = e.target.closest('[data-lp3-note-cancel]');
  if(nx){ lp3RerenderNotesPanels(); return true; }
  return false;
}
function lp3NoteJump(id){
  var arr = lp3NotesGet(), n = null;
  for(var i = 0; i < arr.length; i++){ if(arr[i].id === id){ n = arr[i]; break; } }
  if(!n) return;
  if(S.active && S.lessonId === n.lessonId && S.root){
    lp3HideFab();
    renderStep(Math.min(n.stepIdx || 0, S.steps.length - 1));
    S.root.setAttribute('data-map-open', '0');
    return;
  }
  if(S.active){ LearnPlayer.open(n.lessonId, n.stepIdx || 0); return; }
  lp3OpenFromHome(n.lessonId, n.stepIdx || 0);
}
function lp3NoteHostEl(id){
  var host = null;
  if(S.root) host = S.root.querySelector('.lp3-note[data-nid="' + id + '"]');
  if(!host && H.root) host = H.root.querySelector('.lp3-note[data-nid="' + id + '"]');
  return host;
}
function lp3NoteEditInline(id){
  var host = lp3NoteHostEl(id);
  if(!host) return;
  var meta = host.querySelector('.lp3-note-meta');
  if(!meta || meta.querySelector('textarea')) return;
  var arr = lp3NotesGet(), n = null;
  for(var i = 0; i < arr.length; i++){ if(arr[i].id === id){ n = arr[i]; break; } }
  if(!n) return;
  var wrap = document.createElement('div');
  wrap.style.cssText = 'width:100%;margin-top:6px';
  wrap.innerHTML = '<textarea class="lp3-note-ta" placeholder="Свой комментарий к цитате…" aria-label="Комментарий к заметке">' + esc(n.note || '') + '</textarea>' +
    '<div style="display:flex;gap:8px;margin-top:6px">' +
    '<button type="button" class="lp-btn sm primary" data-lp3-note-save="' + attr(id) + '">Сохранить</button>' +
    '<button type="button" class="lp-btn sm ghost" data-lp3-note-cancel>Отмена</button></div>';
  meta.appendChild(wrap);
  var ta = wrap.querySelector('textarea');
  ta.focus();
  try{ ta.setSelectionRange(ta.value.length, ta.value.length); }catch(e){}
}
function lp3NoteSaveInline(id){
  var host = lp3NoteHostEl(id);
  var ta = host ? host.querySelector('textarea') : null;
  var val = ta ? ta.value.trim() : null;
  var arr = lp3NotesGet(), n = null;
  for(var i = 0; i < arr.length; i++){ if(arr[i].id === id){ n = arr[i]; break; } }
  if(n && val !== null){
    n.note = val.slice(0, 2000);
    n.ts = Date.now();
    lp3NotesSet(arr);
    toast('Комментарий сохранён', '📝');
  }
  lp3RerenderNotesPanels();
}
/* Markdown-экспорт (§P6.4): валидные заголовки/цитаты/пустые строки */
function lp3NotesMarkdown(){
  var arr = lp3NotesGet();
  var out = '# Конспект — КриптоНавигатор\n';
  var order = [], groups = {};
  arr.forEach(function(n){
    if(!groups[n.lessonId]){ groups[n.lessonId] = []; order.push(n.lessonId); }
    groups[n.lessonId].push(n);
  });
  order.forEach(function(lid){
    var l = lessonById(lid);
    out += '\n## ' + (l ? ((l.num ? l.num + ' ' : '') + l.title) : lid) + (l ? ' (Фаза ' + l.phase + ')' : '') + '\n';
    groups[lid].forEach(function(n){
      out += '\n> «' + String(n.quote || '').replace(/\s*\n+\s*/g, ' ') + '»\n';
      if(n.note) out += '\n— ' + String(n.note).replace(/\s*\n+\s*/g, ' ') + '\n';
    });
  });
  return out;
}

/* ============================== НЕДАВНИЕ (P7) ============================== */
function lp3PushRecent(lessonId){
  try{
    if(!lessonId || !lessonById(lessonId)) return;
    var a = lpLS_get('cn_learn_recent', []);
    if(!Array.isArray(a)) a = [];
    a = a.filter(function(x){ return x && x.lessonId !== lessonId; });
    a.unshift({ lessonId: lessonId, ts: Date.now() });
    lpLS_set('cn_learn_recent', a.slice(0, 5));
  }catch(e){}
}

/* ============================== ОБЁРТКИ КАРКАСА (продолжение цепочки Этапа 2) ============================== */
/* buildRoot: якорь фазы в шапке + делегат панели + Ctrl+K (capture) */
var _lp3BuildRoot = buildRoot;
buildRoot = function(l){
  var root = _lp3BuildRoot(l);
  try{
    var row = root.querySelector('.learn-progress-row');
    if(row){
      var a = document.createElement('button');
      a.type = 'button';
      a.className = 'lp3-anchor';
      a.setAttribute('data-lp3-act', 'lp3anchor');
      a.setAttribute('aria-label', 'Прогресс фазы — открыть программу курса');
      a.style.display = 'none';
      row.appendChild(a);
    }
    root.addEventListener('click', lp3PanelClick, false);
    root.addEventListener('keydown', function(e){
      if((e.ctrlKey || e.metaKey) && (e.code === 'KeyK' || String(e.key).toLowerCase() === 'k' || String(e.key).toLowerCase() === 'к')){
        e.preventDefault(); e.stopPropagation();
        lp3SearchOverlayToggle();
      }
    }, true);
  }catch(e){}
  return root;
};
/* Esc: сначала закрыть оверлей поиска, потом плеер */
var _lp3OnKeydown = onKeydown;
onKeydown = function(e){
  if(S.active && e.key === 'Escape' && S.root){
    var ov = S.root.querySelector('.learn-overlay[data-ov="lp3search"]');
    if(ov){ e.stopPropagation(); e.preventDefault(); ov.remove(); return; }
  }
  return _lp3OnKeydown.apply(this, arguments);
};
/* Карта шагов/порций: вкладка «Программа»/«Конспект» заменяет содержимое */
var _lp3RenderMap = renderMap;
renderMap = function(){
  if(!FC.active && _lp3PanelTab === 'program'){ lp3MapProgram(); lp3EnsureTabs(); return; }
  if(!FC.active && _lp3PanelTab === 'notes'){ lp3MapNotes(); lp3EnsureTabs(); return; }
  _lp3RenderMap();
  lp3EnsureTabs();
};
var _lp3RenderTestMap = renderTestMap;
renderTestMap = function(){
  if(!FC.active && _lp3PanelTab === 'program'){ lp3MapProgram(); lp3EnsureTabs(); return; }
  if(!FC.active && _lp3PanelTab === 'notes'){ lp3MapNotes(); lp3EnsureTabs(); return; }
  _lp3RenderTestMap();
  lp3EnsureTabs();
};
/* Хром: якорь фазы */
var _lp3UpdateChrome = updateChrome;
updateChrome = function(){
  _lp3UpdateChrome();
  try{ lp3UpdateAnchor(); }catch(e){}
};
/* Финал: «Фаза X%» + CTA курса + адаптивная рекомендация */
var _lp3FinaleExtras = finaleExtrasHtml;
finaleExtrasHtml = function(l){
  var base = _lp3FinaleExtras(l);
  try{ return base + lp3CourseFinaleHtml(l); }catch(e){ return base; }
};
/* Тема хаба синхронно с плеером */
var _lp3ApplyTheme = applyTheme;
applyTheme = function(){
  _lp3ApplyTheme();
  try{ lp3SyncThemeEl(H.root); }catch(e){}
};
/* Открытие урока: хаб закрывается; недавние; вкладка → «Шаги» (P3.3) */
var _lp3OpenPlayer = openPlayer;
openPlayer = function(lessonId, stepIdx, opts){
  if(H.active) Home.close(true);
  var r = _lp3OpenPlayer.apply(this, arguments);
  try{ lp3PushRecent(lessonId); }catch(e){}
  try{ lp3SetPanelTab('steps'); }catch(e){}
  return r;
};
/* Закрытие плеера: from:'home' → возврат в хаб (патч-план §3) */
var _lp3ClosePlayer = closePlayer;
closePlayer = function(){
  var ret = _lp3ReturnHome;
  _lp3ReturnHome = false;
  _lp3ClosePlayer();
  if(ret && !S.active && !H.active){ try{ Home.open(); }catch(e){} }
};
/* openTest: из хаба — закрыть хаб и пометить возврат */
var _lp3OpenTestExport = window.LearnPlayer.openTest;
window.LearnPlayer.openTest = function(testId, from){
  if(H.active){ Home.close(true); _lp3ReturnHome = true; }
  _lp3OpenTestExport(testId, from);
};

/* ============================== ТОЧКА ВХОДА В ШАПКЕ (P2) ==============================
   Кнопка «🎓» — наша (Этап 1 P8.4); правим поведение СВОЕЙ кнопки на уровне
   DOM (clone без слушателей), исходный код не меняется. */
function lp3HookHeader(){
  var b = document.getElementById('lp_header_btn');
  if(!b) return false;
  if(b.getAttribute('data-lp3') === '1') return true;
  var nb = b.cloneNode(false);
  nb.id = 'lp_header_btn';
  nb.setAttribute('data-lp3', '1');
  nb.title = 'Моё обучение 🎓 — хаб курса (Learn Home)';
  nb.setAttribute('aria-label', 'Моё обучение');
  nb.textContent = '🎓';
  if(b.parentNode) b.parentNode.replaceChild(nb, b);
  nb.addEventListener('click', function(){ if(H.active) return; Home.open(); }); // при открытом хабе — игнор (P2.3)
  return true;
}
(function lp3HeaderRetry(n){
  if(lp3HookHeader()) return;
  if(n > 0) setTimeout(function(){ lp3HeaderRetry(n - 1); }, 150);
})(20);

/* ============================== SMOKE / SELFTEST (P8) ============================== */
function smoke3(){
  if(!(window.V10 && window.V10.smoke)) return;
  try{
    V10.smoke.add('lp3:home-api', typeof window.LearnPlayer.openHome === 'function' &&
      typeof window.LearnPlayer.search === 'function' &&
      typeof window.LearnPlayer.openNote === 'function' &&
      typeof window.LearnPlayer.exportNotesMarkdown === 'function', window.LearnPlayer.version);
    var phs = lp3PhaseNums(), sum = 0, seen = {}, eachOne = true;
    phs.forEach(function(ph){
      LESSONS.forEach(function(l){
        if(l.phase !== ph) return;
        sum++;
        if(seen[l.id]) eachOne = false;
        seen[l.id] = 1;
      });
    });
    V10.smoke.add('lp3:program-213', eachOne && sum === LESSONS.length && LESSONS.length === 213,
      sum + ' уроков в ' + phs.length + ' фазах, каждый ровно в одной');
    var pct = learnCoursePct();
    V10.smoke.add('lp3:course-pct', typeof pct === 'number' && isFinite(pct) && pct >= 0 && pct <= 100,
      'Курс ' + pct + '% — реплика формулы вкладки «Прогресс»');
    var sr = lp3Search('ликвидация');
    var lessonsN = 0;
    sr.results.forEach(function(r){ if(r.it.type === 'lesson') lessonsN++; });
    V10.smoke.add('lp3:search-index', !!_lp3Idx && sr.results.length > 0 && lessonsN >= 2,
      '«ликвидация»: ' + sr.results.length + ' результатов (уроков ' + lessonsN + ')');
    var okN = true;
    try{
      var saveN = lpLS_get('cn_learn_notes', null);
      var big = [];
      for(var i = 0; i < 505; i++) big.push({ id: 'x' + i, lessonId: 'p0_l1', stepIdx: 0, quote: 'q' + i, note: '', ts: i });
      lp3NotesSet(big);
      okN = lp3NotesGet().length === LP3_NOTES_MAX;
      if(saveN === null) localStorage.removeItem('cn_learn_notes'); else lpLS_set('cn_learn_notes', saveN);
    }catch(e){ okN = false; }
    V10.smoke.add('lp3:notes-ls', okN, 'cn_learn_notes читается/пишется, лимит ' + LP3_NOTES_MAX);
    var okR = true;
    try{
      var saveR = lpLS_get('cn_learn_recent', null);
      ['p0_l1', 'p0_l2', 'p0_l3', 'p0_l1', 'p1_l1', 'p1_l2', 'p1_l3'].forEach(function(id){ lp3PushRecent(id); });
      var rr = lpLS_get('cn_learn_recent', []);
      var dups = rr.filter(function(x){ return x.lessonId === 'p0_l1'; }).length;
      okR = rr.length <= 5 && dups === 1 && rr[0].lessonId === 'p1_l3';
      if(saveR === null) localStorage.removeItem('cn_learn_recent'); else lpLS_set('cn_learn_recent', saveR);
    }catch(e){ okR = false; }
    V10.smoke.add('lp3:recent-ls', okR, 'cn_learn_recent ≤5, LRU-уникальные, свежий — первым');
  }catch(e){
    try{ V10.smoke.add('lp3:smoke-error', false, String(e && e.message || e)); }catch(e2){}
  }
}
function selfTest3(){
  var out = { ok: true, errors: [] };
  try{
    var phs = lp3PhaseNums(), sum = 0, seen = {}, eachOne = true;
    phs.forEach(function(ph){
      LESSONS.forEach(function(l){
        if(l.phase !== ph) return;
        sum++;
        if(seen[l.id]) eachOne = false;
        seen[l.id] = 1;
      });
    });
    out.program = { sum: sum, phases: phs.length };
    if(sum !== LESSONS.length || !eachOne) out.errors.push('программа: ' + sum + '/' + LESSONS.length);
    var pct = learnCoursePct();
    out.coursePct = pct;
    if(!(typeof pct === 'number' && isFinite(pct) && pct >= 0 && pct <= 100)) out.errors.push('курс % некорректен');
    var sr = lp3Search('ликвидация');
    var lessonsN = 0;
    sr.results.forEach(function(r){ if(r.it.type === 'lesson') lessonsN++; });
    out.search = { total: sr.results.length, lessons: lessonsN };
    if(sr.results.length < 2 || lessonsN < 2) out.errors.push('поиск «ликвидация» слабый');
    var md = lp3NotesMarkdown();
    out.markdownOk = lp3NotesGet().length === 0 ? true : md.length > 30;
    if(!out.markdownOk) out.errors.push('markdown-экспорт пуст при наличии заметок');
    out.ok = !out.errors.length;
  }catch(e){ out.errors.push(String(e && e.message || e)); out.ok = false; }
  return out;
}
/* ============================== РАСШИРЕНИЕ API (публичный §3) ============================== */
window.LearnPlayer.version = '3.0 (Этап 3, ТЗ v2)';
window.LearnPlayer.openHome = function(){ if(S.active) return; Home.open(); };
window.LearnPlayer.closeHome = function(){ Home.close(); };
window.LearnPlayer.search = function(q){ return lp3Search(q); };
window.LearnPlayer.openNote = function(noteId){
  var arr = lp3NotesGet(), n = null;
  for(var i = 0; i < arr.length; i++){ if(arr[i].id === noteId){ n = arr[i]; break; } }
  if(!n) return null;
  lp3NoteJump(noteId);
  return n;
};
window.LearnPlayer.exportNotesMarkdown = function(){ return lp3NotesMarkdown(); };
window.LearnPlayer._learnCoursePct = learnCoursePct;
window.LearnPlayer._goAdaptive = lp3GoAdaptive;
var _lp3SelfTest2 = window.LearnPlayer.selfTest;
window.LearnPlayer.selfTest = function(){
  var a = _lp3SelfTest2 ? _lp3SelfTest2() : { ok: true, errors: [] };
  var b = selfTest3();
  a.lp3 = b;
  if(b && b.errors && b.errors.length) a.ok = false;
  return a;
};
smoke3(); /* после расширения API — проверяет наличие открытых функций */
/* ============================================================
   learn_player_stage4: ЭТАП 4 — Пункт 1: персистентный счётчик ошибок.
   ------------------------------------------------------------
   Было (Этапы 1–3): S.quizAttempts — сессионный (сброс при каждом
   открытии урока), рекомендация адаптива на финале жила только в той
   сессии, где были ≥3 неверных попыток квиза.
   Стало: накопитель cn_learn_mist = { lid: { n: totalWrong, ts } } —
   растёт между сессиями, читается на финале, сбрасывается по CTA
   «🔄 Пройти адаптивную тренировку» и по ссылке «Не напоминать».

   Паритет с Этапом 1 (§12.6): инкремент — тем же событием (неверная
   попытка квиза: тот же селектор #lquiz_opts_<lid> .ans, тот же
   защитный предикат quizPassed(), тот же тайминг setTimeout —
   слушатель добавлен ПОСЛЕ родного, поэтому срабатывает строго после
   него). Счётчик «Попытка N» внутри квиза остаётся сессионным —
   персистентным live только накопитель для рекомендации.

   §11.9/§0.1: ADAPTIVE_QUESTION_BANK, банки, существующие функции —
   не тронуты; только обёртки и новые LS-ключи (cn_learn_*).
   ============================================================ */

var LP4_KEY = 'cn_learn_mist';
var LP4_THRESHOLD = 3;      // ≥3 неверных попыток — показать рекомендацию
var LP4_EXCERPT = 420;      // обрезка текста шага для контекста наставника

function lp4MistAll(){
  var st = lpLS_get(LP4_KEY, {});
  if(!st || typeof st !== 'object' || Array.isArray(st)) return {};
  return st;
}
function lp4MistTotal(lid){
  var rec = lp4MistAll()[lid];
  return (rec && typeof rec.n === 'number' && isFinite(rec.n) && rec.n > 0) ? rec.n : 0;
}
function lp4MistSet(lid, n){
  if(!lid || typeof lid !== 'string') return;
  var st = lp4MistAll();
  if(typeof n !== 'number' || !isFinite(n) || n <= 0) delete st[lid];
  else st[lid] = { n: Math.floor(n), ts: Date.now() };
  lpLS_set(LP4_KEY, st);
}

/* --- Хук инкремента: обёртка attachStepDelegates (Этап 1) ---
   Родной делегат уже висит на stepEl; наш слушатель добавляется после
   него и потому выполняется позже (same phase, порядок регистрации),
   а его setTimeout встаёт в очередь позже родного setTimeout(0). */
var _lp4AttachDelegates = attachStepDelegates;
attachStepDelegates = function(stepEl, st, l){
  _lp4AttachDelegates.apply(this, arguments);
  try{
    if(!stepEl || stepEl.__lp4mist) return;
    if(!st || st.kind !== 'quiz' || !l || !l.id) return;
    stepEl.__lp4mist = true;
    stepEl.addEventListener('click', function(ev){
      var opt = ev.target.closest('#lquiz_opts_' + l.id + ' .ans');
      if(!opt) return;
      setTimeout(function(){
        try{
          if(quizPassed()) return; /* верная попытка — счётчик не растёт (паритет с Этапом 1) */
          lp4MistSet(l.id, lp4MistTotal(l.id) + 1);
        }catch(e){}
      }, 0);
    });
  }catch(e){}
};

/* --- Финал: карточка рекомендации по ПЕРСИСТЕНТНОМУ итогу ---
   Обёртка lp3CourseFinaleHtml (Этап 3): на время её вызова глушим
   сессионное значение S.quizAttempts[lid] (иначе Этап 3 отрисует свою
   карточку по сессии), затем рисуем свою карточку по накопителю.
   S.quizAttempts восстанавливается синхронно — другой код не работает
   между этими строками. */
var _lp4CourseFinale = lp3CourseFinaleHtml;
lp3CourseFinaleHtml = function(l){
  var saved, h;
  try{ saved = S.quizAttempts[l.id]; }catch(e){}
  var total = lp4MistTotal(l.id);
  try{
    try{ S.quizAttempts[l.id] = 0; }catch(e1){}
    h = _lp4CourseFinale(l);
  } finally {
    try{
      if(saved === undefined) delete S.quizAttempts[l.id];
      else S.quizAttempts[l.id] = saved;
    }catch(e2){}
  }
  try{
    if(total >= LP4_THRESHOLD){
      var sess = 0;
      try{ sess = S.quizAttempts[l.id] || 0; }catch(e3){}
      h += lp4RecommendCard(l, total, sess);
    }
  }catch(e4){}
  return h;
};

function lp4RecommendCard(l, total, sess){
  var hist = total > sess ? ' (всего, с учётом прошлых сессий)' : '';
  return '<div class="learn-card warn" id="lp4_rec_card" style="max-width:560px;margin:16px auto 0;padding:14px 18px;text-align:left">' +
    '<div style="font-weight:800;margin-bottom:6px">🔄 Квиз дался непросто (' + total + ' неверн' + lp4Plural(total) + ' попытк' + lp4Plural2(total) + ')' + hist + '</div>' +
    '<div style="font-size:calc(var(--lp-fs) - 5px);color:var(--mut);line-height:1.55;margin-bottom:10px">Счётчик сохраняется между сессиями. Запусти адаптивную тренировку — она подберёт вопросы по слабым темам из существующего банка и закрепит материал.</div>' +
    '<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">' +
      '<button type="button" class="lp-btn primary" onclick="LearnPlayer._goAdaptive()">🔄 Пройти адаптивную тренировку по этой теме</button>' +
      '<button type="button" class="lp-btn ghost" onclick="LearnPlayer._mistReset(\'' + attr(l.id) + '\')">Не напоминать</button>' +
    '</div></div>';
}
function lp4Plural(n){ /* прилагательное: неверн[ая/ые/ых] */
  var d = n % 10, h = n % 100;
  if(d === 1 && h !== 11) return 'ая';
  if(d >= 2 && d <= 4 && (h < 12 || h > 14)) return 'ые';
  return 'ых';
}
function lp4Plural2(n){ /* существительное: попытк[а/и/ок] */
  var d = n % 10, h = n % 100;
  if(d === 1 && h !== 11) return 'а';
  if(d >= 2 && d <= 4 && (h < 12 || h > 14)) return 'и';
  return 'ок';
}

/* --- Сброс по CTA: считаем, что рекомендация отработала, когда ученик
   нажал «🔄 Пройти адаптивную тренировку» (намерение зафиксировано) --- */
var _lp4GoAdaptive = window.LearnPlayer._goAdaptive;
window.LearnPlayer._goAdaptive = function(){
  var lid = null;
  try{ lid = S.lessonId; }catch(e){}
  var r = _lp4GoAdaptive.apply(this, arguments);
  try{ if(lid && lp4MistTotal(lid) > 0) lp4MistSet(lid, 0); }catch(e){}
  return r;
};

/* --- Публичный API Этапа 4 (приёмка/диагностика) --- */
window.LearnPlayer._mistInfo = function(lid){
  var sess = 0;
  try{ sess = S.quizAttempts[lid] || 0; }catch(e){}
  return { total: lp4MistTotal(lid), sess: sess, threshold: LP4_THRESHOLD };
};
window.LearnPlayer._mistReset = function(lid){
  lp4MistSet(lid, 0);
  try{ if(S.active && S.lessonId === lid && typeof renderStep === 'function') renderStep(S.idx); }catch(e){}
  try{ toast('Счётчик ошибок урока сброшен', '🔄'); }catch(e1){}
};
/* ============================================================
   learn_player_stage4: ЭТАП 4 — Пункт 2: наставник в потоке шагов (§5.5).
   ------------------------------------------------------------
   Было: наставник вызывался по кнопке «💬» шапки плеера как
   mentorOpenPanel(l.id) и не знал, на каком шаге ученик (контекст
   урока наставник строит сам — MENTOR.buildLessonText, весь урок).
   Стало:
   1) window.mentorOpenPanel обёрнут (поверх v10-обёртки «моста чисел»):
      если плеер открыт в режиме урока — наставник автоматически получает
      контекст ТЕКУЩЕГО шага (idx/total/title/kind + фрагмент материала);
   2) в панели появляется карточка шага с кнопкой «💬 Подсказка по этому
      шагу» → MENTOR.ask('socratic', lessonId, { step, stepTitle,
      stepText }) — payload существующего контура; код наставника,
      лимиты (30/день), фильтр запрещённых фраз и тарифный гейт не тронуты;
   3) в футере КАЖДОГО шага урока — кнопка «💬 Наставник» (data-lp-act);
   4) в demo-тире апселл поднят над плеером CSS-фиксом (stage4_css).
   В тестовом режиме (Этап 2) шаговый контекст не передаётся: порции —
   вопросы, а не материал; панель доступна с контекстом урока как раньше.
   ============================================================ */

var lp4LastCtx = null; /* контекст шага, с которого панель открыта */

function lp4EscPanel(s){
  return (window.V10 && typeof V10.escHtml === 'function')
    ? V10.escHtml(s)
    : String(s == null ? '' : s).replace(/[&<>"']/g, function(c){
        return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c];
      });
}

/* Текущий шаг плеера → контекст наставника. null вне плеера/в тестовом режиме. */
function lp4StepCtx(){
  try{
    if(!S || !S.active) return null;
    try{ if(typeof TS !== 'undefined' && TS && TS.active) return null; }catch(eT){}
    if(!S.steps || !S.steps.length) return null;
    var st = S.steps[S.idx];
    if(!st) return null;
    var l = lessonById(S.lessonId);
    if(!l) return null;
    var el = S.root ? S.root.querySelector('.learn-step') : null;
    var text = el ? String(el.innerText || '') : '';
    text = text.replace(/\s+/g, ' ').trim();
    if(text.length > LP4_EXCERPT) text = text.slice(0, LP4_EXCERPT) + '…';
    return {
      lessonId: l.id,
      lessonTitle: l.title || '',
      idx: S.idx,
      total: S.steps.length,
      title: st.title || '',
      kind: st.kind || '',
      text: text
    };
  }catch(e){ return null; }
}

/* Обёртка window.mentorOpenPanel(lessonId[, stepCtx]).
   Вызов с одним аргументом из открытого плеера (шапка/футер) → авто-контекст
   текущего шага. Вызовы приложения (ридер и пр.) при закрытом плеере дают
   ctx = null — панель работает как раньше, без шаговой карточки. */
var _lp4MentorOpen = window.mentorOpenPanel;
window.mentorOpenPanel = function(lessonId, stepCtx){
  var ctx = (arguments.length >= 2) ? stepCtx : lp4StepCtx();
  var r = _lp4MentorOpen.apply(this, [lessonId]);
  try{
    var panel = document.getElementById('mentor_panel');
    if(!panel){ lp4LastCtx = null; return r; } /* demo-тире: открыт апселл (поднят CSS-фиксом) */
    if(ctx){
      lp4LastCtx = ctx;
      lp4InjectStepCtx(ctx);
    } else {
      lp4LastCtx = null;
      var stale = document.getElementById('lp4_mentor_step');
      if(stale) stale.remove();
    }
  }catch(e){}
  return r;
};
window.mentorOpenPanel.__lp4wrapped = true;

/* Карточка шага в панели: строка контекста + фрагмент материала + CTA */
function lp4InjectStepCtx(ctx){
  var body = document.getElementById('mentor_panel_body');
  if(!body) return;
  var head = body.firstElementChild;
  if(head && head.tagName === 'DIV'){
    head.innerHTML = 'Урок: ' + lp4EscPanel(ctx.lessonId) +
      ' · Шаг ' + (ctx.idx + 1) + ' из ' + ctx.total + ': ' + lp4EscPanel(ctx.title);
  }
  var old = document.getElementById('lp4_mentor_step');
  if(old) old.remove();
  var ex = ctx.text ? (ctx.text.length > 140 ? ctx.text.slice(0, 140) + '…' : ctx.text) : '';
  var card = document.createElement('div');
  card.id = 'lp4_mentor_step';
  card.style.cssText = 'margin:0 0 10px;padding:9px 11px;border:1px solid var(--line);border-radius:9px;background:rgba(127,127,127,.07)';
  card.innerHTML =
    '<div style="font-size:11px;color:var(--mut);line-height:1.55;margin-bottom:7px">Наставник видит текущий шаг: ' +
      '<b style="color:var(--txt)">' + lp4EscPanel(ctx.title) + '</b>' +
      (ex ? '<br><span style="font-style:italic">«' + lp4EscPanel(ex) + '»</span>' : '') +
    '</div>' +
    '<button type="button" class="btn sm" style="font-size:12px" onclick="LearnPlayer._mentorStepAsk()">💬 Подсказка по этому шагу</button>';
  var actions = document.getElementById('mentor_actions');
  if(actions && actions.parentNode) actions.parentNode.insertBefore(card, actions);
  else body.insertBefore(card, body.firstChild ? body.firstChild.nextSibling : null);
}

/* Подсказка по шагу — через существующий контур MENTOR.ask (лимит/фильтр/мок
   работают как у всех действий; payload несёт шаговый контекст) */
window.LearnPlayer._mentorStepAsk = function(){
  var ctx = lp4LastCtx || lp4StepCtx();
  var out = document.getElementById('mentor_result');
  if(!ctx || !out) return;
  if(typeof MENTOR === 'undefined' || !MENTOR || typeof MENTOR.ask !== 'function'){
    out.innerHTML = '<div style="font-size:12.5px;color:var(--warn)">Наставник недоступен в этой сборке.</div>';
    return;
  }
  out.innerHTML = '<div style="font-size:12px;color:var(--mut)">🤖 Разбираю материал шага «' + lp4EscPanel(ctx.title) + '»…</div>';
  MENTOR.ask('socratic', ctx.lessonId, { step: ctx.idx + 1, stepTitle: ctx.title, stepText: ctx.text, source: 'learn_player_step' })
    .then(function(r){
      var demo = r && r.json && r.json.demo;
      out.innerHTML = '<div style="font-size:12.5px;line-height:1.6;color:var(--txt);white-space:pre-wrap">' +
        lp4EscPanel(r && r.text ? r.text : '(наставник не вернул текст — попробуй ещё раз)') +
        (demo ? '<div style="margin-top:8px;font-size:11px;color:var(--mut)">🎭 ДЕМО-режим наставника (без ИИ): правило-заглушка вместо модели.</div>' : '') +
        '</div>';
    })
    .catch(function(e){
      var m = (e && e.message) || '';
      out.innerHTML = '<div style="font-size:12.5px;color:var(--warn)">' +
        (m === 'limit' ? 'Дневной лимит наставника исчерпан (' + (window.MENTOR_LIMIT || 30) + ' действий).' :
         m === 'offline' ? 'Нет соединения — наставнику нужна сеть.' :
         'Наставник задумался слишком надолго — попробуй ещё раз.') + '</div>';
    });
};
/* ============================================================
   learn_player_stage4: ЭТАП 4 — футер шага: кнопка «💬 Наставник» +
   смоук lp4:* и секция selfTest.lp4.
   ============================================================ */

/* Кнопка в футере КАЖДОГО шага урока (renderBottom вызывается только в
   режиме урока — updateChrome → renderBottom; тестовый режим Этапа 2
   имеет собственную нижнюю панель и не затрагивается). Клик — тот же
   существующий контур mentorOpenPanel: авто-контекст шага подставит
   обёртка из части 2. */
var _lp4RenderBottom = renderBottom;
renderBottom = function(st, l){
  _lp4RenderBottom.apply(this, arguments);
  try{
    if(!S.root) return;
    var bottom = S.root.querySelector('.learn-bottom');
    if(!bottom || bottom.querySelector('[data-lp-act="lp4-mentor"]')) return;
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'lp-btn ghost lp4-mentor-btn';
    btn.setAttribute('data-lp-act', 'lp4-mentor');
    btn.setAttribute('aria-label', 'Спросить наставника о текущем шаге');
    btn.title = 'Наставник увидит материал текущего шага';
    btn.textContent = '💬 Наставник';
    btn.onclick = function(){
      try{ window.mentorOpenPanel(S.lessonId); }catch(e){}
    };
    /* родной футер: [«← Назад», spacer flex:1, right] — ставим после «Назад» */
    bottom.insertBefore(btn, bottom.children[1] || null);
  }catch(e){}
};

/* ---------- Секция selfTest.lp4 ---------- */
var _lp4SelfTest = window.LearnPlayer.selfTest;
window.LearnPlayer.selfTest = function(){
  var a = _lp4SelfTest ? _lp4SelfTest() : { ok: true, errors: [] };
  var errs = [];
  try{
    ['_mistInfo', '_mistReset', '_mentorStepAsk', '_goAdaptive'].forEach(function(k){
      if(typeof window.LearnPlayer[k] !== 'function') errs.push('lp4:api ' + k);
    });
    if(!window.mentorOpenPanel || !window.mentorOpenPanel.__lp4wrapped) errs.push('lp4:mentor-wrapper');
    var st = lp4MistAll();
    Object.keys(st).forEach(function(k){
      var v = st[k];
      if(!v || typeof v.n !== 'number' || !(v.n >= 0) || typeof v.ts !== 'number') errs.push('lp4:ls ' + k);
    });
  }catch(e){ errs.push('lp4:exception'); }
  a.lp4 = { ok: errs.length === 0, errors: errs };
  if(errs.length) a.ok = false;
  return a;
};

/* ---------- Смоук lp4:* (в V10.smoke, как lp:/lp2:/lp3:) ---------- */
function smoke4(){
  if(!(window.V10 && window.V10.smoke)) return;
  try{
    V10.smoke.add('lp4:api', typeof window.LearnPlayer._mistInfo === 'function' &&
      typeof window.LearnPlayer._mistReset === 'function' &&
      typeof window.LearnPlayer._mentorStepAsk === 'function' &&
      typeof window.LearnPlayer._goAdaptive === 'function', 'Этап 4: API счётчика и наставника');
    V10.smoke.add('lp4:mentor-wrapper', !!(window.mentorOpenPanel && window.mentorOpenPanel.__lp4wrapped),
      'mentorOpenPanel обёрнут: авто-контекст шага + карточка в панели');
    var okLS = true;
    try{
      var save = lpLS_get(LP4_KEY, null);
      lp4MistSet('p0_l1', 3);
      var t = lp4MistTotal('p0_l1');
      lp4MistSet('p0_l1', 0);
      var z = lp4MistTotal('p0_l1');
      okLS = (t === 3 && z === 0);
      if(save === null) localStorage.removeItem(LP4_KEY); else lpLS_set(LP4_KEY, save);
    }catch(e){ okLS = false; }
    V10.smoke.add('lp4:mist-ls', okLS, 'cn_learn_mist: запись/чтение/сброс персистентного счётчика');
    var zOk = false;
    try{
      var stl = document.getElementById('learn_player_css');
      zOk = !!(stl && /#mentor_upsell_modal\{[^}]*z-index:\s*1000500/.test(stl.textContent));
    }catch(e2){}
    V10.smoke.add('lp4:upsell-z', zOk, 'апселл наставника поднят над плеером (CSS-фикс §6)');
    var pl = lp4Plural(1) === 'ая' && lp4Plural(3) === 'ые' && lp4Plural(5) === 'ых' &&
             lp4Plural2(1) === 'а' && lp4Plural2(3) === 'и' && lp4Plural2(5) === 'ок';
    V10.smoke.add('lp4:plural', pl, 'склонение «неверная попытка/неверные попытки/неверных попыток»');
  }catch(e){}
}
smoke4();

/* ============================================================
   learn_player_stage5: ЭТАП 5 (БЭКЛОГ) — Часть 1.
   «Недавние» для тестов (хаб) + экспорт конспекта в файл.
   ------------------------------------------------------------
   Было (Этапы 3–4): хаб показывает «Недавние» только по урокам
   (cn_learn_recent LRU ≤5); конспект имеет кнопку «Скопировать
   (markdown)» (lp3-notes-copy), но файлом не скачивается.
   Стало:
   1) cn_learn_recent_tests = [{testId, ts}] ≤5, LRU — пишется на
      каждое открытие теста (обе точки входа: window-экспорт
      LearnPlayer.openTest и внутренний openTest из пикера 🏁);
   2) в хабе перед «🏁 Тесты и экзамены» — секция «🕘 Недавние
      тесты» (состояния через существующий bankMeta Этапа 2);
   3) в панели конспекта рядом с «Скопировать» — «⬇ Скачать
      файлом (.md)»: Blob + a.download, имя с датой;
      API: LearnPlayer.exportNotesFile().
   §0.1/§7.2: только новые LS-ключи cn_*, существующие функции
   не редактируются — обёртки над lp3HomeHtml / lp3NotesPanelHtml /
   lp3NoteActionClick (переприсвоение связки внутри IIFE).
   ============================================================ */

var LP5_RT_KEY = 'cn_learn_recent_tests';
var LP5_PT_KEY = 'cn_pt_start';

/* ---------- Недавние тесты: LRU ≤5 ---------- */
function lp5RecentTestsAll(){
  var a = lpLS_get(LP5_RT_KEY, []);
  return Array.isArray(a) ? a : [];
}
function lp5PushRecentTest(testId){
  try{
    if(!testId || typeof testId !== 'string') return;
    var r = null;
    try{ r = resolveBank(testId); }catch(e){}
    if(!r) return; /* неизвестный банк не пишем */
    var a = lp5RecentTestsAll().filter(function(x){ return x && x.testId !== testId; });
    a.unshift({ testId: testId, ts: Date.now() });
    lpLS_set(LP5_RT_KEY, a.slice(0, 5));
  }catch(e){}
}

/* Секция хаба: карточки по образцу lp3TestsHtml, клик — существующий
   обработчик data-lp3-test → lp3OpenTestFromHome (Этап 3). */
function lp5RecentTestsHtml(){
  var rec = lp5RecentTestsAll();
  var h = '<section class="lp3-sec" id="lp5_recent_tests"><div class="lp3-sec-h">🕘 Недавние тесты</div>';
  if(!rec.length){
    h += '<div class="lp3-empty">Пока пусто — открой любой тест из раздела «Тесты и экзамены» ниже или через пикер 🏁.</div>';
  } else {
    rec.forEach(function(x){
      var m = null;
      try{ m = bankMeta(x.testId); }catch(e){}
      if(!m) return; /* банк исчез из рантайма — строку не рисуем */
      h += '<button type="button" class="lp3-card" data-lp3-test="' + attr(x.testId) + '">' +
        '<span class="t">🏁 ' + esc(m.r.title) + '</span>' +
        '<span class="m">' + m.draftInfo + m.total + ' вопр.' + (m.req ? ' · порог ' + m.req : '') + '<br>' + m.state + '</span></button>';
    });
  }
  return h + '</section>';
}

/* Вставка секции в хаб БЕЗ правки lp3HomeHtml: детерминированный якорь —
   заголовок «🏁 Тесты и экзамены» (генерируется lp3TestsHtml Этапа 3). */
var _lp5HomeHtml = lp3HomeHtml;
lp3HomeHtml = function(){
  var h = _lp5HomeHtml.apply(this, arguments);
  try{
    var sec = lp5RecentTestsHtml();
    var anchor = '<section class="lp3-sec"><div class="lp3-sec-h">🏁 Тесты и экзамены</div>';
    if(h.indexOf(anchor) >= 0) h = h.replace(anchor, sec + anchor);
    else h += sec; /* якорь не найден — секция всё равно доступна (не теряем функцию) */
  }catch(e){}
  return h;
};

/* ---------- Экспорт конспекта в файл (БЭКЛОГ Э3) ---------- */
function lp5DownloadNotes(){
  try{
    var arr = lp3NotesGet();
    if(!arr.length){ toast('Конспект пуст — скачивать нечего', '📝'); return; }
    var md = lp3NotesMarkdown();
    var d = new Date();
    var stamp = d.getFullYear() + '-' + ('0' + (d.getMonth() + 1)).slice(-2) + '-' + ('0' + d.getDate()).slice(-2);
    /* BOM — чтобы UTF-8 корректно открывался в Блокноте Windows */
    var blob = new Blob(['\ufeff' + md], { type: 'text/markdown;charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'kriptonavigator-konspekt-' + stamp + '.md';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function(){ try{ URL.revokeObjectURL(url); }catch(e2){} }, 4000);
    toast('Конспект скачан файлом (.md) — ' + arr.length + ' заметок', '⬇️');
  }catch(e){
    try{ toast('Не удалось скачать файл — используй «Скопировать всё»', '⚠️'); }catch(e1){}
  }
}
window.LearnPlayer.exportNotesFile = lp5DownloadNotes;

/* Кнопка в панели конспекта: обёртка lp3NotesPanelHtml добавляет кнопку
   в существующую панель инструментов рядом с «Скопировать всё». */
var _lp5NotesPanelHtml = lp3NotesPanelHtml;
lp3NotesPanelHtml = function(){
  var h = _lp5NotesPanelHtml.apply(this, arguments);
  try{
    var old = '<div style="display:flex;justify-content:flex-end;margin-bottom:8px">' +
      '<button type="button" class="lp-btn sm" data-lp3-notes-copy>📋 Скопировать всё (markdown)</button></div>';
    var neu = '<div style="display:flex;justify-content:flex-end;gap:8px;margin-bottom:8px">' +
      '<button type="button" class="lp-btn sm" data-lp3-notes-copy>📋 Скопировать всё (markdown)</button>' +
      '<button type="button" class="lp-btn sm" data-lp3-notes-dl>⬇ Скачать файлом (.md)</button></div>';
    if(h.indexOf(old) >= 0) h = h.replace(old, neu);
  }catch(e){}
  return h;
};

/* Обработчик: обёртка lp3NoteActionClick (общие обработчики панели и хаба).
   Наше действие проверяется ПЕРВЫМ, остальное — существующий контур Этапа 3. */
var _lp5NoteAction = lp3NoteActionClick;
lp3NoteActionClick = function(e){
  try{
    var nd = e.target.closest('[data-lp3-notes-dl]');
    if(nd){ lp5DownloadNotes(); return true; }
  }catch(e0){}
  return _lp5NoteAction.apply(this, arguments);
};
/* ============================================================
   learn_player_stage5: ЭТАП 5 (БЭКЛОГ) — Часть 2.
   Накопитель ошибок на тестовые банки + персистентность _ptStart.
   ------------------------------------------------------------
   Было (Этап 4): накопитель cn_learn_mist вёл только аттестационные
   квизы уроков; спидран-таймер _ptStart жил в памяти страницы —
   после перезагрузки стартовал заново (ghost, находка №13).
   Стало:
   1) неверные ответы фазовых тестов, мат-тестов и капстоуна при
      СДАЧЕ попытки попадают в тот же накопитель: ключ — testId
      банка ('p0'…'exam_capstone'…); диагностики не считаются
      (паритет с lp3FirstUnpassedBank: диагностика — не «несдано»);
      подсчёт — по факту сдачи (total − correct), правки ответов
      в черновике не раздувают счётчик;
   2) на экране результата теста — карточка рекомендации по образцу
      Этапа 4 (≥3 неверных всего, честная пометка «с учётом прошлых
      попыток»), CTA на существующий адаптивный контур + «Не
      напоминать»; ADAPTIVE_QUESTION_BANK не тронут (§11.9);
   3) cn_pt_start = { phaseNum: startTs } — читается при новой
      попытке (ридер-фикс №13a/13b) и при resume плеера: таймер
      продолжается, а не стартует заново; после сдачи — 0.
   Новые LS-ключи: cn_pt_start. Существующие функции не редактируются
   (обёртки newAttempt / startTestSession / submitTest / testResultHtml /
   openTest ×2 / LearnPlayer._goAdaptive / LearnPlayer._mistReset).
   ============================================================ */

/* ---------- cn_pt_start: чтение/запись ---------- */
function lp5PtStartLoad(){
  var s = null;
  try{ s = JSON.parse(localStorage.getItem(LP5_PT_KEY) || 'null'); }catch(e){ s = null; }
  return (s && typeof s === 'object' && !Array.isArray(s)) ? s : {};
}
function lp5PtStartPersist(ph){
  try{
    if(typeof ph !== 'number' || !isFinite(ph)) return;
    window._ptStart = window._ptStart || {};
    var s = lp5PtStartLoad();
    s[ph] = window._ptStart[ph] || 0;
    localStorage.setItem(LP5_PT_KEY, JSON.stringify(s));
  }catch(e){}
}

/* Новая попытка (в т.ч. «Начать заново»/пересдача → restartAttempt):
   после родной установки _ptStart[ph] = Date.now() — фиксируем старт. */
var _lp5NewAttempt = newAttempt;
newAttempt = function(r){
  _lp5NewAttempt.apply(this, arguments);
  try{ if(r && r.kind === 'phase') lp5PtStartPersist(r.ph); }catch(e){}
};

/* Resume (startTestSession): родной код ставит свежий Date.now(), если
   в памяти пусто (после перезагрузки — всегда). Поверх — возвращаем
   сохранённый старт из cn_pt_start (таймер продолжается, №13). */
var _lp5StartTestSession = startTestSession;
startTestSession = function(r){
  var resumePh = null;
  try{
    if(r && r.kind === 'phase'){
      var d0 = testDraftGet();
      if(d0 && d0.testId === r.testId) resumePh = r.ph;
    }
  }catch(e0){}
  _lp5StartTestSession.apply(this, arguments);
  try{
    if(resumePh !== null){
      var saved = lp5PtStartLoad()[resumePh];
      if(typeof saved === 'number' && saved > 0){
        window._ptStart = window._ptStart || {};
        window._ptStart[resumePh] = saved;
      } else {
        lp5PtStartPersist(resumePh);
      }
    }
  }catch(e){}
};

/* ---------- Накопитель на тестовые банки ---------- */
var _lp5SubmitTest = submitTest;
submitTest = function(){
  _lp5SubmitTest.apply(this, arguments);
  var rerender = false;
  try{
    if(TS && TS.active && TS.submitted && TS.result && !TS.result.diag &&
       (TS.kind === 'phase' || TS.kind === 'math') && TS.testId){
      var wrongs = (TS.result.total || 0) - (TS.result.correct || 0);
      if(wrongs > 0){
        lp4MistSet(TS.testId, lp4MistTotal(TS.testId) + wrongs);
        rerender = true; /* родной submit уже отрисовал результат ДО нашего инкремента */
      }
    }
  }catch(e){}
  try{
    /* перерисовываем экран результата, чтобы карточка рекомендации
       появилась сразу (сейчас total уже включает эту попытку) */
    if(rerender && typeof renderTestStep === 'function') renderTestStep(TS.idx);
  }catch(e2){}
};

/* Склонение «ответ»: 1 ответ · 2–4 ответа · 5+ ответов */
function lp5AnsPlural(n){
  var d = n % 10, h = n % 100;
  if(d === 1 && h !== 11) return 'ответ';
  if(d >= 2 && d <= 4 && (h < 12 || h > 14)) return 'ответа';
  return 'ответов';
}

/* Карточка рекомендации на экране результата (образец — lp4RecommendCard).
   Показ по НАКОПЛЕННОМУ итогу ≥3 (как на финале урока); диагностики без
   карточки. CTA несёт testId — сброс именно тестового счётчика. */
var _lp5TestResultHtml = testResultHtml;
testResultHtml = function(){
  var h = _lp5TestResultHtml.apply(this, arguments);
  try{
    if(TS && TS.active && TS.testId && (TS.kind === 'phase' || TS.kind === 'math')){
      var total = lp4MistTotal(TS.testId);
      if(total >= LP4_THRESHOLD){
        var wrongs = TS.result ? ((TS.result.total || 0) - (TS.result.correct || 0)) : 0;
        var hist = total > wrongs ? ' (всего ' + total + ' с учётом прошлых попыток)' : '';
        h += '<div class="learn-card warn" id="lp5_test_rec" style="max-width:560px;margin:16px auto 0;padding:14px 18px;text-align:left">' +
          '<div style="font-weight:800;margin-bottom:6px">🔄 Тест дался непрочно (' + wrongs + ' неверн' + (wrongs === 1 ? 'ый' : 'ых') + ' ' + lp5AnsPlural(wrongs) + ' за попытку)' + hist + '</div>' +
          '<div style="font-size:calc(var(--lp-fs) - 5px);color:var(--mut);line-height:1.55;margin-bottom:10px">Счётчик сохраняется между сессиями. Запусти адаптивную тренировку — она подберёт вопросы по слабым темам из существующего банка и закрепит материал.</div>' +
          '<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">' +
            '<button type="button" class="lp-btn primary" onclick="LearnPlayer._goAdaptive(\'' + attr(TS.testId) + '\')">🔄 Пройти адаптивную тренировку по этой теме</button>' +
            '<button type="button" class="lp-btn ghost" onclick="LearnPlayer._mistReset(\'' + attr(TS.testId) + '\')">Не напоминать</button>' +
          '</div></div>';
      }
    }
  }catch(e){}
  return h;
};

/* CTA с testId: сброс ТЕСТОВОГО счётчика (путь урока — в обёртке Этапа 4
   без изменений; в тестовом режиме S.lessonId = null, там сброса нет). */
var _lp5GoAdaptive = window.LearnPlayer._goAdaptive;
window.LearnPlayer._goAdaptive = function(testId){
  var r = _lp5GoAdaptive.apply(this, arguments);
  try{ if(typeof testId === 'string' && testId && lp4MistTotal(testId) > 0) lp4MistSet(testId, 0); }catch(e){}
  return r;
};

/* «Не напоминать» в тестовом режиме: сброс + перерисовка экрана результата
   (карточка исчезает сразу). Путь урока — существующая обёртка Этапа 4. */
var _lp5MistReset = window.LearnPlayer._mistReset;
window.LearnPlayer._mistReset = function(lid){
  try{
    if(typeof TS !== 'undefined' && TS && TS.active && TS.testId === lid){
      lp4MistSet(lid, 0);
      if(typeof renderTestStep === 'function') renderTestStep(TS.idx);
      toast('Счётчик ошибок теста сброшен', '🔄');
      return;
    }
  }catch(e0){}
  return _lp5MistReset.apply(this, arguments);
};

/* ---------- Недавние тесты: обе точки входа ----------
   1) внутренняя связка openTest — её вызывают пикер 🏁 и код плеера;
   2) window-экспорт LearnPlayer.openTest — его вызывают хаб, финалы
      уроков и onclick-кнопки. Пуш ровно один: window-цепочка Этапа 3
      держит ссылку на исходную функцию, внутренней обёртки не дублируя. */
var _lp5OpenTestInner = openTest;
openTest = function(testId, from){
  try{ lp5PushRecentTest(testId); }catch(e){}
  return _lp5OpenTestInner.apply(this, arguments);
};
var _lp5OpenTestExport = window.LearnPlayer.openTest;
window.LearnPlayer.openTest = function(testId, from){
  try{ lp5PushRecentTest(testId); }catch(e){}
  return _lp5OpenTestExport.apply(this, arguments);
};

/* Публичный API Этапа 5 (приёмка/диагностика) */
window.LearnPlayer._recentTests = lp5RecentTestsAll;
window.LearnPlayer._ptStartStore = lp5PtStartLoad;
/* ============================================================
   learn_player_stage5: ЭТАП 5 (БЭКЛОГ) — Часть 3.
   Смоук lp5:* и секция selfTest.lp5.
   ============================================================ */

/* ---------- Смоук lp5:* (в V10.smoke, как lp:/lp2:/lp3:/lp4:) ---------- */
function smoke5(){
  if(!(window.V10 && window.V10.smoke)) return;
  try{
    V10.smoke.add('lp5:api', typeof window.LearnPlayer.exportNotesFile === 'function' &&
      typeof window.LearnPlayer._recentTests === 'function' &&
      typeof window.LearnPlayer._ptStartStore === 'function', window.LearnPlayer.version);
    /* cn_learn_recent_tests: LRU ≤5, уникальные, свежий первым */
    var okR = true;
    try{
      var saveR = lpLS_get(LP5_RT_KEY, null);
      ['p1', 'p0', 'p1', 'math_core', 'capstone', 'p2'].forEach(function(id){ lp5PushRecentTest(id); });
      var rr = lp5RecentTestsAll();
      okR = rr.length <= 5 && rr[0] && rr[0].testId === 'p2' &&
        rr.filter(function(x){ return x && x.testId === 'p1'; }).length === 1;
      if(saveR === null) localStorage.removeItem(LP5_RT_KEY); else lpLS_set(LP5_RT_KEY, saveR);
    }catch(e){ okR = false; }
    V10.smoke.add('lp5:recent-tests-ls', okR, 'cn_learn_recent_tests ≤5, LRU-уникальные, свежий — первым');
    /* cn_pt_start: старт спидрана переживает перезагрузку (№13) */
    var okP = true;
    try{
      var saveP = lpLS_get(LP5_PT_KEY, null);
      window._ptStart = window._ptStart || {};
      window._ptStart[42] = 1234567890;
      lp5PtStartPersist(42);
      var back = lp5PtStartLoad();
      okP = back[42] === 1234567890;
      delete window._ptStart[42];
      if(saveP === null) localStorage.removeItem(LP5_PT_KEY); else lpLS_set(LP5_PT_KEY, saveP);
    }catch(e){ okP = false; }
    V10.smoke.add('lp5:ptstart-ls', okP, 'cn_pt_start: запись/чтение старта спидрана по фазам');
    /* кнопка «⬇ Скачать файлом» присутствует в панели конспекта (тулбар — при наличии заметок) */
    var dl = false;
    try{
      var saveN5 = lpLS_get('cn_learn_notes', null);
      if(!lp3NotesGet().length){
        lp3NotesSet([{ id: 'lp5probe', lessonId: 'p0_l1', stepIdx: 0, quote: 'smoke-probe', note: '', ts: Date.now() }]);
      }
      dl = lp3NotesPanelHtml().indexOf('data-lp3-notes-dl') >= 0;
      if(saveN5 === null) localStorage.removeItem('cn_learn_notes'); else lpLS_set('cn_learn_notes', saveN5);
    }catch(e){ dl = false; }
    V10.smoke.add('lp5:notes-dl-btn', dl, 'кнопка «⬇ Скачать файлом (.md)» в панели конспекта');
    /* накопитель принимает ключи тестовых банков (тот же cn_learn_mist) */
    var okM = true;
    try{
      var saveM = lpLS_get(LP4_KEY, null);
      lp4MistSet('p1', 2);
      okM = lp4MistTotal('p1') === 2;
      lp4MistSet('p1', 0);
      if(saveM === null) localStorage.removeItem(LP4_KEY); else lpLS_set(LP4_KEY, saveM);
    }catch(e){ okM = false; }
    V10.smoke.add('lp5:mist-banks', okM, 'накопитель cn_learn_mist ведёт и тестовые банки (ключи testId)');
    /* секция «Недавние тесты» вставляется в HTML хаба */
    var secOk = false;
    try{ secOk = lp3HomeHtml().indexOf('lp5_recent_tests') >= 0; }catch(e2){ secOk = false; }
    V10.smoke.add('lp5:home-section', secOk, 'секция «🕘 Недавние тесты» в разметке хаба перед «Тесты и экзамены»');
  }catch(e){
    try{ V10.smoke.add('lp5:smoke-error', false, String(e && e.message || e)); }catch(e2){}
  }
}
smoke5();

/* ---------- Секция selfTest.lp5 ---------- */
var _lp5SelfTest = window.LearnPlayer.selfTest;
window.LearnPlayer.selfTest = function(){
  var a = _lp5SelfTest ? _lp5SelfTest() : { ok: true, errors: [] };
  var errs = [];
  try{
    if(typeof window.LearnPlayer.exportNotesFile !== 'function') errs.push('lp5:api exportNotesFile');
    if(typeof window.LearnPlayer._recentTests !== 'function') errs.push('lp5:api _recentTests');
    if(typeof window.LearnPlayer._ptStartStore !== 'function') errs.push('lp5:api _ptStartStore');
    var rt = lp5RecentTestsAll();
    if(!Array.isArray(rt)) errs.push('lp5:recent-tests формат');
    rt.forEach(function(x){ if(!x || typeof x.testId !== 'string' || typeof x.ts !== 'number') errs.push('lp5:recent-tests элемент'); });
    var pt = lp5PtStartLoad();
    if(!pt || typeof pt !== 'object' || Array.isArray(pt)) errs.push('lp5:ptstart формат');
    Object.keys(pt).forEach(function(k){ if(typeof pt[k] !== 'number') errs.push('lp5:ptstart ' + k); });
    var mst = lp4MistAll();
    Object.keys(mst).forEach(function(k){
      var v = mst[k];
      if(!v || typeof v.n !== 'number' || !(v.n >= 0) || typeof v.ts !== 'number') errs.push('lp5:mist ' + k);
    });
  }catch(e){ errs.push('lp5:exception'); }
  a.lp5 = { ok: errs.length === 0, errors: errs };
  if(errs.length) a.ok = false;
  return a;
};

window.LearnPlayer.version = '5.0 (Этап 5, ТЗ v2)';
/* ===== learn_player_stage5: Этап 5 (конец) ===== */

/* ============================================================
   learn_player_stage6: ЭТАП 6 — Часть 1.
   P1: встроенные практикумы — контент урока не покидает плеер.

   ПРИНЦИП (утверждён владельцем продукта, Э6):
   «Внутренний контент урока не должен покидать Learn Player,
    если интеграция технически возможна.»
   Особо значимо для трека Академии Freqtrade: лабы ft* уже
   внутренние (копирование команд/спек без переходов), все будущие
   практикумы Академии обязаны встраиваться в плеер.

   Было: CTA «🚀 Перейти: <симулятор>» на обложке урока вызывал
   LearnPlayer._goSim → closePlayer() → вкладка «Тренажёры»
   (go('sims')) — ученик покидал плеер, контекст урока терялся из виду.
   Стало: симулятор открывается ОВЕРЛЕЕМ ВНУТРИ плеера: узел
   #sim_<id> переносится из подложки приложения в оверлей (DOM-move,
   без клонов и дублей id), при закрытии возвращается на место.
   Интеграция технически возможна для всех 42 сим-ссылок (probe:
   каждый simId имеет свой #sim_* бокс) — фолбэк на прежнее
   поведение остаётся только для отсутствующих боксов.

   Техника: DOM-перенос узла (appendChild сохраняет слушатели и
   состояние), showSim(id) запускает штатные инициализаторы
   (renderCandleConstructor2 и др.) до переноса; closeOverlays()
   (Э1) обёрнута — узел возвращается ЛЮБЫМ путём закрытия
   (Esc, крестик плеера, переключение режима). §0.1: правок
   существующих функций нет — только обёртки.
   ============================================================ */

var lp6Sim = { ov: null, box: null, ret: null, trigger: null };

function lp6SimTitle(simId){
  try{
    var l = (S.active && S.lessonId) ? lessonById(S.lessonId) : null;
    var m = l && (typeof LESSON_SIM_MAP !== 'undefined') ? LESSON_SIM_MAP[l.id] : null;
    if(m && m.simId === simId && m.title) return String(m.title);
  }catch(e){}
  return 'Практикум';
}

/* Возврат бокса в подложку приложения (любой путь закрытия) */
function lp6RestoreSim(){
  try{
    if(lp6Sim.box && lp6Sim.ret && lp6Sim.ret.parent){
      if(lp6Sim.ret.next && lp6Sim.ret.next.parentNode === lp6Sim.ret.parent){
        lp6Sim.ret.parent.insertBefore(lp6Sim.box, lp6Sim.ret.next);
      } else {
        lp6Sim.ret.parent.appendChild(lp6Sim.box);
      }
    }
    if(lp6Sim.ov && lp6Sim.ov.parentNode) lp6Sim.ov.remove();
  }catch(e){}
  lp6Sim = { ov: null, box: null, ret: null, trigger: null };
}

function lp6CloseSim(){
  var trigger = lp6Sim.trigger;
  lp6RestoreSim();
  try{
    var tgt = (trigger && document.body.contains(trigger)) ? trigger :
      (S.root ? S.root.querySelector('[data-lp-act="close"]') : null);
    if(tgt){ try{ tgt.focus(); }catch(e1){} } /* фокус возвращается в шаг урока */
  }catch(e2){}
}

function lp6OpenSim(simId){
  if(lp6Sim.ov){ lp6CloseSim(); } /* переключение практикума */
  var box = document.getElementById('sim_' + simId);
  if(!box || !S.root){ return false; } /* нет бокса — фолбэк на прежнее поведение */
  try{ if(typeof showSim === 'function') showSim(simId); }catch(e0){} /* штатные инициализаторы */
  var ov = document.createElement('div');
  ov.className = 'learn-overlay';
  ov.setAttribute('data-ov', 'lp6sim');
  var title = lp6SimTitle(simId);
  ov.innerHTML = '<div class="lp6-sim-sheet" role="dialog" aria-modal="true" aria-label="Практикум: ' + attr(title) + '">' +
    '<div class="lp6-sim-head"><div><div class="lp6-sim-title">🕹️ ' + esc(title) + '</div>' +
    '<div class="lp6-sim-note">Практикум открыт внутри урока — плеер не закрывается. Esc или ✕ — вернуться к материалу.</div></div>' +
    '<button type="button" class="lp-btn icon ghost" data-lp6-sim-close aria-label="Закрыть практикум и вернуться к уроку">✕</button></div>' +
    '<div class="lp6-sim-body"></div></div>';
  lp6Sim = { ov: ov, box: box, ret: { parent: box.parentNode, next: box.nextSibling }, trigger: null };
  ov.querySelector('.lp6-sim-body').appendChild(box); /* DOM-move: слушатели и состояние сохраняются */
  ov.addEventListener('click', function(e){
    if(e.target === ov || e.target.closest('[data-lp6-sim-close]')){ lp6CloseSim(); }
  });
  S.root.appendChild(ov);
  var cb = ov.querySelector('[data-lp6-sim-close]');
  if(cb){ try{ cb.focus(); }catch(e2){} } /* фокус внутрь оверлея при открытии */
  return true;
}

/* _goSim: Э1 закрывал плеер и уходил на вкладку «Тренажёры» — теперь
   практикум открывается внутри; фолбэк (нет бокса/нет плеера) — прежний контур */
var _lp6GoSim = window.LearnPlayer._goSim;
window.LearnPlayer._goSim = function(simId){
  try{
    if(S.active && S.root && typeof simId === 'string' && lp6OpenSim(simId)) return;
  }catch(e){}
  return _lp6GoSim.apply(this, arguments);
};
window.LearnPlayer._goSim.__lp6 = true;

/* closeOverlays (Э1) вызывается при открытии плеера/теста и переключениях —
   возвращаем узел практикума ДО удаления оверлеев (иначе бокс теряется) */
var _lp6CloseOverlays = closeOverlays;
closeOverlays = function(){
  try{ if(lp6Sim.ov) lp6RestoreSim(); }catch(e){}
  return _lp6CloseOverlays.apply(this, arguments);
};

/* Переключение режима на тест — практикум закрывается до пересборки шагов */
var _lp6StartTestSession = startTestSession;
startTestSession = function(r){
  try{ if(lp6Sim.ov) lp6RestoreSim(); }catch(e0){}
  return _lp6StartTestSession.apply(this, arguments);
};

/* Esc: сначала закрыть практикум, затем оверлей поиска (Э3), затем плеер (Э1) */
var _lp6OnKeydown = onKeydown;
onKeydown = function(e){
  if(S.active && e.key === 'Escape' && S.root){
    var ov = S.root.querySelector('.learn-overlay[data-ov="lp6sim"]');
    if(ov){ e.stopPropagation(); e.preventDefault(); lp6CloseSim(); return; }
  }
  return _lp6OnKeydown.apply(this, arguments);
};
/* ============================================================
   learn_player_stage6: ЭТАП 6 — Часть 2.
   P2: accessibility фокуса плеера (aria-modal, фокус при открытии/
   закрытии) и P3: ИИ-верификация метода Фейнмана.

   P2 — что уже было (Э1/Э3, проверено пробой на v12.7) и что добавлено:
   • initial focus — ЕСТЬ: openPlayer/openTestWindow фокусируют кнопку
     «✕» (комментарий «Фокус внутрь (a11y)»); хаб — поле поиска (Э3);
   • return focus — ЕСТЬ: closePlayer возвращает фокус на S.entryEl;
   • НОВОЕ 1: aria-modal="true" на корне плеера (buildRoot — общий
     для урока и теста) и на корне хаба (Home);
   • НОВОЕ 2: краевой случай возврата фокуса после входа «из ридера»:
     closePlayer переоткрывает ридер (readerWasOpen) — узел S.entryEl
     к этому моменту перерисован, фокус падал на body; теперь если
     точка входа устарела — фокус получает модал ридера (первая кнопка),
     «логический фокус» не остаётся под окном.

   P3 — контур наставника УЖЕ содержит экшен 'feynman' (v10/ДЕФ-22:
   MENTOR.ask('feynman', lessonId, {explanation}) → вердикт
   understood/partial/missed + advice + gaps; мок честно помечен) и
   готовый рендер window.mentorF1 (лимиты 30/день, фильтр, сохранение
   cn_feynman_ai). Кнопка «🤖 Спросить Наставника: понятно ли я
   объяснил?» ставится на шаг Фейнмана (renderFeynmanBox — общий для
   ридера и плеера) и вызывает СУЩЕСТВУЮЩИЙ контур — код наставника
   не тронут (§5.5/§11.9).
   ============================================================ */

/* ---------- P2: aria-modal на диалогах ---------- */
var _lp6BuildRoot = buildRoot;
buildRoot = function(l){
  var root = _lp6BuildRoot.apply(this, arguments);
  try{ if(root) root.setAttribute('aria-modal', 'true'); }catch(e){}
  return root;
};
var _lp6HomeOpen = Home.open;
Home.open = function(){
  var r = _lp6HomeOpen.apply(this, arguments);
  try{ if(H.root) H.root.setAttribute('aria-modal', 'true'); }catch(e){}
  return r;
};

/* ---------- P2: возврат фокуса при входе «из ридера» ---------- */
var _lp6ClosePlayer = closePlayer;
closePlayer = function(){
  var wasReader = false, entry = null;
  try{ wasReader = !!S.readerWasOpen; entry = S.entryEl; }catch(e0){}
  try{ if(lp6Sim.ov) lp6RestoreSim(); }catch(eR){} /* практикум не должен уйти вместе с корнем плеера */
  _lp6ClosePlayer.apply(this, arguments);
  try{
    if(wasReader && !S.active){
      /* ридер переоткрыт (readerWasOpen): точка входа могла остаться валидной,
         но семантически устареть (например, кнопка «🎓» шапки под модалом) —
         фокус получает модал ридера, а не элемент под ним */
      var m = document.getElementById('lessonFullscreenReaderModal');
      if(m && getComputedStyle(m).display !== 'none'){
        var tgt = m.querySelector('button, [href], input, [tabindex]:not([tabindex="-1"])');
        if(tgt){ try{ tgt.focus(); }catch(e1){} }
      }
    }
  }catch(e2){}
};

/* ---------- P3: кнопка наставника на шаге Фейнмана ---------- */
var _lp6FeynmanBox = renderFeynmanBox;
renderFeynmanBox = function(lesson){
  var h = _lp6FeynmanBox.apply(this, arguments);
  try{
    var id = lesson && lesson.id;
    if(!id) return h;
    h += '<div style="margin:-6px 0 20px;padding:0 2px">' +
      '<button type="button" class="lp-btn sm ghost" data-lp6-feynman="' + attr(id) + '" ' +
      'onclick="LearnPlayer._feynmanAsk(\'' + attr(id) + '\')" ' +
      'title="Наставник сверит твоё объяснение с эталоном урока (существующий контур MENTOR, лимит 30/день)">🤖 Спросить Наставника: понятно ли я объяснил?</button>' +
      '<div id="feynman_ai_' + attr(id) + '" style="margin-top:10px" aria-live="polite"></div></div>';
  }catch(e){}
  return h;
};

window.LearnPlayer._feynmanAsk = function(lessonId){
  var ta = document.getElementById('feynman_input_' + lessonId);
  var out = document.getElementById('feynman_ai_' + lessonId);
  if(!ta || !out) return;
  var text = String(ta.value || '').trim();
  if(text.length < 10){
    out.innerHTML = '<div style="font-size:12px;color:var(--warn)">Сначала напиши объяснение своими словами — хотя бы пару предложений, и наставник его оценит.</div>';
    try{ ta.focus(); }catch(e0){}
    return;
  }
  if(typeof window.mentorF1 !== 'function'){
    out.innerHTML = '<div style="font-size:12px;color:var(--warn)">Наставник недоступен в этой сборке.</div>';
    return;
  }
  window.mentorF1(lessonId, out); /* существующий контур: MENTOR.ask('feynman'), лимиты, фильтр, cn_feynman_ai */
};
/* ============================================================
   learn_player_stage6: ЭТАП 6 — Часть 3.
   Смоук lp6:*, секция selfTest.lp6, версия.
   ============================================================ */

/* ---------- Смоук lp6:* (в V10.smoke) ---------- */
function smoke6(){
  if(!(window.V10 && window.V10.smoke)) return;
  try{
    V10.smoke.add('lp6:api', typeof window.LearnPlayer._feynmanAsk === 'function' &&
      typeof window.LearnPlayer._goSim === 'function' &&
      window.LearnPlayer._goSim.__lp6 === true, window.LearnPlayer.version);
    /* aria-modal на каркасе плеера (buildRoot) */
    var ariaOk = false;
    try{
      var savedSteps = S.steps;
      S.steps = [1, 2];
      var probeRoot = buildRoot({ title: 'lp6-probe' });
      ariaOk = probeRoot.getAttribute('aria-modal') === 'true' && probeRoot.getAttribute('role') === 'dialog';
      S.steps = savedSteps;
    }catch(e){ ariaOk = false; }
    V10.smoke.add('lp6:aria-modal', ariaOk, 'aria-modal="true" + role="dialog" на корне плеера (урок и тест)');
    /* кнопка наставника присутствует в боксе Фейнмана (V2, общий для ридера и плеера) */
    var fmOk = false;
    try{
      var l = lessonById('p0_l1');
      fmOk = typeof renderFeynmanBox === 'function' && !!l &&
        renderFeynmanBox(l).indexOf('data-lp6-feynman="p0_l1"') >= 0 &&
        renderFeynmanBox(l).indexOf('feynman_ai_p0_l1') >= 0;
    }catch(e2){ fmOk = false; }
    V10.smoke.add('lp6:feynman-mentor', fmOk, 'кнопка «🤖 Спросить Наставника» на шаге Фейнмана + контейнер вердикта');
    /* все сим-ссылки уроков имеют боксы — встраивание технически возможно (принцип Э6) */
    var simOk = true, simN = 0;
    try{
      Object.keys(LESSON_SIM_MAP).forEach(function(lid){
        var m = LESSON_SIM_MAP[lid];
        if(!m) return;
        simN++;
        if(!document.getElementById('sim_' + m.simId)) simOk = false;
      });
    }catch(e3){ simOk = false; }
    V10.smoke.add('lp6:sim-boxes', simOk && simN > 0, simN + ' сим-ссылок — у всех есть #sim_* боксы для встраивания');
  }catch(e){
    try{ V10.smoke.add('lp6:smoke-error', false, String(e && e.message || e)); }catch(e2){}
  }
}
smoke6();

/* ---------- Секция selfTest.lp6 ---------- */
var _lp6SelfTest = window.LearnPlayer.selfTest;
window.LearnPlayer.selfTest = function(){
  var a = _lp6SelfTest ? _lp6SelfTest() : { ok: true, errors: [] };
  var errs = [];
  try{
    if(typeof window.LearnPlayer._feynmanAsk !== 'function') errs.push('lp6:api _feynmanAsk');
    if(!window.LearnPlayer._goSim || window.LearnPlayer._goSim.__lp6 !== true) errs.push('lp6:goSim-обёртка');
    if(typeof window.mentorF1 !== 'function') errs.push('lp6:mentorF1 отсутствует');
    var probe = null;
    try{
      var savedSteps2 = S.steps; S.steps = [1];
      probe = buildRoot({ title: 'probe' });
      S.steps = savedSteps2;
      if(!probe || probe.getAttribute('aria-modal') !== 'true') errs.push('lp6:aria-modal');
      probe = null;
    }catch(e4){ S.steps = (typeof savedSteps2 !== 'undefined') ? savedSteps2 : S.steps; errs.push('lp6:buildRoot-исключение'); }
    var l = lessonById('p0_l1');
    if(!l || renderFeynmanBox(l).indexOf('feynman_ai_p0_l1') < 0) errs.push('lp6:фейнман-кнопка');
  }catch(e){ errs.push('lp6:exception'); }
  a.lp6 = { ok: errs.length === 0, errors: errs };
  if(errs.length) a.ok = false;
  return a;
};

window.LearnPlayer.version = '6.0 (Этап 6, ТЗ v2)';
/* ============================================================
   learn_player_stage7: ЭТАП 7 — Часть 1.
   P1-1: контекст Ментора в тестовом режиме (закрывает §5.4.1).

   Было: в тестовом режиме (Этап 2) ветка mentor в rootClick
   передавала S.lessonId — он пуст, панель открывалась «в вакууме»:
   заголовок «Урок: общий», _mentorLessonId = null, шаговой
   карточки Этапа 4 нет (lp4StepCtx честно возвращает null —
   порции теста не материал урока). Наставник не знал, что
   ученик сдает «Тест Фазы 1, вопросы 6–10».
   Стало: обёртка window.mentorOpenPanel (поверх обёртки Этапа 4,
   rootClick не тронут) подставляет
     lessonId || (TS.active && TS.kind !== 'math' ? TS.testId : 'generic')
   и вставляет в панель карточку «Наставник видит тест»: тип банка,
   название, текущая порция (номер + диапазон вопросов) или шаг
   сдачи (отвечено X из Y) или результат попытки. Код наставника,
   лимиты и фильтры не тронуты (§5.5/§11.9) — v10-панель толерантна
   к произвольным id (проба: «Урок: capstone», 13 действий, 0 крахов).
   ============================================================ */

function lp7Esc(s){
  return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){
    return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c];
  });
}

var _lp7MentorOpen = window.mentorOpenPanel;
window.mentorOpenPanel = function(lessonId, stepCtx){
  try{
    if(lessonId == null || lessonId === ''){
      var inTest = false;
      try{ inTest = !!(typeof TS !== 'undefined' && TS && TS.active); }catch(eT){}
      lessonId = (inTest && TS.kind !== 'math' && TS.testId) ? TS.testId : 'generic';
    }
  }catch(e0){}
  var r = (arguments.length >= 2)
    ? _lp7MentorOpen.call(this, lessonId, stepCtx)
    : _lp7MentorOpen.call(this, lessonId);
  try{ lp7InjectTestCtx(); }catch(e1){}
  return r;
};
window.mentorOpenPanel.__lp7 = true;
/* переносим флаги предыдущего звена цепочки (напр. __lp4wrapped — selfTest Э4) */
try{
  Object.keys(_lp7MentorOpen).forEach(function(k){
    try{ if(!(k in window.mentorOpenPanel)) window.mentorOpenPanel[k] = _lp7MentorOpen[k]; }catch(e2){}
  });
}catch(e3){}

/* Описание текущего состояния теста для карточки в панели */
function lp7TestKicker(){
  try{
    if(typeof TS === 'undefined' || !TS || !TS.active) return null;
    var k = TS.kind === 'math' ? '🧮 Мат-тест факультатива'
      : (TS.kind === 'diag' ? '🔬 Диагностика' : '📝 Аттестация фазы ' + TS.ph);
    var t = (TS.bank && TS.bank.title) ? String(TS.bank.title) : '';
    return t ? (k + ' · ' + t) : k;
  }catch(e){ return null; }
}

function lp7TestDetail(){
  try{
    if(TS.submitted && TS.result){
      return 'Результат попытки: ' + TS.result.correct + ' из ' + TS.result.total +
        (TS.result.required !== undefined ? ' (порог ' + TS.result.required + ')' : '');
    }
    var st = (TS.steps && TS.steps.length) ? TS.steps[TS.idx] : null;
    if(st && st.qs){
      return 'Порция ' + (TS.idx + 1) + ' из ' + (TS.steps.length - 1) +
        ' · вопросы ' + (st.qs[0] + 1) + '–' + (st.qs[st.qs.length - 1] + 1);
    }
    if(st && st.kind === 'gate'){
      var ans = -1;
      try{ ans = tsAnsweredCount(); }catch(eA){}
      var total = (TS.bank && TS.bank.questions) ? TS.bank.questions.length : -1;
      return 'Шаг сдачи' + (ans >= 0 && total > 0 ? ' · отвечено ' + ans + ' из ' + total : '');
    }
    return '';
  }catch(e){ return ''; }
}

function lp7InjectTestCtx(){
  try{
    if(typeof TS === 'undefined' || !TS || !TS.active) return;
    if(!document.getElementById('mentor_panel')) return;
    var old = document.getElementById('lp7_mentor_test');
    if(old) old.remove();
    var actions = document.getElementById('mentor_actions');
    if(!actions) return;
    var kick = lp7TestKicker() || 'Тест';
    var detail = lp7TestDetail();
    var card = document.createElement('div');
    card.id = 'lp7_mentor_test';
    card.style.cssText = 'margin:0 0 10px;padding:9px 11px;border:1px solid var(--line);border-radius:9px;background:rgba(127,127,127,.07)';
    card.innerHTML = '<div style="font-size:11px;color:var(--mut);line-height:1.55">Наставник видит тест: ' +
      '<b style="color:var(--txt)">' + lp7Esc(kick) + '</b>' +
      (detail ? '<br>' + lp7Esc(detail) : '') + '</div>';
    actions.parentNode.insertBefore(card, actions);
  }catch(e){}
}
/* ============================================================
   learn_player_stage7: ЭТАП 7 — Часть 2.
   P1-2: «🧑‍🏫 Проверка Фейнмана» из панели, когда поля
   #feynman_input_<lid> нет в DOM.

   Было: действие панели вызывало mentorF1, который читает
   #feynman_input_<lid>; если шаг Фейнмана не отрисован (панель
   открыта с другого шага, из хаба или после смены урока) —
   объяснение пустое и уходило в ИИ вслепую (расход лимита без
   пользы). Стало: обёртка window.mentorRun (поверх v10-цепочки):
     1) поля нет → плеер сам переходит на шаг Фейнмана
        (goTo(findStepIdx('feynman')) — вариант из рекомендации);
     2) после перехода текст всё ещё пуст (<10 симв.) → ввод
        показывается прямо в панели: для живого шага — связанное
        поле lp7_feynman_in c копированием в шаг и dispatch input
        (черновик/запрет-слова работают), для урока без видимого
        шага — поле с штатным id feynman_input_<lid> (mentorF1
        прочитает его сам);
     3) короткий ввод (<10 симв.) не отправляется в ИИ — подсказка
        без расхода лимита (паритет с кнопкой Этапа 6 на шаге).
   Контур проверки — СУЩЕСТВУЮЩИЙ mentorF1/MENTOR.ask('feynman'),
   вердикт, cn_feynman_ai, лимиты и фильтры не тронуты.
   ============================================================ */

var _lp7MentorRun = window.mentorRun;
window.mentorRun = function(action){
  if(action === 'feynman'){
    try{
      var lid0 = window._mentorLessonId;
      if(lid0){
        var ta0 = document.getElementById('feynman_input_' + lid0);
        if(!ta0){ lp7GoToFeynmanStep(lid0); ta0 = document.getElementById('feynman_input_' + lid0); }
        if(ta0 && !document.body.contains(ta0)) ta0 = null;
        var val0 = ta0 ? String(ta0.value || '').trim() : '';
        if(val0.length < 10){ lp7FeynmanPanelInput(lid0, ta0, val0); return; }
      }
    }catch(e0){}
  }
  return _lp7MentorRun.apply(this, arguments);
};
window.mentorRun.__lp7 = true;
/* переносим флаги предыдущего звена цепочки mentorRun (v10-патчи) */
try{
  Object.keys(_lp7MentorRun).forEach(function(k){
    try{ if(!(k in window.mentorRun)) window.mentorRun[k] = _lp7MentorRun[k]; }catch(e2){}
  });
}catch(e3){}

/* Плеер открыт на этом уроке (не тест) → перейти на шаг Фейнмана.
   Контур из рекомендации заказчика: LearnPlayer.open(lid, idx) —
   «точно на шаг» (goTo блокировал бы прыжок вперёд: S.visited). */
function lp7GoToFeynmanStep(lid){
  try{
    if(typeof S === 'undefined' || !S || !S.root) return;
    if(typeof TS !== 'undefined' && TS && TS.active) return;
    if(S.active && S.lessonId === lid){
      var fi = findStepIdx('feynman');
      if(S.steps[fi] && S.steps[fi].kind === 'feynman' && fi !== S.idx){
        window.LearnPlayer.open(lid, fi);
      }
    }
  }catch(e){}
}

/* Поле ввода прямо в панели (между действиями и результатом).
   Если поле уже показано в панели (штатный id) — бокс не пересобирается:
   растёт подсказка, фокус возвращается в поле, набранный текст сохранён. */
function lp7FeynmanPanelInput(lid, ta, val){
  try{
    var existing = document.getElementById('lp7_mentor_feynman');
    var own = existing ? existing.querySelector('textarea[id="feynman_input_' + lid + '"]') : null;
    if(own){
      var hint0 = document.getElementById('lp7_feynman_hint');
      if(hint0) hint0.textContent = 'Добавь ещё пару предложений — нужно хотя бы 10 символов, чтобы наставник оценил объяснение.';
      try{ own.focus(); }catch(eF){}
      return;
    }
    var prevVal = '';
    if(existing){
      var pt = existing.querySelector('textarea');
      if(pt && !val) prevVal = String(pt.value || '');
      existing.remove();
    }
    if(prevVal && !val) val = prevVal; /* набранный текст не теряется при перерисовке */
    var actions = document.getElementById('mentor_actions');
    var result = document.getElementById('mentor_result');
    if(!actions || !result) return;
    var box = document.createElement('div');
    box.id = 'lp7_mentor_feynman';
    box.style.cssText = 'margin:10px 0 4px;padding:10px 11px;border:1px dashed var(--line);border-radius:9px;background:rgba(127,127,127,.05)';
    var note = ta
      ? 'Шаг Фейнмана открыт в плеере — заполни поле там или здесь:'
      : 'Шаг Фейнмана сейчас не виден — введи объяснение прямо здесь:';
    box.innerHTML = '<div style="font-size:11px;color:var(--mut);margin-bottom:7px">🧑‍🏫 ' + lp7Esc(note) + '</div>' +
      (ta
        ? '<textarea id="lp7_feynman_in" rows="4" style="width:100%;background:#040714;border:1px solid var(--line);border-radius:8px;padding:9px;color:var(--txt);font-size:12.5px;font-family:var(--font);box-sizing:border-box"></textarea>' +
          '<button type="button" class="btn sm" style="margin-top:7px" onclick="LearnPlayer._feynmanPanelCheck(\'' + attr(lid) + '\')">🔍 Проверить</button>'
        : '<textarea id="feynman_input_' + attr(lid) + '" rows="4" style="width:100%;background:#040714;border:1px solid var(--line);border-radius:8px;padding:9px;color:var(--txt);font-size:12.5px;font-family:var(--font);box-sizing:border-box"></textarea>' +
          '<button type="button" class="btn sm" style="margin-top:7px" onclick="mentorRun(\'feynman\')">🔍 Проверить</button>') +
      '<div id="lp7_feynman_hint" style="font-size:11px;color:var(--warn);margin-top:6px" aria-live="polite"></div>';
    actions.parentNode.insertBefore(box, result);
    var field = box.querySelector('textarea');
    if(field){ field.value = val || ''; try{ field.focus(); }catch(e2){} }
  }catch(e){}
}

/* Проверка из связанного поля панели: копия → живой шаг (черновик и
   фильтры слов работают через штатный input) → существующий mentorRun */
window.LearnPlayer._feynmanPanelCheck = function(lid){
  try{
    var pv = document.getElementById('lp7_feynman_in');
    var ta = document.getElementById('feynman_input_' + lid);
    if(pv && ta && document.body.contains(ta)){
      ta.value = pv.value;
      try{ ta.dispatchEvent(new Event('input', { bubbles: true })); }catch(e0){}
    }
  }catch(e1){}
  mentorRun('feynman');
};
/* ============================================================
   learn_player_stage7: ЭТАП 7 — Часть 3.
   P2-3: сертификат капстоуна в контексте плеера.
   P2-4: гейт «Завершить урок» на mobile — тост вместо молчания.

   P2-3 (проба на v12.8): сам сертификат на экране результата
   плеера ЕСТЬ ещё с Этапа 2 (P5.2: testResultHtml вставляет
   renderCapstoneCertificate при TS.ph===6 && passed; проба:
   38/38 → «СЕРТИФИКАТ КВАНТ-АРХИТЕКТОРА» на .learn-step). Пробел
   в другом: внутренняя кнопка сертификата «Перейти к достижениям»
   зовёт go('progress') — навигация происходит ПОД открытым
   плеером, ученик её не видит. Обёртка renderCapstoneCertificate:
   в контексте активной тест-сессии плеера onclick заменяется на
   «LearnPlayer.close();go('progress')» — плеер закрывается,
   подложка восстанавливается, вкладка «Прогресс» открывается
   на виду. Читательский путь (плеер закрыт) не меняется.

   P2-4: на мобильных title-подсказка заблокированной кнопки
   недоступна (нет hover), тап на <button disabled> молчит —
   непонятно, почему «Завершить урок» не работает. Решение без
   правок шаблонов (§0.1 — только обёртки):
     1) lp7UnlockGates() после каждого рендера снимает атрибут
        disabled с кнопок-гейтов (id lesson_complete_btn_* /
        lesson_bottom_complete_btn_*) и выставляет
        aria-disabled="true" (кликабельность + семантика SR);
     2) гейт переносится в обёртки completeLessonWithMastery
        (ридер) и LearnPlayer.completeLessonOnce (плеер): пока
        квиз не сдан — тост «🔒 Сначала сдайте квиз», урок НЕ
        завершается; существующие alert-гейты остаются фолбэком.
   Точки нормализации: renderStep/renderBottom (плеер),
   updateLessonCompleteBtn (шов ридера и плеера),
   openFullscreenLesson (модал ридера).
   ============================================================ */

/* ---------- P2-3: сертификат — CTA «К достижениям» закрывает плеер ---------- */
var _lp7Cert = window.renderCapstoneCertificate;
window.renderCapstoneCertificate = function(score, total){
  var h = _lp7Cert.apply(this, arguments);
  try{
    var inPlayerTest = false;
    try{
      inPlayerTest = !!(typeof S !== 'undefined' && S && S.active &&
        typeof TS !== 'undefined' && TS && TS.active);
    }catch(eP){}
    if(inPlayerTest){
      h = String(h).replace(/onclick="go\('progress'\)"/g,
        'onclick="LearnPlayer.close();go(\'progress\')"');
    }
  }catch(e){}
  return h;
};
window.renderCapstoneCertificate.__lp7 = true;

/* ---------- P2-4: нормализация кнопок-гейтов ----------
   Заблокированность определяется СОСТОЯНИЕМ урока (гейт квиза), а не
   атрибутом — иначе повторный проход нормализатора срывал aria-disabled
   с кнопки, разблокированной им же самим (клик работает, семантика теряется). */
function lp7GateLocked(lid){
  try{
    if(!lid || lessonsDone[lid]) return false;
    var l = null;
    try{ l = LESSONS.find(function(x){ return x.id === lid; }); }catch(eL){}
    var hasMastery = !!(l && l.blocks && l.blocks.some(function(b){ return b.type === 'mastery_check'; }));
    var st = (typeof lessonCheckState !== 'undefined' && lessonCheckState[lid]) || {};
    if(hasMastery) return !(st.quizDone && st.promptConfirmed);
    return !(lessonQuizPassed[lid] === true || st.quizDone === true);
  }catch(e){ return false; }
}

function lp7UnlockGates(){
  try{
    var btns = document.querySelectorAll('button[id^="lesson_complete_btn_"], button[id^="lesson_bottom_complete_btn_"]');
    for(var i = 0; i < btns.length; i++){
      var b = btns[i];
      var m = /^lesson_(?:bottom_)?complete_btn_(.+)$/.exec(b.id);
      var locked = lp7GateLocked(m ? m[1] : null);
      if(b.disabled){
        b.disabled = false;
        if(locked) b.setAttribute('aria-disabled', 'true');
      } else if(b.getAttribute('aria-disabled') === 'true' && !locked){
        b.removeAttribute('aria-disabled');
      }
    }
  }catch(e){}
}

var _lp7RenderStep = renderStep;
renderStep = function(){
  var r = _lp7RenderStep.apply(this, arguments);
  try{ lp7UnlockGates(); }catch(e0){}
  return r;
};
var _lp7RenderBottom = renderBottom;
renderBottom = function(){
  var r = _lp7RenderBottom.apply(this, arguments);
  try{ lp7UnlockGates(); }catch(e1){}
  return r;
};

var _lp7UpdateLCB = window.updateLessonCompleteBtn;
if(typeof _lp7UpdateLCB === 'function'){
  window.updateLessonCompleteBtn = function(){
    var r = _lp7UpdateLCB.apply(this, arguments);
    try{ lp7UnlockGates(); }catch(e2){}
    return r;
  };
  window.updateLessonCompleteBtn.__lp7 = true;
}

var _lp7OFSL = window.openFullscreenLesson;
if(typeof _lp7OFSL === 'function'){
  window.openFullscreenLesson = function(){
    var r = _lp7OFSL.apply(this, arguments);
    try{ lp7UnlockGates(); setTimeout(lp7UnlockGates, 60); }catch(e3){}
    return r;
  };
  window.openFullscreenLesson.__lp7 = true;
}

/* квиз отвечен верно → ридер/плеер включают кнопки напрямую, минуя
   updateLessonCompleteBtn — снимаем устаревший aria-disabled сразу */
var _lp7HQA = window.handleLessonQuizAnswer;
if(typeof _lp7HQA === 'function'){
  window.handleLessonQuizAnswer = function(){
    var r = _lp7HQA.apply(this, arguments);
    try{ lp7UnlockGates(); }catch(e4){}
    return r;
  };
  window.handleLessonQuizAnswer.__lp7 = true;
}

/* ---------- P2-4: тост на заблокированном гейте (ридер) ---------- */
var _lp7CLM = window.completeLessonWithMastery;
if(typeof _lp7CLM === 'function'){
  window.completeLessonWithMastery = function(id){
    try{
      if(id && !lessonsDone[id]){
        var state = (typeof lessonCheckState !== 'undefined' && lessonCheckState[id]) || {};
        var lesson = null;
        try{ lesson = LESSONS.find(function(x){ return x.id === id; }); }catch(eL){}
        var hasMastery = !!(lesson && lesson.blocks &&
          lesson.blocks.some(function(b){ return b.type === 'mastery_check'; }));
        if(hasMastery){
          if(!state.quizDone){ toast('Сначала сдайте квиз', '🔒'); return; }
          if(!state.promptConfirmed){ toast('Сначала подтвердите критерий приёмки урока', '🔒'); return; }
        } else {
          var quizOk = lessonQuizPassed[id] === true || state.quizDone === true;
          if(!quizOk){ toast('Сначала сдайте квиз', '🔒'); return; }
        }
      }
    }catch(e0){ /* гейт не реплицирован — работает существующий alert-путь */ }
    return _lp7CLM.apply(this, arguments);
  };
  window.completeLessonWithMastery.__lp7 = true;
}

/* ---------- P2-4: тост на заблокированном гейте (плеер) ---------- */
var _lp7Clo = window.LearnPlayer.completeLessonOnce;
window.LearnPlayer.completeLessonOnce = function(){
  try{
    var lid = S.lessonId;
    var l = lid ? lessonById(lid) : null;
    if(l && !S.completedCalled && !isDone(lid)){
      var quizOk = false;
      try{
        quizOk = lessonQuizPassed[lid] === true ||
          (lessonCheckState[lid] && lessonCheckState[lid].quizDone === true);
      }catch(eQ){}
      if(!quizOk){ toast('Сначала сдайте квиз', '🔒'); return; }
    }
  }catch(e0){}
  return _lp7Clo.apply(this, arguments);
};
window.LearnPlayer.completeLessonOnce.__lp7 = true;
/* ============================================================
   learn_player_stage7: ЭТАП 7 — Часть 4.
   Смоук lp7:*, секция selfTest.lp7, версия.
   ============================================================ */

/* ---------- Смоук lp7:* (в V10.smoke) ---------- */
function smoke7(){
  if(!(window.V10 && window.V10.smoke)) return;
  try{
    V10.smoke.add('lp7:api', typeof window.LearnPlayer._feynmanPanelCheck === 'function' &&
      window.mentorOpenPanel.__lp7 === true && window.mentorRun.__lp7 === true,
      window.LearnPlayer.version);
    V10.smoke.add('lp7:cert-wrap', window.renderCapstoneCertificate.__lp7 === true,
      'сертификат капстоуна в плеере: «К достижениям» закрывает плеер');
    V10.smoke.add('lp7:gate-toast', window.completeLessonWithMastery.__lp7 === true &&
      window.LearnPlayer.completeLessonOnce.__lp7 === true,
      'гейт «Завершить урок»: тост «🔒 Сначала сдайте квиз» на заблокированной кнопке');
    var gOK = false;
    try{
      var probe = document.createElement('button');
      probe.id = 'lesson_complete_btn_lp7probe';
      probe.disabled = true;
      document.body.appendChild(probe);
      lp7UnlockGates();
      gOK = !probe.disabled && probe.getAttribute('aria-disabled') === 'true';
      probe.remove();
    }catch(e1){ gOK = false; }
    V10.smoke.add('lp7:gate-unlock', gOK,
      'гейты кликабельны (aria-disabled вместо disabled) — тап даёт подсказку');
  }catch(e){
    try{ V10.smoke.add('lp7:smoke-error', false, String(e && e.message || e)); }catch(e2){}
  }
}
smoke7();

/* ---------- Секция selfTest.lp7 ---------- */
var _lp7SelfTest = window.LearnPlayer.selfTest;
window.LearnPlayer.selfTest = function(){
  var a = _lp7SelfTest ? _lp7SelfTest() : { ok: true, errors: [] };
  var errs = [];
  try{
    if(typeof window.LearnPlayer._feynmanPanelCheck !== 'function') errs.push('lp7:_feynmanPanelCheck');
    if(!window.mentorOpenPanel || window.mentorOpenPanel.__lp7 !== true) errs.push('lp7:mentorOpenPanel-обёртка');
    if(!window.mentorRun || window.mentorRun.__lp7 !== true) errs.push('lp7:mentorRun-обёртка');
    if(!window.renderCapstoneCertificate || window.renderCapstoneCertificate.__lp7 !== true) errs.push('lp7:cert-обёртка');
    if(typeof lp7UnlockGates !== 'function') errs.push('lp7:lp7UnlockGates');
    if(!window.LearnPlayer.completeLessonOnce || window.LearnPlayer.completeLessonOnce.__lp7 !== true) errs.push('lp7:completeLessonOnce-обёртка');
  }catch(e){ errs.push('lp7:exception'); }
  a.lp7 = { ok: errs.length === 0, errors: errs };
  if(errs.length) a.ok = false;
  return a;
};

window.LearnPlayer.version = '7.0 (Этап 7, ТЗ v2)';
